INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO3-2-u2-C1','soc',3,2,'u2',1,'풍습과 세시 풍속 — 풍습은 옛날부터 되풀이되어 전해 오는 생활 습관과 생활 모습(생일 미역국, 돌잔치, 전통 결혼식, 김장) · 세시 풍속은 해마다 일정한 때에 되풀이하는 풍습(차례, 세시 음식, 전통 놀이) · 세시 풍속도 풍습의 하나 · 명절은 설날·정월 대보름·단오·추석처럼 해마다 일정하게 지켜 즐기는 날, 차례는 명절날 아침 조상들에게 지내는 제사, 덕담은 남이 잘되기를 바라며 나누는 좋은 말, 설빔은 설을 맞이해 새로 마련한 옷이나 신발',ARRAY['[4사04-01] 옛날 풍습에 대해 알아보고, 오늘날과 비교하여 변화상을 파악한다.']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO3-2-u2-C2','soc',3,2,'u2',2,'옛날의 일상생활 속 풍습 — 두레는 한꺼번에 많은 일손이 필요한 농사일을 함께하려고 마을에 만든 공동 조직, 품앗이는 김장·지붕 얹기처럼 일손이 모자란 일을 서로 돌아가며 돕는 풍습(오늘날 육아·반찬 품앗이) · 일생 동안의 풍습: 출생(대문에 21일 동안 금줄) → 백일 → 첫돌(돌잡이: 쌀·붓·활·돈·실) → 관례(결혼 전 성인식) → 혼례 → 회갑(환갑, 60년 건강하게 사신 것 축하) → 장례 · 서로 축하하거나 위로하며 마음을 나눔',ARRAY['[4사04-01] 옛날 풍습에 대해 알아보고, 오늘날과 비교하여 변화상을 파악한다.']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO3-2-u2-C3','soc',3,2,'u2',3,'옛날과 오늘날의 일상생활 속 풍습 비교 — 결혼 풍습: 옛날 신부 집·혼례복(한복)·나무 기러기(평생 함께)·폐백(신부가 신랑 쪽 어른께 큰절, 대추와 밤)·신부 집에서 며칠 뒤 신랑 집 / 오늘날 결혼식장·공원, 턱시도·웨딩드레스, 반지, 신혼여행 · 변함없는 것: 부부가 된 것을 알리고 가족과 친척이 미래를 축복하는 마음 · 변화하며 이어지는 풍습(백일잔치·회갑잔치·폐백), 사라져 가는 풍습(금줄 치기·관례), 장례는 매장이 줄고 수목장·해양장이 늘어남',ARRAY['[4사04-01] 옛날 풍습에 대해 알아보고, 오늘날과 비교하여 변화상을 파악한다.']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO3-2-u2-C4','soc',3,2,'u2',4,'옛날의 세시 풍속 — 설날(음력 1월 1일, 설빔·세배·덕담·떡국, 윷놀이·널뛰기·연날리기) · 정월 대보름(음력 1월 15일, 달맞이·쥐불놀이·다리밟기, 부럼·오곡밥과 나물) · 단오(음력 5월 5일, 씨름·그네뛰기·부채, 수리취떡·앵두화채, 창포 삶은 물에 머리 감기) · 추석(음력 8월 15일, 차례·성묘·강강술래·소싸움, 송편) · 동지(양력 12월 22일 무렵, 밤이 가장 긴 날·작은 설, 팥죽·달력·버선) · 떡국 흰색은 밝은 한 해, 긴 모양은 건강하고 오래 살기 · 송편은 점점 나아지기를 바라는 마음 · 차례·윷놀이·떡국·송편·팥죽은 오늘날까지 이어짐',ARRAY['[4사04-01] 옛날 풍습에 대해 알아보고, 오늘날과 비교하여 변화상을 파악한다.']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO3-2-u2-C5','soc',3,2,'u2',5,'옛날과 오늘날의 세시 풍속 비교 — 옛날 조상들은 주로 농사를 지었고 농사는 계절과 날씨의 영향을 받아 농사와 관련 있는 세시 풍속이 계절마다 다양했음(겨울 새해 첫 보름달에 풍년 기원, 가을 수확의 기쁨) · 오늘날에는 직업이 다양해져 농사짓는 사람이 줄어 큰 명절을 중심으로 한 세시 풍속이 이어짐 · 오늘날 설날: 차례·세배·떡국은 이어지는 모습, 여행·영화·케이크는 달라진 모습 · 가족이나 이웃과 기쁨을 함께 나누는 것은 변함없음',ARRAY['[4사04-01] 옛날 풍습에 대해 알아보고, 오늘날과 비교하여 변화상을 파악한다.']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO3-2-u2-C6','soc',3,2,'u2',6,'옛날부터 전해 내려오는 풍습 체험 — 복주머니는 복이 들어온다는 뜻으로 설날 아침 옷에 차고 다녔고 오늘날에도 선물함 · 만드는 차례: 활동 자료 뜯기 → 색칠하고 모양대로 뜯기 → 풀로 모양 만들기 → 리본이나 끈으로 손잡이 · 전통 놀이: 윷놀이(윷·윷판·윷말, 도·개·걸·윷·모, 윷이나 모가 나오거나 상대 말을 잡으면 한 번 더), 제기차기, 투호(병에 화살), 고누(고누판에서 말 따기·가두기) · 안전과 규칙 · 전통 놀이 지도사',ARRAY['[4사04-01] 옛날 풍습에 대해 알아보고, 오늘날과 비교하여 변화상을 파악한다.']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO3-2-u2-C7','soc',3,2,'u2',7,'옛날과 오늘날의 풍습 정리 — 세시 음식(떡국·송편·팥죽·오곡밥·수리취떡)과 명절·절기에 하던 일(쥐불놀이·다리밟기·강강술래·그네뛰기·부채 선물) · 오늘날 풍습에 담긴 뜻: 시험 보는 사람에게 엿(합격 기원), 어버이날 카네이션(부모님 사랑에 감사), 설날 복주머니(복이 들어오기를) · 전통 놀이에 새 도구를 더해 새 놀이 만들기(플라잉 디스크 윷놀이, 달리는 제기차기) · 풍습에는 생활과 생각이 담겨 있고 이어져 내려오는 풍습도 있음',ARRAY['[4사04-01] 옛날 풍습에 대해 알아보고, 오늘날과 비교하여 변화상을 파악한다.']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO3-2-u2-C8','soc',3,2,'u2',8,'교통의 뜻 — 교통은 어떤 장소에서 다른 장소로 사람이 이동하거나 물건을 옮기는 것 · 교통수단은 이동하거나 물건을 옮길 때 사용하는 도구, 교통로는 교통에 이용하는 길 · 도로(버스·오토바이), 고속 국도(고속버스), 철도(열차·지하철), 자전거 도로, 수로(배·유람선), 눈에 보이지 않는 항공로(비행기) · 필요에 따라 다양하게 이용: 많은 짐(지게차·트럭), 위험에 빠진 사람 구조(구조 헬기), 높은 곳(케이블카)',ARRAY['[4사04-02] 옛날부터 오늘날까지 교통의 변화에 따른 이동과 생활 모습의 변화를 이해한다.']::text[],8) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO3-2-u2-C9','soc',3,2,'u2',9,'옛날의 교통수단 — 옛날 사람들은 주로 걸어서 이동, 많이 다녀 생긴 길과 강을 교통로로 이용 · 말(먼 거리·빨리), 달구지(소나 말이 끄는 수레, 무거운 짐), 가마(가마꾼이 들어 옮김), 뗏목(통나무를 이어 긴 막대기로 밈), 나룻배(노를 저어 강 양쪽을 오감), 돛단배(바람의 힘을 이용하는 돛) · 자연에서 쉽게 얻는 재료, 사람·동물·바람(자연)의 힘 · 과학 기술의 발달로 기계의 힘: 증기 기차·증기선(수증기), 자동차·비행기(석유)',ARRAY['[4사04-02] 옛날부터 오늘날까지 교통의 변화에 따른 이동과 생활 모습의 변화를 이해한다.']::text[],9) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO3-2-u2-C10','soc',3,2,'u2',10,'오늘날의 교통수단과 교통 시설 — 버스·트럭·자가용·오토바이·지하철·기차·자전거·킥보드, 하늘의 비행기·헬리콥터, 바다의 여객선·화물선·잠수함·요트 · 대부분 석유·가스·전기를 연료로 씀 · 교통 시설: 주유소, 기차역, 휴게소, 자동차 정비소, 버스 터미널, 활주로, 관제탑, 등대, 크레인 · 안전을 위한 신호와 약속(빨간색 등대는 왼쪽에 장애물이 있으니 오른쪽, 흰색 등대는 오른쪽에 장애물이 있으니 왼쪽) · 나라마다 자연환경과 생활에 따라 독특한 교통수단(공중에 매달린 전동차, 세 발 택시, 물길의 배)',ARRAY['[4사04-02] 옛날부터 오늘날까지 교통의 변화에 따른 이동과 생활 모습의 변화를 이해한다.']::text[],10) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO3-2-u2-C11','soc',3,2,'u2',11,'교통의 변화로 달라진 생활 — 먼 곳까지 더 빠르고 편하게, 가기 어려웠던 곳에 쉽게 · 옛날 선비는 걸어서·말·나룻배로 15일 정도, 오늘날 어린이는 지하철·고속 열차·버스로 반나절 정도 · 달구지 → 트럭: 더 많은 짐을 먼 곳까지 · 생활 공간이 넓어짐(먼 직장·학교, 여러 곳의 물건, 먼 곳 여행) · 가마꾼·뱃사공은 거의 사라지고 철도 기관사·항공기 조종사·해양 경찰관·도선사(배가 안전하게 항구를 드나들도록 안내) 등이 새로 생김 · 교통 약자 택시',ARRAY['[4사04-02] 옛날부터 오늘날까지 교통의 변화에 따른 이동과 생활 모습의 변화를 이해한다.']::text[],11) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO3-2-u2-C12','soc',3,2,'u2',12,'교통이 변화하며 생긴 문제와 해결 노력 — 문제: 교통 체증(차가 너무 많이 모여 길이 막힘), 교통사고, 대기 오염과 소음, 주차할 곳 부족 · 노력: 과학적인 교통 관리(막히는 길·사고 정보를 빠르게 알림), 새로운 교통 시설 개발, 친환경 에너지 사용, 새 주차 시설, 대중교통 중심, 전기 자전거 공유 · 교통안전 수칙: 횡단보도에서 주위 살피기, 무단 횡단 안 하기, 스마트폰 보며 걷지 않기, 자전거·킥보드는 정해진 도로에서 안전 장비, 어린이 보호 구역에서 자동차는 천천히',ARRAY['[4사04-02] 옛날부터 오늘날까지 교통의 변화에 따른 이동과 생활 모습의 변화를 이해한다.']::text[],12) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO3-2-u2-C13','soc',3,2,'u2',13,'미래의 교통과 달라질 생활 — 자율 주행 휠체어(장애인·환자의 안전한 이동), 착용하는 로봇(무거운 물건), 우주선(우주여행·우주로 물건), 자율 주행 자동차(직접 운전할 필요 없음, 일하고 쉬는 공간), 자율 운항 선박(스스로 목적지까지), 초고속 자기 부상 열차(전기의 힘으로 떠서 터널을 통해 비행기보다 빠르게) · 도심 항공 교통(하늘로 다녀 교통 혼잡이 없고 공해·소음이 적음) · 더 빠르고 안전하면서 환경을 보호하는 방향 · 새 직업: 우주 관광 가이드, 도심 항공 관제사, 이착륙장 관리자, 인공지능 개발자',ARRAY['[4사04-02] 옛날부터 오늘날까지 교통의 변화에 따른 이동과 생활 모습의 변화를 이해한다.']::text[],13) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO3-2-u2-C14','soc',3,2,'u2',14,'교통의 변화로 달라진 생활 정리 — 교통의 발달로 사람과 물건의 이동이 빨라지고 편리해짐 · 교통 체증·환경 문제 같은 문제도 생겨 지금도 해결하려고 노력 · 새 시설이 생기고 생활 모습이 달라짐 · 옛날 사람이 상상한 미래 교통수단(나는 신발) · 여러 나라의 독특한 교통 표지판(동물 조심, 걸으며 스마트폰 쓰지 말기, 보행자 우선 도로)',ARRAY['[4사04-02] 옛날부터 오늘날까지 교통의 변화에 따른 이동과 생활 모습의 변화를 이해한다.']::text[],14) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO3-2-u2-C15','soc',3,2,'u2',15,'통신과 통신수단 — 통신은 소식이나 정보를 주고받는 것, 통신수단은 그때 사용하는 방법이나 도구(전화·텔레비전·컴퓨터·스마트폰·편지·전자 우편·인터폰) · 목적: 위험을 알리고 도움 청하기, 친구와 연락, 일기 예보로 날씨 알기, 길 도우미로 길 찾기 · 통신수단이 없다면 급한 소식을 직접 가서 전해야 하고 다른 지역 소식을 알기 어려움',ARRAY['[4사04-03] 옛날부터 오늘날까지 통신수단의 변화에 따른 정보 교류와 의사소통 방식의 변화를 설명한다.']::text[],15) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO3-2-u2-C16','soc',3,2,'u2',16,'옛날의 통신수단 — 서찰(안부·소식을 글로 적어 사람이 직접 전달), 방(나라의 중요한 소식을 사람들이 많이 모이는 곳에 붙임), 봉수(낮에는 연기·밤에는 불, 평상시 1개·적이 나타나면 2개·가까이 오면 3개·쳐들어오면 4개·싸움이 시작되면 5개), 파발(나라의 중요한 문서를 말을 타거나 걸어가 전달), 신호 연(암호를 적은 연), 신호 깃발, 북, 나발 · 특징: 시간이 오래 걸림, 많은 내용을 자세하고 정확하게 전하기 어려움, 날씨의 영향(안개가 짙으면 봉수가 안 보임)',ARRAY['[4사04-03] 옛날부터 오늘날까지 통신수단의 변화에 따른 정보 교류와 의사소통 방식의 변화를 설명한다.']::text[],16) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO3-2-u2-C17','soc',3,2,'u2',17,'오늘날의 통신수단 — 모바일 메신저(어디에서나 대화), 디지털 안내판(버스 오는 시각), 대기 정보 알리미(미세 먼지), 등하교 알리미, 무전기(구급 대원이 구조 헬기 요청), 텔레비전 뉴스·전자 우편, 길 도우미(내비게이션) · 학교: 전자 칠판, 태블릿 컴퓨터, 스피커(종소리·안내 방송), 전화기 · 하는 일에 따라: 야구 심판 수신호, 교통경찰 수신호와 호루라기, 축구 심판 색 카드, 마을 안내 방송 · 여러 사람과 동시에 많은 정보를 실시간으로 빠르게',ARRAY['[4사04-03] 옛날부터 오늘날까지 통신수단의 변화에 따른 정보 교류와 의사소통 방식의 변화를 설명한다.']::text[],17) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO3-2-u2-C18','soc',3,2,'u2',18,'통신수단의 변화로 달라진 생활 — 언제 어디서나 정보를 쉽고 빠르게, 직접 가지 않아도 할 수 있는 일이 많아짐(모바일 메신저, 집에서 물건 사기·은행 거래, 진료, 화상 회의) · 전화기: 초기의 전화기(벽, 숫자 번호판 없음, 교환원이 연결) → 유선 전화(숫자 번호판, 전화기 있는 곳으로 가야 함, 공중전화는 동전·전화 카드) → 휴대 전화(들고 다니며 통화) → 오늘날 휴대 전화(사진·쇼핑·은행) · 새 시설·직업: 기지국과 통신 설비 기술자, 인공위성 개발자, 촬영 기사, 폐회로 텔레비전 통합 관제 요원 · 사라진 것: 교환원, 무선 호출기 · 디지털 배움터, 변화를 따라가기 힘든 사람 배려',ARRAY['[4사04-03] 옛날부터 오늘날까지 통신수단의 변화에 따른 정보 교류와 의사소통 방식의 변화를 설명한다.']::text[],18) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO3-2-u2-C19','soc',3,2,'u2',19,'통신수단을 올바르게 이용하기 — 올바르게 쓰지 않으면 몸과 마음의 건강을 해치고 다른 사람에게 피해 · 이어폰 끼고 동영상 보며 걷기(위험), 공공장소에서 큰 소리 통화, 상처 주는 댓글, 허락 없이 사진 찍기, 나쁜 자세로 오래 게임 · 스마트폰 과의존은 일상생활에 문제가 생길 정도로 지나치게 쓰는 것 · 약속: 진동으로 바꾸고 작은 소리로 짧게, 바른 표현·확인되지 않은 정보 올리지 않기, 개인 정보 보안, 정한 시간에만, 때와 장소에 맞게, 길에서는 안전 · 통신 예절',ARRAY['[4사04-03] 옛날부터 오늘날까지 통신수단의 변화에 따른 정보 교류와 의사소통 방식의 변화를 설명한다.']::text[],19) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO3-2-u2-C20','soc',3,2,'u2',20,'통신수단의 변화로 달라진 생활 정리 — 옛날 통신수단(서찰·방·파발·봉수)은 자세한 정보를 전하기 어렵고 시간이 오래 걸림 · 오늘날에는 한 번에 많은 정보를 실시간으로, 하나의 통신수단으로 여러 통신 방법 · 새로운 시설과 직업 · 몸과 마음의 건강을 위해 안전하고 올바르게 사용 · 미래 통신수단 상상(불편했던 경험에서 출발) · 이모티콘 만들기(상황에 알맞은 말 → 모습 정하기 → 스케치·색칠)',ARRAY['[4사04-03] 옛날부터 오늘날까지 통신수단의 변화에 따른 정보 교류와 의사소통 방식의 변화를 설명한다.']::text[],20) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO3-2-u2-X01','soc',3,'u2',ARRAY['SO3-2-u2-C1']::text[],'풍습과 세시 풍속의 관계를 거꾸로 안다(세시 풍속은 풍습이 아니라고, 또는 풍습은 모두 세시 풍속이라고 여기는 등)','세시 풍속도 풍습이에요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO3-2-u2-X02','soc',3,'u2',ARRAY['SO3-2-u2-C1','SO3-2-u2-C3','SO3-2-u2-C7']::text[],'풍습은 옛날에만 있고 오늘날에는 볼 수 없다고 여긴다','오늘날에도 이어져요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO3-2-u2-X03','soc',3,'u2',ARRAY['SO3-2-u2-C1','SO3-2-u2-C4']::text[],'명절·차례·덕담·설빔 같은 낱말의 뜻을 서로 바꾸어 안다','낱말 뜻을 다시 봐요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO3-2-u2-X04','soc',3,'u2',ARRAY['SO3-2-u2-C2']::text[],'두레와 품앗이를 바꾸어 알거나, 옛날 사람들이 함께 일한 까닭을 잘못 안다','마을 조직 · 돌아가며 돕기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO3-2-u2-X05','soc',3,'u2',ARRAY['SO3-2-u2-C2']::text[],'일생 동안의 풍습(금줄·돌잔치·관례·혼례·회갑·장례)의 차례나 뜻을 바꾸어 안다','태어나서 늙기까지 차례대로') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO3-2-u2-X06','soc',3,'u2',ARRAY['SO3-2-u2-C2']::text[],'옛날 풍습에 담긴 마음(축하·위로·서로 돕는 정)을 놓친다','기쁨과 슬픔을 함께 나눠요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO3-2-u2-X07','soc',3,'u2',ARRAY['SO3-2-u2-C3']::text[],'옛날과 오늘날의 결혼 풍습(장소·옷·주고받는 물건·마친 뒤)을 바꾸어 안다','나무 기러기 · 반지') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO3-2-u2-X08','soc',3,'u2',ARRAY['SO3-2-u2-C3']::text[],'결혼 풍습이 모두 같다고, 또는 모두 달라져 변함없는 마음은 없다고 여긴다','알리고 축복하는 마음') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO3-2-u2-X09','soc',3,'u2',ARRAY['SO3-2-u2-C3']::text[],'변화하면서 이어져 내려오는 풍습과 사라져 가는 풍습을 바꾸어 안다','백일잔치 · 금줄 치기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO3-2-u2-X10','soc',3,'u2',ARRAY['SO3-2-u2-C4']::text[],'명절의 이름과 날짜를 바꾸어 안다','1월 1일 · 1월 15일 · 5월 5일 · 8월 15일 · 동지') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO3-2-u2-X11','soc',3,'u2',ARRAY['SO3-2-u2-C4']::text[],'명절과 그날 하는 일·먹는 음식·놀이를 잘못 짝짓는다','명절마다 달라요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO3-2-u2-X12','soc',3,'u2',ARRAY['SO3-2-u2-C4']::text[],'세시 음식과 세시 풍속에 담긴 바람(건강·복·풍년)을 잘못 안다','무엇을 바랐을까요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO3-2-u2-X13','soc',3,'u2',ARRAY['SO3-2-u2-C5']::text[],'옛날 세시 풍속이 농사·계절과 관련 있었다는 점을 놓친다','농사는 계절을 따라요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO3-2-u2-X14','soc',3,'u2',ARRAY['SO3-2-u2-C5']::text[],'오늘날 세시 풍속이 달라진 모습이나 까닭을 잘못 안다','농사짓는 사람이 줄었어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO3-2-u2-X15','soc',3,'u2',ARRAY['SO3-2-u2-C5']::text[],'오늘날 명절 모습에서 이어져 오는 모습과 달라진 모습을 바꾸어 가른다','차례·세배 · 여행·영화') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO3-2-u2-X16','soc',3,'u2',ARRAY['SO3-2-u2-C5','SO3-2-u2-C7']::text[],'세시 풍속이 달라져도 변함없는 것(가족·이웃과 기쁨 나누기)을 놓친다','함께 기쁨을 나눠요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO3-2-u2-X17','soc',3,'u2',ARRAY['SO3-2-u2-C6']::text[],'복주머니에 담긴 뜻이나 만드는 차례를 잘못 안다','복이 들어와요 · 뜯고 색칠하고 붙이고 끈') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO3-2-u2-X18','soc',3,'u2',ARRAY['SO3-2-u2-C6']::text[],'전통 놀이의 이름·도구·방법을 바꾸어 안다','윷 · 제기 · 투호 병 · 고누판') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO3-2-u2-X19','soc',3,'u2',ARRAY['SO3-2-u2-C7']::text[],'오늘날 풍습에 담긴 뜻을 잘못 짝짓는다','어떤 마음이 담겼을까요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO3-2-u2-X20','soc',3,'u2',ARRAY['SO3-2-u2-C8','SO3-2-u2-C14']::text[],'교통·교통수단·교통로의 뜻을 서로 바꾸어 안다','이동 · 도구 · 길') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO3-2-u2-X21','soc',3,'u2',ARRAY['SO3-2-u2-C8']::text[],'교통수단과 그 교통수단이 다니는 교통로를 잘못 짝짓는다','도로 · 철도 · 수로 · 항공로') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO3-2-u2-X22','soc',3,'u2',ARRAY['SO3-2-u2-C8']::text[],'교통수단은 사람만 옮긴다고, 또는 한 가지 까닭으로만 이용한다고 여긴다','필요에 따라 다양하게') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO3-2-u2-X23','soc',3,'u2',ARRAY['SO3-2-u2-C9']::text[],'옛날 교통수단의 이름과 쓰임을 바꾸어 안다','말 · 달구지 · 가마 · 뗏목 · 나룻배 · 돛단배') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO3-2-u2-X24','soc',3,'u2',ARRAY['SO3-2-u2-C9','SO3-2-u2-C14']::text[],'옛날 교통수단을 움직인 힘이나 만든 재료를 잘못 안다(기계·석유의 힘으로 여기는 등)','사람 · 동물 · 바람의 힘') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO3-2-u2-X25','soc',3,'u2',ARRAY['SO3-2-u2-C9','SO3-2-u2-C10']::text[],'기계의 힘으로 움직이는 교통수단과 그 연료를 잘못 안다','수증기 · 석유 · 가스 · 전기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO3-2-u2-X26','soc',3,'u2',ARRAY['SO3-2-u2-C10']::text[],'교통 시설과 그 쓰임을 잘못 짝짓는다','주유소 · 활주로 · 관제탑 · 등대') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO3-2-u2-X27','soc',3,'u2',ARRAY['SO3-2-u2-C10']::text[],'교통 신호와 약속이 생긴 까닭이나 그 뜻을 잘못 안다','안전을 위해서예요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO3-2-u2-X28','soc',3,'u2',ARRAY['SO3-2-u2-C11','SO3-2-u2-C14']::text[],'교통이 발달하며 이동 시간·실어 나르는 짐·생활 공간이 달라진 것을 거꾸로 안다','빠르게 · 많이 · 넓게') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO3-2-u2-X29','soc',3,'u2',ARRAY['SO3-2-u2-C11']::text[],'교통의 변화로 새로 생긴 직업과 거의 사라진 직업을 바꾸어 안다','가마꾼 · 도선사') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO3-2-u2-X30','soc',3,'u2',ARRAY['SO3-2-u2-C12']::text[],'교통의 문제점과 그것을 해결하려는 노력을 잘못 짝짓는다','체증 · 사고 · 환경 · 주차') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO3-2-u2-X31','soc',3,'u2',ARRAY['SO3-2-u2-C12']::text[],'교통안전 수칙을 잘못 알거나 운전자만 지키면 된다고 여긴다','보행자도 지켜요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO3-2-u2-X32','soc',3,'u2',ARRAY['SO3-2-u2-C12','SO3-2-u2-C14']::text[],'교통을 한쪽으로만 본다(편리하니 문제가 없다, 또는 문제가 있으니 교통수단을 없애자)','편리해졌지만 문제도 있어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO3-2-u2-X33','soc',3,'u2',ARRAY['SO3-2-u2-C13']::text[],'미래 교통수단의 이름과 특징을 바꾸어 안다','휠체어 · 로봇 · 우주선 · 자율 주행 · 자기 부상') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO3-2-u2-X34','soc',3,'u2',ARRAY['SO3-2-u2-C13']::text[],'미래 교통의 발전 방향을 빠르기만으로, 또는 지금과 똑같을 것으로 여긴다','빠르고 · 안전하고 · 환경을 보호해요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO3-2-u2-X35','soc',3,'u2',ARRAY['SO3-2-u2-C15','SO3-2-u2-C20']::text[],'통신과 교통, 통신수단과 교통수단을 서로 바꾸어 안다','소식을 주고받아요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO3-2-u2-X36','soc',3,'u2',ARRAY['SO3-2-u2-C15']::text[],'통신수단을 쓰는 목적을 한 가지로만 보거나 통신수단이 없어도 생활이 똑같다고 여긴다','연락 · 날씨 · 길 찾기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO3-2-u2-X37','soc',3,'u2',ARRAY['SO3-2-u2-C16']::text[],'옛날 통신수단(서찰·방·봉수·파발·신호 연)의 이름과 쓰임을 바꾸어 안다','글 · 붙이기 · 연기와 불 · 말') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO3-2-u2-X38','soc',3,'u2',ARRAY['SO3-2-u2-C16','SO3-2-u2-C17','SO3-2-u2-C20']::text[],'옛날 통신수단과 오늘날 통신수단의 특징을 서로 바꾸어 안다','오래·날씨 · 실시간·여러 사람') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO3-2-u2-X39','soc',3,'u2',ARRAY['SO3-2-u2-C17']::text[],'오늘날 통신수단과 그것을 쓰는 장면을 잘못 짝짓는다','메신저 · 안내판 · 알리미 · 무전기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO3-2-u2-X40','soc',3,'u2',ARRAY['SO3-2-u2-C18']::text[],'전화기가 변해 온 차례나 그때의 생활 모습을 바꾸어 안다','초기 → 유선 → 휴대 → 오늘날') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO3-2-u2-X41','soc',3,'u2',ARRAY['SO3-2-u2-C18']::text[],'통신수단의 발달로 생기거나 사라진 시설·직업을 바꾸어 안다','교환원 · 통신 설비 기술자') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO3-2-u2-X42','soc',3,'u2',ARRAY['SO3-2-u2-C19']::text[],'통신수단을 올바르게 쓰지 않아도 괜찮다고, 또는 문제는 나 혼자에게만 생긴다고 여긴다','건강 · 다른 사람 피해') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO3-2-u2-X43','soc',3,'u2',ARRAY['SO3-2-u2-C19']::text[],'통신 예절과 올바른 이용 방법을 잘못 안다','작은 소리 · 바른 표현 · 허락 · 정한 시간') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO3-2-u2-X44','soc',3,'u2',ARRAY['SO3-2-u2-C20','SO3-2-u2-C14','SO3-2-u2-C7']::text[],'옛날과 오늘날의 생활 모습을 섞거나, 생활 모습이 변하지 않았다고 여긴다','옛날과 오늘날을 견줘요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO3-2-u2-X45','soc',3,'u2',ARRAY['SO3-2-u2-C3']::text[],'폐백은 모든 결혼식에서 반드시 드린다고 여기거나, 옛날과 오늘날 폐백을 받는 사람이 같다고 여긴다(옛날 신랑 집안 어른들 → 오늘날 양쪽 집안 어른들)','누가 폐백을 받았나? 모든 결혼식에서 하나?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO3-2-u2-X46','soc',3,'u2',ARRAY['SO3-2-u2-C11']::text[],'크레인 기사는 바다(항구)에서만 일하는 직업이라고 여긴다(공사장 같은 땅 위나 공항에서도 일함)','크레인은 항구에만 있을까?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO3-2-u2-X47','soc',3,'u2',ARRAY['SO3-2-u2-C4']::text[],'동지도 설날·추석처럼 음력 날짜를 따른다고 여긴다(동지는 태양의 움직임에 따라 나눈 24절기의 하나라 양력 12월 22일 무렵)','동지는 달? 태양?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO3-2-u2-X48','soc',3,'u2',ARRAY['SO3-2-u2-C9','SO3-2-u2-C16']::text[],'옛날에는 통신수단·교통수단이 아예 없었다고 여기거나, 옛날 수단을 오늘날 눈으로만 보아 쓸모없었다고 여긴다','그때 사람들은 무엇을 썼을까?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO3-2-u2-X49','soc',3,'u2',ARRAY['SO3-2-u2-C12']::text[],'어린이는 보행자일 뿐이라 자전거·킥보드를 탈 때 지킬 운전자 안전 수칙과는 상관없다고 여긴다','자전거를 탈 때 나는 누구?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO3-2-u2-X50','soc',3,'u2',ARRAY['SO3-2-u2-C18','SO3-2-u2-C20']::text[],'통신수단이 바뀌어도 사람들이 정보를 찾고 의사소통하는 방식은 옛날과 같다고 여긴다','옛날엔 어떻게 소식을 찾았지?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO3-2-u2-X51','soc',3,'u2',ARRAY['SO3-2-u2-C18']::text[],'통신수단이 발달하면 모든 사람이 똑같이 편리해진다고 여겨, 변화를 따라가기 힘든 사람이 있다는 것을 놓친다','키오스크가 어려운 사람은?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L01_basic#1','soc',3,2,'u2','L01','tb_g3_2_soc_u2_L01_basic','lesson_basic','SO3-2-u2-C1',1,'blank','auto','동시 「설날 아침」의 두 번째 줄 빈칸에 들어갈 낱말은 무엇인가요?',ARRAY['SO3-2-u2-X03']::text[],true,'{"seq":1,"concept":"SO3-2-u2-C1","difficulty":1,"kind":"blank","stem":"동시 「설날 아침」의 두 번째 줄 빈칸에 들어갈 낱말은 무엇인가요?","options":[{"t":"설빔","correct":true},{"t":"덕담","mis":"SO3-2-u2-X03"},{"t":"떡국","mis":"SO3-2-u2-X03"},{"t":"까치","mis":"SO3-2-u2-X03"}],"explanation":["오색 고운 옷이에요.","설에 새로 마련해 입어요.","설빔이에요."],"asset":{"type":"passage","lines":["까치 우는 설날 아침","오색 고운 (    ) 입고","어른들께 (    ) 해요","꿀꺽, (    ) 한 그릇"],"title":"동시 「설날 아침」 앞부분(김나은) — 빈칸 셋"},"variant_rule":{"alt":[{"stem":"동시 「설날 아침」의 세 번째 줄 빈칸에 들어갈 낱말은 무엇인가요?","options":[{"t":"세배","correct":true},{"t":"설빔","mis":"SO3-2-u2-X03"},{"t":"덕담","mis":"SO3-2-u2-X03"},{"t":"복주머니","mis":"SO3-2-u2-X03"}],"explanation":["어른들께 하는 일이에요.","설날 아침에 해요.","세배예요."],"asset":{"type":"passage","lines":["까치 우는 설날 아침","오색 고운 (    ) 입고","어른들께 (    ) 해요","꿀꺽, (    ) 한 그릇"],"title":"동시 「설날 아침」 앞부분(김나은) — 빈칸 셋"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L01_basic#2','soc',3,2,'u2','L01','tb_g3_2_soc_u2_L01_basic','lesson_basic','SO3-2-u2-C1',1,'sa','auto','『사회』 66쪽 낱말 풀이에서 「남이 잘되기를 바라며 서로 나누는 좋은 말」을 가리키는 낱말을 두 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SO3-2-u2-C1","difficulty":1,"kind":"sa","stem":"『사회』 66쪽 낱말 풀이에서 「남이 잘되기를 바라며 서로 나누는 좋은 말」을 가리키는 낱말을 두 글자로 쓰세요.","answer":["덕담"],"explanation":["좋은 말이에요.","덕◯이에요.","덕담이에요."],"mis":"SO3-2-u2-X03"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L01_basic#3','soc',3,2,'u2','L01','tb_g3_2_soc_u2_L01_basic','lesson_basic','SO3-2-u2-C1',1,'mc','auto','67쪽 사진 네 장처럼 옛날부터 되풀이되어 전해 오는 생활 습관과 생활 모습을 무엇이라고 하나요?',ARRAY['SO3-2-u2-X01','SO3-2-u2-X03']::text[],true,'{"seq":3,"concept":"SO3-2-u2-C1","difficulty":1,"kind":"mc","stem":"67쪽 사진 네 장처럼 옛날부터 되풀이되어 전해 오는 생활 습관과 생활 모습을 무엇이라고 하나요?","options":[{"t":"풍습","correct":true},{"t":"세시 풍속","mis":"SO3-2-u2-X01"},{"t":"절기","mis":"SO3-2-u2-X03"},{"t":"명절","mis":"SO3-2-u2-X03"}],"explanation":["미역국, 돌잔치, 결혼식, 김장이에요.","옛날부터 되풀이돼요.","풍습이에요."],"asset":{"type":"passage","lines":["사진 ① 생일날 미역국을 먹어요.","사진 ② 첫 번째 생일에 돌잔치를 해요.","사진 ③ 남자와 여자가 전통 결혼식을 해요.","사진 ④ 겨울이 되기 전에 사람들이 모여 김장을 해요."],"numbered":false,"title":"『사회』 67쪽 사진 네 장"},"variant_rule":{"alt":[{"stem":"명절날 차례, 추석 송편, 연날리기처럼 해마다 일정한 때에 되풀이하는 풍습을 무엇이라고 하나요?","options":[{"t":"세시 풍속","correct":true},{"t":"김장","mis":"SO3-2-u2-X01"},{"t":"돌잔치","mis":"SO3-2-u2-X01"},{"t":"덕담","mis":"SO3-2-u2-X03"}],"explanation":["해마다 일정한 때예요.","명절이나 절기에 해요.","세시 풍속이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L01_basic#4','soc',3,2,'u2','L01','tb_g3_2_soc_u2_L01_basic','lesson_basic','SO3-2-u2-C1',1,'ox','auto','『사회』 68쪽 말풍선처럼 명절 전통 놀이도 풍습이에요.',ARRAY['SO3-2-u2-X01']::text[],false,'{"seq":4,"concept":"SO3-2-u2-C1","difficulty":1,"kind":"ox","stem":"『사회』 68쪽 말풍선처럼 명절 전통 놀이도 풍습이에요.","answer":"O","reason_options":[{"t":"옛날부터 해마다 되풀이되어 전해 오는 생활 모습이기 때문에","correct":true},{"t":"놀이는 생활 습관이 아니어서 풍습이 될 수 없기 때문에","mis":"SO3-2-u2-X01"}],"mis":"SO3-2-u2-X01","explanation":["연날리기를 떠올려요.","옛날부터 전해 와요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L01_basic#5','soc',3,2,'u2','L01','tb_g3_2_soc_u2_L01_basic','lesson_basic','SO3-2-u2-C1',2,'match','auto','68쪽 낱말 풀이를 보고 낱말과 뜻을 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"SO3-2-u2-C1","difficulty":2,"kind":"match","stem":"68쪽 낱말 풀이를 보고 낱말과 뜻을 알맞게 이으세요.","pairs":[{"l":"명절","r":"설날, 추석처럼 해마다 일정하게 지켜 즐기는 날"},{"l":"절기","r":"태양의 움직임에 따라 일 년을 24개로 나누어 정한 날"},{"l":"차례","r":"명절날 아침에 조상들에게 지내는 제사"},{"l":"세시","r":"해마다 같은 시기에 반복되는 날"}],"mis":"SO3-2-u2-X03","explanation":["즐기는 날은 명절이에요.","24개로 나눈 날은 절기예요.","제사는 차례, 반복되는 날은 세시예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L01_basic#6','soc',3,2,'u2','L01','tb_g3_2_soc_u2_L01_basic','lesson_basic','SO3-2-u2-C1',2,'mc','auto','친구들이 쓴 풍습 가운데 세시 풍속에 해당하는 것은 무엇인가요?',ARRAY['SO3-2-u2-X01']::text[],false,'{"seq":6,"concept":"SO3-2-u2-C1","difficulty":2,"kind":"mc","stem":"친구들이 쓴 풍습 가운데 세시 풍속에 해당하는 것은 무엇인가요?","options":[{"t":"복날에 삼계탕을 먹어요","correct":true},{"t":"태어난 지 100일에 백일잔치를 해요","mis":"SO3-2-u2-X01"},{"t":"이사할 때 이웃들에게 떡을 돌려요","mis":"SO3-2-u2-X01"},{"t":"생일날 미역국을 먹어요","mis":"SO3-2-u2-X01"}],"explanation":["모두에게 같은 때인지 봐요.","복날은 해마다 같은 때에 와요.","복날 삼계탕이에요."],"asset":{"type":"passage","lines":["태어난 지 100일이 되는 날 — 백일잔치를 하고 백일 떡을 나누어 먹어요.","이사할 때 — 이웃들에게 떡을 돌려요.","복날 — 삼계탕을 먹으며 영양을 보충해요.","생일날 — 미역국을 먹어요."],"title":"친구와 활동 — 알고 있거나 경험해 본 풍습"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L01_basic#7','soc',3,2,'u2','L01','tb_g3_2_soc_u2_L01_basic','lesson_basic','SO3-2-u2-C1',2,'blank','auto','『사회』 68쪽: 「명절이나 절기마다 하는 일, 먹는 음식, 입는 옷, 즐기는 놀이 등 고유의 (    )이 전해집니다.」 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SO3-2-u2-X01','SO3-2-u2-X03']::text[],false,'{"seq":7,"concept":"SO3-2-u2-C1","difficulty":2,"kind":"blank","stem":"『사회』 68쪽: 「명절이나 절기마다 하는 일, 먹는 음식, 입는 옷, 즐기는 놀이 등 고유의 (    )이 전해집니다.」 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"세시 풍속","correct":true},{"t":"돌잔치","mis":"SO3-2-u2-X01"},{"t":"설빔","mis":"SO3-2-u2-X03"},{"t":"김장","mis":"SO3-2-u2-X01"}],"explanation":["명절과 절기의 일이에요.","해마다 되풀이해요.","세시 풍속이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L01_basic#8','soc',3,2,'u2','L01','tb_g3_2_soc_u2_L01_basic','lesson_basic','SO3-2-u2-C1',2,'mc','auto','67쪽 사진 ④ 김장은 어느 쪽에 들어가나요?',ARRAY['SO3-2-u2-X01','SO3-2-u2-X02']::text[],false,'{"seq":8,"concept":"SO3-2-u2-C1","difficulty":2,"kind":"mc","stem":"67쪽 사진 ④ 김장은 어느 쪽에 들어가나요?","options":[{"t":"일상생활 속 풍습","correct":true},{"t":"세시 풍속","mis":"SO3-2-u2-X01"},{"t":"풍습이 아니에요","mis":"SO3-2-u2-X02"}],"explanation":["겨울이 되기 전에 해요.","명절이나 절기의 일은 아니에요.","일상생활 속 풍습이에요."],"asset":{"type":"passage","lines":["사진 ① 생일날 미역국을 먹어요.","사진 ② 첫 번째 생일에 돌잔치를 해요.","사진 ③ 남자와 여자가 전통 결혼식을 해요.","사진 ④ 겨울이 되기 전에 사람들이 모여 김장을 해요."],"numbered":false,"title":"『사회』 67쪽 사진 네 장"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L01_basic#9','soc',3,2,'u2','L01','tb_g3_2_soc_u2_L01_basic','lesson_basic','SO3-2-u2-C1',2,'ox','auto','세시 풍속이 아닌 풍습은 오늘날 모두 사라졌어요.',ARRAY['SO3-2-u2-X02']::text[],false,'{"seq":9,"concept":"SO3-2-u2-C1","difficulty":2,"kind":"ox","stem":"세시 풍속이 아닌 풍습은 오늘날 모두 사라졌어요.","answer":"X","reason_options":[{"t":"생일날 미역국, 돌잔치, 김장처럼 오늘날에도 이어지는 일상생활 속 풍습이 많기 때문에","correct":true},{"t":"해마다 같은 때에 하지 않는 풍습은 이어질 수 없기 때문에","mis":"SO3-2-u2-X02"}],"mis":"SO3-2-u2-X02","explanation":["우리 집을 떠올려요.","미역국을 먹어요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L01_basic#10','soc',3,2,'u2','L01','tb_g3_2_soc_u2_L01_basic','lesson_basic','SO3-2-u2-C1',3,'error','auto','설날 동시를 읽고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO3-2-u2-X01']::text[],false,'{"seq":10,"concept":"SO3-2-u2-C1","difficulty":3,"kind":"error","stem":"설날 동시를 읽고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「세배와 떡국은 설날에만 하는 일이라 풍습이 아니야.」","correct":true,"mis_target":"SO3-2-u2-X01"},{"t":"친구 가 — 「설빔을 입고 세배하는 것은 세시 풍속이야.」","mis":"SO3-2-u2-X01"},{"t":"친구 나 — 「돌잔치는 세시 풍속은 아니지만 풍습이야.」","mis":"SO3-2-u2-X01"}],"explanation":["세시 풍속도 풍습이에요.","세배와 떡국도 풍습이에요.","친구 다가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L01_challenge#1','soc',3,2,'u2','L01','tb_g3_2_soc_u2_L01_challenge','lesson_challenge','SO3-2-u2-C1',2,'sa','auto','『사회』 68쪽에서 「해마다 같은 시기에 반복되는 날」을 가리키는 말을 두 글자로 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"SO3-2-u2-C1","difficulty":2,"kind":"sa","stem":"『사회』 68쪽에서 「해마다 같은 시기에 반복되는 날」을 가리키는 말을 두 글자로 쓰세요.","answer":["세시"],"explanation":["해마다 반복돼요.","세◯예요.","세시예요."],"mis":"SO3-2-u2-X01"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L01_challenge#2','soc',3,2,'u2','L01','tb_g3_2_soc_u2_L01_challenge','lesson_challenge','SO3-2-u2-C1',2,'mc','auto','동시 「설날 아침」에 그려진 설날 모습이 아닌 것은 무엇인가요?',ARRAY['SO3-2-u2-X03']::text[],false,'{"seq":2,"concept":"SO3-2-u2-C1","difficulty":2,"kind":"mc","stem":"동시 「설날 아침」에 그려진 설날 모습이 아닌 것은 무엇인가요?","options":[{"t":"돌잡이를 해요","correct":true},{"t":"까치 우는 아침에 고운 옷을 입어요","mis":"SO3-2-u2-X03"},{"t":"어른들께 세배해요","mis":"SO3-2-u2-X03"},{"t":"떡국 한 그릇을 먹어요","mis":"SO3-2-u2-X03"}],"explanation":["동시의 줄을 다시 봐요.","돌잡이는 첫돌의 일이에요.","돌잡이예요."],"asset":{"type":"passage","lines":["까치 우는 설날 아침","오색 고운 (    ) 입고","어른들께 (    ) 해요","꿀꺽, (    ) 한 그릇"],"title":"동시 「설날 아침」 앞부분(김나은) — 빈칸 셋"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L01_challenge#3','soc',3,2,'u2','L01','tb_g3_2_soc_u2_L01_challenge','lesson_challenge','SO3-2-u2-C1',3,'mc','auto','사진 일곱 장 가운데 세시 풍속을 나타낸 사진은 모두 몇 장인가요?',ARRAY['SO3-2-u2-X01','SO3-2-u2-X02']::text[],false,'{"seq":3,"concept":"SO3-2-u2-C1","difficulty":3,"kind":"mc","stem":"사진 일곱 장 가운데 세시 풍속을 나타낸 사진은 모두 몇 장인가요?","options":[{"t":"3장","correct":true},{"t":"4장","mis":"SO3-2-u2-X01"},{"t":"7장","mis":"SO3-2-u2-X01"},{"t":"0장","mis":"SO3-2-u2-X02"}],"explanation":["명절이나 절기의 일을 찾아요.","차례, 송편, 연날리기예요.","3장이에요."],"asset":{"type":"passage","lines":["사진 ① 생일날 미역국을 먹어요.","사진 ② 첫 번째 생일에 돌잔치를 해요.","사진 ③ 전통 결혼식을 해요.","사진 ④ 겨울이 되기 전에 김장을 해요.","사진 ⑤ 명절날 아침에 차례를 지내요.","사진 ⑥ 추석에 세시 음식인 송편을 먹어요.","사진 ⑦ 옛날부터 전해 오는 연날리기를 즐겨요."],"numbered":false,"title":"『사회』 67~68쪽 사진 일곱 장"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L01_challenge#4','soc',3,2,'u2','L01','tb_g3_2_soc_u2_L01_challenge','lesson_challenge','SO3-2-u2-C1',3,'ox','auto','생일날 미역국을 먹는 것은 해마다 생일에 되풀이하니 세시 풍속이에요.',ARRAY['SO3-2-u2-X01']::text[],false,'{"seq":4,"concept":"SO3-2-u2-C1","difficulty":3,"kind":"ox","stem":"생일날 미역국을 먹는 것은 해마다 생일에 되풀이하니 세시 풍속이에요.","answer":"X","reason_options":[{"t":"세시 풍속은 명절이나 절기처럼 해마다 같은 때에 되풀이하는 것이고, 생일 미역국은 일상생활 속 풍습이기 때문에","correct":true},{"t":"해마다 되풀이하는 일은 모두 세시 풍속이기 때문에","mis":"SO3-2-u2-X01"}],"mis":"SO3-2-u2-X01","explanation":["67쪽 사진 ①이에요.","일상생활 속 풍습이에요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L01_challenge#5','soc',3,2,'u2','L01','tb_g3_2_soc_u2_L01_challenge','lesson_challenge','SO3-2-u2-C1',3,'match','auto','친구와 활동 표를 보고 「언제」와 「풍습」을 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"SO3-2-u2-C1","difficulty":3,"kind":"match","stem":"친구와 활동 표를 보고 「언제」와 「풍습」을 알맞게 이으세요.","pairs":[{"l":"태어난 지 100일","r":"백일잔치를 하고 백일 떡을 나누어 먹어요"},{"l":"이사할 때","r":"이웃들에게 떡을 돌려요"},{"l":"복날","r":"삼계탕을 먹으며 영양을 보충해요"},{"l":"명절날 아침","r":"조상들에게 차례를 지내요"}],"mis":"SO3-2-u2-X03","explanation":["100일은 백일잔치예요.","이사는 떡 돌리기, 복날은 삼계탕이에요.","명절 아침은 차례예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L01_challenge#6','soc',3,2,'u2','L01','tb_g3_2_soc_u2_L01_challenge','lesson_challenge','SO3-2-u2-C1',3,'mc','auto','설날에 친척들이 모여 차례를 지내고 떡국을 먹는 모습을 두고 바르게 말한 것은 무엇인가요?',ARRAY['SO3-2-u2-X01','SO3-2-u2-X02']::text[],false,'{"seq":6,"concept":"SO3-2-u2-C1","difficulty":3,"kind":"mc","stem":"설날에 친척들이 모여 차례를 지내고 떡국을 먹는 모습을 두고 바르게 말한 것은 무엇인가요?","options":[{"t":"풍습이면서 세시 풍속이에요","correct":true},{"t":"풍습이지만 세시 풍속은 아니에요","mis":"SO3-2-u2-X01"},{"t":"세시 풍속이지만 풍습은 아니에요","mis":"SO3-2-u2-X01"},{"t":"오늘날 새로 생긴 일이라 풍습이 아니에요","mis":"SO3-2-u2-X02"}],"explanation":["설날은 해마다 와요.","세시 풍속도 풍습이에요.","둘 다 맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L01_challenge#7','soc',3,2,'u2','L01','tb_g3_2_soc_u2_L01_challenge','lesson_challenge','SO3-2-u2-C1',3,'error','auto','낱말 사전을 만들며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO3-2-u2-X03']::text[],false,'{"seq":7,"concept":"SO3-2-u2-C1","difficulty":3,"kind":"error","stem":"낱말 사전을 만들며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 나 — 「덕담은 설을 맞아 새로 마련해 입는 옷이야.」","correct":true,"mis_target":"SO3-2-u2-X03"},{"t":"친구 가 — 「설빔은 설을 맞이해 새로 마련해 입는 옷이나 신발이야.」","mis":"SO3-2-u2-X03"},{"t":"친구 다 — 「차례는 명절날 아침에 조상들에게 지내는 제사야.」","mis":"SO3-2-u2-X03"}],"explanation":["덕담은 좋은 말이에요.","새 옷은 설빔이에요.","친구 나가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L01_challenge#8','soc',3,2,'u2','L01','tb_g3_2_soc_u2_L01_challenge','lesson_challenge','SO3-2-u2-C1',4,'mc','auto','풍습, 세시 풍속, 명절, 절기의 관계를 가장 바르게 정리한 것은 무엇인가요?',ARRAY['SO3-2-u2-X01','SO3-2-u2-X03']::text[],false,'{"seq":8,"concept":"SO3-2-u2-C1","difficulty":4,"kind":"mc","stem":"풍습, 세시 풍속, 명절, 절기의 관계를 가장 바르게 정리한 것은 무엇인가요?","options":[{"t":"세시 풍속은 풍습 가운데 명절이나 절기처럼 해마다 일정한 때에 되풀이하는 것이에요","correct":true},{"t":"명절과 절기는 풍습과 상관없는 날이에요","mis":"SO3-2-u2-X01"},{"t":"풍습은 모두 명절에만 하는 일이에요","mis":"SO3-2-u2-X01"},{"t":"절기는 달의 움직임에 따라 정한 날이에요","mis":"SO3-2-u2-X03"}],"explanation":["풍습이 가장 넓어요.","그 안에 세시 풍속이 있어요.","명절과 절기에 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L01_challenge#9','soc',3,2,'u2','L01','tb_g3_2_soc_u2_L01_challenge','lesson_challenge','SO3-2-u2-C1',4,'ox','auto','오늘날 우리 생활에서 볼 수 있는 풍습은 옛날 사람들의 생활과 아무 관계가 없어요.',ARRAY['SO3-2-u2-X02']::text[],false,'{"seq":9,"concept":"SO3-2-u2-C1","difficulty":4,"kind":"ox","stem":"오늘날 우리 생활에서 볼 수 있는 풍습은 옛날 사람들의 생활과 아무 관계가 없어요.","answer":"X","reason_options":[{"t":"생일날 미역국, 김장, 차례처럼 옛날부터 되풀이되어 전해 오는 생활 모습이기 때문에","correct":true},{"t":"오늘날 하는 일은 모두 오늘날 새로 생긴 것이기 때문에","mis":"SO3-2-u2-X02"}],"mis":"SO3-2-u2-X02","explanation":["풍습의 뜻을 떠올려요.","옛날부터 전해 와요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L01_challenge#10','soc',3,2,'u2','L01','tb_g3_2_soc_u2_L01_challenge','lesson_challenge','SO3-2-u2-C1',4,'essay','teacher','내가 경험한 풍습을 하나 쓰고, 그것이 일상생활 속 풍습인지 세시 풍속인지 까닭과 함께 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO3-2-u2-C1","difficulty":4,"kind":"essay","stem":"내가 경험한 풍습을 하나 쓰고, 그것이 일상생활 속 풍습인지 세시 풍속인지 까닭과 함께 쓰세요.","answer_guide":{"answer":"예: 추석에 가족과 함께 송편을 빚어 먹었어요. 추석이라는 해마다 일정한 때에 되풀이하는 풍습이라서 세시 풍속이에요.","scoring_points":["경험한 풍습을 썼는가","일상생활 속 풍습과 세시 풍속 가운데 바르게 골랐는가","까닭을 썼는가"]},"explanation":["경험을 떠올려요.","언제 했는지 봐요.","까닭을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L02_basic#1','soc',3,2,'u2','L02','tb_g3_2_soc_u2_L02_basic','lesson_basic','SO3-2-u2-C2',1,'mc','auto','그림 ㉮처럼 한꺼번에 많은 일손이 필요한 농사일을 함께하려고 마을에 만든 공동 조직은 무엇인가요?',ARRAY['SO3-2-u2-X04','SO3-2-u2-X05']::text[],true,'{"seq":1,"concept":"SO3-2-u2-C2","difficulty":1,"kind":"mc","stem":"그림 ㉮처럼 한꺼번에 많은 일손이 필요한 농사일을 함께하려고 마을에 만든 공동 조직은 무엇인가요?","options":[{"t":"두레","correct":true},{"t":"품앗이","mis":"SO3-2-u2-X04"},{"t":"관례","mis":"SO3-2-u2-X05"},{"t":"금줄","mis":"SO3-2-u2-X05"}],"explanation":["모내기, 김매기, 벼 베기예요.","마을의 공동 조직이에요.","두레예요."],"asset":{"type":"passage","lines":["그림 ㉮ 많은 사람이 함께 모내기, 김매기, 벼 베기를 해요.","그림 ㉯ 몇몇 사람이 이웃집의 지붕을 함께 얹어요.","그림 ㉰ 이웃들이 모여 한 집의 김장을 함께 담가요."],"numbered":false,"title":"『사회』 69쪽 — 옛날 사람들이 함께한 일"},"variant_rule":{"alt":[{"stem":"그림 ㉯처럼 한 집에서 하기에 일손이 모자란 일을 서로 돌아가면서 도운 풍습은 무엇인가요?","options":[{"t":"품앗이","correct":true},{"t":"두레","mis":"SO3-2-u2-X04"},{"t":"회갑","mis":"SO3-2-u2-X05"},{"t":"돌잡이","mis":"SO3-2-u2-X05"}],"explanation":["지붕 얹기, 김장이에요.","돌아가며 도와요.","품앗이예요."],"asset":{"type":"passage","lines":["그림 ㉮ 많은 사람이 함께 모내기, 김매기, 벼 베기를 해요.","그림 ㉯ 몇몇 사람이 이웃집의 지붕을 함께 얹어요.","그림 ㉰ 이웃들이 모여 한 집의 김장을 함께 담가요."],"numbered":false,"title":"『사회』 69쪽 — 옛날 사람들이 함께한 일"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L02_basic#2','soc',3,2,'u2','L02','tb_g3_2_soc_u2_L02_basic','lesson_basic','SO3-2-u2-C2',1,'sa','auto','『사회』 69쪽 낱말 풀이에서 「논밭의 잡초를 뽑는 일」을 무엇이라고 하나요? 세 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SO3-2-u2-C2","difficulty":1,"kind":"sa","stem":"『사회』 69쪽 낱말 풀이에서 「논밭의 잡초를 뽑는 일」을 무엇이라고 하나요? 세 글자로 쓰세요.","answer":["김매기"],"explanation":["잡초를 뽑아요.","김◯◯예요.","김매기예요."],"mis":"SO3-2-u2-X04"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L02_basic#3','soc',3,2,'u2','L02','tb_g3_2_soc_u2_L02_basic','lesson_basic','SO3-2-u2-C2',1,'mc','auto','옛날에 아기가 태어나면 대문에 금줄을 친 날은 며칠 동안이었나요?',ARRAY['SO3-2-u2-X05']::text[],false,'{"seq":3,"concept":"SO3-2-u2-C2","difficulty":1,"kind":"mc","stem":"옛날에 아기가 태어나면 대문에 금줄을 친 날은 며칠 동안이었나요?","options":[{"t":"21일","correct":true},{"t":"100일","mis":"SO3-2-u2-X05"},{"t":"60일","mis":"SO3-2-u2-X05"},{"t":"1년","mis":"SO3-2-u2-X05"}],"explanation":["출생 풍습이에요.","나쁜 기운을 막았어요.","21일이에요."],"asset":{"type":"passage","lines":["출생 — 대문에 21일 동안 금줄을 쳐 나쁜 기운을 막고, 사람들이 드나들지 않게 했어요.","백일 — 아기가 태어난 지 100일이 된 것을 축하하며 잔치를 했어요.","첫돌 — 아프지 않고 오래 살기를 바라는 음식을 먹고, 돌잡이로 앞날을 점쳤어요.","관례 — 결혼하기 전에 하던 성인식으로, 마치면 어른으로 대해 줬어요."],"title":"『사회』 70쪽 — 일생 동안의 풍습 ①"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L02_basic#4','soc',3,2,'u2','L02','tb_g3_2_soc_u2_L02_basic','lesson_basic','SO3-2-u2-C2',1,'mc','auto','『사회』 70쪽 낱말 풀이에서 돌잔치 때 쌀, 붓, 활, 돈, 실 등을 펼쳐 놓고 아이가 골라잡게 하는 일은 무엇인가요?',ARRAY['SO3-2-u2-X05']::text[],true,'{"seq":4,"concept":"SO3-2-u2-C2","difficulty":1,"kind":"mc","stem":"『사회』 70쪽 낱말 풀이에서 돌잔치 때 쌀, 붓, 활, 돈, 실 등을 펼쳐 놓고 아이가 골라잡게 하는 일은 무엇인가요?","options":[{"t":"돌잡이","correct":true},{"t":"관례","mis":"SO3-2-u2-X05"},{"t":"폐백","mis":"SO3-2-u2-X05"},{"t":"금줄 치기","mis":"SO3-2-u2-X05"}],"explanation":["첫돌의 일이에요.","앞날을 점쳐요.","돌잡이예요."],"variant_rule":{"alt":[{"stem":"남자와 여자가 결혼하기 전에 하던 성인식으로, 마치면 어른으로 대해 준 풍습은 무엇인가요?","options":[{"t":"관례","correct":true},{"t":"혼례","mis":"SO3-2-u2-X05"},{"t":"돌잡이","mis":"SO3-2-u2-X05"},{"t":"회갑","mis":"SO3-2-u2-X05"}],"explanation":["결혼하기 전이에요.","성인식이에요.","관례예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L02_basic#5','soc',3,2,'u2','L02','tb_g3_2_soc_u2_L02_basic','lesson_basic','SO3-2-u2-C2',2,'match','auto','일생 동안의 풍습과 그 모습을 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"SO3-2-u2-C2","difficulty":2,"kind":"match","stem":"일생 동안의 풍습과 그 모습을 알맞게 이으세요.","pairs":[{"l":"출생","r":"대문에 금줄을 쳐 나쁜 기운을 막았어요"},{"l":"첫돌","r":"돌잡이로 아이의 앞날을 점쳤어요"},{"l":"회갑","r":"자식들이 생신상을 크게 차리고 잔치를 했어요"},{"l":"장례","r":"남은 가족들을 위로하고 죽은 사람의 복을 빌었어요"}],"mis":"SO3-2-u2-X05","explanation":["태어나면 금줄이에요.","첫돌은 돌잡이, 회갑은 생신상이에요.","장례는 위로예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L02_basic#6','soc',3,2,'u2','L02','tb_g3_2_soc_u2_L02_basic','lesson_basic','SO3-2-u2-C2',2,'mc','auto','두레와 품앗이의 공통점으로 알맞은 것은 무엇인가요?',ARRAY['SO3-2-u2-X04']::text[],false,'{"seq":6,"concept":"SO3-2-u2-C2","difficulty":2,"kind":"mc","stem":"두레와 품앗이의 공통점으로 알맞은 것은 무엇인가요?","options":[{"t":"여럿이 힘을 합해 서로 도우며 정을 나누는 풍습이에요","correct":true},{"t":"혼자서 해야 하는 일을 정해 주는 풍습이에요","mis":"SO3-2-u2-X04"},{"t":"나라에서 시켜서 억지로 하는 일이에요","mis":"SO3-2-u2-X04"},{"t":"명절에만 하는 놀이예요","mis":"SO3-2-u2-X04"}],"explanation":["함께 일했어요.","서로 도왔어요.","정을 나누는 풍습이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L02_basic#7','soc',3,2,'u2','L02','tb_g3_2_soc_u2_L02_basic','lesson_basic','SO3-2-u2-C2',2,'mc','auto','혼례에 대한 설명으로 알맞은 것은 무엇인가요?',ARRAY['SO3-2-u2-X05']::text[],false,'{"seq":7,"concept":"SO3-2-u2-C2","difficulty":2,"kind":"mc","stem":"혼례에 대한 설명으로 알맞은 것은 무엇인가요?","options":[{"t":"성인이 된 남자와 여자가 부부가 되는 예식으로, 주로 집안 어른들이 정한 사람과 결혼했어요","correct":true},{"t":"결혼하기 전에 하던 성인식이에요","mis":"SO3-2-u2-X05"},{"t":"태어난 지 100일을 축하하는 잔치예요","mis":"SO3-2-u2-X05"},{"t":"60년 동안 건강하게 사신 것을 축하해요","mis":"SO3-2-u2-X05"}],"explanation":["부부가 되는 예식이에요.","집안 어른들이 정했어요.","혼례예요."],"asset":{"type":"passage","lines":["혼례 — 성인이 된 남자와 여자가 부부가 되는 예식으로, 주로 집안 어른들이 정한 사람과 결혼했어요.","회갑 — 부모님이 60년 동안 건강하게 사신 것을 축하하려고 자식들이 생신상을 크게 차리고 잔치를 했어요.","장례 — 남은 가족들을 위로하고 힘을 북돋워 주며 죽은 사람의 복을 빌어 줬어요."],"title":"『사회』 71쪽 — 일생 동안의 풍습 ②"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L02_basic#8','soc',3,2,'u2','L02','tb_g3_2_soc_u2_L02_basic','lesson_basic','SO3-2-u2-C2',2,'ox','auto','회갑은 환갑이라고도 부르며, 부모님이 건강하게 오래 사시기를 비는 마음이 담겨 있어요.',ARRAY['SO3-2-u2-X05']::text[],false,'{"seq":8,"concept":"SO3-2-u2-C2","difficulty":2,"kind":"ox","stem":"회갑은 환갑이라고도 부르며, 부모님이 건강하게 오래 사시기를 비는 마음이 담겨 있어요.","answer":"O","reason_options":[{"t":"회갑잔치에서 자식들이 생신상을 차리며 부모님의 건강을 빌었기 때문에","correct":true},{"t":"회갑은 아기의 앞날을 점치는 날이기 때문에","mis":"SO3-2-u2-X05"}],"mis":"SO3-2-u2-X05","explanation":["60년을 축하해요.","오래 사시기를 빌어요.","그래서 O예요."],"asset":{"type":"passage","lines":["혼례 — 성인이 된 남자와 여자가 부부가 되는 예식으로, 주로 집안 어른들이 정한 사람과 결혼했어요.","회갑 — 부모님이 60년 동안 건강하게 사신 것을 축하하려고 자식들이 생신상을 크게 차리고 잔치를 했어요.","장례 — 남은 가족들을 위로하고 힘을 북돋워 주며 죽은 사람의 복을 빌어 줬어요."],"title":"『사회』 71쪽 — 일생 동안의 풍습 ②"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L02_basic#9','soc',3,2,'u2','L02','tb_g3_2_soc_u2_L02_basic','lesson_basic','SO3-2-u2-C2',2,'blank','auto','『사회』 69쪽: 「오늘날에는 아이를 같이 돌보는 (    ) 품앗이, 반찬을 같이 나누는 반찬 품앗이 등의 모습으로 품앗이 풍습이 변화하고 있어요.」 빈칸에 알맞은 말은?',ARRAY['SO3-2-u2-X04']::text[],false,'{"seq":9,"concept":"SO3-2-u2-C2","difficulty":2,"kind":"blank","stem":"『사회』 69쪽: 「오늘날에는 아이를 같이 돌보는 (    ) 품앗이, 반찬을 같이 나누는 반찬 품앗이 등의 모습으로 품앗이 풍습이 변화하고 있어요.」 빈칸에 알맞은 말은?","options":[{"t":"육아","correct":true},{"t":"김장","mis":"SO3-2-u2-X04"},{"t":"농사","mis":"SO3-2-u2-X04"},{"t":"두레","mis":"SO3-2-u2-X04"}],"explanation":["아이를 돌봐요.","오늘날의 품앗이예요.","육아예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L02_basic#10','soc',3,2,'u2','L02','tb_g3_2_soc_u2_L02_basic','lesson_basic','SO3-2-u2-C2',3,'error','auto','옛날 사람들이 농사일이나 집안일을 함께한 까닭을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO3-2-u2-X06','SO3-2-u2-X04']::text[],false,'{"seq":10,"concept":"SO3-2-u2-C2","difficulty":3,"kind":"error","stem":"옛날 사람들이 농사일이나 집안일을 함께한 까닭을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「서로 모르는 사람이라서 일을 나누어 맡긴 거야.」","correct":true,"mis_target":"SO3-2-u2-X06"},{"t":"친구 가 — 「도움이 필요할 때 힘을 합해 도와주는 정이 있었기 때문이야.」","mis":"SO3-2-u2-X04"},{"t":"친구 나 — 「혼자서는 하기 어려운 일을 함께하면 서로 힘이 되었어.」","mis":"SO3-2-u2-X04"}],"explanation":["핵심 질문을 떠올려요.","도와주는 정이 있었어요.","친구 다가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L02_challenge#1','soc',3,2,'u2','L02','tb_g3_2_soc_u2_L02_challenge','lesson_challenge','SO3-2-u2-C2',2,'sa','auto','옛날 사람들이 살아가며 출생, 혼례, 장례 같은 중요한 일이 있을 때 서로 축하하거나 위로하며 나눈 것은 무엇인가요? 한 글자로 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"SO3-2-u2-C2","difficulty":2,"kind":"sa","stem":"옛날 사람들이 살아가며 출생, 혼례, 장례 같은 중요한 일이 있을 때 서로 축하하거나 위로하며 나눈 것은 무엇인가요? 한 글자로 쓰세요.","answer":["마음"],"explanation":["꼭 기억해요 2예요.","축하하고 위로했어요.","마음을 나눴어요."],"mis":"SO3-2-u2-X06"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L02_challenge#2','soc',3,2,'u2','L02','tb_g3_2_soc_u2_L02_challenge','lesson_challenge','SO3-2-u2-C2',2,'mc','auto','그림 ㉰처럼 이웃들이 모여 한 집의 김장을 함께 담그는 일은 두레와 품앗이 가운데 무엇인가요?',ARRAY['SO3-2-u2-X04']::text[],false,'{"seq":2,"concept":"SO3-2-u2-C2","difficulty":2,"kind":"mc","stem":"그림 ㉰처럼 이웃들이 모여 한 집의 김장을 함께 담그는 일은 두레와 품앗이 가운데 무엇인가요?","options":[{"t":"품앗이","correct":true},{"t":"두레","mis":"SO3-2-u2-X04"},{"t":"둘 다 아니에요","mis":"SO3-2-u2-X04"}],"explanation":["한 집의 일이에요.","일손이 모자란 일을 돌아가며 도와요.","품앗이예요."],"asset":{"type":"passage","lines":["그림 ㉮ 많은 사람이 함께 모내기, 김매기, 벼 베기를 해요.","그림 ㉯ 몇몇 사람이 이웃집의 지붕을 함께 얹어요.","그림 ㉰ 이웃들이 모여 한 집의 김장을 함께 담가요."],"numbered":false,"title":"『사회』 69쪽 — 옛날 사람들이 함께한 일"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L02_challenge#3','soc',3,2,'u2','L02','tb_g3_2_soc_u2_L02_challenge','lesson_challenge','SO3-2-u2-C2',3,'mc','auto','일생 동안의 풍습을 일어나는 차례대로 바르게 늘어놓은 것은 무엇인가요?',ARRAY['SO3-2-u2-X05']::text[],false,'{"seq":3,"concept":"SO3-2-u2-C2","difficulty":3,"kind":"mc","stem":"일생 동안의 풍습을 일어나는 차례대로 바르게 늘어놓은 것은 무엇인가요?","options":[{"t":"출생 → 백일 → 첫돌 → 관례 → 혼례 → 회갑 → 장례","correct":true},{"t":"출생 → 관례 → 백일 → 첫돌 → 혼례 → 장례 → 회갑","mis":"SO3-2-u2-X05"},{"t":"백일 → 출생 → 첫돌 → 혼례 → 관례 → 회갑 → 장례","mis":"SO3-2-u2-X05"},{"t":"출생 → 첫돌 → 백일 → 혼례 → 관례 → 장례 → 회갑","mis":"SO3-2-u2-X05"}],"explanation":["태어나서 100일, 1년이에요.","관례 뒤에 혼례예요.","회갑 다음 장례예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L02_challenge#4','soc',3,2,'u2','L02','tb_g3_2_soc_u2_L02_challenge','lesson_challenge','SO3-2-u2-C2',3,'mc','auto','첫돌 풍습에 담긴 옛날 사람들의 마음으로 알맞은 것은 무엇인가요?',ARRAY['SO3-2-u2-X05','SO3-2-u2-X04']::text[],false,'{"seq":4,"concept":"SO3-2-u2-C2","difficulty":3,"kind":"mc","stem":"첫돌 풍습에 담긴 옛날 사람들의 마음으로 알맞은 것은 무엇인가요?","options":[{"t":"아기가 아프지 않고 오래 살기를 바라는 마음","correct":true},{"t":"어른이 된 것을 알리는 마음","mis":"SO3-2-u2-X05"},{"t":"죽은 사람의 복을 비는 마음","mis":"SO3-2-u2-X05"},{"t":"일손이 모자란 집을 돕는 마음","mis":"SO3-2-u2-X04"}],"explanation":["첫 번째 생일이에요.","음식에 바람이 담겼어요.","건강하게 오래 살기예요."],"asset":{"type":"passage","lines":["출생 — 대문에 21일 동안 금줄을 쳐 나쁜 기운을 막고, 사람들이 드나들지 않게 했어요.","백일 — 아기가 태어난 지 100일이 된 것을 축하하며 잔치를 했어요.","첫돌 — 아프지 않고 오래 살기를 바라는 음식을 먹고, 돌잡이로 앞날을 점쳤어요.","관례 — 결혼하기 전에 하던 성인식으로, 마치면 어른으로 대해 줬어요."],"title":"『사회』 70쪽 — 일생 동안의 풍습 ①"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L02_challenge#5','soc',3,2,'u2','L02','tb_g3_2_soc_u2_L02_challenge','lesson_challenge','SO3-2-u2-C2',3,'ox','auto','옛날에 아기가 태어난 뒤 21일 동안 사람들이 드나들지 않게 한 것은 이웃을 미워해서였어요.',ARRAY['SO3-2-u2-X06']::text[],false,'{"seq":5,"concept":"SO3-2-u2-C2","difficulty":3,"kind":"ox","stem":"옛날에 아기가 태어난 뒤 21일 동안 사람들이 드나들지 않게 한 것은 이웃을 미워해서였어요.","answer":"X","reason_options":[{"t":"산모와 아기의 건강을 바라며 나쁜 기운을 막으려 했기 때문에","correct":true},{"t":"옛날 사람들은 아기가 태어나면 이웃과 어울리지 않았기 때문에","mis":"SO3-2-u2-X06"}],"mis":"SO3-2-u2-X06","explanation":["금줄을 친 까닭이에요.","산모와 아기를 지켰어요.","그래서 X예요."],"asset":{"type":"passage","lines":["출생 — 대문에 21일 동안 금줄을 쳐 나쁜 기운을 막고, 사람들이 드나들지 않게 했어요.","백일 — 아기가 태어난 지 100일이 된 것을 축하하며 잔치를 했어요.","첫돌 — 아프지 않고 오래 살기를 바라는 음식을 먹고, 돌잡이로 앞날을 점쳤어요.","관례 — 결혼하기 전에 하던 성인식으로, 마치면 어른으로 대해 줬어요."],"title":"『사회』 70쪽 — 일생 동안의 풍습 ①"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L02_challenge#6','soc',3,2,'u2','L02','tb_g3_2_soc_u2_L02_challenge','lesson_challenge','SO3-2-u2-C2',3,'match','auto','옛날 풍습과 그 속에 담긴 생각을 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"SO3-2-u2-C2","difficulty":3,"kind":"match","stem":"옛날 풍습과 그 속에 담긴 생각을 알맞게 이으세요.","pairs":[{"l":"금줄 치기","r":"생명을 귀하게 여겨 나쁜 기운을 막았어요"},{"l":"회갑잔치","r":"부모님이 건강하게 오래 사시기를 빌었어요"},{"l":"장례","r":"슬픈 일에 남은 가족을 위로했어요"},{"l":"관례","r":"어른으로 인정받는 성인식을 치렀어요"}],"mis":"SO3-2-u2-X06","explanation":["기쁜 날은 축하해요.","슬픈 날은 위로해요.","모두 마음을 나눴어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L02_challenge#7','soc',3,2,'u2','L02','tb_g3_2_soc_u2_L02_challenge','lesson_challenge','SO3-2-u2-C2',3,'error','auto','친구와 활동에서 옛날 풍습에 담긴 생각을 썼어요. 잘못 쓴 친구는 누구인가요?',ARRAY['SO3-2-u2-X05','SO3-2-u2-X06']::text[],false,'{"seq":7,"concept":"SO3-2-u2-C2","difficulty":3,"kind":"error","stem":"친구와 활동에서 옛날 풍습에 담긴 생각을 썼어요. 잘못 쓴 친구는 누구인가요?","options":[{"t":"친구 나 — 「장례에서는 기쁜 마음으로 잔치를 열어 축하했어.」","correct":true,"mis_target":"SO3-2-u2-X05"},{"t":"친구 가 — 「백일, 돌, 회갑 같은 기쁜 날에는 잔치를 열어 축하했어.」","mis":"SO3-2-u2-X06"},{"t":"친구 다 — 「어른으로 인정을 받으려면 관례를 치러야 했어.」","mis":"SO3-2-u2-X05"}],"explanation":["장례는 슬픈 일이에요.","위로하고 복을 빌어요.","친구 나가 잘못 썼어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L02_challenge#8','soc',3,2,'u2','L02','tb_g3_2_soc_u2_L02_challenge','lesson_challenge','SO3-2-u2-C2',4,'mc','auto','두레와 품앗이를 바르게 견준 것은 무엇인가요?',ARRAY['SO3-2-u2-X04','SO3-2-u2-X06']::text[],false,'{"seq":8,"concept":"SO3-2-u2-C2","difficulty":4,"kind":"mc","stem":"두레와 품앗이를 바르게 견준 것은 무엇인가요?","options":[{"t":"두레는 마을의 공동 조직이 함께한 농사일이고, 품앗이는 집집이 서로 돌아가며 도운 일이에요","correct":true},{"t":"두레는 집집이 돌아가며 돕고, 품앗이는 마을의 공동 조직이에요","mis":"SO3-2-u2-X04"},{"t":"두레와 품앗이는 모두 명절에만 하는 놀이예요","mis":"SO3-2-u2-X04"},{"t":"두레는 기쁜 일, 품앗이는 슬픈 일에만 해요","mis":"SO3-2-u2-X06"}],"explanation":["두레는 마을 조직이에요.","품앗이는 돌아가며 도와요.","둘을 견줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L02_challenge#9','soc',3,2,'u2','L02','tb_g3_2_soc_u2_L02_challenge','lesson_challenge','SO3-2-u2-C2',4,'ox','auto','옛날의 일상생활 속 풍습을 보면 기쁨과 슬픔을 나누며 서로 돕고 사는 조상들의 마음을 알 수 있어요.',ARRAY['SO3-2-u2-X06']::text[],false,'{"seq":9,"concept":"SO3-2-u2-C2","difficulty":4,"kind":"ox","stem":"옛날의 일상생활 속 풍습을 보면 기쁨과 슬픔을 나누며 서로 돕고 사는 조상들의 마음을 알 수 있어요.","answer":"O","reason_options":[{"t":"잔치로 축하하고 장례로 위로하며, 두레와 품앗이로 서로 도왔기 때문에","correct":true},{"t":"옛날 풍습은 각자 자기 집안일만 하던 모습이기 때문에","mis":"SO3-2-u2-X06"}],"mis":"SO3-2-u2-X06","explanation":["축하하고 위로했어요.","서로 도왔어요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L02_challenge#10','soc',3,2,'u2','L02','tb_g3_2_soc_u2_L02_challenge','lesson_challenge','SO3-2-u2-C2',4,'essay','teacher','옛날 풍습 가운데 하나를 골라 그 풍습 속에 담긴 옛날 사람들의 생활 모습과 생각을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO3-2-u2-C2","difficulty":4,"kind":"essay","stem":"옛날 풍습 가운데 하나를 골라 그 풍습 속에 담긴 옛날 사람들의 생활 모습과 생각을 쓰세요.","answer_guide":{"answer":"예: 금줄 치기 — 아기가 태어나면 생명을 귀하게 여겨 대문에 21일 동안 금줄을 쳐서 나쁜 기운을 막았어요. 산모와 아기가 건강하기를 바라는 마음이 담겨 있어요.","scoring_points":["풍습 하나를 골랐는가","그 풍습의 모습을 썼는가","담긴 생각이나 마음을 썼는가"]},"explanation":["풍습을 골라요.","모습을 써요.","마음을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L03_basic#1','soc',3,2,'u2','L03','tb_g3_2_soc_u2_L03_basic','lesson_basic','SO3-2-u2-C3',1,'mc','auto','옛날 결혼하는 날 신랑이 신부 집에 가지고 간 물건은 무엇인가요?',ARRAY['SO3-2-u2-X07']::text[],true,'{"seq":1,"concept":"SO3-2-u2-C3","difficulty":1,"kind":"mc","stem":"옛날 결혼하는 날 신랑이 신부 집에 가지고 간 물건은 무엇인가요?","options":[{"t":"나무로 만든 기러기","correct":true},{"t":"반지","mis":"SO3-2-u2-X07"},{"t":"꽃다발","mis":"SO3-2-u2-X07"},{"t":"복주머니","mis":"SO3-2-u2-X07"}],"explanation":["그림 ①을 봐요.","한번 짝을 맺으면 평생 함께해요.","나무 기러기예요."],"asset":{"type":"passage","lines":["① 결혼하는 날 신랑은 나무 기러기를 가지고 말을 타고 신부 집으로 갔어요.","② 나무 기러기를 신부 측에 건네고, 혼례복을 입고 혼례를 치렀어요.","③ 신부 집에서 며칠을 보낸 뒤에 신랑은 말을, 신부는 가마를 타고 신랑 집으로 갔어요.","④ 신부가 신랑 집안에 새로 들어왔다는 뜻으로 어른들께 폐백을 드렸어요."],"numbered":false,"title":"『사회』 72~73쪽 — 옛날 결혼 풍습 그림 차례"},"variant_rule":{"alt":[{"stem":"오늘날 결혼식에서 신랑과 신부가 평생 함께할 것을 약속하며 주고받는 것은 무엇인가요?","options":[{"t":"반지","correct":true},{"t":"나무 기러기","mis":"SO3-2-u2-X07"},{"t":"대추와 밤","mis":"SO3-2-u2-X07"},{"t":"부채","mis":"SO3-2-u2-X07"}],"explanation":["그림 ②를 봐요.","평생 함께할 약속이에요.","반지예요."],"asset":{"type":"passage","lines":["① 결혼식장에서 턱시도와 웨딩드레스를 입고 결혼식을 해요.","② 평생 함께할 것을 약속하며 반지를 주고받아요.","③ 사람들과 축하와 감사의 인사를 나누고 기념사진을 찍어요.","④ 전통 혼례복을 입고 양쪽 집안 어른들께 폐백을 드리기도 해요.","⑤ 결혼식이 끝나면 신랑 신부는 신혼여행을 떠나요."],"numbered":false,"title":"『사회』 72~73쪽 — 오늘날 결혼 풍습 그림 차례"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L03_basic#2','soc',3,2,'u2','L03','tb_g3_2_soc_u2_L03_basic','lesson_basic','SO3-2-u2-C3',1,'sa','auto','신부가 처음으로 신랑 부모나 신랑 쪽 어른들을 뵐 때 큰절을 올리는 것을 무엇이라고 하나요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SO3-2-u2-C3","difficulty":1,"kind":"sa","stem":"신부가 처음으로 신랑 부모나 신랑 쪽 어른들을 뵐 때 큰절을 올리는 것을 무엇이라고 하나요? 두 글자로 쓰세요.","answer":["폐백"],"explanation":["『사회』 73쪽 낱말이에요.","폐◯이에요.","폐백이에요."],"mis":"SO3-2-u2-X07"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L03_basic#3','soc',3,2,'u2','L03','tb_g3_2_soc_u2_L03_basic','lesson_basic','SO3-2-u2-C3',1,'mc','auto','옛날 신부 집에서 며칠을 보낸 뒤 신랑 집으로 갈 때 신부가 타고 간 것은 무엇인가요?',ARRAY['SO3-2-u2-X07']::text[],false,'{"seq":3,"concept":"SO3-2-u2-C3","difficulty":1,"kind":"mc","stem":"옛날 신부 집에서 며칠을 보낸 뒤 신랑 집으로 갈 때 신부가 타고 간 것은 무엇인가요?","options":[{"t":"가마","correct":true},{"t":"말","mis":"SO3-2-u2-X07"},{"t":"자동차","mis":"SO3-2-u2-X07"},{"t":"나룻배","mis":"SO3-2-u2-X07"}],"explanation":["그림 ③을 봐요.","신랑은 말을 탔어요.","신부는 가마예요."],"asset":{"type":"passage","lines":["① 결혼하는 날 신랑은 나무 기러기를 가지고 말을 타고 신부 집으로 갔어요.","② 나무 기러기를 신부 측에 건네고, 혼례복을 입고 혼례를 치렀어요.","③ 신부 집에서 며칠을 보낸 뒤에 신랑은 말을, 신부는 가마를 타고 신랑 집으로 갔어요.","④ 신부가 신랑 집안에 새로 들어왔다는 뜻으로 어른들께 폐백을 드렸어요."],"numbered":false,"title":"『사회』 72~73쪽 — 옛날 결혼 풍습 그림 차례"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L03_basic#4','soc',3,2,'u2','L03','tb_g3_2_soc_u2_L03_basic','lesson_basic','SO3-2-u2-C3',1,'ox','auto','오늘날 신랑은 턱시도를, 신부는 웨딩드레스를 입고 결혼식을 해요.',ARRAY['SO3-2-u2-X07']::text[],false,'{"seq":4,"concept":"SO3-2-u2-C3","difficulty":1,"kind":"ox","stem":"오늘날 신랑은 턱시도를, 신부는 웨딩드레스를 입고 결혼식을 해요.","answer":"O","reason_options":[{"t":"『사회』 72쪽 오늘날 결혼 풍습 그림 ①의 모습이기 때문에","correct":true},{"t":"오늘날에도 모두 혼례복을 입고 신부 집에서 결혼하기 때문에","mis":"SO3-2-u2-X07"}],"mis":"SO3-2-u2-X07","explanation":["오늘날 그림이에요.","턱시도와 웨딩드레스예요.","그래서 O예요."],"asset":{"type":"passage","lines":["① 결혼식장에서 턱시도와 웨딩드레스를 입고 결혼식을 해요.","② 평생 함께할 것을 약속하며 반지를 주고받아요.","③ 사람들과 축하와 감사의 인사를 나누고 기념사진을 찍어요.","④ 전통 혼례복을 입고 양쪽 집안 어른들께 폐백을 드리기도 해요.","⑤ 결혼식이 끝나면 신랑 신부는 신혼여행을 떠나요."],"numbered":false,"title":"『사회』 72~73쪽 — 오늘날 결혼 풍습 그림 차례"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L03_basic#5','soc',3,2,'u2','L03','tb_g3_2_soc_u2_L03_basic','lesson_basic','SO3-2-u2-C3',2,'blank','auto','비교표의 「폐백 받는 사람 — 오늘날」 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SO3-2-u2-X45','SO3-2-u2-X07']::text[],false,'{"seq":5,"concept":"SO3-2-u2-C3","difficulty":2,"kind":"blank","stem":"비교표의 「폐백 받는 사람 — 오늘날」 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"양쪽 집안의 어른들","correct":true},{"t":"신랑 집안의 어른들만","mis":"SO3-2-u2-X45"},{"t":"폐백을 받는 사람이 없어요","mis":"SO3-2-u2-X45"},{"t":"신부의 친구들","mis":"SO3-2-u2-X07"}],"explanation":["옛날은 신랑 집안이었어요.","오늘날에는 양쪽에 드리기도 해요.","양쪽 집안의 어른들이에요."],"asset":{"type":"passage","lines":["장소 — 옛날: 신부 집 / 오늘날: 결혼식장, 공원 등","입는 옷 — 옛날: 한복(혼례복) / 오늘날: 턱시도, 웨딩드레스","주고받는 물건 — 옛날: 나무로 만든 기러기 / 오늘날: 반지","폐백 받는 사람 — 옛날: 신랑 집안의 어른들 / 오늘날: (    )","비슷한 점 — 가족과 친척들이 신랑 신부를 축복해 줘요."],"numbered":false,"title":"『사회』 73쪽 — 결혼 풍습 비교표(한 칸 비움)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L03_basic#6','soc',3,2,'u2','L03','tb_g3_2_soc_u2_L03_basic','lesson_basic','SO3-2-u2-C3',2,'mc','auto','나무 기러기를 신부 측에 건네준 까닭으로 알맞은 것은 무엇인가요?',ARRAY['SO3-2-u2-X07']::text[],false,'{"seq":6,"concept":"SO3-2-u2-C3","difficulty":2,"kind":"mc","stem":"나무 기러기를 신부 측에 건네준 까닭으로 알맞은 것은 무엇인가요?","options":[{"t":"기러기는 한번 짝을 맺으면 평생 함께한다고 여겨 오래도록 행복하게 함께 살자는 뜻이었어요","correct":true},{"t":"기러기 고기로 잔치 음식을 만들려고요","mis":"SO3-2-u2-X07"},{"t":"신부에게 날마다 소식을 전하려고요","mis":"SO3-2-u2-X07"},{"t":"자식을 많이 낳고 부자가 되라는 뜻이었어요","mis":"SO3-2-u2-X07"}],"explanation":["기러기의 짝이에요.","평생 함께해요.","행복하게 함께 살자는 뜻이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L03_basic#7','soc',3,2,'u2','L03','tb_g3_2_soc_u2_L03_basic','lesson_basic','SO3-2-u2-C3',2,'match','auto','옛날 풍습을 두 묶음으로 나누었어요. 풍습과 묶음을 알맞게 이으세요.','{}'::text[],false,'{"seq":7,"concept":"SO3-2-u2-C3","difficulty":2,"kind":"match","stem":"옛날 풍습을 두 묶음으로 나누었어요. 풍습과 묶음을 알맞게 이으세요.","pairs":[{"l":"백일잔치","r":"변화하면서 이어져 내려오는 풍습"},{"l":"금줄 치기","r":"사라져 가는 풍습"}],"mis":"SO3-2-u2-X09","explanation":["백일잔치는 오늘날에도 해요.","금줄은 거의 볼 수 없어요.","두 묶음이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L03_basic#8','soc',3,2,'u2','L03','tb_g3_2_soc_u2_L03_basic','lesson_basic','SO3-2-u2-C3',2,'mc','auto','신문 기사에 나타난 오늘날 장례 모습으로 알맞은 것은 무엇인가요?',ARRAY['SO3-2-u2-X09','SO3-2-u2-X08']::text[],false,'{"seq":8,"concept":"SO3-2-u2-C3","difficulty":2,"kind":"mc","stem":"신문 기사에 나타난 오늘날 장례 모습으로 알맞은 것은 무엇인가요?","options":[{"t":"수목장이나 해양장과 같은 자연장으로 치르는 경우가 많아지고 있어요","correct":true},{"t":"명절마다 모두 묘지에 가서 성묘해요","mis":"SO3-2-u2-X09"},{"t":"장례를 치르지 않게 되었어요","mis":"SO3-2-u2-X08"},{"t":"옛날과 달라진 점이 하나도 없어요","mis":"SO3-2-u2-X08"}],"explanation":["기사를 다시 읽어요.","매장이 줄었어요.","수목장, 해양장이 늘었어요."],"asset":{"type":"passage","lines":["(간추림) 묘지 대신 수목장, 해양장 같은 장례 문화가 널리 퍼지면서 명절 풍경이 달라지고 있다.","김 씨는 이번 명절에 돌아가신 아버지를 뵈러 수목장을 찾을 예정이다.","이△△ 씨는 해양장을 치른 바다에 가서 어머니를 그리며 생각하는 시간을 가진다.","시신을 땅에 묻는 매장이 줄고, 명절에 묘지 대신 다른 장소를 찾는 사람이 늘고 있다."],"title":"『사회』 75쪽 신문 기사 「달라진 장례 모습, 조상님 뵈러 바다에 가요」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L03_basic#9','soc',3,2,'u2','L03','tb_g3_2_soc_u2_L03_basic','lesson_basic','SO3-2-u2-C3',2,'ox','auto','폐백 풍습은 지역이나 집안에 따라 달라서 모든 결혼식에서 폐백을 드리는 것은 아니에요.',ARRAY['SO3-2-u2-X45']::text[],false,'{"seq":9,"concept":"SO3-2-u2-C3","difficulty":2,"kind":"ox","stem":"폐백 풍습은 지역이나 집안에 따라 달라서 모든 결혼식에서 폐백을 드리는 것은 아니에요.","answer":"O","reason_options":[{"t":"오늘날 결혼식 뒤에 양쪽 집안 어른들께 폐백을 드리기도 하지만 하지 않는 집도 있기 때문에","correct":true},{"t":"오늘날 모든 결혼식은 반드시 폐백으로 끝나기 때문에","mis":"SO3-2-u2-X45"}],"mis":"SO3-2-u2-X45","explanation":["「드리기도 해요」예요.","집안마다 달라요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L03_basic#10','soc',3,2,'u2','L03','tb_g3_2_soc_u2_L03_basic','lesson_basic','SO3-2-u2-C3',3,'error','auto','결혼 풍습 비교표를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO3-2-u2-X08','SO3-2-u2-X07']::text[],false,'{"seq":10,"concept":"SO3-2-u2-C3","difficulty":3,"kind":"error","stem":"결혼 풍습 비교표를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 가 — 「옛날과 오늘날의 결혼 풍습은 다르니까 결혼에 담긴 마음도 완전히 달라졌어.」","correct":true,"mis_target":"SO3-2-u2-X08"},{"t":"친구 나 — 「장소, 입는 옷, 주고받는 물건이 달라졌어.」","mis":"SO3-2-u2-X07"},{"t":"친구 다 — 「부부가 된 것을 알리고 축복해 주는 마음은 변함없어.」","mis":"SO3-2-u2-X08"}],"explanation":["다른 점이 있어요.","변함없는 마음도 있어요.","친구 가가 잘못 말했어요."],"asset":{"type":"passage","lines":["장소 — 옛날: 신부 집 / 오늘날: 결혼식장, 공원 등","입는 옷 — 옛날: 한복(혼례복) / 오늘날: 턱시도, 웨딩드레스","주고받는 물건 — 옛날: 나무로 만든 기러기 / 오늘날: 반지","폐백 받는 사람 — 옛날: 신랑 집안의 어른들 / 오늘날: (    )","비슷한 점 — 가족과 친척들이 신랑 신부를 축복해 줘요."],"numbered":false,"title":"『사회』 73쪽 — 결혼 풍습 비교표(한 칸 비움)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L03_challenge#1','soc',3,2,'u2','L03','tb_g3_2_soc_u2_L03_challenge','lesson_challenge','SO3-2-u2-C3',2,'sa','auto','조상의 산소를 찾아가서 돌보는 일로, 주로 봄과 가을에 하는 것을 무엇이라고 하나요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"SO3-2-u2-C3","difficulty":2,"kind":"sa","stem":"조상의 산소를 찾아가서 돌보는 일로, 주로 봄과 가을에 하는 것을 무엇이라고 하나요? 두 글자로 쓰세요.","answer":["성묘"],"explanation":["75쪽 낱말 풀이예요.","성◯예요.","성묘예요."],"mis":"SO3-2-u2-X09"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L03_challenge#2','soc',3,2,'u2','L03','tb_g3_2_soc_u2_L03_challenge','lesson_challenge','SO3-2-u2-C3',2,'mc','auto','폐백을 할 때 어른들이 대추와 밤 등을 던져 주는 까닭은 무엇인가요?',ARRAY['SO3-2-u2-X07']::text[],false,'{"seq":2,"concept":"SO3-2-u2-C3","difficulty":2,"kind":"mc","stem":"폐백을 할 때 어른들이 대추와 밤 등을 던져 주는 까닭은 무엇인가요?","options":[{"t":"신랑 신부가 자식을 많이 낳고 부자가 되라는 뜻이에요","correct":true},{"t":"평생 함께하자는 약속이에요","mis":"SO3-2-u2-X07"},{"t":"나쁜 기운을 쫓으려는 뜻이에요","mis":"SO3-2-u2-X07"},{"t":"결혼식장을 꾸미려는 뜻이에요","mis":"SO3-2-u2-X07"}],"explanation":["『사회』 73쪽 말풍선이에요.","자식과 부자를 바랐어요.","그 뜻이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L03_challenge#3','soc',3,2,'u2','L03','tb_g3_2_soc_u2_L03_challenge','lesson_challenge','SO3-2-u2-C3',3,'mc','auto','옛날 결혼 풍습 그림 차례에서 혼례를 치른 곳과 폐백을 드린 곳을 바르게 짝지은 것은 무엇인가요?',ARRAY['SO3-2-u2-X07','SO3-2-u2-X45']::text[],false,'{"seq":3,"concept":"SO3-2-u2-C3","difficulty":3,"kind":"mc","stem":"옛날 결혼 풍습 그림 차례에서 혼례를 치른 곳과 폐백을 드린 곳을 바르게 짝지은 것은 무엇인가요?","options":[{"t":"혼례 — 신부 집 / 폐백 — 신랑 집","correct":true},{"t":"혼례 — 신랑 집 / 폐백 — 신부 집","mis":"SO3-2-u2-X07"},{"t":"혼례 — 결혼식장 / 폐백 — 공원","mis":"SO3-2-u2-X07"},{"t":"혼례 — 신부 집 / 폐백 — 결혼식장","mis":"SO3-2-u2-X45"}],"explanation":["신랑이 신부 집으로 갔어요.","며칠 뒤 신랑 집으로 갔어요.","그곳에서 폐백을 드렸어요."],"asset":{"type":"passage","lines":["① 결혼하는 날 신랑은 나무 기러기를 가지고 말을 타고 신부 집으로 갔어요.","② 나무 기러기를 신부 측에 건네고, 혼례복을 입고 혼례를 치렀어요.","③ 신부 집에서 며칠을 보낸 뒤에 신랑은 말을, 신부는 가마를 타고 신랑 집으로 갔어요.","④ 신부가 신랑 집안에 새로 들어왔다는 뜻으로 어른들께 폐백을 드렸어요."],"numbered":false,"title":"『사회』 72~73쪽 — 옛날 결혼 풍습 그림 차례"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L03_challenge#4','soc',3,2,'u2','L03','tb_g3_2_soc_u2_L03_challenge','lesson_challenge','SO3-2-u2-C3',3,'mc','auto','76쪽 조사 표를 보고 옛날과 오늘날 「출생」 풍습의 비슷한 점을 바르게 쓴 것은 무엇인가요?',ARRAY['SO3-2-u2-X09','SO3-2-u2-X08']::text[],false,'{"seq":4,"concept":"SO3-2-u2-C3","difficulty":3,"kind":"mc","stem":"76쪽 조사 표를 보고 옛날과 오늘날 「출생」 풍습의 비슷한 점을 바르게 쓴 것은 무엇인가요?","options":[{"t":"아기가 건강하기를 바라고, 산모가 미역국을 먹어요","correct":true},{"t":"아기가 태어나면 대문에 금줄을 쳐요","mis":"SO3-2-u2-X09"},{"t":"아기는 신생아실에서 예방 주사를 맞아요","mis":"SO3-2-u2-X09"},{"t":"비슷한 점은 하나도 없어요","mis":"SO3-2-u2-X08"}],"explanation":["달라진 점과 비슷한 점을 갈라요.","바라는 마음은 같아요.","미역국도 같아요."],"asset":{"type":"passage","lines":["장소 — 옛날: 집 / 오늘날: 산부인과 병원","하는 일(옛날) — 대문에 금줄을 치고, 삼신할머니에게 아기의 안전과 건강을 빌어요.","하는 일(오늘날) — 신생아실에서 아기를 돌보고, 아기는 예방 주사를 맞아요.","비슷한 점 — 아기가 건강하기를 바라고, 산모는 미역국을 먹어요."],"numbered":false,"title":"『사회』 76쪽 디지털 할 수 있어요 — 인터넷으로 조사한 「출생」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L03_challenge#5','soc',3,2,'u2','L03','tb_g3_2_soc_u2_L03_challenge','lesson_challenge','SO3-2-u2-C3',3,'ox','auto','오늘날 백일잔치를 하는 것은 옛날에 아기가 100일을 넘기기 어려웠던 때부터 이어진 풍습이에요.',ARRAY['SO3-2-u2-X09']::text[],false,'{"seq":5,"concept":"SO3-2-u2-C3","difficulty":3,"kind":"ox","stem":"오늘날 백일잔치를 하는 것은 옛날에 아기가 100일을 넘기기 어려웠던 때부터 이어진 풍습이에요.","answer":"O","reason_options":[{"t":"옛날에는 아기가 100일을 못 넘기고 병으로 죽는 일이 많아 100일이 되면 잔치를 열어 건강을 빌었기 때문에","correct":true},{"t":"백일잔치는 오늘날 새로 생긴 풍습이기 때문에","mis":"SO3-2-u2-X09"}],"mis":"SO3-2-u2-X09","explanation":["74쪽 말풍선이에요.","건강과 복을 빌었어요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L03_challenge#6','soc',3,2,'u2','L03','tb_g3_2_soc_u2_L03_challenge','lesson_challenge','SO3-2-u2-C3',3,'match','auto','옛날과 오늘날의 장례 모습을 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"SO3-2-u2-C3","difficulty":3,"kind":"match","stem":"옛날과 오늘날의 장례 모습을 알맞게 이으세요.","pairs":[{"l":"옛날","r":"시신을 땅에 묻는 매장을 주로 했어요"},{"l":"오늘날","r":"수목장, 해양장 같은 자연장이 늘고 있어요"}],"mis":"SO3-2-u2-X09","explanation":["옛날은 매장이에요.","오늘날은 자연장이 늘어요.","조금씩 변하며 이어져요."],"asset":{"type":"passage","lines":["(간추림) 묘지 대신 수목장, 해양장 같은 장례 문화가 널리 퍼지면서 명절 풍경이 달라지고 있다.","김 씨는 이번 명절에 돌아가신 아버지를 뵈러 수목장을 찾을 예정이다.","이△△ 씨는 해양장을 치른 바다에 가서 어머니를 그리며 생각하는 시간을 가진다.","시신을 땅에 묻는 매장이 줄고, 명절에 묘지 대신 다른 장소를 찾는 사람이 늘고 있다."],"title":"『사회』 75쪽 신문 기사 「달라진 장례 모습, 조상님 뵈러 바다에 가요」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L03_challenge#7','soc',3,2,'u2','L03','tb_g3_2_soc_u2_L03_challenge','lesson_challenge','SO3-2-u2-C3',3,'error','auto','병풍 책 예시(제사)를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO3-2-u2-X08','SO3-2-u2-X09']::text[],false,'{"seq":7,"concept":"SO3-2-u2-C3","difficulty":3,"kind":"error","stem":"병풍 책 예시(제사)를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「제사 시간과 방법이 달라졌으니 조상을 추모하는 마음도 사라졌어.」","correct":true,"mis_target":"SO3-2-u2-X08"},{"t":"친구 가 — 「오늘날에는 가족들이 많이 모이는 시간에 제사를 지내.」","mis":"SO3-2-u2-X09"},{"t":"친구 나 — 「남녀 구분 없이 모든 자손이 절을 하게 됐어.」","mis":"SO3-2-u2-X09"}],"explanation":["달라진 것을 찾아요.","추모하는 마음은 이어져요.","친구 다가 잘못 말했어요."],"asset":{"type":"passage","lines":["옛날 — 밤 12시 무렵에 제사를 지냈고, 남자들만 조상에게 절을 했어요.","옛날 — 할아버지와 할머니의 제사를 각각 지냈어요.","오늘날 — 가족들이 많이 모이는 시간에 지내고, 남녀 구분 없이 절을 해요.","오늘날 — 할머니 제사를 할아버지 제사와 함께 지내 횟수가 줄었어요."],"title":"과정 중심 평가 병풍 책 예시 — 제사"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L03_challenge#8','soc',3,2,'u2','L03','tb_g3_2_soc_u2_L03_challenge','lesson_challenge','SO3-2-u2-C3',4,'mc','auto','장례 풍습이 달라지면서 명절 모습이 어떻게 달라지고 있는지 바르게 쓴 것은 무엇인가요?',ARRAY['SO3-2-u2-X08','SO3-2-u2-X09']::text[],false,'{"seq":8,"concept":"SO3-2-u2-C3","difficulty":4,"kind":"mc","stem":"장례 풍습이 달라지면서 명절 모습이 어떻게 달라지고 있는지 바르게 쓴 것은 무엇인가요?","options":[{"t":"묘지에 가서 성묘하던 사람들이 수목장이나 해양장을 치른 곳을 찾아가 추모해요","correct":true},{"t":"명절에 조상을 생각하는 사람이 없어졌어요","mis":"SO3-2-u2-X08"},{"t":"모든 사람이 바다에서 명절을 보내야 해요","mis":"SO3-2-u2-X08"},{"t":"명절에 성묘하는 사람이 더 늘었어요","mis":"SO3-2-u2-X09"}],"explanation":["정보 활용 물음이에요.","찾아가는 곳이 달라졌어요.","추모하는 마음은 같아요."],"asset":{"type":"passage","lines":["(간추림) 묘지 대신 수목장, 해양장 같은 장례 문화가 널리 퍼지면서 명절 풍경이 달라지고 있다.","김 씨는 이번 명절에 돌아가신 아버지를 뵈러 수목장을 찾을 예정이다.","이△△ 씨는 해양장을 치른 바다에 가서 어머니를 그리며 생각하는 시간을 가진다.","시신을 땅에 묻는 매장이 줄고, 명절에 묘지 대신 다른 장소를 찾는 사람이 늘고 있다."],"title":"『사회』 75쪽 신문 기사 「달라진 장례 모습, 조상님 뵈러 바다에 가요」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L03_challenge#9','soc',3,2,'u2','L03','tb_g3_2_soc_u2_L03_challenge','lesson_challenge','SO3-2-u2-C3',4,'ox','auto','옛날과 오늘날 결혼 풍습을 견주면 결혼에 담긴 마음까지 모두 달라졌다는 것을 알 수 있어요.',ARRAY['SO3-2-u2-X08']::text[],false,'{"seq":9,"concept":"SO3-2-u2-C3","difficulty":4,"kind":"ox","stem":"옛날과 오늘날 결혼 풍습을 견주면 결혼에 담긴 마음까지 모두 달라졌다는 것을 알 수 있어요.","answer":"X","reason_options":[{"t":"부부가 된 것을 알리고 가족과 친척들이 신랑 신부의 미래를 축복해 주는 마음은 변함없기 때문에","correct":true},{"t":"모습이 달라지면 마음도 반드시 달라지기 때문에","mis":"SO3-2-u2-X08"}],"mis":"SO3-2-u2-X08","explanation":["비슷한 점을 봐요.","축복하는 마음은 같아요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L03_challenge#10','soc',3,2,'u2','L03','tb_g3_2_soc_u2_L03_challenge','lesson_challenge','SO3-2-u2-C3',4,'essay','teacher','옛날 풍습 하나를 골라 오늘날과 견주어 다른 점과 비슷한 점을 쓰고, 견주어 알게 된 사실을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO3-2-u2-C3","difficulty":4,"kind":"essay","stem":"옛날 풍습 하나를 골라 오늘날과 견주어 다른 점과 비슷한 점을 쓰고, 견주어 알게 된 사실을 쓰세요.","answer_guide":{"answer":"예: 제사 — 옛날에는 밤 12시 무렵에 남자들만 절을 했지만, 오늘날에는 가족이 많이 모이는 시간에 남녀 구분 없이 절을 해요. 조상을 추모하는 마음은 비슷해요. 모습은 달라져도 조상을 생각하는 마음은 이어진다는 것을 알았어요.","scoring_points":["다른 점을 썼는가","비슷한 점을 썼는가","알게 된 사실을 썼는가"]},"explanation":["풍습을 골라요.","다른 점과 비슷한 점이에요.","알게 된 점을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L04_basic#1','soc',3,2,'u2','L04','tb_g3_2_soc_u2_L04_basic','lesson_basic','SO3-2-u2-C4',1,'mc','auto','새해 처음으로 보름달이 뜨는 정월 대보름은 언제인가요?',ARRAY['SO3-2-u2-X10','SO3-2-u2-X47']::text[],true,'{"seq":1,"concept":"SO3-2-u2-C4","difficulty":1,"kind":"mc","stem":"새해 처음으로 보름달이 뜨는 정월 대보름은 언제인가요?","options":[{"t":"음력 1월 15일","correct":true},{"t":"음력 1월 1일","mis":"SO3-2-u2-X10"},{"t":"음력 5월 5일","mis":"SO3-2-u2-X10"},{"t":"양력 12월 22일 무렵","mis":"SO3-2-u2-X47"}],"explanation":["보름달이에요.","정월은 1월이에요.","음력 1월 15일이에요."],"asset":{"type":"passage","lines":["정월 대보름(음력 1월 15일) — 새해 처음으로 보름달이 뜨는 날","달집(나뭇가지 무더기)에 불을 질러 태우며 풍년을 기원했어요.","논밭에 불을 붙여 쥐불놀이를 하며 나쁜 기운을 쫓아냈어요.","다리에 병이 나지 않고 튼튼해진다고 하여 다리밟기를 했어요.","부럼을 깨물며 이가 튼튼해지고 피부병이 생기지 않기를 빌었어요.","다섯 가지 곡식으로 만든 오곡밥과 나물을 먹었어요."],"title":"『사회』 78쪽 — 정월 대보름의 세시 풍속"},"variant_rule":{"alt":[{"stem":"모내기를 마치고 더운 여름을 맞이하기 전에 잠시 쉬던 단오는 언제인가요?","options":[{"t":"음력 5월 5일","correct":true},{"t":"음력 8월 15일","mis":"SO3-2-u2-X10"},{"t":"음력 1월 15일","mis":"SO3-2-u2-X10"},{"t":"양력 12월 22일 무렵","mis":"SO3-2-u2-X47"}],"explanation":["모내기 뒤예요.","여름이 오기 전이에요.","음력 5월 5일이에요."],"asset":{"type":"passage","lines":["단오(음력 5월 5일) — 모내기를 마치고 더운 여름 전에 잠시 쉬는 날","농악을 울리며 흥을 돋우었어요.","남자들은 씨름을 즐겼고, 여자들은 주로 그네뛰기를 했어요.","여름을 시원하게 보내라고 부채를 주고받았어요.","수레바퀴 모양의 수리취떡과 앵두화채를 먹으며 건강을 빌었어요.","창포 삶은 물에 머리를 감아 나쁜 기운을 쫓고 윤기 있는 머릿결을 유지했어요."],"title":"『사회』 79쪽 — 단오의 세시 풍속"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L04_basic#2','soc',3,2,'u2','L04','tb_g3_2_soc_u2_L04_basic','lesson_basic','SO3-2-u2-C4',1,'sa','auto','정월 대보름에 이가 튼튼해지기를 빌며 깨문 밤, 호두, 땅콩 같은 단단한 열매를 무엇이라고 하나요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SO3-2-u2-C4","difficulty":1,"kind":"sa","stem":"정월 대보름에 이가 튼튼해지기를 빌며 깨문 밤, 호두, 땅콩 같은 단단한 열매를 무엇이라고 하나요? 두 글자로 쓰세요.","answer":["부럼"],"explanation":["단단한 열매예요.","부◯이에요.","부럼이에요."],"mis":"SO3-2-u2-X11"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L04_basic#3','soc',3,2,'u2','L04','tb_g3_2_soc_u2_L04_basic','lesson_basic','SO3-2-u2-C4',1,'mc','auto','단오에 여름을 시원하게 보내라고 주고받은 물건은 무엇인가요?',ARRAY['SO3-2-u2-X11']::text[],true,'{"seq":3,"concept":"SO3-2-u2-C4","difficulty":1,"kind":"mc","stem":"단오에 여름을 시원하게 보내라고 주고받은 물건은 무엇인가요?","options":[{"t":"부채","correct":true},{"t":"버선","mis":"SO3-2-u2-X11"},{"t":"새해 달력","mis":"SO3-2-u2-X11"},{"t":"복주머니","mis":"SO3-2-u2-X11"}],"explanation":["더운 여름이 와요.","시원한 바람이에요.","부채예요."],"asset":{"type":"passage","lines":["단오(음력 5월 5일) — 모내기를 마치고 더운 여름 전에 잠시 쉬는 날","농악을 울리며 흥을 돋우었어요.","남자들은 씨름을 즐겼고, 여자들은 주로 그네뛰기를 했어요.","여름을 시원하게 보내라고 부채를 주고받았어요.","수레바퀴 모양의 수리취떡과 앵두화채를 먹으며 건강을 빌었어요.","창포 삶은 물에 머리를 감아 나쁜 기운을 쫓고 윤기 있는 머릿결을 유지했어요."],"title":"『사회』 79쪽 — 단오의 세시 풍속"},"variant_rule":{"alt":[{"stem":"동지에 오래 살기를 기원하며 드린 물건은 무엇인가요?","options":[{"t":"버선","correct":true},{"t":"부채","mis":"SO3-2-u2-X11"},{"t":"송편","mis":"SO3-2-u2-X11"},{"t":"복조리","mis":"SO3-2-u2-X11"}],"explanation":["밤이 가장 긴 날이에요.","오래 살기를 빌었어요.","버선이에요."],"asset":{"type":"passage","lines":["동지(양력 12월 22일~23일 무렵) — 한 해 중 밤이 가장 길고 낮이 가장 짧은 날","동지부터 낮이 길어져 새해의 시작이라 생각해 「작은 설」이라고 했어요.","붉은팥이 나쁜 기운을 쫓는다고 여겨 팥죽을 먹고, 대문에 뿌리기도 했어요.","오래 살기를 기원하며 버선을 드렸어요.","새해 달력을 주고받으며 새해 맞을 준비를 했어요."],"title":"『사회』 81쪽 — 동지의 세시 풍속"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L04_basic#4','soc',3,2,'u2','L04','tb_g3_2_soc_u2_L04_basic','lesson_basic','SO3-2-u2-C4',1,'ox','auto','추석에는 그해에 새로 난 곡식과 과일로 차례를 지냈어요.',ARRAY['SO3-2-u2-X11']::text[],false,'{"seq":4,"concept":"SO3-2-u2-C4","difficulty":1,"kind":"ox","stem":"추석에는 그해에 새로 난 곡식과 과일로 차례를 지냈어요.","answer":"O","reason_options":[{"t":"추석은 농사지은 곡식과 과일을 거두어들이는 때여서 풍년에 감사했기 때문에","correct":true},{"t":"추석은 농사를 시작하기 전이라 거둔 곡식이 없었기 때문에","mis":"SO3-2-u2-X11"}],"mis":"SO3-2-u2-X11","explanation":["음력 8월 15일이에요.","곡식을 거두는 때예요.","그래서 O예요."],"asset":{"type":"passage","lines":["추석(음력 8월 15일) — 농사지은 곡식과 과일을 거두어들이는 때","그해에 새로 난 곡식과 과일로 차례를 지냈어요.","보름달 아래에서 강강술래를 하며 축제를 벌였어요.","조상들에게 감사하며 성묘하러 갔어요.","그해에 새로 난 쌀로 송편을 빚어 먹었어요.","자기 마을의 소를 응원하며 소싸움을 즐겼어요."],"title":"『사회』 80쪽 — 추석의 세시 풍속"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L04_basic#5','soc',3,2,'u2','L04','tb_g3_2_soc_u2_L04_basic','lesson_basic','SO3-2-u2-C4',2,'match','auto','『사회』 77~80쪽을 보고 명절과 그날 옛날 사람들이 즐긴 놀이를 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"SO3-2-u2-C4","difficulty":2,"kind":"match","stem":"『사회』 77~80쪽을 보고 명절과 그날 옛날 사람들이 즐긴 놀이를 알맞게 이으세요.","pairs":[{"l":"설날","r":"널뛰기와 연날리기"},{"l":"정월 대보름","r":"쥐불놀이와 다리밟기"},{"l":"단오","r":"씨름과 그네뛰기"},{"l":"추석","r":"강강술래와 소싸움"}],"mis":"SO3-2-u2-X11","explanation":["설날은 널뛰기예요.","대보름은 쥐불놀이, 단오는 씨름이에요.","추석은 강강술래예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L04_basic#6','soc',3,2,'u2','L04','tb_g3_2_soc_u2_L04_basic','lesson_basic','SO3-2-u2-C4',2,'mc','auto','『사회』 81쪽에서 옛날 사람들이 동지를 「작은 설」이라고 부른 까닭은 무엇인가요?',ARRAY['SO3-2-u2-X10','SO3-2-u2-X11']::text[],false,'{"seq":6,"concept":"SO3-2-u2-C4","difficulty":2,"kind":"mc","stem":"『사회』 81쪽에서 옛날 사람들이 동지를 「작은 설」이라고 부른 까닭은 무엇인가요?","options":[{"t":"동지부터 낮의 길이가 점점 길어져 새해의 시작이라고 생각했기 때문이에요","correct":true},{"t":"설날과 날짜가 같았기 때문이에요","mis":"SO3-2-u2-X10"},{"t":"설날보다 먹는 음식이 적었기 때문이에요","mis":"SO3-2-u2-X11"},{"t":"새해 처음으로 보름달이 뜨는 날이었기 때문이에요","mis":"SO3-2-u2-X10"}],"explanation":["밤이 가장 긴 날이에요.","다음 날부터 낮이 길어져요.","새해의 시작이에요."],"asset":{"type":"passage","lines":["동지(양력 12월 22일~23일 무렵) — 한 해 중 밤이 가장 길고 낮이 가장 짧은 날","동지부터 낮이 길어져 새해의 시작이라 생각해 「작은 설」이라고 했어요.","붉은팥이 나쁜 기운을 쫓는다고 여겨 팥죽을 먹고, 대문에 뿌리기도 했어요.","오래 살기를 기원하며 버선을 드렸어요.","새해 달력을 주고받으며 새해 맞을 준비를 했어요."],"title":"『사회』 81쪽 — 동지의 세시 풍속"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L04_basic#7','soc',3,2,'u2','L04','tb_g3_2_soc_u2_L04_basic','lesson_basic','SO3-2-u2-C4',2,'blank','auto','「달이 지구를 한 바퀴 도는 데 걸리는 시간을 한 달로 계산하여 일 년으로 나타낸 것」을 (    )이라고 해요. 빈칸에 알맞은 말은?',ARRAY['SO3-2-u2-X47','SO3-2-u2-X03']::text[],false,'{"seq":7,"concept":"SO3-2-u2-C4","difficulty":2,"kind":"blank","stem":"「달이 지구를 한 바퀴 도는 데 걸리는 시간을 한 달로 계산하여 일 년으로 나타낸 것」을 (    )이라고 해요. 빈칸에 알맞은 말은?","options":[{"t":"음력","correct":true},{"t":"양력","mis":"SO3-2-u2-X47"},{"t":"절기","mis":"SO3-2-u2-X47"},{"t":"세시","mis":"SO3-2-u2-X03"}],"explanation":["달을 기준으로 해요.","설날, 추석이 이것을 따라요.","음력이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L04_basic#8','soc',3,2,'u2','L04','tb_g3_2_soc_u2_L04_basic','lesson_basic','SO3-2-u2-C4',2,'mc','auto','떡국을 끓이는 가래떡의 흰색에 담긴 생각은 무엇인가요?',ARRAY['SO3-2-u2-X12']::text[],false,'{"seq":8,"concept":"SO3-2-u2-C4","difficulty":2,"kind":"mc","stem":"떡국을 끓이는 가래떡의 흰색에 담긴 생각은 무엇인가요?","options":[{"t":"밝은 한 해가 되기를 바라는 생각","correct":true},{"t":"건강하고 오래 살기를 바라는 마음","mis":"SO3-2-u2-X12"},{"t":"부자가 되기를 바라는 마음","mis":"SO3-2-u2-X12"},{"t":"집안이 점점 나아지기를 바라는 마음","mis":"SO3-2-u2-X12"}],"explanation":["흰색을 봐요.","긴 모양과 동전 모양은 다른 뜻이에요.","밝은 한 해예요."],"asset":{"type":"passage","lines":["떡국 — 가래떡의 흰색에는 밝은 한 해가 되기를 바라는 생각이 담겨 있어요.","떡국 — 가래떡의 긴 모양에는 건강하고 오래 살기를 바라는 마음이 담겨 있어요.","떡국 — 부자가 되기를 바라며 가래떡을 동전 모양으로 납작하게 썰었대요.","송편 — 소를 넣기 전엔 보름달 모양, 빚은 뒤엔 반달 모양이에요.","송편 — 반달이 커져 보름달이 되듯 집안과 나라가 점점 나아지기를 바랐대요."],"title":"『사회』 82쪽 — 세시 음식에 담긴 마음"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L04_basic#9','soc',3,2,'u2','L04','tb_g3_2_soc_u2_L04_basic','lesson_basic','SO3-2-u2-C4',2,'ox','auto','동지는 설날, 추석처럼 음력 날짜로 정한 날이에요.',ARRAY['SO3-2-u2-X47']::text[],false,'{"seq":9,"concept":"SO3-2-u2-C4","difficulty":2,"kind":"ox","stem":"동지는 설날, 추석처럼 음력 날짜로 정한 날이에요.","answer":"X","reason_options":[{"t":"동지는 태양의 움직임에 따라 일 년을 24개로 나눈 절기 가운데 하나라 양력을 따르기 때문에","correct":true},{"t":"옛날 명절과 절기는 모두 음력으로 정했기 때문에","mis":"SO3-2-u2-X47"}],"mis":"SO3-2-u2-X47","explanation":["양력 12월 22일 무렵이에요.","24절기 가운데 하나예요.","그래서 X예요."],"asset":{"type":"passage","lines":["동지(양력 12월 22일~23일 무렵) — 한 해 중 밤이 가장 길고 낮이 가장 짧은 날","동지부터 낮이 길어져 새해의 시작이라 생각해 「작은 설」이라고 했어요.","붉은팥이 나쁜 기운을 쫓는다고 여겨 팥죽을 먹고, 대문에 뿌리기도 했어요.","오래 살기를 기원하며 버선을 드렸어요.","새해 달력을 주고받으며 새해 맞을 준비를 했어요."],"title":"『사회』 81쪽 — 동지의 세시 풍속"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L04_basic#10','soc',3,2,'u2','L04','tb_g3_2_soc_u2_L04_basic','lesson_basic','SO3-2-u2-C4',3,'error','auto','단오의 세시 풍속을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO3-2-u2-X11','SO3-2-u2-X10']::text[],false,'{"seq":10,"concept":"SO3-2-u2-C4","difficulty":3,"kind":"error","stem":"단오의 세시 풍속을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「단오에는 창포 삶은 물에 머리를 감고 팥죽을 먹었어.」","correct":true,"mis_target":"SO3-2-u2-X11"},{"t":"친구 가 — 「단오에는 수레바퀴 모양의 수리취떡을 먹었어.」","mis":"SO3-2-u2-X11"},{"t":"친구 나 — 「단오는 모내기를 마치고 잠시 쉬는 날이야.」","mis":"SO3-2-u2-X10"}],"explanation":["팥죽은 동지예요.","단오는 수리취떡이에요.","친구 다가 잘못 말했어요."],"asset":{"type":"passage","lines":["단오(음력 5월 5일) — 모내기를 마치고 더운 여름 전에 잠시 쉬는 날","농악을 울리며 흥을 돋우었어요.","남자들은 씨름을 즐겼고, 여자들은 주로 그네뛰기를 했어요.","여름을 시원하게 보내라고 부채를 주고받았어요.","수레바퀴 모양의 수리취떡과 앵두화채를 먹으며 건강을 빌었어요.","창포 삶은 물에 머리를 감아 나쁜 기운을 쫓고 윤기 있는 머릿결을 유지했어요."],"title":"『사회』 79쪽 — 단오의 세시 풍속"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L04_challenge#1','soc',3,2,'u2','L04','tb_g3_2_soc_u2_L04_challenge','lesson_challenge','SO3-2-u2-C4',2,'sa','auto','8월의 한가운데에 있는 큰 날이라는 뜻으로, 추석을 달리 부르는 말을 세 글자로 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"SO3-2-u2-C4","difficulty":2,"kind":"sa","stem":"8월의 한가운데에 있는 큰 날이라는 뜻으로, 추석을 달리 부르는 말을 세 글자로 쓰세요.","answer":["한가위"],"explanation":["추석의 다른 이름이에요.","한◯◯예요.","한가위예요."],"mis":"SO3-2-u2-X10"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L04_challenge#2','soc',3,2,'u2','L04','tb_g3_2_soc_u2_L04_challenge','lesson_challenge','SO3-2-u2-C4',2,'mc','auto','옛날 사람들이 설날에 복이 들어오기를 바라며 건 것은 무엇인가요?',ARRAY['SO3-2-u2-X11']::text[],false,'{"seq":2,"concept":"SO3-2-u2-C4","difficulty":2,"kind":"mc","stem":"옛날 사람들이 설날에 복이 들어오기를 바라며 건 것은 무엇인가요?","options":[{"t":"복조리","correct":true},{"t":"창포","mis":"SO3-2-u2-X11"},{"t":"달집","mis":"SO3-2-u2-X11"},{"t":"버선","mis":"SO3-2-u2-X11"}],"explanation":["77쪽을 봐요.","복을 바랐어요.","복조리예요."],"asset":{"type":"passage","lines":["설날(음력 1월 1일) — 한 해가 시작되는 날","떡국을 먹고 나이를 한 살 더 먹었어요.","널뛰기와 연날리기를 즐기고, 한 해의 운세를 점치며 윷놀이를 했어요.","복이 들어오기를 바라며 복조리를 걸고, 복주머니를 찼어요.","설빔을 입고 어른들께 세배를 드리고 덕담을 들었어요."],"title":"『사회』 77쪽 — 설날의 세시 풍속"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L04_challenge#3','soc',3,2,'u2','L04','tb_g3_2_soc_u2_L04_challenge','lesson_challenge','SO3-2-u2-C4',3,'mc','auto','수수께끼의 단서를 보고 알맞은 명절을 고르세요. 「모내기를 마친 뒤예요. 농악을 울렸어요. 창포 삶은 물에 머리를 감았어요.」',ARRAY['SO3-2-u2-X11']::text[],false,'{"seq":3,"concept":"SO3-2-u2-C4","difficulty":3,"kind":"mc","stem":"수수께끼의 단서를 보고 알맞은 명절을 고르세요. 「모내기를 마친 뒤예요. 농악을 울렸어요. 창포 삶은 물에 머리를 감았어요.」","options":[{"t":"단오","correct":true},{"t":"추석","mis":"SO3-2-u2-X11"},{"t":"정월 대보름","mis":"SO3-2-u2-X11"},{"t":"동지","mis":"SO3-2-u2-X11"}],"explanation":["모내기 뒤예요.","창포물이에요.","단오예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L04_challenge#4','soc',3,2,'u2','L04','tb_g3_2_soc_u2_L04_challenge','lesson_challenge','SO3-2-u2-C4',3,'mc','auto','정월 대보름의 세시 풍속 가운데 풍년을 기원한 것끼리 묶은 것은 무엇인가요?',ARRAY['SO3-2-u2-X12','SO3-2-u2-X11']::text[],false,'{"seq":4,"concept":"SO3-2-u2-C4","difficulty":3,"kind":"mc","stem":"정월 대보름의 세시 풍속 가운데 풍년을 기원한 것끼리 묶은 것은 무엇인가요?","options":[{"t":"달집태우기, 오곡밥과 나물 먹기","correct":true},{"t":"부럼 깨물기, 다리밟기","mis":"SO3-2-u2-X12"},{"t":"널뛰기, 연날리기","mis":"SO3-2-u2-X11"},{"t":"세배하기, 덕담 듣기","mis":"SO3-2-u2-X11"}],"explanation":["풍년은 곡식이 잘되는 해예요.","부럼과 다리밟기는 몸 건강이에요.","달집과 오곡밥이에요."],"asset":{"type":"passage","lines":["정월 대보름(음력 1월 15일) — 새해 처음으로 보름달이 뜨는 날","달집(나뭇가지 무더기)에 불을 질러 태우며 풍년을 기원했어요.","논밭에 불을 붙여 쥐불놀이를 하며 나쁜 기운을 쫓아냈어요.","다리에 병이 나지 않고 튼튼해진다고 하여 다리밟기를 했어요.","부럼을 깨물며 이가 튼튼해지고 피부병이 생기지 않기를 빌었어요.","다섯 가지 곡식으로 만든 오곡밥과 나물을 먹었어요."],"title":"『사회』 78쪽 — 정월 대보름의 세시 풍속"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L04_challenge#5','soc',3,2,'u2','L04','tb_g3_2_soc_u2_L04_challenge','lesson_challenge','SO3-2-u2-C4',3,'ox','auto','송편을 반달 모양으로 빚은 데에는 집안이나 나라가 점점 나아지기를 바라는 마음이 담겨 있어요.',ARRAY['SO3-2-u2-X12']::text[],false,'{"seq":5,"concept":"SO3-2-u2-C4","difficulty":3,"kind":"ox","stem":"송편을 반달 모양으로 빚은 데에는 집안이나 나라가 점점 나아지기를 바라는 마음이 담겨 있어요.","answer":"O","reason_options":[{"t":"반달이 점점 커져서 보름달이 되는 것처럼 나아지기를 바랐기 때문에","correct":true},{"t":"반달처럼 점점 작아지기를 바랐기 때문에","mis":"SO3-2-u2-X12"}],"mis":"SO3-2-u2-X12","explanation":["82쪽을 봐요.","반달이 보름달로 커져요.","그래서 O예요."],"asset":{"type":"passage","lines":["떡국 — 가래떡의 흰색에는 밝은 한 해가 되기를 바라는 생각이 담겨 있어요.","떡국 — 가래떡의 긴 모양에는 건강하고 오래 살기를 바라는 마음이 담겨 있어요.","떡국 — 부자가 되기를 바라며 가래떡을 동전 모양으로 납작하게 썰었대요.","송편 — 소를 넣기 전엔 보름달 모양, 빚은 뒤엔 반달 모양이에요.","송편 — 반달이 커져 보름달이 되듯 집안과 나라가 점점 나아지기를 바랐대요."],"title":"『사회』 82쪽 — 세시 음식에 담긴 마음"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L04_challenge#6','soc',3,2,'u2','L04','tb_g3_2_soc_u2_L04_challenge','lesson_challenge','SO3-2-u2-C4',3,'match','auto','세시 풍속과 그 속에 담긴 바람을 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"SO3-2-u2-C4","difficulty":3,"kind":"match","stem":"세시 풍속과 그 속에 담긴 바람을 알맞게 이으세요.","pairs":[{"l":"부럼 깨물기","r":"이가 튼튼해지고 피부병이 생기지 않기를"},{"l":"다리밟기","r":"다리에 병이 나지 않고 튼튼해지기를"},{"l":"창포물에 머리 감기","r":"나쁜 기운을 쫓고 머릿결이 윤기 있기를"},{"l":"팥죽 먹기","r":"붉은팥으로 나쁜 기운을 쫓기를"}],"mis":"SO3-2-u2-X12","explanation":["부럼은 이예요.","다리밟기는 다리, 창포는 머릿결이에요.","팥죽은 나쁜 기운이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L04_challenge#7','soc',3,2,'u2','L04','tb_g3_2_soc_u2_L04_challenge','lesson_challenge','SO3-2-u2-C4',3,'error','auto','동지를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO3-2-u2-X10','SO3-2-u2-X11']::text[],false,'{"seq":7,"concept":"SO3-2-u2-C4","difficulty":3,"kind":"error","stem":"동지를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 가 — 「동지는 음력 1월 15일이고, 보름달을 보며 소원을 빌어.」","correct":true,"mis_target":"SO3-2-u2-X10"},{"t":"친구 나 — 「동지에는 새해 달력을 주고받았어.」","mis":"SO3-2-u2-X11"},{"t":"친구 다 — 「동지는 한 해 중 밤이 가장 긴 날이야.」","mis":"SO3-2-u2-X10"}],"explanation":["보름달은 정월 대보름이에요.","동지는 양력 12월 22일 무렵이에요.","친구 가가 잘못 말했어요."],"asset":{"type":"passage","lines":["동지(양력 12월 22일~23일 무렵) — 한 해 중 밤이 가장 길고 낮이 가장 짧은 날","동지부터 낮이 길어져 새해의 시작이라 생각해 「작은 설」이라고 했어요.","붉은팥이 나쁜 기운을 쫓는다고 여겨 팥죽을 먹고, 대문에 뿌리기도 했어요.","오래 살기를 기원하며 버선을 드렸어요.","새해 달력을 주고받으며 새해 맞을 준비를 했어요."],"title":"『사회』 81쪽 — 동지의 세시 풍속"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L04_challenge#8','soc',3,2,'u2','L04','tb_g3_2_soc_u2_L04_challenge','lesson_challenge','SO3-2-u2-C4',4,'mc','auto','옛날 세시 풍속에 대해 바르게 정리한 것은 무엇인가요?',ARRAY['SO3-2-u2-X02','SO3-2-u2-X44']::text[],false,'{"seq":8,"concept":"SO3-2-u2-C4","difficulty":4,"kind":"mc","stem":"옛날 세시 풍속에 대해 바르게 정리한 것은 무엇인가요?","options":[{"t":"사람들의 생활과 생각이 담겨 있고, 차례 지내기·윷놀이·떡국 먹기·송편 빚기·팥죽 먹기는 오늘날까지 이어져요","correct":true},{"t":"오늘날까지 이어지는 세시 풍속은 하나도 없어요","mis":"SO3-2-u2-X02"},{"t":"명절이 바뀌어 차례 지내기는 사라졌어요","mis":"SO3-2-u2-X02"},{"t":"옛날 세시 풍속은 오늘날 모두 그대로예요","mis":"SO3-2-u2-X44"}],"explanation":["담긴 생활과 생각이에요.","이어지는 것도 있어요.","81쪽 글이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L04_challenge#9','soc',3,2,'u2','L04','tb_g3_2_soc_u2_L04_challenge','lesson_challenge','SO3-2-u2-C4',4,'error','auto','82쪽 「세시 음식에도 옛날 사람들의 마음이 담겨 있어요」를 읽고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO3-2-u2-X12']::text[],false,'{"seq":9,"concept":"SO3-2-u2-C4","difficulty":4,"kind":"error","stem":"82쪽 「세시 음식에도 옛날 사람들의 마음이 담겨 있어요」를 읽고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「가래떡을 길게 뽑는 것은 부자가 되기를 바라서야.」","correct":true,"mis_target":"SO3-2-u2-X12"},{"t":"친구 가 — 「가래떡을 동전 모양으로 썬 것은 부자가 되기를 바라서야.」","mis":"SO3-2-u2-X12"},{"t":"친구 나 — 「가래떡의 긴 모양에는 건강하고 오래 살기를 바라는 마음이 담겼어.」","mis":"SO3-2-u2-X12"}],"explanation":["긴 모양은 건강하고 오래 살기예요.","동전 모양이 부자예요.","친구 다가 잘못 말했어요."],"asset":{"type":"passage","lines":["떡국 — 가래떡의 흰색에는 밝은 한 해가 되기를 바라는 생각이 담겨 있어요.","떡국 — 가래떡의 긴 모양에는 건강하고 오래 살기를 바라는 마음이 담겨 있어요.","떡국 — 부자가 되기를 바라며 가래떡을 동전 모양으로 납작하게 썰었대요.","송편 — 소를 넣기 전엔 보름달 모양, 빚은 뒤엔 반달 모양이에요.","송편 — 반달이 커져 보름달이 되듯 집안과 나라가 점점 나아지기를 바랐대요."],"title":"『사회』 82쪽 — 세시 음식에 담긴 마음"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L04_challenge#10','soc',3,2,'u2','L04','tb_g3_2_soc_u2_L04_challenge','lesson_challenge','SO3-2-u2-C4',4,'essay','teacher','우리 반 친구에게 나누고 싶은 새해 덕담을 쓰고, 그 덕담에 담긴 마음을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO3-2-u2-C4","difficulty":4,"kind":"essay","stem":"우리 반 친구에게 나누고 싶은 새해 덕담을 쓰고, 그 덕담에 담긴 마음을 쓰세요.","answer_guide":{"answer":"예: 「△△야, 아프지 말고 건강하길 바라.」 — 친구가 새해에 건강하고 잘되기를 바라는 마음을 담았어요.","scoring_points":["덕담을 썼는가","남이 잘되기를 바라는 말인가","담긴 마음을 썼는가"]},"explanation":["덕담은 좋은 말이에요.","친구를 떠올려요.","마음을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L05_basic#1','soc',3,2,'u2','L05','tb_g3_2_soc_u2_L05_basic','lesson_basic','SO3-2-u2-C5',1,'mc','auto','『사회』 83쪽에서 우리 조상들은 주로 어떤 일을 하며 살았다고 했나요?',ARRAY['SO3-2-u2-X13']::text[],false,'{"seq":1,"concept":"SO3-2-u2-C5","difficulty":1,"kind":"mc","stem":"『사회』 83쪽에서 우리 조상들은 주로 어떤 일을 하며 살았다고 했나요?","options":[{"t":"농사","correct":true},{"t":"공장에서 물건 만들기","mis":"SO3-2-u2-X13"},{"t":"물건을 사고파는 장사","mis":"SO3-2-u2-X13"},{"t":"먼 나라로 여행하기","mis":"SO3-2-u2-X13"}],"explanation":["83쪽 첫 줄이에요.","계절 따라 일해요.","농사예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L05_basic#2','soc',3,2,'u2','L05','tb_g3_2_soc_u2_L05_basic','lesson_basic','SO3-2-u2-C5',1,'sa','auto','「옛날에는 (    )와 관련 있는 세시 풍속이 계절마다 다양했습니다.」 빈칸에 알맞은 말을 두 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SO3-2-u2-C5","difficulty":1,"kind":"sa","stem":"「옛날에는 (    )와 관련 있는 세시 풍속이 계절마다 다양했습니다.」 빈칸에 알맞은 말을 두 글자로 쓰세요.","answer":["농사"],"explanation":["꼭 기억해요 1이에요.","조상들이 주로 한 일이에요.","농사예요."],"mis":"SO3-2-u2-X13"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L05_basic#3','soc',3,2,'u2','L05','tb_g3_2_soc_u2_L05_basic','lesson_basic','SO3-2-u2-C5',1,'mc','auto','옛날 농촌에서 가을에 한 세시 풍속은 무엇인가요?',ARRAY['SO3-2-u2-X13']::text[],true,'{"seq":3,"concept":"SO3-2-u2-C5","difficulty":1,"kind":"mc","stem":"옛날 농촌에서 가을에 한 세시 풍속은 무엇인가요?","options":[{"t":"곡식을 거두고 음식을 만들어 먹으며 수확의 기쁨을 나눴어요","correct":true},{"t":"새해 첫 보름달을 보며 풍년을 기원했어요","mis":"SO3-2-u2-X13"},{"t":"무더위를 피해 잠시 농사일을 쉬었어요","mis":"SO3-2-u2-X13"},{"t":"성묘를 하고 농사일을 시작했어요","mis":"SO3-2-u2-X13"}],"explanation":["가을은 거두는 때예요.","수확의 기쁨이에요.","그 모습이에요."],"asset":{"type":"passage","lines":["겨울 — 새해 첫 보름달을 보며 한 해의 풍년을 기원했어요.","봄 — 농사가 잘되기를 바라며 성묘를 하고 농사일을 시작했어요.","여름 — 무더위를 피해 잠시 농사일을 쉬며 영양이 풍부한 음식을 먹었어요.","가을 — 곡식을 거두고, 음식을 만들어 먹으며 수확의 기쁨을 함께 나눴어요."],"title":"『사회』 83쪽 — 옛날 농촌의 계절과 세시 풍속"},"variant_rule":{"alt":[{"stem":"옛날 농촌에서 여름에 한 세시 풍속은 무엇인가요?","options":[{"t":"무더위를 피해 잠시 농사일을 쉬며 영양이 풍부한 음식을 먹었어요","correct":true},{"t":"새해 첫 보름달을 보며 풍년을 기원했어요","mis":"SO3-2-u2-X13"},{"t":"곡식을 거두고 수확의 기쁨을 나눴어요","mis":"SO3-2-u2-X13"},{"t":"성묘를 하고 농사일을 시작했어요","mis":"SO3-2-u2-X13"}],"explanation":["여름은 더워요.","잠시 쉬었어요.","그 모습이에요."],"asset":{"type":"passage","lines":["겨울 — 새해 첫 보름달을 보며 한 해의 풍년을 기원했어요.","봄 — 농사가 잘되기를 바라며 성묘를 하고 농사일을 시작했어요.","여름 — 무더위를 피해 잠시 농사일을 쉬며 영양이 풍부한 음식을 먹었어요.","가을 — 곡식을 거두고, 음식을 만들어 먹으며 수확의 기쁨을 함께 나눴어요."],"title":"『사회』 83쪽 — 옛날 농촌의 계절과 세시 풍속"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L05_basic#4','soc',3,2,'u2','L05','tb_g3_2_soc_u2_L05_basic','lesson_basic','SO3-2-u2-C5',1,'ox','auto','오늘날에는 여러 지역에서 축제와 체험 행사를 열어 계절과 관계없이 세시 풍속을 즐길 수 있어요.',ARRAY['SO3-2-u2-X14']::text[],false,'{"seq":4,"concept":"SO3-2-u2-C5","difficulty":1,"kind":"ox","stem":"오늘날에는 여러 지역에서 축제와 체험 행사를 열어 계절과 관계없이 세시 풍속을 즐길 수 있어요.","answer":"O","reason_options":[{"t":"84쪽 그림처럼 세시 풍속 체험장에서 연날리기, 그네뛰기 등을 체험하기 때문에","correct":true},{"t":"세시 풍속은 오늘날 명절날 집에서만 할 수 있기 때문에","mis":"SO3-2-u2-X14"}],"mis":"SO3-2-u2-X14","explanation":["84쪽 그림이에요.","체험 행사가 열려요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L05_basic#5','soc',3,2,'u2','L05','tb_g3_2_soc_u2_L05_basic','lesson_basic','SO3-2-u2-C5',2,'mc','auto','『사회』 84쪽에서 오늘날 농사와 관련 있는 세시 풍속을 즐기는 사람이 줄어든 까닭으로 든 것은 무엇인가요?',ARRAY['SO3-2-u2-X14']::text[],false,'{"seq":5,"concept":"SO3-2-u2-C5","difficulty":2,"kind":"mc","stem":"『사회』 84쪽에서 오늘날 농사와 관련 있는 세시 풍속을 즐기는 사람이 줄어든 까닭으로 든 것은 무엇인가요?","options":[{"t":"직업이 다양해지면서 농사짓는 사람이 줄었기 때문이에요","correct":true},{"t":"사람들이 명절을 싫어하게 되었기 때문이에요","mis":"SO3-2-u2-X14"},{"t":"계절이 없어졌기 때문이에요","mis":"SO3-2-u2-X14"},{"t":"나라에서 세시 풍속을 금지했기 때문이에요","mis":"SO3-2-u2-X14"}],"explanation":["84쪽 말풍선이에요.","직업이 다양해졌어요.","농사짓는 사람이 줄었어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L05_basic#6','soc',3,2,'u2','L05','tb_g3_2_soc_u2_L05_basic','lesson_basic','SO3-2-u2-C5',2,'match','auto','계절과 옛날 농촌의 세시 풍속을 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"SO3-2-u2-C5","difficulty":2,"kind":"match","stem":"계절과 옛날 농촌의 세시 풍속을 알맞게 이으세요.","pairs":[{"l":"겨울","r":"새해 첫 보름달을 보며 풍년을 기원했어요"},{"l":"봄","r":"성묘를 하고 농사일을 시작했어요"},{"l":"여름","r":"농사일을 잠시 쉬며 영양이 풍부한 음식을 먹었어요"},{"l":"가을","r":"곡식을 거두고 수확의 기쁨을 나눴어요"}],"mis":"SO3-2-u2-X13","explanation":["겨울은 풍년 기원이에요.","봄은 시작, 여름은 쉼이에요.","가을은 수확이에요."],"asset":{"type":"passage","lines":["겨울 — 새해 첫 보름달을 보며 한 해의 풍년을 기원했어요.","봄 — 농사가 잘되기를 바라며 성묘를 하고 농사일을 시작했어요.","여름 — 무더위를 피해 잠시 농사일을 쉬며 영양이 풍부한 음식을 먹었어요.","가을 — 곡식을 거두고, 음식을 만들어 먹으며 수확의 기쁨을 함께 나눴어요."],"title":"『사회』 83쪽 — 옛날 농촌의 계절과 세시 풍속"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L05_basic#7','soc',3,2,'u2','L05','tb_g3_2_soc_u2_L05_basic','lesson_basic','SO3-2-u2-C5',2,'mc','auto','사회 관계망 서비스 글에서 옛날부터 이어져 오는 설날 모습은 무엇인가요?',ARRAY['SO3-2-u2-X15']::text[],false,'{"seq":7,"concept":"SO3-2-u2-C5","difficulty":2,"kind":"mc","stem":"사회 관계망 서비스 글에서 옛날부터 이어져 오는 설날 모습은 무엇인가요?","options":[{"t":"차례를 지내고 세배를 하고 떡국을 먹었다","correct":true},{"t":"고모가 사 온 케이크를 먹었다","mis":"SO3-2-u2-X15"},{"t":"영화관에 가서 영화를 봤다","mis":"SO3-2-u2-X15"},{"t":"남은 연휴에 해외여행을 떠났다","mis":"SO3-2-u2-X15"}],"explanation":["옛날 설날을 떠올려요.","차례, 세배, 떡국이에요.","이어지는 모습이에요."],"asset":{"type":"passage","lines":["#설날 #세배 #해외여행","설날 아침 동해에 가서 일출을 보고 할아버지 댁으로 갔다.","친척들이 모여 차례를 지냈다. 나는 절을 했고, 사촌 동생들은 서서 기도했다.","세배를 하고 떡국을 먹고, 고모가 사 온 케이크를 후식으로 먹었다.","점심에는 사촌 동생들과 공원에서 자전거를 타고 보드게임을 했다.","우리 가족은 영화관에 갔고, 사촌 동생네는 남은 연휴에 해외여행을 떠난다고 했다."],"title":"『사회』 85쪽 — 사회 관계망 서비스에 올린 설날 글"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L05_basic#8','soc',3,2,'u2','L05','tb_g3_2_soc_u2_L05_basic','lesson_basic','SO3-2-u2-C5',2,'blank','auto','「옛날과 오늘날의 세시 풍속이 달라지고 있지만, 가족이나 이웃과 (    )을 함께 나누는 것은 변함없습니다.」 빈칸에 알맞은 말은?',ARRAY['SO3-2-u2-X16','SO3-2-u2-X13']::text[],false,'{"seq":8,"concept":"SO3-2-u2-C5","difficulty":2,"kind":"blank","stem":"「옛날과 오늘날의 세시 풍속이 달라지고 있지만, 가족이나 이웃과 (    )을 함께 나누는 것은 변함없습니다.」 빈칸에 알맞은 말은?","options":[{"t":"기쁨","correct":true},{"t":"일손","mis":"SO3-2-u2-X16"},{"t":"농사일","mis":"SO3-2-u2-X13"},{"t":"걱정","mis":"SO3-2-u2-X16"}],"explanation":["84쪽 글이에요.","함께 나눠요.","기쁨이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L05_basic#9','soc',3,2,'u2','L05','tb_g3_2_soc_u2_L05_basic','lesson_basic','SO3-2-u2-C5',2,'ox','auto','옛날과 오늘날의 생활 모습은 달라졌지만, 세시 풍속은 변함이 없어요.',ARRAY['SO3-2-u2-X44']::text[],false,'{"seq":9,"concept":"SO3-2-u2-C5","difficulty":2,"kind":"ox","stem":"옛날과 오늘날의 생활 모습은 달라졌지만, 세시 풍속은 변함이 없어요.","answer":"X","reason_options":[{"t":"생활 모습이 달라지면서 세시 풍속도 큰 명절을 중심으로 달라졌기 때문에","correct":true},{"t":"세시 풍속은 옛날 그대로 이어지기 때문에","mis":"SO3-2-u2-X44"}],"mis":"SO3-2-u2-X44","explanation":["꼭 기억해요 2예요.","세시 풍속도 달라졌어요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L05_basic#10','soc',3,2,'u2','L05','tb_g3_2_soc_u2_L05_basic','lesson_basic','SO3-2-u2-C5',3,'error','auto','설날 글에서 옛날과 다른 점을 찾았어요. 잘못 찾은 친구는 누구인가요?',ARRAY['SO3-2-u2-X15']::text[],false,'{"seq":10,"concept":"SO3-2-u2-C5","difficulty":3,"kind":"error","stem":"설날 글에서 옛날과 다른 점을 찾았어요. 잘못 찾은 친구는 누구인가요?","options":[{"t":"친구 가 — 「친척들이 할아버지 댁에 모인 것은 옛날과 다른 모습이야.」","correct":true,"mis_target":"SO3-2-u2-X15"},{"t":"친구 나 — 「사촌 동생들이 서서 기도한 것은 옛날과 다른 모습이야.」","mis":"SO3-2-u2-X15"},{"t":"친구 다 — 「후식으로 케이크를 먹은 것은 옛날과 다른 모습이야.」","mis":"SO3-2-u2-X15"}],"explanation":["친척이 모이는 것은 옛날에도 했어요.","이어지는 모습이에요.","친구 가가 잘못 찾았어요."],"asset":{"type":"passage","lines":["#설날 #세배 #해외여행","설날 아침 동해에 가서 일출을 보고 할아버지 댁으로 갔다.","친척들이 모여 차례를 지냈다. 나는 절을 했고, 사촌 동생들은 서서 기도했다.","세배를 하고 떡국을 먹고, 고모가 사 온 케이크를 후식으로 먹었다.","점심에는 사촌 동생들과 공원에서 자전거를 타고 보드게임을 했다.","우리 가족은 영화관에 갔고, 사촌 동생네는 남은 연휴에 해외여행을 떠난다고 했다."],"title":"『사회』 85쪽 — 사회 관계망 서비스에 올린 설날 글"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L05_challenge#1','soc',3,2,'u2','L05','tb_g3_2_soc_u2_L05_challenge','lesson_challenge','SO3-2-u2-C5',2,'sa','auto','곡식이 잘 자라고 잘 익어 평년보다 수확이 많은 해를 무엇이라고 하나요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"SO3-2-u2-C5","difficulty":2,"kind":"sa","stem":"곡식이 잘 자라고 잘 익어 평년보다 수확이 많은 해를 무엇이라고 하나요? 두 글자로 쓰세요.","answer":["풍년"],"explanation":["78쪽 낱말 풀이예요.","풍◯이에요.","풍년이에요."],"mis":"SO3-2-u2-X13"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L05_challenge#2','soc',3,2,'u2','L05','tb_g3_2_soc_u2_L05_challenge','lesson_challenge','SO3-2-u2-C5',2,'mc','auto','친구들이 명절에 하는 일 가운데 옛날 명절에도 하던 일은 무엇인가요?',ARRAY['SO3-2-u2-X15']::text[],false,'{"seq":2,"concept":"SO3-2-u2-C5","difficulty":2,"kind":"mc","stem":"친구들이 명절에 하는 일 가운데 옛날 명절에도 하던 일은 무엇인가요?","options":[{"t":"설날에 세배하기","correct":true},{"t":"설날에 여행 가기","mis":"SO3-2-u2-X15"},{"t":"놀이공원 가기","mis":"SO3-2-u2-X15"},{"t":"추석에 영화 보기","mis":"SO3-2-u2-X15"}],"explanation":["조사 표를 봐요.","세배는 옛날부터 했어요.","설날 세배예요."],"asset":{"type":"passage","lines":["김○○ — 설날에 여행 가기","이△△ — 설날에 세배하기","최□□ — 놀이공원 가기","박◇◇ — 추석에 영화 보기"],"title":"『사회』 84쪽 친구와 활동 — 우리 반 친구들이 명절에 하는 일"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L05_challenge#3','soc',3,2,'u2','L05','tb_g3_2_soc_u2_L05_challenge','lesson_challenge','SO3-2-u2-C5',3,'mc','auto','옛날에 계절마다 세시 풍속이 달랐던 까닭은 무엇인가요?',ARRAY['SO3-2-u2-X13','SO3-2-u2-X10']::text[],false,'{"seq":3,"concept":"SO3-2-u2-C5","difficulty":3,"kind":"mc","stem":"옛날에 계절마다 세시 풍속이 달랐던 까닭은 무엇인가요?","options":[{"t":"농사는 계절에 따라 해야 하는 일이 정해져 있었기 때문이에요","correct":true},{"t":"계절마다 놀이를 바꾸는 규칙이 있었기 때문이에요","mis":"SO3-2-u2-X13"},{"t":"날씨와 상관없이 농사를 지었기 때문이에요","mis":"SO3-2-u2-X13"},{"t":"명절이 한 계절에만 있었기 때문이에요","mis":"SO3-2-u2-X10"}],"explanation":["83쪽 글이에요.","농사는 계절을 따라요.","그래서 달랐어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L05_challenge#4','soc',3,2,'u2','L05','tb_g3_2_soc_u2_L05_challenge','lesson_challenge','SO3-2-u2-C5',3,'mc','auto','84쪽 세시 풍속 체험장 그림에서 어린이들이 체험하는 것 가운데 단오의 세시 풍속이 아닌 것은 무엇인가요?',ARRAY['SO3-2-u2-X11']::text[],false,'{"seq":4,"concept":"SO3-2-u2-C5","difficulty":3,"kind":"mc","stem":"84쪽 세시 풍속 체험장 그림에서 어린이들이 체험하는 것 가운데 단오의 세시 풍속이 아닌 것은 무엇인가요?","options":[{"t":"연날리기","correct":true},{"t":"그네뛰기","mis":"SO3-2-u2-X11"},{"t":"씨름","mis":"SO3-2-u2-X11"},{"t":"창포물에 머리 감기","mis":"SO3-2-u2-X11"}],"explanation":["명절과 놀이를 떠올려요.","연날리기는 설날이에요.","연날리기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L05_challenge#5','soc',3,2,'u2','L05','tb_g3_2_soc_u2_L05_challenge','lesson_challenge','SO3-2-u2-C5',3,'ox','auto','오늘날 설날에 여행을 가거나 영화를 보는 집이 있는 것은 생활 모습이 다양해졌기 때문이에요.',ARRAY['SO3-2-u2-X16']::text[],false,'{"seq":5,"concept":"SO3-2-u2-C5","difficulty":3,"kind":"ox","stem":"오늘날 설날에 여행을 가거나 영화를 보는 집이 있는 것은 생활 모습이 다양해졌기 때문이에요.","answer":"O","reason_options":[{"t":"교통과 과학 기술이 발달하고 직업과 생활이 다양해져 명절을 보내는 모습도 다양해졌기 때문에","correct":true},{"t":"오늘날 사람들이 가족을 소중히 여기지 않기 때문에","mis":"SO3-2-u2-X16"}],"mis":"SO3-2-u2-X16","explanation":["85쪽 핵심 질문이에요.","생활이 다양해졌어요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L05_challenge#6','soc',3,2,'u2','L05','tb_g3_2_soc_u2_L05_challenge','lesson_challenge','SO3-2-u2-C5',3,'match','auto','오늘날 설날 모습을 두 갈래로 나누어 이으세요.','{}'::text[],false,'{"seq":6,"concept":"SO3-2-u2-C5","difficulty":3,"kind":"match","stem":"오늘날 설날 모습을 두 갈래로 나누어 이으세요.","pairs":[{"l":"세배하고 떡국 먹기","r":"옛날부터 이어지는 모습"},{"l":"영화관에서 영화 보기","r":"옛날과 달라진 모습"}],"mis":"SO3-2-u2-X15","explanation":["세배와 떡국은 옛날에도 했어요.","영화는 오늘날 모습이에요.","두 갈래예요."],"asset":{"type":"passage","lines":["#설날 #세배 #해외여행","설날 아침 동해에 가서 일출을 보고 할아버지 댁으로 갔다.","친척들이 모여 차례를 지냈다. 나는 절을 했고, 사촌 동생들은 서서 기도했다.","세배를 하고 떡국을 먹고, 고모가 사 온 케이크를 후식으로 먹었다.","점심에는 사촌 동생들과 공원에서 자전거를 타고 보드게임을 했다.","우리 가족은 영화관에 갔고, 사촌 동생네는 남은 연휴에 해외여행을 떠난다고 했다."],"title":"『사회』 85쪽 — 사회 관계망 서비스에 올린 설날 글"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L05_challenge#7','soc',3,2,'u2','L05','tb_g3_2_soc_u2_L05_challenge','lesson_challenge','SO3-2-u2-C5',3,'error','auto','세시 풍속의 변화를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO3-2-u2-X02','SO3-2-u2-X14','SO3-2-u2-X13']::text[],false,'{"seq":7,"concept":"SO3-2-u2-C5","difficulty":3,"kind":"error","stem":"세시 풍속의 변화를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「오늘날에는 세시 풍속이 모두 사라져서 명절에 가족이 모이지 않아.」","correct":true,"mis_target":"SO3-2-u2-X02"},{"t":"친구 가 — 「오늘날에는 큰 명절을 중심으로 세시 풍속이 이어져 와.」","mis":"SO3-2-u2-X14"},{"t":"친구 나 — 「옛날에는 풍년을 기원하고 수확을 감사하는 마음으로 세시 풍속을 즐겼어.」","mis":"SO3-2-u2-X13"}],"explanation":["세시 풍속은 이어져요.","가족이 모여요.","친구 다가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L05_challenge#8','soc',3,2,'u2','L05','tb_g3_2_soc_u2_L05_challenge','lesson_challenge','SO3-2-u2-C5',4,'mc','auto','옛날과 오늘날의 세시 풍속을 비교한 결과로 가장 알맞은 것은 무엇인가요?',ARRAY['SO3-2-u2-X44','SO3-2-u2-X14','SO3-2-u2-X16']::text[],false,'{"seq":8,"concept":"SO3-2-u2-C5","difficulty":4,"kind":"mc","stem":"옛날과 오늘날의 세시 풍속을 비교한 결과로 가장 알맞은 것은 무엇인가요?","options":[{"t":"옛날엔 농사와 관련된 세시 풍속이 계절마다 다양했고, 오늘날엔 큰 명절 중심으로 이어지며, 기쁨을 나누는 마음은 같아요","correct":true},{"t":"옛날과 오늘날의 세시 풍속은 똑같아요","mis":"SO3-2-u2-X44"},{"t":"오늘날에는 농사와 관련 있는 세시 풍속이 더 많아졌어요","mis":"SO3-2-u2-X14"},{"t":"오늘날에는 가족과 기쁨을 나누지 않아요","mis":"SO3-2-u2-X16"}],"explanation":["옛날 특징이에요.","오늘날 특징이에요.","변함없는 것이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L05_challenge#9','soc',3,2,'u2','L05','tb_g3_2_soc_u2_L05_challenge','lesson_challenge','SO3-2-u2-C5',4,'ox','auto','옛날 농촌에서 정월 대보름에 보름달을 보며 풍년을 빈 것은 한 해 농사를 시작하기 전이었기 때문이에요.',ARRAY['SO3-2-u2-X13']::text[],false,'{"seq":9,"concept":"SO3-2-u2-C5","difficulty":4,"kind":"ox","stem":"옛날 농촌에서 정월 대보름에 보름달을 보며 풍년을 빈 것은 한 해 농사를 시작하기 전이었기 때문이에요.","answer":"O","reason_options":[{"t":"겨울철 정월 대보름은 농사를 시작하기 전이라 한 해 농사가 잘되기를 빌었기 때문에","correct":true},{"t":"정월 대보름은 곡식을 모두 거둔 뒤였기 때문에","mis":"SO3-2-u2-X13"}],"mis":"SO3-2-u2-X13","explanation":["겨울 그림이에요.","농사 시작 전이에요.","그래서 O예요."],"asset":{"type":"passage","lines":["겨울 — 새해 첫 보름달을 보며 한 해의 풍년을 기원했어요.","봄 — 농사가 잘되기를 바라며 성묘를 하고 농사일을 시작했어요.","여름 — 무더위를 피해 잠시 농사일을 쉬며 영양이 풍부한 음식을 먹었어요.","가을 — 곡식을 거두고, 음식을 만들어 먹으며 수확의 기쁨을 함께 나눴어요."],"title":"『사회』 83쪽 — 옛날 농촌의 계절과 세시 풍속"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L05_challenge#10','soc',3,2,'u2','L05','tb_g3_2_soc_u2_L05_challenge','lesson_challenge','SO3-2-u2-C5',4,'essay','teacher','지난 설날이나 추석에 한 일을 떠올려 옛날과 비슷한 점 하나와 다른 점 하나를 쓰고, 다른 까닭을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO3-2-u2-C5","difficulty":4,"kind":"essay","stem":"지난 설날이나 추석에 한 일을 떠올려 옛날과 비슷한 점 하나와 다른 점 하나를 쓰고, 다른 까닭을 쓰세요.","answer_guide":{"answer":"예: 친척들이 모여 차례를 지내고 송편을 먹은 것은 옛날과 비슷해요. 추석 연휴에 가족과 여행을 간 것은 달라요. 직업과 생활 모습이 다양해져 명절을 보내는 모습도 다양해졌기 때문이에요.","scoring_points":["비슷한 점을 썼는가","다른 점을 썼는가","다른 까닭을 썼는가"]},"explanation":["내 경험을 떠올려요.","비슷한 점과 다른 점이에요.","까닭을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L06_basic#1','soc',3,2,'u2','L06','tb_g3_2_soc_u2_L06_basic','lesson_basic','SO3-2-u2-C6',1,'mc','auto','옛날 사람들이 설날 아침에 복주머니를 옷에 차고 다닌 까닭은 무엇인가요?',ARRAY['SO3-2-u2-X17']::text[],false,'{"seq":1,"concept":"SO3-2-u2-C6","difficulty":1,"kind":"mc","stem":"옛날 사람들이 설날 아침에 복주머니를 옷에 차고 다닌 까닭은 무엇인가요?","options":[{"t":"복이 들어온다는 좋은 뜻이 있었기 때문이에요","correct":true},{"t":"여름을 시원하게 보내려고요","mis":"SO3-2-u2-X17"},{"t":"나쁜 기운을 쫓으려고 창포를 넣었어요","mis":"SO3-2-u2-X17"},{"t":"장을 볼 돈을 넣어 다니려고요","mis":"SO3-2-u2-X17"}],"explanation":["복주머니의 이름을 봐요.","복이 들어와요.","좋은 뜻이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L06_basic#2','soc',3,2,'u2','L06','tb_g3_2_soc_u2_L06_basic','lesson_basic','SO3-2-u2-C6',1,'sa','auto','윷놀이할 때 필요한 것은 윷, 윷판, 그리고 무엇인가요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SO3-2-u2-C6","difficulty":1,"kind":"sa","stem":"윷놀이할 때 필요한 것은 윷, 윷판, 그리고 무엇인가요? 두 글자로 쓰세요.","answer":["윷말"],"explanation":["판 위에서 움직여요.","윷◯이에요.","윷말이에요."],"mis":"SO3-2-u2-X18"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L06_basic#3','soc',3,2,'u2','L06','tb_g3_2_soc_u2_L06_basic','lesson_basic','SO3-2-u2-C6',1,'mc','auto','86쪽 그림 해설에서 주로 옛날에 궁중이나 양반집에서 즐기던 놀이는 무엇인가요?',ARRAY['SO3-2-u2-X18']::text[],true,'{"seq":3,"concept":"SO3-2-u2-C6","difficulty":1,"kind":"mc","stem":"86쪽 그림 해설에서 주로 옛날에 궁중이나 양반집에서 즐기던 놀이는 무엇인가요?","options":[{"t":"투호","correct":true},{"t":"제기차기","mis":"SO3-2-u2-X18"},{"t":"윷놀이","mis":"SO3-2-u2-X18"},{"t":"고누","mis":"SO3-2-u2-X18"}],"explanation":["그림 ⑤예요.","화살을 던져요.","투호예요."],"asset":{"type":"passage","lines":["그림 ① 복주머니를 만들어요.","그림 ② 윷놀이를 해요.","그림 ③ 제기차기를 해요.","그림 ④ 고누를 해요.","그림 ⑤ 투호를 해요."],"numbered":false,"title":"『사회』 86쪽 — 옛날부터 전해 내려오는 풍습 체험"},"variant_rule":{"alt":[{"stem":"86쪽 그림 해설에서 주로 겨울에 즐기던 놀이는 무엇인가요?","options":[{"t":"제기차기","correct":true},{"t":"투호","mis":"SO3-2-u2-X18"},{"t":"고누","mis":"SO3-2-u2-X18"},{"t":"강강술래","mis":"SO3-2-u2-X11"}],"explanation":["그림 ③이에요.","발로 차요.","제기차기예요."],"asset":{"type":"passage","lines":["그림 ① 복주머니를 만들어요.","그림 ② 윷놀이를 해요.","그림 ③ 제기차기를 해요.","그림 ④ 고누를 해요.","그림 ⑤ 투호를 해요."],"numbered":false,"title":"『사회』 86쪽 — 옛날부터 전해 내려오는 풍습 체험"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L06_basic#4','soc',3,2,'u2','L06','tb_g3_2_soc_u2_L06_basic','lesson_basic','SO3-2-u2-C6',1,'ox','auto','오늘날에도 설날에 복이 들어오기를 바라며 복주머니를 선물하기도 해요.',ARRAY['SO3-2-u2-X02']::text[],false,'{"seq":4,"concept":"SO3-2-u2-C6","difficulty":1,"kind":"ox","stem":"오늘날에도 설날에 복이 들어오기를 바라며 복주머니를 선물하기도 해요.","answer":"O","reason_options":[{"t":"『사회』 87쪽 말풍선처럼 오늘날에도 이어지는 풍습이기 때문에","correct":true},{"t":"복주머니는 옛날에만 쓰던 물건이라 오늘날에는 볼 수 없기 때문에","mis":"SO3-2-u2-X02"}],"mis":"SO3-2-u2-X02","explanation":["87쪽 말풍선이에요.","오늘날에도 선물해요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L06_basic#5','soc',3,2,'u2','L06','tb_g3_2_soc_u2_L06_basic','lesson_basic','SO3-2-u2-C6',2,'blank','auto','복주머니 만드는 차례에서 빈 2단계에 알맞은 것은 무엇인가요?',ARRAY['SO3-2-u2-X17']::text[],false,'{"seq":5,"concept":"SO3-2-u2-C6","difficulty":2,"kind":"blank","stem":"복주머니 만드는 차례에서 빈 2단계에 알맞은 것은 무엇인가요?","options":[{"t":"도안에 색칠하고 복주머니 모양으로 뜯어요","correct":true},{"t":"리본이나 끈으로 손잡이를 만들어요","mis":"SO3-2-u2-X17"},{"t":"완성한 복주머니를 친구에게 선물해요","mis":"SO3-2-u2-X17"},{"t":"도안에 풀을 발라 모양을 만들어요","mis":"SO3-2-u2-X17"}],"explanation":["1단계는 준비예요.","3단계는 풀칠이에요.","그 사이는 색칠하고 뜯기예요."],"asset":{"type":"passage","lines":["1 「복주머니 만들기」 활동 자료를 뜯어 준비해요.","2 (                    )","3 도안에 풀을 발라 복주머니 모양을 만들어요.","4 리본이나 끈으로 복주머니 손잡이를 만들어 완성해요."],"numbered":false,"title":"『사회』 87쪽 — 복주머니 만들기(한 단계 비움)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L06_basic#6','soc',3,2,'u2','L06','tb_g3_2_soc_u2_L06_basic','lesson_basic','SO3-2-u2-C6',2,'match','auto','전통 놀이와 놀이에 필요한 것을 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"SO3-2-u2-C6","difficulty":2,"kind":"match","stem":"전통 놀이와 놀이에 필요한 것을 알맞게 이으세요.","pairs":[{"l":"윷놀이","r":"윷, 윷판, 윷말"},{"l":"제기차기","r":"제기"},{"l":"투호","r":"투호 병과 화살"},{"l":"고누","r":"고누판과 말"}],"mis":"SO3-2-u2-X18","explanation":["윷놀이는 윷이에요.","제기차기는 제기, 투호는 병과 화살이에요.","고누는 고누판이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L06_basic#7','soc',3,2,'u2','L06','tb_g3_2_soc_u2_L06_basic','lesson_basic','SO3-2-u2-C6',2,'mc','auto','윷놀이 방법에서 한 번 더 던지는 때는 언제인가요?',ARRAY['SO3-2-u2-X18']::text[],false,'{"seq":7,"concept":"SO3-2-u2-C6","difficulty":2,"kind":"mc","stem":"윷놀이 방법에서 한 번 더 던지는 때는 언제인가요?","options":[{"t":"윷 또는 모가 나오거나 상대편 윷말을 잡았을 때","correct":true},{"t":"도나 개가 나왔을 때","mis":"SO3-2-u2-X18"},{"t":"내 윷말이 출발점에 들어왔을 때","mis":"SO3-2-u2-X18"},{"t":"상대편 윷말이 내 윷말을 잡았을 때","mis":"SO3-2-u2-X18"}],"explanation":["넷째 줄을 봐요.","윷, 모, 잡기예요.","그때 한 번 더 던져요."],"asset":{"type":"passage","lines":["· 윷판을 펼쳐 놓고 편을 둘로 나눠요.","· 각각의 편은 윷말을 네 개씩 나누어 가져요.","· 윷을 던져 나온 결과(도, 개, 걸, 윷, 모)에 따라 윷말을 움직여요.","· 윷 또는 모가 나오거나 상대편 윷말을 잡으면 한 번 더 던져요.","· 네 개의 윷말이 먼저 출발점으로 들어오면 이겨요."],"title":"『사회』 88쪽 — 윷놀이 방법"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L06_basic#8','soc',3,2,'u2','L06','tb_g3_2_soc_u2_L06_basic','lesson_basic','SO3-2-u2-C6',2,'blank','auto','「투호는 일정한 거리에 투호 항아리나 병을 놓고, 그 속에 (    )을 던져 넣은 개수로 승부를 가리는 놀이예요.」 빈칸에 알맞은 말은?',ARRAY['SO3-2-u2-X18']::text[],false,'{"seq":8,"concept":"SO3-2-u2-C6","difficulty":2,"kind":"blank","stem":"「투호는 일정한 거리에 투호 항아리나 병을 놓고, 그 속에 (    )을 던져 넣은 개수로 승부를 가리는 놀이예요.」 빈칸에 알맞은 말은?","options":[{"t":"화살","correct":true},{"t":"제기","mis":"SO3-2-u2-X18"},{"t":"윷","mis":"SO3-2-u2-X18"},{"t":"고누 말","mis":"SO3-2-u2-X18"}],"explanation":["병에 던져 넣어요.","들어간 개수를 세요.","화살이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L06_basic#9','soc',3,2,'u2','L06','tb_g3_2_soc_u2_L06_basic','lesson_basic','SO3-2-u2-C6',2,'ox','auto','모둠 친구들과 전통 놀이를 체험할 때는 안전에 유의하고 규칙을 잘 지켜야 해요.',ARRAY['SO3-2-u2-X18']::text[],false,'{"seq":9,"concept":"SO3-2-u2-C6","difficulty":2,"kind":"ox","stem":"모둠 친구들과 전통 놀이를 체험할 때는 안전에 유의하고 규칙을 잘 지켜야 해요.","answer":"O","reason_options":[{"t":"『사회』 89쪽 말풍선처럼 친구들과 함께 안전하게 즐겨야 하기 때문에","correct":true},{"t":"전통 놀이는 옛날 놀이라서 규칙이 없기 때문에","mis":"SO3-2-u2-X18"}],"mis":"SO3-2-u2-X18","explanation":["89쪽 말풍선이에요.","규칙이 있어요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L06_basic#10','soc',3,2,'u2','L06','tb_g3_2_soc_u2_L06_basic','lesson_basic','SO3-2-u2-C6',3,'error','auto','모둠에서 전통 놀이 방법을 조사해 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO3-2-u2-X18']::text[],false,'{"seq":10,"concept":"SO3-2-u2-C6","difficulty":3,"kind":"error","stem":"모둠에서 전통 놀이 방법을 조사해 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 나 — 「고누는 제기가 바닥에 떨어지지 않게 발로 차는 놀이야.」","correct":true,"mis_target":"SO3-2-u2-X18"},{"t":"친구 가 — 「제기차기는 한 발 또는 양발로 제기를 툭툭 차는 놀이야.」","mis":"SO3-2-u2-X18"},{"t":"친구 다 — 「고누는 판에서 말을 옮기며 상대 말을 따거나 가두는 놀이야.」","mis":"SO3-2-u2-X18"}],"explanation":["제기는 제기차기예요.","고누는 판과 말이에요.","친구 나가 잘못 말했어요."],"asset":{"type":"speech","turns":[{"who":"친구 1","text":"다 같이 윷놀이를 하는 건 어때?"},{"who":"친구 2","text":"고누는 어떻게 하는 거지?"},{"who":"친구 3","text":"난 제기차기를 해 보고 싶어."},{"who":"친구 4","text":"편을 나누어 투호를 해 볼까?"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L06_challenge#1','soc',3,2,'u2','L06','tb_g3_2_soc_u2_L06_challenge','lesson_challenge','SO3-2-u2-C6',2,'sa','auto','어린이들에게 전통 놀이를 가르쳐 주고 체험 활동을 진행하는 직업을 무엇이라고 하나요?','{}'::text[],false,'{"seq":1,"concept":"SO3-2-u2-C6","difficulty":2,"kind":"sa","stem":"어린이들에게 전통 놀이를 가르쳐 주고 체험 활동을 진행하는 직업을 무엇이라고 하나요?","answer":["전통 놀이 지도사","전통놀이지도사","전래 놀이 지도사","전래놀이지도사"],"explanation":["90쪽 직업이에요.","전통 놀이 ◯◯◯예요.","전통 놀이 지도사예요."],"mis":"SO3-2-u2-X18"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L06_challenge#2','soc',3,2,'u2','L06','tb_g3_2_soc_u2_L06_challenge','lesson_challenge','SO3-2-u2-C6',2,'mc','auto','옛날에는 땅바닥이나 널판에 그렸던 고누판을 오늘날에는 어디에 그려서 할 수 있나요?',ARRAY['SO3-2-u2-X18','SO3-2-u2-X02']::text[],false,'{"seq":2,"concept":"SO3-2-u2-C6","difficulty":2,"kind":"mc","stem":"옛날에는 땅바닥이나 널판에 그렸던 고누판을 오늘날에는 어디에 그려서 할 수 있나요?","options":[{"t":"종이","correct":true},{"t":"윷판 위","mis":"SO3-2-u2-X18"},{"t":"고누는 오늘날 할 수 없어요","mis":"SO3-2-u2-X02"},{"t":"물 위","mis":"SO3-2-u2-X18"}],"explanation":["고누판과 말이 필요해요.","오늘날에는 쉽게 그려요.","종이예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L06_challenge#3','soc',3,2,'u2','L06','tb_g3_2_soc_u2_L06_challenge','lesson_challenge','SO3-2-u2-C6',3,'mc','auto','윷놀이에서 이기는 방법은 무엇인가요?',ARRAY['SO3-2-u2-X18']::text[],false,'{"seq":3,"concept":"SO3-2-u2-C6","difficulty":3,"kind":"mc","stem":"윷놀이에서 이기는 방법은 무엇인가요?","options":[{"t":"네 개의 윷말이 먼저 출발점으로 들어오면 이겨요","correct":true},{"t":"윷말 하나만 먼저 들어오면 이겨요","mis":"SO3-2-u2-X18"},{"t":"화살을 많이 던져 넣으면 이겨요","mis":"SO3-2-u2-X18"},{"t":"상대편 윷말을 모두 가두면 이겨요","mis":"SO3-2-u2-X18"}],"explanation":["마지막 줄이에요.","네 개 모두예요.","먼저 들어오면 이겨요."],"asset":{"type":"passage","lines":["· 윷판을 펼쳐 놓고 편을 둘로 나눠요.","· 각각의 편은 윷말을 네 개씩 나누어 가져요.","· 윷을 던져 나온 결과(도, 개, 걸, 윷, 모)에 따라 윷말을 움직여요.","· 윷 또는 모가 나오거나 상대편 윷말을 잡으면 한 번 더 던져요.","· 네 개의 윷말이 먼저 출발점으로 들어오면 이겨요."],"title":"『사회』 88쪽 — 윷놀이 방법"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L06_challenge#4','soc',3,2,'u2','L06','tb_g3_2_soc_u2_L06_challenge','lesson_challenge','SO3-2-u2-C6',3,'mc','auto','88~89쪽 친구와 활동의 차례로 알맞은 것은 무엇인가요?',ARRAY['SO3-2-u2-X18']::text[],false,'{"seq":4,"concept":"SO3-2-u2-C6","difficulty":3,"kind":"mc","stem":"88~89쪽 친구와 활동의 차례로 알맞은 것은 무엇인가요?","options":[{"t":"체험할 놀이 정하기 → 놀이 준비물과 방법 조사하기 → 모둠 친구들과 체험하기 → 느낀 점 쓰기","correct":true},{"t":"느낀 점 쓰기 → 체험하기 → 놀이 정하기 → 조사하기","mis":"SO3-2-u2-X18"},{"t":"조사하기 → 느낀 점 쓰기 → 놀이 정하기 → 체험하기","mis":"SO3-2-u2-X18"},{"t":"체험하기 → 놀이 정하기 → 느낀 점 쓰기 → 조사하기","mis":"SO3-2-u2-X18"}],"explanation":["먼저 정해요.","조사하고 체험해요.","마지막에 느낀 점이에요."],"asset":{"type":"speech","turns":[{"who":"친구 1","text":"다 같이 윷놀이를 하는 건 어때?"},{"who":"친구 2","text":"고누는 어떻게 하는 거지?"},{"who":"친구 3","text":"난 제기차기를 해 보고 싶어."},{"who":"친구 4","text":"편을 나누어 투호를 해 볼까?"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L06_challenge#5','soc',3,2,'u2','L06','tb_g3_2_soc_u2_L06_challenge','lesson_challenge','SO3-2-u2-C6',3,'ox','auto','전통 놀이 지도사는 명절에 하던 놀이만 가르치고 고누, 투호, 제기차기 같은 평소의 놀이는 다루지 않아요.',ARRAY['SO3-2-u2-X18']::text[],false,'{"seq":5,"concept":"SO3-2-u2-C6","difficulty":3,"kind":"ox","stem":"전통 놀이 지도사는 명절에 하던 놀이만 가르치고 고누, 투호, 제기차기 같은 평소의 놀이는 다루지 않아요.","answer":"X","reason_options":[{"t":"명절 놀이와 평소에 하던 놀이를 모두 알리고, 오늘날 놀이와 결합해 새 놀이도 만들기 때문에","correct":true},{"t":"전통 놀이는 모두 명절에만 하는 놀이이기 때문에","mis":"SO3-2-u2-X18"}],"mis":"SO3-2-u2-X18","explanation":["90쪽 글이에요.","평소에 하던 놀이도 있어요.","그래서 X예요."],"asset":{"type":"passage","lines":["전통 놀이 지도사(전래 놀이 지도사)는 어린이들에게 전통 놀이를 가르쳐 주고 체험 활동을 진행해요.","명절에 하던 놀이(윷놀이, 강강술래)와 평소에 하던 놀이(고누, 투호, 제기차기)를 알려요.","우리 전통 놀이와 오늘날 놀이를 결합해 창의적인 놀이를 만들기도 해요.","필요한 것: 전통 놀이 지식과 이해력, 소통하는 능력, 창의적인 기획 능력, 전통문화에 관한 애정과 관심"],"title":"『사회』 90쪽 별별 직업 속으로 — 전통 놀이 지도사"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L06_challenge#6','soc',3,2,'u2','L06','tb_g3_2_soc_u2_L06_challenge','lesson_challenge','SO3-2-u2-C6',3,'match','auto','86쪽 그림 해설을 보고 놀이와 설명을 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"SO3-2-u2-C6","difficulty":3,"kind":"match","stem":"86쪽 그림 해설을 보고 놀이와 설명을 알맞게 이으세요.","pairs":[{"l":"윷놀이","r":"주로 설날에 즐기던 놀이"},{"l":"제기차기","r":"주로 겨울에 즐기던 놀이"},{"l":"고누","r":"주로 바깥에서 즐겼고, 방법과 종류가 다양한 놀이"},{"l":"투호","r":"주로 궁중이나 양반집에서 즐기던 놀이"}],"mis":"SO3-2-u2-X18","explanation":["윷놀이는 설날이에요.","제기는 겨울, 고누는 바깥이에요.","투호는 궁중이에요."],"asset":{"type":"passage","lines":["그림 ① 복주머니를 만들어요.","그림 ② 윷놀이를 해요.","그림 ③ 제기차기를 해요.","그림 ④ 고누를 해요.","그림 ⑤ 투호를 해요."],"numbered":false,"title":"『사회』 86쪽 — 옛날부터 전해 내려오는 풍습 체험"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L06_challenge#7','soc',3,2,'u2','L06','tb_g3_2_soc_u2_L06_challenge','lesson_challenge','SO3-2-u2-C6',3,'error','auto','복주머니를 만든 뒤 느낀 점을 나누었어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO3-2-u2-X17','SO3-2-u2-X02']::text[],false,'{"seq":7,"concept":"SO3-2-u2-C6","difficulty":3,"kind":"error","stem":"복주머니를 만든 뒤 느낀 점을 나누었어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 가 — 「복주머니는 여름을 시원하게 보내라고 주고받던 물건이래.」","correct":true,"mis_target":"SO3-2-u2-X17"},{"t":"친구 나 — 「복이 들어온다는 뜻으로 설날 아침 옷에 차고 다녔대.」","mis":"SO3-2-u2-X17"},{"t":"친구 다 — 「오늘날에도 설날에 복주머니를 선물하기도 한대.」","mis":"SO3-2-u2-X02"}],"explanation":["여름 선물은 부채예요.","복주머니는 설날이에요.","친구 가가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L06_challenge#8','soc',3,2,'u2','L06','tb_g3_2_soc_u2_L06_challenge','lesson_challenge','SO3-2-u2-C6',4,'mc','auto','전통 놀이 지도사가 되려면 무엇보다 중요한 것은 무엇이라고 했나요?',ARRAY['SO3-2-u2-X18']::text[],false,'{"seq":8,"concept":"SO3-2-u2-C6","difficulty":4,"kind":"mc","stem":"전통 놀이 지도사가 되려면 무엇보다 중요한 것은 무엇이라고 했나요?","options":[{"t":"우리 전통문화에 관한 애정과 관심","correct":true},{"t":"오늘날 놀이를 하나도 모르는 것","mis":"SO3-2-u2-X18"},{"t":"혼자서만 놀이하는 습관","mis":"SO3-2-u2-X18"},{"t":"명절 놀이만 아는 것","mis":"SO3-2-u2-X18"}],"explanation":["90쪽 마지막 문장이에요.","「무엇보다」를 찾아요.","애정과 관심이에요."],"asset":{"type":"passage","lines":["전통 놀이 지도사(전래 놀이 지도사)는 어린이들에게 전통 놀이를 가르쳐 주고 체험 활동을 진행해요.","명절에 하던 놀이(윷놀이, 강강술래)와 평소에 하던 놀이(고누, 투호, 제기차기)를 알려요.","우리 전통 놀이와 오늘날 놀이를 결합해 창의적인 놀이를 만들기도 해요.","필요한 것: 전통 놀이 지식과 이해력, 소통하는 능력, 창의적인 기획 능력, 전통문화에 관한 애정과 관심"],"title":"『사회』 90쪽 별별 직업 속으로 — 전통 놀이 지도사"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L06_challenge#9','soc',3,2,'u2','L06','tb_g3_2_soc_u2_L06_challenge','lesson_challenge','SO3-2-u2-C6',4,'ox','auto','옛날부터 전해 내려오는 풍습을 체험하면 옛날 사람들의 생활과 생각을 떠올릴 수 있어요.',ARRAY['SO3-2-u2-X06']::text[],false,'{"seq":9,"concept":"SO3-2-u2-C6","difficulty":4,"kind":"ox","stem":"옛날부터 전해 내려오는 풍습을 체험하면 옛날 사람들의 생활과 생각을 떠올릴 수 있어요.","answer":"O","reason_options":[{"t":"복주머니와 전통 놀이에 옛날 사람들의 바람과 즐거움이 담겨 있기 때문에","correct":true},{"t":"체험은 재미만 있을 뿐 옛날 사람들과는 관계가 없기 때문에","mis":"SO3-2-u2-X06"}],"mis":"SO3-2-u2-X06","explanation":["86쪽 첫 글이에요.","생활과 생각을 떠올려요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L06_challenge#10','soc',3,2,'u2','L06','tb_g3_2_soc_u2_L06_challenge','lesson_challenge','SO3-2-u2-C6',4,'essay','teacher','전통 놀이 하나를 골라 준비물과 놀이 방법을 소개하고, 체험한 뒤 느낀 점을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO3-2-u2-C6","difficulty":4,"kind":"essay","stem":"전통 놀이 하나를 골라 준비물과 놀이 방법을 소개하고, 체험한 뒤 느낀 점을 쓰세요.","answer_guide":{"answer":"예: 제기차기 — 준비물은 제기예요. 제기를 띄우고 바닥에 떨어지지 않게 발로 차며, 더 많이 찬 사람이 이겨요. 친구들과 편을 나누어 해 보니 재미있었고 다리 운동도 되었어요.","scoring_points":["준비물을 썼는가","놀이 방법을 썼는가","느낀 점을 썼는가"]},"explanation":["놀이를 골라요.","준비물과 방법이에요.","느낀 점을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L07_basic#1','soc',3,2,'u2','L07','tb_g3_2_soc_u2_L07_basic','lesson_basic','SO3-2-u2-C7',1,'mc','auto','91쪽 만화 1에서 동생이 시험을 앞둔 누나에게 준 것은 무엇인가요?',ARRAY['SO3-2-u2-X19']::text[],true,'{"seq":1,"concept":"SO3-2-u2-C7","difficulty":1,"kind":"mc","stem":"91쪽 만화 1에서 동생이 시험을 앞둔 누나에게 준 것은 무엇인가요?","options":[{"t":"엿","correct":true},{"t":"카네이션","mis":"SO3-2-u2-X19"},{"t":"복주머니","mis":"SO3-2-u2-X19"},{"t":"부채","mis":"SO3-2-u2-X19"}],"explanation":["만화 1이에요.","시험을 앞뒀어요.","엿이에요."],"asset":{"type":"passage","lines":["만화 1 — 동생이 시험을 앞둔 누나에게 엿을 주며 「이번 시험 잘 봐.」 하고 말해요.","만화 2 — 딸이 부모님께 감사하는 마음으로 카네이션을 만들어 달아 드려요."],"title":"『사회』 91쪽 — 미래에 전해 주고 싶은 오늘날 풍습 만화"},"variant_rule":{"alt":[{"stem":"91쪽 만화 2에서 딸이 부모님께 감사하는 마음으로 만들어 달아 드린 것은 무엇인가요?","options":[{"t":"카네이션","correct":true},{"t":"엿","mis":"SO3-2-u2-X19"},{"t":"버선","mis":"SO3-2-u2-X19"},{"t":"복조리","mis":"SO3-2-u2-X19"}],"explanation":["만화 2예요.","부모님께 감사해요.","카네이션이에요."],"asset":{"type":"passage","lines":["만화 1 — 동생이 시험을 앞둔 누나에게 엿을 주며 「이번 시험 잘 봐.」 하고 말해요.","만화 2 — 딸이 부모님께 감사하는 마음으로 카네이션을 만들어 달아 드려요."],"title":"『사회』 91쪽 — 미래에 전해 주고 싶은 오늘날 풍습 만화"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L07_basic#2','soc',3,2,'u2','L07','tb_g3_2_soc_u2_L07_basic','lesson_basic','SO3-2-u2-C7',1,'sa','auto','93쪽 숨은 수 찾기: 「동지는 태양의 움직임에 따라 나눈 (    )절기 중 하나입니다.」 빈칸의 수를 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SO3-2-u2-C7","difficulty":1,"kind":"sa","stem":"93쪽 숨은 수 찾기: 「동지는 태양의 움직임에 따라 나눈 (    )절기 중 하나입니다.」 빈칸의 수를 쓰세요.","answer":["24"],"explanation":["일 년을 나눴어요.","이십사예요.","24예요."],"mis":"SO3-2-u2-X47"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L07_basic#3','soc',3,2,'u2','L07','tb_g3_2_soc_u2_L07_basic','lesson_basic','SO3-2-u2-C7',1,'mc','auto','색칠판의 칸 가운데 옛날에 먹었던 세시 음식이 아닌 것은 무엇인가요?',ARRAY['SO3-2-u2-X12']::text[],false,'{"seq":3,"concept":"SO3-2-u2-C7","difficulty":1,"kind":"mc","stem":"색칠판의 칸 가운데 옛날에 먹었던 세시 음식이 아닌 것은 무엇인가요?","options":[{"t":"라면","correct":true},{"t":"떡국","mis":"SO3-2-u2-X12"},{"t":"수리취떡","mis":"SO3-2-u2-X12"},{"t":"팥죽","mis":"SO3-2-u2-X12"}],"explanation":["세시 음식을 떠올려요.","떡국, 수리취떡, 팥죽은 세시 음식이에요.","라면이에요."],"asset":{"type":"passage","lines":["떡국 · 버선 선물 · 연날리기 · 축구 · 쥐불놀이 · 미역국 · 차례 · 장례식","술래잡기 · 줄넘기 · 널뛰기 · 빵 · 세배 · 잡채 · 수리취떡 · 책 읽기","윷놀이 · 씨름 · 부럼 · 금줄 치기 · 다리밟기 · 오곡밥 · 그네뛰기 · 달맞이","강강술래 · 김장 · 품앗이 · 달리기 · 돌잔치 · 우유 선물 · 부채 선물 · 밤 까기","달집태우기 · 소싸움 · 송편 · 결혼식 · 라면 · 회갑잔치 · 팥죽 · 머리 감기"],"title":"『사회』 93쪽 재미있게 확인해요 — 색칠판의 칸"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L07_basic#4','soc',3,2,'u2','L07','tb_g3_2_soc_u2_L07_basic','lesson_basic','SO3-2-u2-C7',1,'ox','auto','시험 보는 사람에게 엿을 주는 풍습에는 합격을 기원하는 마음이 담겨 있어요.',ARRAY['SO3-2-u2-X19']::text[],false,'{"seq":4,"concept":"SO3-2-u2-C7","difficulty":1,"kind":"ox","stem":"시험 보는 사람에게 엿을 주는 풍습에는 합격을 기원하는 마음이 담겨 있어요.","answer":"O","reason_options":[{"t":"시험 점수가 높게 나오기를 바라고 합격을 기원하는 마음으로 주기 때문에","correct":true},{"t":"엿은 그냥 간식이라 담긴 뜻이 없기 때문에","mis":"SO3-2-u2-X19"}],"mis":"SO3-2-u2-X19","explanation":["91쪽 예시예요.","합격을 바라요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L07_basic#5','soc',3,2,'u2','L07','tb_g3_2_soc_u2_L07_basic','lesson_basic','SO3-2-u2-C7',2,'mc','auto','색칠판에서 옛날 명절이나 절기에 하던 일로 색칠할 칸은 무엇인가요?',ARRAY['SO3-2-u2-X11']::text[],false,'{"seq":5,"concept":"SO3-2-u2-C7","difficulty":2,"kind":"mc","stem":"색칠판에서 옛날 명절이나 절기에 하던 일로 색칠할 칸은 무엇인가요?","options":[{"t":"쥐불놀이","correct":true},{"t":"축구","mis":"SO3-2-u2-X11"},{"t":"줄넘기","mis":"SO3-2-u2-X11"},{"t":"책 읽기","mis":"SO3-2-u2-X11"}],"explanation":["정월 대보름을 떠올려요.","쥐불놀이를 했어요.","쥐불놀이예요."],"asset":{"type":"passage","lines":["떡국 · 버선 선물 · 연날리기 · 축구 · 쥐불놀이 · 미역국 · 차례 · 장례식","술래잡기 · 줄넘기 · 널뛰기 · 빵 · 세배 · 잡채 · 수리취떡 · 책 읽기","윷놀이 · 씨름 · 부럼 · 금줄 치기 · 다리밟기 · 오곡밥 · 그네뛰기 · 달맞이","강강술래 · 김장 · 품앗이 · 달리기 · 돌잔치 · 우유 선물 · 부채 선물 · 밤 까기","달집태우기 · 소싸움 · 송편 · 결혼식 · 라면 · 회갑잔치 · 팥죽 · 머리 감기"],"title":"『사회』 93쪽 재미있게 확인해요 — 색칠판의 칸"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L07_basic#6','soc',3,2,'u2','L07','tb_g3_2_soc_u2_L07_basic','lesson_basic','SO3-2-u2-C7',2,'match','auto','오늘날 볼 수 있는 풍습과 담긴 뜻을 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"SO3-2-u2-C7","difficulty":2,"kind":"match","stem":"오늘날 볼 수 있는 풍습과 담긴 뜻을 알맞게 이으세요.","pairs":[{"l":"시험 보는 사람에게 엿 주기","r":"시험을 잘 보고 합격하기를 바라는 마음"},{"l":"어버이날 카네이션 달아 드리기","r":"부모님의 사랑에 감사하는 마음"},{"l":"설날 복주머니 선물하기","r":"복이 들어오기를 바라는 마음"}],"mis":"SO3-2-u2-X19","explanation":["엿은 합격이에요.","카네이션은 감사예요.","복주머니는 복이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L07_basic#7','soc',3,2,'u2','L07','tb_g3_2_soc_u2_L07_basic','lesson_basic','SO3-2-u2-C7',2,'mc','auto','플라잉 디스크 윷놀이에서 윷 대신 던지는 것은 무엇인가요?',ARRAY['SO3-2-u2-X18']::text[],false,'{"seq":7,"concept":"SO3-2-u2-C7","difficulty":2,"kind":"mc","stem":"플라잉 디스크 윷놀이에서 윷 대신 던지는 것은 무엇인가요?","options":[{"t":"플라잉 디스크","correct":true},{"t":"제기","mis":"SO3-2-u2-X18"},{"t":"투호 화살","mis":"SO3-2-u2-X18"},{"t":"고누 말","mis":"SO3-2-u2-X18"}],"explanation":["놀이 이름을 봐요.","윷 대신이에요.","플라잉 디스크예요."],"asset":{"type":"passage","lines":["새로운 놀이 이름 — 플라잉 디스크 윷놀이","전통 놀이 이름 — 윷놀이","도구 — 플라잉 디스크, 윷놀이 판, 말판","놀이 방법 — 윷 대신 플라잉 디스크를 던져 윷놀이 판에 적힌 글자를 통과하면 그 말을 옮겨요."],"title":"『사회』 92쪽 — 새로운 놀이 만들기 예시"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L07_basic#8','soc',3,2,'u2','L07','tb_g3_2_soc_u2_L07_basic','lesson_basic','SO3-2-u2-C7',2,'blank','auto','달리는 제기차기의 놀이 방법 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SO3-2-u2-X18']::text[],false,'{"seq":8,"concept":"SO3-2-u2-C7","difficulty":2,"kind":"blank","stem":"달리는 제기차기의 놀이 방법 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"안전 고깔(반환점)","correct":true},{"t":"윷판","mis":"SO3-2-u2-X18"},{"t":"투호 병","mis":"SO3-2-u2-X18"},{"t":"고누판","mis":"SO3-2-u2-X18"}],"explanation":["도구를 봐요.","돌아오는 곳이에요.","안전 고깔이에요."],"asset":{"type":"passage","lines":["새로운 놀이 이름 — 달리는 제기차기","전통 놀이 이름 — 제기차기","도구 — 제기, 안전 고깔(반환점)","놀이 방법 — 제기를 차면서 (    )을 돌아오는 경기로, 먼저 들어오면 이겨요."],"title":"새로운 놀이 만들기 — 또 다른 예시"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L07_basic#9','soc',3,2,'u2','L07','tb_g3_2_soc_u2_L07_basic','lesson_basic','SO3-2-u2-C7',2,'ox','auto','색칠판에서 금줄 치기와 돌잔치는 옛날 명절이나 절기에 하던 일이라 색칠해야 해요.',ARRAY['SO3-2-u2-X01']::text[],false,'{"seq":9,"concept":"SO3-2-u2-C7","difficulty":2,"kind":"ox","stem":"색칠판에서 금줄 치기와 돌잔치는 옛날 명절이나 절기에 하던 일이라 색칠해야 해요.","answer":"X","reason_options":[{"t":"금줄 치기와 돌잔치는 일상생활 속 풍습이지 세시 풍속이 아니기 때문에","correct":true},{"t":"옛날 풍습은 모두 명절에 하던 일이기 때문에","mis":"SO3-2-u2-X01"}],"mis":"SO3-2-u2-X01","explanation":["언제 하는 일인지 봐요.","태어날 때와 첫돌이에요.","그래서 X예요."],"asset":{"type":"passage","lines":["떡국 · 버선 선물 · 연날리기 · 축구 · 쥐불놀이 · 미역국 · 차례 · 장례식","술래잡기 · 줄넘기 · 널뛰기 · 빵 · 세배 · 잡채 · 수리취떡 · 책 읽기","윷놀이 · 씨름 · 부럼 · 금줄 치기 · 다리밟기 · 오곡밥 · 그네뛰기 · 달맞이","강강술래 · 김장 · 품앗이 · 달리기 · 돌잔치 · 우유 선물 · 부채 선물 · 밤 까기","달집태우기 · 소싸움 · 송편 · 결혼식 · 라면 · 회갑잔치 · 팥죽 · 머리 감기"],"title":"『사회』 93쪽 재미있게 확인해요 — 색칠판의 칸"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L07_basic#10','soc',3,2,'u2','L07','tb_g3_2_soc_u2_L07_basic','lesson_basic','SO3-2-u2-C7',3,'error','auto','만화로 표현할 풍습을 정하며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO3-2-u2-X02','SO3-2-u2-X19']::text[],false,'{"seq":10,"concept":"SO3-2-u2-C7","difficulty":3,"kind":"error","stem":"만화로 표현할 풍습을 정하며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「미래에 전해 줄 풍습은 옛날 것이어야 하니 오늘날 생활 모습은 고를 수 없어.」","correct":true,"mis_target":"SO3-2-u2-X02"},{"t":"친구 가 — 「어버이날 카네이션을 다는 풍습을 그리고 싶어.」","mis":"SO3-2-u2-X19"},{"t":"친구 나 — 「시험 보는 누나에게 엿을 주는 장면을 그릴래.」","mis":"SO3-2-u2-X19"}],"explanation":["91쪽 활동 이름을 봐요.","오늘날 생활 모습 가운데 골라요.","친구 다가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L07_challenge#1','soc',3,2,'u2','L07','tb_g3_2_soc_u2_L07_challenge','lesson_challenge','SO3-2-u2-C7',2,'sa','auto','색칠판의 세시 음식 가운데 정월 대보름에 다섯 가지 곡식으로 지어 먹은 밥을 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"SO3-2-u2-C7","difficulty":2,"kind":"sa","stem":"색칠판의 세시 음식 가운데 정월 대보름에 다섯 가지 곡식으로 지어 먹은 밥을 쓰세요.","answer":["오곡밥"],"explanation":["다섯 가지 곡식이에요.","오◯◯이에요.","오곡밥이에요."],"mis":"SO3-2-u2-X12"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L07_challenge#2','soc',3,2,'u2','L07','tb_g3_2_soc_u2_L07_challenge','lesson_challenge','SO3-2-u2-C7',2,'mc','auto','「새로운 놀이 만들기」 활동지에 쓰는 칸이 아닌 것은 무엇인가요?',ARRAY['SO3-2-u2-X18']::text[],false,'{"seq":2,"concept":"SO3-2-u2-C7","difficulty":2,"kind":"mc","stem":"「새로운 놀이 만들기」 활동지에 쓰는 칸이 아닌 것은 무엇인가요?","options":[{"t":"담긴 뜻","correct":true},{"t":"새로운 놀이 이름","mis":"SO3-2-u2-X18"},{"t":"전통 놀이 이름","mis":"SO3-2-u2-X18"},{"t":"놀이 방법","mis":"SO3-2-u2-X18"}],"explanation":["92쪽 칸을 봐요.","담긴 뜻은 만화 활동 칸이에요.","담긴 뜻이에요."],"asset":{"type":"passage","lines":["새로운 놀이 이름 — 플라잉 디스크 윷놀이","전통 놀이 이름 — 윷놀이","도구 — 플라잉 디스크, 윷놀이 판, 말판","놀이 방법 — 윷 대신 플라잉 디스크를 던져 윷놀이 판에 적힌 글자를 통과하면 그 말을 옮겨요."],"title":"『사회』 92쪽 — 새로운 놀이 만들기 예시"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L07_challenge#3','soc',3,2,'u2','L07','tb_g3_2_soc_u2_L07_challenge','lesson_challenge','SO3-2-u2-C7',3,'mc','auto','색칠판에서 세시 음식과 명절·절기에 하던 일을 모두 색칠했을 때 색칠하지 않는 칸끼리 묶은 것은 무엇인가요?',ARRAY['SO3-2-u2-X12','SO3-2-u2-X11']::text[],false,'{"seq":3,"concept":"SO3-2-u2-C7","difficulty":3,"kind":"mc","stem":"색칠판에서 세시 음식과 명절·절기에 하던 일을 모두 색칠했을 때 색칠하지 않는 칸끼리 묶은 것은 무엇인가요?","options":[{"t":"미역국, 김장, 결혼식","correct":true},{"t":"떡국, 송편, 팥죽","mis":"SO3-2-u2-X12"},{"t":"씨름, 그네뛰기, 강강술래","mis":"SO3-2-u2-X11"},{"t":"세배, 차례, 달맞이","mis":"SO3-2-u2-X11"}],"explanation":["세시 풍속을 찾아요.","미역국, 김장, 결혼식은 일상생활 속 풍습이에요.","그 칸들이에요."],"asset":{"type":"passage","lines":["떡국 · 버선 선물 · 연날리기 · 축구 · 쥐불놀이 · 미역국 · 차례 · 장례식","술래잡기 · 줄넘기 · 널뛰기 · 빵 · 세배 · 잡채 · 수리취떡 · 책 읽기","윷놀이 · 씨름 · 부럼 · 금줄 치기 · 다리밟기 · 오곡밥 · 그네뛰기 · 달맞이","강강술래 · 김장 · 품앗이 · 달리기 · 돌잔치 · 우유 선물 · 부채 선물 · 밤 까기","달집태우기 · 소싸움 · 송편 · 결혼식 · 라면 · 회갑잔치 · 팥죽 · 머리 감기"],"title":"『사회』 93쪽 재미있게 확인해요 — 색칠판의 칸"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L07_challenge#4','soc',3,2,'u2','L07','tb_g3_2_soc_u2_L07_challenge','lesson_challenge','SO3-2-u2-C7',3,'mc','auto','플라잉 디스크 윷놀이는 윷놀이에서 무엇을 바꾸어 만든 놀이인가요?',ARRAY['SO3-2-u2-X18']::text[],false,'{"seq":4,"concept":"SO3-2-u2-C7","difficulty":3,"kind":"mc","stem":"플라잉 디스크 윷놀이는 윷놀이에서 무엇을 바꾸어 만든 놀이인가요?","options":[{"t":"윷 대신 플라잉 디스크를 던지고, 판의 글자를 통과하면 말을 옮기게 했어요","correct":true},{"t":"윷판과 말판을 모두 없앴어요","mis":"SO3-2-u2-X18"},{"t":"혼자서만 할 수 있게 했어요","mis":"SO3-2-u2-X18"},{"t":"이기고 지는 규칙을 없앴어요","mis":"SO3-2-u2-X18"}],"explanation":["도구가 바뀌었어요.","방법이 바뀌었어요.","윷판은 그대로예요."],"asset":{"type":"passage","lines":["새로운 놀이 이름 — 플라잉 디스크 윷놀이","전통 놀이 이름 — 윷놀이","도구 — 플라잉 디스크, 윷놀이 판, 말판","놀이 방법 — 윷 대신 플라잉 디스크를 던져 윷놀이 판에 적힌 글자를 통과하면 그 말을 옮겨요."],"title":"『사회』 92쪽 — 새로운 놀이 만들기 예시"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L07_challenge#5','soc',3,2,'u2','L07','tb_g3_2_soc_u2_L07_challenge','lesson_challenge','SO3-2-u2-C7',3,'ox','auto','오늘날 생활 모습 가운데에도 미래에 이어질 필요가 있는 좋은 풍습이 있어요.',ARRAY['SO3-2-u2-X02']::text[],false,'{"seq":5,"concept":"SO3-2-u2-C7","difficulty":3,"kind":"ox","stem":"오늘날 생활 모습 가운데에도 미래에 이어질 필요가 있는 좋은 풍습이 있어요.","answer":"O","reason_options":[{"t":"어버이날 카네이션처럼 오늘날 풍습에도 좋은 마음이 담겨 있기 때문에","correct":true},{"t":"풍습은 옛날 것만 해당해서 오늘날 생활 모습은 풍습이 될 수 없기 때문에","mis":"SO3-2-u2-X02"}],"mis":"SO3-2-u2-X02","explanation":["91쪽 선택 활동이에요.","오늘날 풍습도 있어요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L07_challenge#6','soc',3,2,'u2','L07','tb_g3_2_soc_u2_L07_challenge','lesson_challenge','SO3-2-u2-C7',3,'match','auto','세시 음식과 그 음식을 먹던 명절이나 절기를 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"SO3-2-u2-C7","difficulty":3,"kind":"match","stem":"세시 음식과 그 음식을 먹던 명절이나 절기를 알맞게 이으세요.","pairs":[{"l":"떡국","r":"설날"},{"l":"오곡밥","r":"정월 대보름"},{"l":"수리취떡","r":"단오"},{"l":"송편","r":"추석"},{"l":"팥죽","r":"동지"}],"mis":"SO3-2-u2-X11","explanation":["떡국은 설날이에요.","오곡밥은 대보름, 수리취떡은 단오예요.","송편은 추석, 팥죽은 동지예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L07_challenge#7','soc',3,2,'u2','L07','tb_g3_2_soc_u2_L07_challenge','lesson_challenge','SO3-2-u2-C7',3,'error','auto','「옛날과 오늘날의 풍습」을 정리하며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO3-2-u2-X02','SO3-2-u2-X15','SO3-2-u2-X19']::text[],false,'{"seq":7,"concept":"SO3-2-u2-C7","difficulty":3,"kind":"error","stem":"「옛날과 오늘날의 풍습」을 정리하며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 나 — 「풍습에는 생활과 생각이 담겨 있지만 오늘날까지 이어지는 것은 없어.」","correct":true,"mis_target":"SO3-2-u2-X02"},{"t":"친구 가 — 「떡국 먹기와 송편 빚기는 오늘날까지 이어져.」","mis":"SO3-2-u2-X15"},{"t":"친구 다 — 「어버이날 카네이션처럼 오늘날 풍습에도 마음이 담겨 있어.」","mis":"SO3-2-u2-X19"}],"explanation":["이어지는 풍습이 있어요.","떡국과 송편이에요.","친구 나가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L07_challenge#8','soc',3,2,'u2','L07','tb_g3_2_soc_u2_L07_challenge','lesson_challenge','SO3-2-u2-C7',4,'mc','auto','「옛날과 오늘날의 풍습」 주제에서 공부한 내용을 가장 잘 정리한 것은 무엇인가요?',ARRAY['SO3-2-u2-X02','SO3-2-u2-X44','SO3-2-u2-X06']::text[],false,'{"seq":8,"concept":"SO3-2-u2-C7","difficulty":4,"kind":"mc","stem":"「옛날과 오늘날의 풍습」 주제에서 공부한 내용을 가장 잘 정리한 것은 무엇인가요?","options":[{"t":"풍습에는 사람들의 생활과 생각이 담겨 있고, 변화하며 이어지는 풍습과 사라져 가는 풍습이 있어요","correct":true},{"t":"옛날 풍습은 모두 사라졌어요","mis":"SO3-2-u2-X02"},{"t":"풍습은 바뀌지 않고 그대로 전해져요","mis":"SO3-2-u2-X44"},{"t":"풍습에 담긴 마음은 시대마다 없어졌어요","mis":"SO3-2-u2-X06"}],"explanation":["담긴 생활과 생각이에요.","이어지는 풍습이 있어요.","사라져 가는 풍습도 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L07_challenge#9','soc',3,2,'u2','L07','tb_g3_2_soc_u2_L07_challenge','lesson_challenge','SO3-2-u2-C7',4,'essay','teacher','오늘날 생활 습관이나 모습 가운데 미래에 전해 주고 싶은 풍습을 하나 골라 풍습 설명과 담긴 뜻을 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"SO3-2-u2-C7","difficulty":4,"kind":"essay","stem":"오늘날 생활 습관이나 모습 가운데 미래에 전해 주고 싶은 풍습을 하나 골라 풍습 설명과 담긴 뜻을 쓰세요.","answer_guide":{"answer":"예: 풍습 설명 — 어버이날 부모님께 카네이션을 선물하는 풍습이에요. 담긴 뜻 — 부모님의 사랑에 감사하는 마음이 담겨 있어요.","scoring_points":["풍습 하나를 골랐는가","풍습을 설명했는가","담긴 뜻을 썼는가"]},"explanation":["오늘날 풍습을 골라요.","설명을 써요.","담긴 뜻을 써요."],"asset":{"type":"passage","lines":["만화 1 — 동생이 시험을 앞둔 누나에게 엿을 주며 「이번 시험 잘 봐.」 하고 말해요.","만화 2 — 딸이 부모님께 감사하는 마음으로 카네이션을 만들어 달아 드려요."],"title":"『사회』 91쪽 — 미래에 전해 주고 싶은 오늘날 풍습 만화"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L07_challenge#10','soc',3,2,'u2','L07','tb_g3_2_soc_u2_L07_challenge','lesson_challenge','SO3-2-u2-C7',4,'essay','teacher','전통 놀이 하나에 새로운 도구나 오늘날 놀이를 더해 새로운 놀이를 만들고, 놀이 이름·도구·놀이 방법을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO3-2-u2-C7","difficulty":4,"kind":"essay","stem":"전통 놀이 하나에 새로운 도구나 오늘날 놀이를 더해 새로운 놀이를 만들고, 놀이 이름·도구·놀이 방법을 쓰세요.","answer_guide":{"answer":"예: 새로운 놀이 이름 — 달리는 제기차기 / 전통 놀이 — 제기차기 / 도구 — 제기, 안전 고깔 / 방법 — 제기를 차면서 반환점을 돌아오고, 먼저 들어오면 이겨요.","scoring_points":["전통 놀이를 바탕으로 했는가","도구를 썼는가","놀이 방법을 썼는가"]},"explanation":["전통 놀이를 골라요.","새 도구를 더해요.","방법을 써요."],"asset":{"type":"passage","lines":["새로운 놀이 이름 — 플라잉 디스크 윷놀이","전통 놀이 이름 — 윷놀이","도구 — 플라잉 디스크, 윷놀이 판, 말판","놀이 방법 — 윷 대신 플라잉 디스크를 던져 윷놀이 판에 적힌 글자를 통과하면 그 말을 옮겨요."],"title":"『사회』 92쪽 — 새로운 놀이 만들기 예시"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L08_basic#1','soc',3,2,'u2','L08','tb_g3_2_soc_u2_L08_basic','lesson_basic','SO3-2-u2-C8',1,'mc','auto','명절에 먼 곳의 친척을 만나러 가거나 주문한 물건을 받는 것처럼, 어떤 장소에서 다른 장소로 사람이 이동하거나 물건을 옮기는 것을 무엇이라고 하나요?',ARRAY['SO3-2-u2-X20']::text[],true,'{"seq":1,"concept":"SO3-2-u2-C8","difficulty":1,"kind":"mc","stem":"명절에 먼 곳의 친척을 만나러 가거나 주문한 물건을 받는 것처럼, 어떤 장소에서 다른 장소로 사람이 이동하거나 물건을 옮기는 것을 무엇이라고 하나요?","options":[{"t":"교통","correct":true},{"t":"교통수단","mis":"SO3-2-u2-X20"},{"t":"교통로","mis":"SO3-2-u2-X20"},{"t":"여행","mis":"SO3-2-u2-X20"}],"explanation":["95쪽 첫 글이에요.","이동하고 옮겨요.","교통이에요."],"variant_rule":{"alt":[{"stem":"사람이 이동하거나 물건을 옮길 때 사용하는 도구를 무엇이라고 하나요?","options":[{"t":"교통수단","correct":true},{"t":"교통","mis":"SO3-2-u2-X20"},{"t":"교통로","mis":"SO3-2-u2-X20"},{"t":"교통 시설","mis":"SO3-2-u2-X26"}],"explanation":["95쪽 낱말이에요.","도구예요.","교통수단이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L08_basic#2','soc',3,2,'u2','L08','tb_g3_2_soc_u2_L08_basic','lesson_basic','SO3-2-u2-C8',1,'sa','auto','하늘에 비행기가 다니도록 정해진 길을 무엇이라고 하나요? 세 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SO3-2-u2-C8","difficulty":1,"kind":"sa","stem":"하늘에 비행기가 다니도록 정해진 길을 무엇이라고 하나요? 세 글자로 쓰세요.","answer":["항공로"],"explanation":["하늘에도 길이 있어요.","항◯◯예요.","항공로예요."],"mis":"SO3-2-u2-X21"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L08_basic#3','soc',3,2,'u2','L08','tb_g3_2_soc_u2_L08_basic','lesson_basic','SO3-2-u2-C8',1,'mc','auto','96쪽 사진에서 위험에 빠진 사람을 구할 때 이용하는 교통수단은 무엇인가요?',ARRAY['SO3-2-u2-X22']::text[],true,'{"seq":3,"concept":"SO3-2-u2-C8","difficulty":1,"kind":"mc","stem":"96쪽 사진에서 위험에 빠진 사람을 구할 때 이용하는 교통수단은 무엇인가요?","options":[{"t":"구조 헬기","correct":true},{"t":"케이블카","mis":"SO3-2-u2-X22"},{"t":"지게차","mis":"SO3-2-u2-X22"},{"t":"유람선","mis":"SO3-2-u2-X22"}],"explanation":["위험에 빠진 사람이에요.","하늘에서 빨리 가요.","구조 헬기예요."],"asset":{"type":"passage","lines":["지하철 — 다른 장소로 이동할 때","지게차와 트럭 — 많은 짐을 옮길 때","케이블카 — 높은 곳으로 이동하거나 경치를 구경할 때","여객선 — 강이나 바다에서 이동할 때","자전거 — 가까운 거리를 이동하거나 운동할 때","구조 헬기 — 위험에 빠진 사람을 구할 때"],"title":"『사회』 96쪽 — 필요에 따라 이용하는 교통수단"},"variant_rule":{"alt":[{"stem":"96쪽 사진에서 높은 곳으로 이동하거나 경치를 구경할 때 이용하는 교통수단은 무엇인가요?","options":[{"t":"케이블카","correct":true},{"t":"구조 헬기","mis":"SO3-2-u2-X22"},{"t":"트럭","mis":"SO3-2-u2-X22"},{"t":"지하철","mis":"SO3-2-u2-X22"}],"explanation":["높은 곳이에요.","경치를 봐요.","케이블카예요."],"asset":{"type":"passage","lines":["지하철 — 다른 장소로 이동할 때","지게차와 트럭 — 많은 짐을 옮길 때","케이블카 — 높은 곳으로 이동하거나 경치를 구경할 때","여객선 — 강이나 바다에서 이동할 때","자전거 — 가까운 거리를 이동하거나 운동할 때","구조 헬기 — 위험에 빠진 사람을 구할 때"],"title":"『사회』 96쪽 — 필요에 따라 이용하는 교통수단"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L08_basic#4','soc',3,2,'u2','L08','tb_g3_2_soc_u2_L08_basic','lesson_basic','SO3-2-u2-C8',1,'ox','auto','바다나 강처럼 물에도 배가 다니도록 정해진 수로가 있어요.',ARRAY['SO3-2-u2-X21']::text[],false,'{"seq":4,"concept":"SO3-2-u2-C8","difficulty":1,"kind":"ox","stem":"바다나 강처럼 물에도 배가 다니도록 정해진 수로가 있어요.","answer":"O","reason_options":[{"t":"도로나 철도처럼 구분되어 보이지는 않지만 배가 다니도록 정해진 길이 있기 때문에","correct":true},{"t":"물 위는 길이 보이지 않으니 교통로가 없기 때문에","mis":"SO3-2-u2-X21"}],"mis":"SO3-2-u2-X21","explanation":["95쪽 사진이에요.","수로가 있어요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L08_basic#5','soc',3,2,'u2','L08','tb_g3_2_soc_u2_L08_basic','lesson_basic','SO3-2-u2-C8',2,'match','auto','교통수단과 그 교통수단이 이용하는 교통로를 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"SO3-2-u2-C8","difficulty":2,"kind":"match","stem":"교통수단과 그 교통수단이 이용하는 교통로를 알맞게 이으세요.","pairs":[{"l":"마을버스","r":"도로"},{"l":"고속버스","r":"고속 국도"},{"l":"지하철","r":"철도"},{"l":"유람선","r":"바다나 강의 정해진 수로"}],"mis":"SO3-2-u2-X21","explanation":["버스는 도로예요.","지하철은 철도예요.","유람선은 수로예요."],"asset":{"type":"passage","lines":["마을버스 — 도로","고속버스 — 고속 국도","지하철 — 철도","자전거 — 자전거 도로","유람선 — 바다나 강의 정해진 수로","비행기 — 하늘의 항공로"],"title":"『사회』 95쪽 스스로 활동 — 교통수단과 교통로"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L08_basic#6','soc',3,2,'u2','L08','tb_g3_2_soc_u2_L08_basic','lesson_basic','SO3-2-u2-C8',2,'mc','auto','생각을 열어요 그림에서 실제로 보기 어려운 장면과 그 까닭을 바르게 짝지은 것은 무엇인가요?',ARRAY['SO3-2-u2-X21']::text[],false,'{"seq":6,"concept":"SO3-2-u2-C8","difficulty":2,"kind":"mc","stem":"생각을 열어요 그림에서 실제로 보기 어려운 장면과 그 까닭을 바르게 짝지은 것은 무엇인가요?","options":[{"t":"바다 위를 달리는 열차 — 열차는 철도로 다니기 때문이에요","correct":true},{"t":"하늘에 뜬 오토바이 — 오토바이는 항공로로 다니기 때문이에요","mis":"SO3-2-u2-X21"},{"t":"강 위의 자전거 — 자전거는 수로로 다니기 때문이에요","mis":"SO3-2-u2-X21"},{"t":"도로 위의 배 — 배는 고속 국도로 다니기 때문이에요","mis":"SO3-2-u2-X21"}],"explanation":["교통수단의 길을 떠올려요.","열차는 철도예요.","그 짝이에요."],"asset":{"type":"passage","lines":["도로 위에 배가 떠 있어요.","철도 위로 비행기가 지나가요.","바다 위를 열차가 달려요.","하늘에 오토바이가 떠 있어요.","강 위를 자전거가 달려요."],"title":"『사회』 94쪽 생각을 열어요 — 실제 모습으로 보기 어려운 장면들"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L08_basic#7','soc',3,2,'u2','L08','tb_g3_2_soc_u2_L08_basic','lesson_basic','SO3-2-u2-C8',2,'blank','auto','「교통은 주로 (    )를 따라 움직이는 교통수단에 의해 이루어집니다.」 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SO3-2-u2-X20','SO3-2-u2-X26']::text[],false,'{"seq":7,"concept":"SO3-2-u2-C8","difficulty":2,"kind":"blank","stem":"「교통은 주로 (    )를 따라 움직이는 교통수단에 의해 이루어집니다.」 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"교통로","correct":true},{"t":"교통","mis":"SO3-2-u2-X20"},{"t":"정거장","mis":"SO3-2-u2-X26"},{"t":"운전자","mis":"SO3-2-u2-X20"}],"explanation":["95쪽 글이에요.","교통수단은 길을 따라가요.","교통로예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L08_basic#8','soc',3,2,'u2','L08','tb_g3_2_soc_u2_L08_basic','lesson_basic','SO3-2-u2-C8',2,'mc','auto','교통의 예로 알맞은 것은 무엇인가요?',ARRAY['SO3-2-u2-X35','SO3-2-u2-X20']::text[],false,'{"seq":8,"concept":"SO3-2-u2-C8","difficulty":2,"kind":"mc","stem":"교통의 예로 알맞은 것은 무엇인가요?","options":[{"t":"집에서 주문한 음식이나 물건을 받아요","correct":true},{"t":"집에서 텔레비전으로 뉴스를 봐요","mis":"SO3-2-u2-X35"},{"t":"교실에서 책을 읽어요","mis":"SO3-2-u2-X20"},{"t":"방에서 숙제를 해요","mis":"SO3-2-u2-X20"}],"explanation":["물건이 옮겨 와요.","장소가 바뀌어요.","주문한 물건 받기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L08_basic#9','soc',3,2,'u2','L08','tb_g3_2_soc_u2_L08_basic','lesson_basic','SO3-2-u2-C8',2,'ox','auto','같은 교통수단이라도 이용하는 까닭이 다양할 수 있어요.',ARRAY['SO3-2-u2-X22']::text[],false,'{"seq":9,"concept":"SO3-2-u2-C8","difficulty":2,"kind":"ox","stem":"같은 교통수단이라도 이용하는 까닭이 다양할 수 있어요.","answer":"O","reason_options":[{"t":"자전거를 가까운 곳에 갈 때도, 운동할 때도 타는 것처럼 필요에 따라 쓰기 때문에","correct":true},{"t":"교통수단마다 이용하는 까닭이 꼭 한 가지로 정해져 있기 때문에","mis":"SO3-2-u2-X22"}],"mis":"SO3-2-u2-X22","explanation":["96쪽 말풍선이에요.","까닭이 여러 가지예요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L08_basic#10','soc',3,2,'u2','L08','tb_g3_2_soc_u2_L08_basic','lesson_basic','SO3-2-u2-C8',3,'error','auto','최근에 이용한 교통수단 표를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO3-2-u2-X22']::text[],false,'{"seq":10,"concept":"SO3-2-u2-C8","difficulty":3,"kind":"error","stem":"최근에 이용한 교통수단 표를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「교통수단은 사람만 옮기고 물건은 옮기지 않아.」","correct":true,"mis_target":"SO3-2-u2-X22"},{"t":"친구 가 — 「진은 지하철로 영화관에 가려고 다른 장소로 이동했어.」","mis":"SO3-2-u2-X22"},{"t":"친구 나 — 「자전거를 타고 친구를 만나러 갈 수 있어.」","mis":"SO3-2-u2-X22"}],"explanation":["지게차와 트럭을 떠올려요.","물건도 옮겨요.","친구 다가 잘못 말했어요."],"asset":{"type":"passage","lines":["진 — 지하철 / 지난주 토요일 / 가족과 영화관에 가려고","박□□ — 자전거 / 어제 오후 / 친구를 만나러 갈 때","조◇◇ — 승용차 / △△일 / 병원에 갈 때"],"title":"『사회』 96쪽 친구와 활동 — 최근에 이용한 교통수단"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L08_challenge#1','soc',3,2,'u2','L08','tb_g3_2_soc_u2_L08_challenge','lesson_challenge','SO3-2-u2-C8',2,'sa','auto','도로, 철도, 수로, 항공로처럼 교통에 이용하는 길을 무엇이라고 하나요? 세 글자로 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"SO3-2-u2-C8","difficulty":2,"kind":"sa","stem":"도로, 철도, 수로, 항공로처럼 교통에 이용하는 길을 무엇이라고 하나요? 세 글자로 쓰세요.","answer":["교통로"],"explanation":["교통의 길이에요.","교통◯예요.","교통로예요."],"mis":"SO3-2-u2-X20"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L08_challenge#2','soc',3,2,'u2','L08','tb_g3_2_soc_u2_L08_challenge','lesson_challenge','SO3-2-u2-C8',2,'mc','auto','물에서 다니는 교통수단 가운데 물속으로 다니는 것은 무엇인가요?',ARRAY['SO3-2-u2-X21']::text[],false,'{"seq":2,"concept":"SO3-2-u2-C8","difficulty":2,"kind":"mc","stem":"물에서 다니는 교통수단 가운데 물속으로 다니는 것은 무엇인가요?","options":[{"t":"잠수함","correct":true},{"t":"헬리콥터","mis":"SO3-2-u2-X21"},{"t":"고속버스","mis":"SO3-2-u2-X21"},{"t":"케이블카","mis":"SO3-2-u2-X21"}],"explanation":["물속이에요.","물 위가 아니에요.","잠수함이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L08_challenge#3','soc',3,2,'u2','L08','tb_g3_2_soc_u2_L08_challenge','lesson_challenge','SO3-2-u2-C8',3,'mc','auto','생각을 열어요 그림을 실제 모습에 맞게 고칠 때 바르게 고친 것은 무엇인가요?',ARRAY['SO3-2-u2-X21']::text[],false,'{"seq":3,"concept":"SO3-2-u2-C8","difficulty":3,"kind":"mc","stem":"생각을 열어요 그림을 실제 모습에 맞게 고칠 때 바르게 고친 것은 무엇인가요?","options":[{"t":"비행기는 철도가 아니라 하늘의 항공로로 다니게 해요","correct":true},{"t":"열차는 바다 위를 달려도 괜찮아요","mis":"SO3-2-u2-X21"},{"t":"배는 도로로 옮겨 다니게 해요","mis":"SO3-2-u2-X21"},{"t":"자전거는 강 위의 수로로 다니게 해요","mis":"SO3-2-u2-X21"}],"explanation":["실제 상황을 기준으로 해요.","비행기는 하늘로 다녀요.","항공로예요."],"asset":{"type":"passage","lines":["도로 위에 배가 떠 있어요.","철도 위로 비행기가 지나가요.","바다 위를 열차가 달려요.","하늘에 오토바이가 떠 있어요.","강 위를 자전거가 달려요."],"title":"『사회』 94쪽 생각을 열어요 — 실제 모습으로 보기 어려운 장면들"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L08_challenge#4','soc',3,2,'u2','L08','tb_g3_2_soc_u2_L08_challenge','lesson_challenge','SO3-2-u2-C8',3,'mc','auto','생활의 필요에 따라 이용하는 교통수단으로 알맞은 것은 무엇인가요?',ARRAY['SO3-2-u2-X22']::text[],false,'{"seq":4,"concept":"SO3-2-u2-C8","difficulty":3,"kind":"mc","stem":"생활의 필요에 따라 이용하는 교통수단으로 알맞은 것은 무엇인가요?","options":[{"t":"농사지을 때 — 트랙터, 경운기","correct":true},{"t":"농사지을 때 — 구조 헬기","mis":"SO3-2-u2-X22"},{"t":"길에 쌓인 눈을 치울 때 — 케이블카","mis":"SO3-2-u2-X22"},{"t":"경치를 구경할 때 — 지게차","mis":"SO3-2-u2-X22"}],"explanation":["필요를 먼저 봐요.","농사에는 농사용 차가 필요해요.","트랙터, 경운기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L08_challenge#5','soc',3,2,'u2','L08','tb_g3_2_soc_u2_L08_challenge','lesson_challenge','SO3-2-u2-C8',3,'ox','auto','하늘에는 길이 보이지 않으니 비행기는 아무 곳으로나 날아다녀요.',ARRAY['SO3-2-u2-X20']::text[],false,'{"seq":5,"concept":"SO3-2-u2-C8","difficulty":3,"kind":"ox","stem":"하늘에는 길이 보이지 않으니 비행기는 아무 곳으로나 날아다녀요.","answer":"X","reason_options":[{"t":"하늘에도 보이지 않지만 비행기가 다니도록 정해진 항공로가 있기 때문에","correct":true},{"t":"교통로는 눈에 보이는 길만 말하기 때문에","mis":"SO3-2-u2-X20"}],"mis":"SO3-2-u2-X20","explanation":["95쪽 말풍선이에요.","항공로가 있어요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L08_challenge#6','soc',3,2,'u2','L08','tb_g3_2_soc_u2_L08_challenge','lesson_challenge','SO3-2-u2-C8',3,'match','auto','교통과 관련된 세 낱말과 그 뜻을 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"SO3-2-u2-C8","difficulty":3,"kind":"match","stem":"교통과 관련된 세 낱말과 그 뜻을 알맞게 이으세요.","pairs":[{"l":"교통","r":"어떤 장소에서 다른 장소로 사람이 이동하거나 물건이 옮겨 가는 것"},{"l":"교통수단","r":"자동차, 기차, 배, 비행기처럼 이동하거나 옮길 때 쓰는 도구"},{"l":"교통로","r":"도로, 철도, 수로, 항공로처럼 교통에 이용하는 길"}],"mis":"SO3-2-u2-X20","explanation":["교통은 이동이에요.","교통수단은 도구예요.","교통로는 길이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L08_challenge#7','soc',3,2,'u2','L08','tb_g3_2_soc_u2_L08_challenge','lesson_challenge','SO3-2-u2-C8',3,'error','auto','교통수단을 이용하는 까닭을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO3-2-u2-X22']::text[],false,'{"seq":7,"concept":"SO3-2-u2-C8","difficulty":3,"kind":"error","stem":"교통수단을 이용하는 까닭을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 가 — 「여객선은 높은 곳으로 올라가 경치를 볼 때 이용해.」","correct":true,"mis_target":"SO3-2-u2-X22"},{"t":"친구 나 — 「지게차와 트럭은 많은 짐을 옮길 때 이용해.」","mis":"SO3-2-u2-X22"},{"t":"친구 다 — 「자전거는 가까운 거리를 이동하거나 운동할 때 이용해.」","mis":"SO3-2-u2-X22"}],"explanation":["여객선은 물에서 다녀요.","강이나 바다에서 이동해요.","친구 가가 잘못 말했어요."],"asset":{"type":"passage","lines":["지하철 — 다른 장소로 이동할 때","지게차와 트럭 — 많은 짐을 옮길 때","케이블카 — 높은 곳으로 이동하거나 경치를 구경할 때","여객선 — 강이나 바다에서 이동할 때","자전거 — 가까운 거리를 이동하거나 운동할 때","구조 헬기 — 위험에 빠진 사람을 구할 때"],"title":"『사회』 96쪽 — 필요에 따라 이용하는 교통수단"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L08_challenge#8','soc',3,2,'u2','L08','tb_g3_2_soc_u2_L08_challenge','lesson_challenge','SO3-2-u2-C8',4,'mc','auto','교통의 뜻을 가장 바르게 설명한 것은 무엇인가요?',ARRAY['SO3-2-u2-X22','SO3-2-u2-X20']::text[],false,'{"seq":8,"concept":"SO3-2-u2-C8","difficulty":4,"kind":"mc","stem":"교통의 뜻을 가장 바르게 설명한 것은 무엇인가요?","options":[{"t":"명절에 친척을 만나러 가는 것도, 주문한 물건이 집에 오는 것도 모두 교통이에요","correct":true},{"t":"사람이 탈것을 타는 것만 교통이에요","mis":"SO3-2-u2-X22"},{"t":"물건이 오가는 것만 교통이에요","mis":"SO3-2-u2-X22"},{"t":"길을 만드는 일만 교통이에요","mis":"SO3-2-u2-X20"}],"explanation":["95쪽 첫 글이에요.","사람과 물건 모두예요.","둘 다 교통이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L08_challenge#9','soc',3,2,'u2','L08','tb_g3_2_soc_u2_L08_challenge','lesson_challenge','SO3-2-u2-C8',4,'ox','auto','교통은 주로 교통로를 따라 움직이는 교통수단에 의해 이루어져요.',ARRAY['SO3-2-u2-X20']::text[],false,'{"seq":9,"concept":"SO3-2-u2-C8","difficulty":4,"kind":"ox","stem":"교통은 주로 교통로를 따라 움직이는 교통수단에 의해 이루어져요.","answer":"O","reason_options":[{"t":"자동차는 도로로, 열차는 철도로, 배는 수로로 다니며 사람과 물건을 옮기기 때문에","correct":true},{"t":"교통수단과 교통로는 서로 관계가 없기 때문에","mis":"SO3-2-u2-X20"}],"mis":"SO3-2-u2-X20","explanation":["교통수단과 교통로예요.","함께 교통을 이뤄요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L08_challenge#10','soc',3,2,'u2','L08','tb_g3_2_soc_u2_L08_challenge','lesson_challenge','SO3-2-u2-C8',4,'essay','teacher','최근에 이용한 교통수단을 하나 쓰고, 이용한 때와 까닭, 그 교통수단이 다니는 교통로를 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO3-2-u2-C8","difficulty":4,"kind":"essay","stem":"최근에 이용한 교통수단을 하나 쓰고, 이용한 때와 까닭, 그 교통수단이 다니는 교통로를 쓰세요.","answer_guide":{"answer":"예: 지난 주말에 가족과 할아버지 댁에 가려고 기차를 탔어요. 기차는 철도로 다녀요.","scoring_points":["교통수단을 썼는가","이용한 때와 까닭을 썼는가","알맞은 교통로를 썼는가"]},"explanation":["교통수단을 떠올려요.","때와 까닭이에요.","교통로를 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L09_basic#1','soc',3,2,'u2','L09','tb_g3_2_soc_u2_L09_basic','lesson_basic','SO3-2-u2-C9',1,'mc','auto','옛날 사람들은 다른 곳으로 가거나 물건을 옮길 때 주로 어떻게 이동했나요?',ARRAY['SO3-2-u2-X24']::text[],false,'{"seq":1,"concept":"SO3-2-u2-C9","difficulty":1,"kind":"mc","stem":"옛날 사람들은 다른 곳으로 가거나 물건을 옮길 때 주로 어떻게 이동했나요?","options":[{"t":"주로 걸어서 이동했어요","correct":true},{"t":"주로 자동차를 탔어요","mis":"SO3-2-u2-X24"},{"t":"주로 비행기를 탔어요","mis":"SO3-2-u2-X24"},{"t":"주로 지하철을 탔어요","mis":"SO3-2-u2-X24"}],"explanation":["97쪽 첫 글이에요.","주로 걸었어요.","교통수단도 썼어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L09_basic#2','soc',3,2,'u2','L09','tb_g3_2_soc_u2_L09_basic','lesson_basic','SO3-2-u2-C9',1,'sa','auto','소나 말이 끄는 수레로 무거운 짐을 옮긴 옛날 교통수단을 무엇이라고 하나요? 세 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SO3-2-u2-C9","difficulty":1,"kind":"sa","stem":"소나 말이 끄는 수레로 무거운 짐을 옮긴 옛날 교통수단을 무엇이라고 하나요? 세 글자로 쓰세요.","answer":["달구지"],"explanation":["소나 말이 끌어요.","달◯◯예요.","달구지예요."],"mis":"SO3-2-u2-X23"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L09_basic#3','soc',3,2,'u2','L09','tb_g3_2_soc_u2_L09_basic','lesson_basic','SO3-2-u2-C9',1,'mc','auto','사람을 태우고 가마꾼이 들어 옮긴 옛날 교통수단은 무엇인가요?',ARRAY['SO3-2-u2-X23']::text[],true,'{"seq":3,"concept":"SO3-2-u2-C9","difficulty":1,"kind":"mc","stem":"사람을 태우고 가마꾼이 들어 옮긴 옛날 교통수단은 무엇인가요?","options":[{"t":"가마","correct":true},{"t":"뗏목","mis":"SO3-2-u2-X23"},{"t":"나룻배","mis":"SO3-2-u2-X23"},{"t":"달구지","mis":"SO3-2-u2-X23"}],"explanation":["가마꾼이 들어요.","사람을 태워요.","가마예요."],"asset":{"type":"passage","lines":["말 — 먼 거리를 이동하거나 빨리 갈 때 타고 다녔어요.","뗏목 — 통나무 여러 개를 이어 붙여 만들고, 긴 막대기로 밀어 강을 건넜어요.","달구지 — 소나 말이 끄는 수레를 이용해 무거운 짐을 옮겼어요.","돛단배 — 바람의 힘을 이용하는 돛을 달고 강이나 바다를 건넜어요.","가마 — 사람을 태우고 가마꾼이 가마를 들어 옮겼어요.","나룻배 — 사람과 짐을 싣고 주로 노를 저어 강의 양쪽을 오갔어요."],"title":"『사회』 97~98쪽 — 옛날 교통수단"},"variant_rule":{"alt":[{"stem":"통나무 여러 개를 이어 붙여 만들고 긴 막대기로 밀어 강을 건넌 옛날 교통수단은 무엇인가요?","options":[{"t":"뗏목","correct":true},{"t":"가마","mis":"SO3-2-u2-X23"},{"t":"돛단배","mis":"SO3-2-u2-X23"},{"t":"말","mis":"SO3-2-u2-X23"}],"explanation":["통나무예요.","막대기로 밀어요.","뗏목이에요."],"asset":{"type":"passage","lines":["말 — 먼 거리를 이동하거나 빨리 갈 때 타고 다녔어요.","뗏목 — 통나무 여러 개를 이어 붙여 만들고, 긴 막대기로 밀어 강을 건넜어요.","달구지 — 소나 말이 끄는 수레를 이용해 무거운 짐을 옮겼어요.","돛단배 — 바람의 힘을 이용하는 돛을 달고 강이나 바다를 건넜어요.","가마 — 사람을 태우고 가마꾼이 가마를 들어 옮겼어요.","나룻배 — 사람과 짐을 싣고 주로 노를 저어 강의 양쪽을 오갔어요."],"title":"『사회』 97~98쪽 — 옛날 교통수단"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L09_basic#4','soc',3,2,'u2','L09','tb_g3_2_soc_u2_L09_basic','lesson_basic','SO3-2-u2-C9',1,'ox','auto','옛날 교통수단은 나무나 풀의 줄기 등 자연에서 쉽게 얻을 수 있는 재료로 만들었어요.',ARRAY['SO3-2-u2-X24']::text[],false,'{"seq":4,"concept":"SO3-2-u2-C9","difficulty":1,"kind":"ox","stem":"옛날 교통수단은 나무나 풀의 줄기 등 자연에서 쉽게 얻을 수 있는 재료로 만들었어요.","answer":"O","reason_options":[{"t":"『사회』 97쪽처럼 주변 자연에서 얻은 재료로 만들었기 때문에","correct":true},{"t":"옛날 교통수단은 공장에서 쇠로 만들었기 때문에","mis":"SO3-2-u2-X24"}],"mis":"SO3-2-u2-X24","explanation":["재료의 공통점이에요.","자연에서 얻었어요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L09_basic#5','soc',3,2,'u2','L09','tb_g3_2_soc_u2_L09_basic','lesson_basic','SO3-2-u2-C9',2,'mc','auto','옛날 교통수단을 움직이는 힘으로 알맞은 것끼리 묶은 것은 무엇인가요?',ARRAY['SO3-2-u2-X24']::text[],false,'{"seq":5,"concept":"SO3-2-u2-C9","difficulty":2,"kind":"mc","stem":"옛날 교통수단을 움직이는 힘으로 알맞은 것끼리 묶은 것은 무엇인가요?","options":[{"t":"사람, 동물, 바람","correct":true},{"t":"석유, 전기, 가스","mis":"SO3-2-u2-X24"},{"t":"사람, 석유, 바람","mis":"SO3-2-u2-X24"},{"t":"동물, 전기, 바람","mis":"SO3-2-u2-X24"}],"explanation":["98쪽 스스로 활동이에요.","석유, 전기, 가스는 아니에요.","사람, 동물, 바람이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L09_basic#6','soc',3,2,'u2','L09','tb_g3_2_soc_u2_L09_basic','lesson_basic','SO3-2-u2-C9',2,'match','auto','옛날 교통수단과 쓰임을 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"SO3-2-u2-C9","difficulty":2,"kind":"match","stem":"옛날 교통수단과 쓰임을 알맞게 이으세요.","pairs":[{"l":"말","r":"먼 거리를 이동하거나 빨리 갈 때"},{"l":"달구지","r":"무거운 짐을 옮길 때"},{"l":"돛단배","r":"바람의 힘으로 강이나 바다를 건널 때"},{"l":"나룻배","r":"노를 저어 강의 양쪽을 오갈 때"}],"mis":"SO3-2-u2-X23","explanation":["말은 빨리 가요.","달구지는 짐, 돛단배는 바람이에요.","나룻배는 노예요."],"asset":{"type":"passage","lines":["말 — 먼 거리를 이동하거나 빨리 갈 때 타고 다녔어요.","뗏목 — 통나무 여러 개를 이어 붙여 만들고, 긴 막대기로 밀어 강을 건넜어요.","달구지 — 소나 말이 끄는 수레를 이용해 무거운 짐을 옮겼어요.","돛단배 — 바람의 힘을 이용하는 돛을 달고 강이나 바다를 건넜어요.","가마 — 사람을 태우고 가마꾼이 가마를 들어 옮겼어요.","나룻배 — 사람과 짐을 싣고 주로 노를 저어 강의 양쪽을 오갔어요."],"title":"『사회』 97~98쪽 — 옛날 교통수단"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L09_basic#7','soc',3,2,'u2','L09','tb_g3_2_soc_u2_L09_basic','lesson_basic','SO3-2-u2-C9',2,'mc','auto','돛단배는 나룻배와 무엇이 다른가요?',ARRAY['SO3-2-u2-X24','SO3-2-u2-X23']::text[],false,'{"seq":7,"concept":"SO3-2-u2-C9","difficulty":2,"kind":"mc","stem":"돛단배는 나룻배와 무엇이 다른가요?","options":[{"t":"돛단배에는 바람의 힘을 이용하는 돛이 달려 있어요","correct":true},{"t":"나룻배는 석유의 힘으로 움직여요","mis":"SO3-2-u2-X24"},{"t":"돛단배는 땅 위로 다녀요","mis":"SO3-2-u2-X23"},{"t":"둘은 다른 점이 없어요","mis":"SO3-2-u2-X23"}],"explanation":["이름을 봐요.","돛이 있어요.","바람을 이용해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L09_basic#8','soc',3,2,'u2','L09','tb_g3_2_soc_u2_L09_basic','lesson_basic','SO3-2-u2-C9',2,'blank','auto','「증기 기차와 증기선은 물을 끓이면 생기는 (    )의 힘으로 움직여요.」 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SO3-2-u2-X25','SO3-2-u2-X24']::text[],false,'{"seq":8,"concept":"SO3-2-u2-C9","difficulty":2,"kind":"blank","stem":"「증기 기차와 증기선은 물을 끓이면 생기는 (    )의 힘으로 움직여요.」 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"수증기","correct":true},{"t":"바람","mis":"SO3-2-u2-X25"},{"t":"석유","mis":"SO3-2-u2-X25"},{"t":"사람","mis":"SO3-2-u2-X24"}],"explanation":["물을 끓여요.","증기예요.","수증기예요."],"asset":{"type":"passage","lines":["증기 기차, 증기선 — 물을 끓이면 생기는 수증기의 힘으로 움직여요.","자동차, 프로펠러 비행기 — 석유의 힘으로 움직여요.","사람들은 이전보다 더 먼 곳을 더 빠르고 편하게 이동하게 됐어요."],"title":"『사회』 99쪽 — 과학 기술이 발달하면서 생겨난 교통수단"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L09_basic#9','soc',3,2,'u2','L09','tb_g3_2_soc_u2_L09_basic','lesson_basic','SO3-2-u2-C9',2,'ox','auto','옛날에도 사람들이 많이 다녀서 자연스럽게 생긴 길이나 강을 교통로로 이용했어요.',ARRAY['SO3-2-u2-X48']::text[],false,'{"seq":9,"concept":"SO3-2-u2-C9","difficulty":2,"kind":"ox","stem":"옛날에도 사람들이 많이 다녀서 자연스럽게 생긴 길이나 강을 교통로로 이용했어요.","answer":"O","reason_options":[{"t":"『사회』 97쪽 말풍선처럼 옛날에도 교통로가 있었기 때문에","correct":true},{"t":"옛날에는 교통로가 하나도 없었기 때문에","mis":"SO3-2-u2-X48"}],"mis":"SO3-2-u2-X48","explanation":["97쪽 말풍선이에요.","길과 강이에요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L09_basic#10','soc',3,2,'u2','L09','tb_g3_2_soc_u2_L09_basic','lesson_basic','SO3-2-u2-C9',3,'error','auto','97~98쪽 옛날 교통수단 사진을 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO3-2-u2-X48','SO3-2-u2-X23']::text[],false,'{"seq":10,"concept":"SO3-2-u2-C9","difficulty":3,"kind":"error","stem":"97~98쪽 옛날 교통수단 사진을 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 가 — 「옛날 사람들은 교통수단이 없어서 모두 걸어서만 다녔어.」","correct":true,"mis_target":"SO3-2-u2-X48"},{"t":"친구 나 — 「말은 먼 거리를 빨리 갈 때 탔어.」","mis":"SO3-2-u2-X23"},{"t":"친구 다 — 「가마는 가마꾼이 들어 옮겼어.」","mis":"SO3-2-u2-X23"}],"explanation":["주로 걸었지만 교통수단도 썼어요.","말, 가마, 배가 있었어요.","친구 가가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L09_challenge#1','soc',3,2,'u2','L09','tb_g3_2_soc_u2_L09_challenge','lesson_challenge','SO3-2-u2-C9',2,'sa','auto','과학 기술이 발달하면서 만든 자동차와 비행기는 무엇의 힘으로 움직였나요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"SO3-2-u2-C9","difficulty":2,"kind":"sa","stem":"과학 기술이 발달하면서 만든 자동차와 비행기는 무엇의 힘으로 움직였나요? 두 글자로 쓰세요.","answer":["석유"],"explanation":["99쪽 말풍선이에요.","석◯예요.","석유예요."],"mis":"SO3-2-u2-X25"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L09_challenge#2','soc',3,2,'u2','L09','tb_g3_2_soc_u2_L09_challenge','lesson_challenge','SO3-2-u2-C9',2,'mc','auto','97쪽 사진 속 「비 내린 다음 날에는 흙길이 젖어서 불편하군.」이라는 말로 알 수 있는 것은 무엇인가요?',ARRAY['SO3-2-u2-X48','SO3-2-u2-X24','SO3-2-u2-X23']::text[],false,'{"seq":2,"concept":"SO3-2-u2-C9","difficulty":2,"kind":"mc","stem":"97쪽 사진 속 「비 내린 다음 날에는 흙길이 젖어서 불편하군.」이라는 말로 알 수 있는 것은 무엇인가요?","options":[{"t":"옛날 길은 날씨의 영향을 많이 받았어요","correct":true},{"t":"옛날에는 길이 하나도 없었어요","mis":"SO3-2-u2-X48"},{"t":"흙길은 기계로 만든 길이었어요","mis":"SO3-2-u2-X24"},{"t":"비가 오면 길이 더 편해졌어요","mis":"SO3-2-u2-X23"}],"explanation":["흙길이에요.","비가 오면 젖어요.","날씨의 영향이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L09_challenge#3','soc',3,2,'u2','L09','tb_g3_2_soc_u2_L09_challenge','lesson_challenge','SO3-2-u2-C9',3,'mc','auto','특징 세 가지를 모두 가진 옛날 교통수단은 무엇인가요?',ARRAY['SO3-2-u2-X23']::text[],false,'{"seq":3,"concept":"SO3-2-u2-C9","difficulty":3,"kind":"mc","stem":"특징 세 가지를 모두 가진 옛날 교통수단은 무엇인가요?","options":[{"t":"돛단배","correct":true},{"t":"가마","mis":"SO3-2-u2-X23"},{"t":"달구지","mis":"SO3-2-u2-X23"},{"t":"말","mis":"SO3-2-u2-X23"}],"explanation":["바람을 이용해요.","강이나 바다를 다녀요.","돛단배예요."],"asset":{"type":"passage","lines":["① 바람을 이용해요.","② 강이나 바다를 다녀요.","③ 사람이나 많은 짐을 싣고 다녀요."],"numbered":false,"title":"옛날 교통수단의 특징 세 가지"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L09_challenge#4','soc',3,2,'u2','L09','tb_g3_2_soc_u2_L09_challenge','lesson_challenge','SO3-2-u2-C9',3,'mc','auto','자연의 힘으로 교통수단을 움직이면 좋은 점으로 알맞은 것은 무엇인가요?',ARRAY['SO3-2-u2-X25','SO3-2-u2-X24','SO3-2-u2-X28']::text[],false,'{"seq":4,"concept":"SO3-2-u2-C9","difficulty":3,"kind":"mc","stem":"자연의 힘으로 교통수단을 움직이면 좋은 점으로 알맞은 것은 무엇인가요?","options":[{"t":"환경이 오염되지 않고 연료를 수시로 채우지 않아도 돼요","correct":true},{"t":"한꺼번에 아주 많은 짐을 옮길 수 있어요","mis":"SO3-2-u2-X25"},{"t":"날씨와 관계없이 늘 빨라요","mis":"SO3-2-u2-X24"},{"t":"먼 곳도 하루 만에 갈 수 있어요","mis":"SO3-2-u2-X28"}],"explanation":["바람과 동물의 힘이에요.","연료가 필요 없어요.","환경이 깨끗해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L09_challenge#5','soc',3,2,'u2','L09','tb_g3_2_soc_u2_L09_challenge','lesson_challenge','SO3-2-u2-C9',3,'ox','auto','과학 기술이 발달하면서 사람들은 이전보다 더 먼 곳을 빠르고 편하게 이동하고, 더 많은 물건을 한꺼번에 옮기게 됐어요.',ARRAY['SO3-2-u2-X28']::text[],false,'{"seq":5,"concept":"SO3-2-u2-C9","difficulty":3,"kind":"ox","stem":"과학 기술이 발달하면서 사람들은 이전보다 더 먼 곳을 빠르고 편하게 이동하고, 더 많은 물건을 한꺼번에 옮기게 됐어요.","answer":"O","reason_options":[{"t":"기계의 힘으로 움직이는 기차, 배, 자동차, 비행기가 생겼기 때문에","correct":true},{"t":"기계의 힘으로 움직이는 교통수단은 옛날 교통수단보다 느렸기 때문에","mis":"SO3-2-u2-X28"}],"mis":"SO3-2-u2-X28","explanation":["99쪽 글이에요.","기계의 힘이에요.","그래서 O예요."],"asset":{"type":"passage","lines":["증기 기차, 증기선 — 물을 끓이면 생기는 수증기의 힘으로 움직여요.","자동차, 프로펠러 비행기 — 석유의 힘으로 움직여요.","사람들은 이전보다 더 먼 곳을 더 빠르고 편하게 이동하게 됐어요."],"title":"『사회』 99쪽 — 과학 기술이 발달하면서 생겨난 교통수단"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L09_challenge#6','soc',3,2,'u2','L09','tb_g3_2_soc_u2_L09_challenge','lesson_challenge','SO3-2-u2-C9',3,'match','auto','교통수단과 그것을 움직이는 힘을 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"SO3-2-u2-C9","difficulty":3,"kind":"match","stem":"교통수단과 그것을 움직이는 힘을 알맞게 이으세요.","pairs":[{"l":"가마","r":"사람의 힘"},{"l":"달구지","r":"소나 말의 힘"},{"l":"돛단배","r":"바람의 힘"},{"l":"증기 기차","r":"수증기의 힘"},{"l":"자동차","r":"석유의 힘"}],"mis":"SO3-2-u2-X24","explanation":["가마는 사람, 달구지는 동물이에요.","돛단배는 바람이에요.","증기 기차와 자동차는 기계예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L09_challenge#7','soc',3,2,'u2','L09','tb_g3_2_soc_u2_L09_challenge','lesson_challenge','SO3-2-u2-C9',3,'error','auto','「꼭 기억해요」를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO3-2-u2-X24','SO3-2-u2-X25']::text[],false,'{"seq":7,"concept":"SO3-2-u2-C9","difficulty":3,"kind":"error","stem":"「꼭 기억해요」를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 나 — 「돛단배는 기계의 힘을 이용했어.」","correct":true,"mis_target":"SO3-2-u2-X24"},{"t":"친구 가 — 「돛단배는 바람과 같은 자연의 힘을 이용했어.」","mis":"SO3-2-u2-X24"},{"t":"친구 다 — 「증기선은 기계의 힘으로 움직였어.」","mis":"SO3-2-u2-X25"}],"explanation":["돛은 바람을 받아요.","자연의 힘이에요.","친구 나가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L09_challenge#8','soc',3,2,'u2','L09','tb_g3_2_soc_u2_L09_challenge','lesson_challenge','SO3-2-u2-C9',4,'mc','auto','옛날 교통수단과 과학 기술로 생겨난 교통수단을 바르게 견준 것은 무엇인가요?',ARRAY['SO3-2-u2-X24','SO3-2-u2-X28','SO3-2-u2-X25']::text[],false,'{"seq":8,"concept":"SO3-2-u2-C9","difficulty":4,"kind":"mc","stem":"옛날 교통수단과 과학 기술로 생겨난 교통수단을 바르게 견준 것은 무엇인가요?","options":[{"t":"옛날 것은 자연의 재료와 사람·동물·자연의 힘을, 새것은 기계의 힘을 이용해요","correct":true},{"t":"둘 다 기계의 힘을 이용해요","mis":"SO3-2-u2-X24"},{"t":"옛날 것이 더 많은 짐을 한꺼번에 옮겨요","mis":"SO3-2-u2-X28"},{"t":"새것은 동물의 힘을 이용해요","mis":"SO3-2-u2-X25"}],"explanation":["옛날은 자연의 힘이에요.","새것은 기계의 힘이에요.","그렇게 견줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L09_challenge#9','soc',3,2,'u2','L09','tb_g3_2_soc_u2_L09_challenge','lesson_challenge','SO3-2-u2-C9',4,'ox','auto','옛날 교통수단은 오늘날보다 느리니 그때 사람들에게도 쓸모가 없었어요.',ARRAY['SO3-2-u2-X48']::text[],false,'{"seq":9,"concept":"SO3-2-u2-C9","difficulty":4,"kind":"ox","stem":"옛날 교통수단은 오늘날보다 느리니 그때 사람들에게도 쓸모가 없었어요.","answer":"X","reason_options":[{"t":"그때 사람들은 자연에서 얻은 재료와 힘으로 필요에 맞게 이동하고 짐을 옮기는 데 꼭 썼기 때문에","correct":true},{"t":"빠르지 않은 교통수단은 언제나 쓸모가 없기 때문에","mis":"SO3-2-u2-X48"}],"mis":"SO3-2-u2-X48","explanation":["그때의 눈으로 봐요.","꼭 필요한 수단이었어요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L09_challenge#10','soc',3,2,'u2','L09','tb_g3_2_soc_u2_L09_challenge','lesson_challenge','SO3-2-u2-C9',4,'essay','teacher','옛날 교통수단 가운데 타 보고 싶은 것을 하나 골라 그 까닭을 쓰고, 그 교통수단을 움직인 힘을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO3-2-u2-C9","difficulty":4,"kind":"essay","stem":"옛날 교통수단 가운데 타 보고 싶은 것을 하나 골라 그 까닭을 쓰고, 그 교통수단을 움직인 힘을 쓰세요.","answer_guide":{"answer":"예: 나는 돛단배를 타 보고 싶어요. 바람을 받으며 강을 건너면 시원하고 재미있을 것 같기 때문이에요. 돛단배는 바람의 힘으로 움직여요.","scoring_points":["교통수단을 골랐는가","까닭을 썼는가","움직인 힘을 바르게 썼는가"]},"explanation":["하나를 골라요.","까닭을 써요.","힘을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L10_basic#1','soc',3,2,'u2','L10','tb_g3_2_soc_u2_L10_basic','lesson_basic','SO3-2-u2-C10',1,'mc','auto','자동차에 연료를 넣기 위한 교통 시설은 무엇인가요?',ARRAY['SO3-2-u2-X26']::text[],true,'{"seq":1,"concept":"SO3-2-u2-C10","difficulty":1,"kind":"mc","stem":"자동차에 연료를 넣기 위한 교통 시설은 무엇인가요?","options":[{"t":"주유소","correct":true},{"t":"자동차 정비소","mis":"SO3-2-u2-X26"},{"t":"휴게소","mis":"SO3-2-u2-X26"},{"t":"주차장","mis":"SO3-2-u2-X26"}],"explanation":["연료를 넣어요.","기름을 넣는 곳이에요.","주유소예요."],"variant_rule":{"alt":[{"stem":"자동차를 수리하기 위한 교통 시설은 무엇인가요?","options":[{"t":"자동차 정비소","correct":true},{"t":"주유소","mis":"SO3-2-u2-X26"},{"t":"기차역","mis":"SO3-2-u2-X26"},{"t":"물류 창고","mis":"SO3-2-u2-X26"}],"explanation":["고장 난 차예요.","고치는 곳이에요.","자동차 정비소예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L10_basic#2','soc',3,2,'u2','L10','tb_g3_2_soc_u2_L10_basic','lesson_basic','SO3-2-u2-C10',1,'sa','auto','공항에서 비행기가 뜨고 내리는 곳을 무엇이라고 하나요? 세 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SO3-2-u2-C10","difficulty":1,"kind":"sa","stem":"공항에서 비행기가 뜨고 내리는 곳을 무엇이라고 하나요? 세 글자로 쓰세요.","answer":["활주로"],"explanation":["102쪽 그림이에요.","활◯◯예요.","활주로예요."],"mis":"SO3-2-u2-X26"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L10_basic#3','soc',3,2,'u2','L10','tb_g3_2_soc_u2_L10_basic','lesson_basic','SO3-2-u2-C10',1,'mc','auto','104쪽에서 독일의 공중에 매달려 다니는 전동차는 무엇인가요?',ARRAY['SO3-2-u2-X26','SO3-2-u2-X22']::text[],false,'{"seq":3,"concept":"SO3-2-u2-C10","difficulty":1,"kind":"mc","stem":"104쪽에서 독일의 공중에 매달려 다니는 전동차는 무엇인가요?","options":[{"t":"슈베베반","correct":true},{"t":"툭툭","mis":"SO3-2-u2-X26"},{"t":"곤돌라","mis":"SO3-2-u2-X26"},{"t":"케이블카","mis":"SO3-2-u2-X22"}],"explanation":["독일이에요.","공중에 매달려요.","슈베베반이에요."],"asset":{"type":"passage","lines":["타이의 툭툭 — 오토바이로 만든 세 발 택시로, 짧은 거리를 이동할 때 주로 이용해요.","독일의 슈베베반 — 공중에 매달려 다니는 전동차로, 철도를 만들 땅이 부족해 생겼어요.","이탈리아의 곤돌라 — 물 위에 만들어진 도시 베네치아에서 물길을 따라 이동하는 배예요."],"title":"『사회』 104쪽 — 나라마다 독특한 교통수단"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L10_basic#4','soc',3,2,'u2','L10','tb_g3_2_soc_u2_L10_basic','lesson_basic','SO3-2-u2-C10',1,'ox','auto','오늘날 교통수단들은 대부분 석유, 가스, 전기 등을 연료로 사용해요.',ARRAY['SO3-2-u2-X25']::text[],false,'{"seq":4,"concept":"SO3-2-u2-C10","difficulty":1,"kind":"ox","stem":"오늘날 교통수단들은 대부분 석유, 가스, 전기 등을 연료로 사용해요.","answer":"O","reason_options":[{"t":"『사회』 100쪽 말풍선처럼 기계의 힘을 이용하는 교통수단이 많기 때문에","correct":true},{"t":"오늘날 교통수단은 대부분 사람이나 동물의 힘으로 움직이기 때문에","mis":"SO3-2-u2-X25"}],"mis":"SO3-2-u2-X25","explanation":["100쪽 말풍선이에요.","기계의 힘이에요.","그래서 O예요."],"asset":{"type":"speech","turns":[{"who":"말풍선 1","text":"기계의 힘을 이용하는 교통수단이 많아요."},{"who":"말풍선 2","text":"교통수단들은 대부분 석유, 가스, 전기 등을 연료로 사용해요."},{"who":"말풍선 3","text":"지하철을 타면 약속 시간에 늦지 않게 갈 수 있어요."},{"who":"말풍선 4","text":"택시를 타면 가려는 장소까지 편하게 이동할 수 있어요."},{"who":"말풍선 5","text":"트럭은 한 번에 물건을 많이 옮길 수 있어요."},{"who":"말풍선 6","text":"교통수단을 편리하게 이용하도록 돕는 시설이 많이 생겼어요."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L10_basic#5','soc',3,2,'u2','L10','tb_g3_2_soc_u2_L10_basic','lesson_basic','SO3-2-u2-C10',2,'match','auto','교통 시설과 그 쓰임을 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"SO3-2-u2-C10","difficulty":2,"kind":"match","stem":"교통 시설과 그 쓰임을 알맞게 이으세요.","pairs":[{"l":"휴게소","r":"고속 국도를 지나다 잠시 쉬고 식사도 하는 곳"},{"l":"관제탑","r":"비행기가 다닐 수 있도록 신호를 알려 주는 곳"},{"l":"등대","r":"배가 바다에서 안전하게 다니도록 알려 주는 곳"},{"l":"선착장","r":"배가 육지에 붙어 머무는 곳"}],"mis":"SO3-2-u2-X26","explanation":["휴게소는 쉬는 곳이에요.","관제탑은 비행기, 등대는 배예요.","선착장은 배가 머물러요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L10_basic#6','soc',3,2,'u2','L10','tb_g3_2_soc_u2_L10_basic','lesson_basic','SO3-2-u2-C10',2,'mc','auto','배가 항구에서 나갈 때 빨간색 등대를 보면 어느 쪽으로 다녀야 하나요?',ARRAY['SO3-2-u2-X27']::text[],false,'{"seq":6,"concept":"SO3-2-u2-C10","difficulty":2,"kind":"mc","stem":"배가 항구에서 나갈 때 빨간색 등대를 보면 어느 쪽으로 다녀야 하나요?","options":[{"t":"오른쪽 — 왼쪽에 장애물이 있기 때문이에요","correct":true},{"t":"왼쪽 — 오른쪽에 장애물이 있기 때문이에요","mis":"SO3-2-u2-X27"},{"t":"등대 바로 옆으로 붙어서요","mis":"SO3-2-u2-X27"},{"t":"아무 쪽으로나 다녀도 돼요","mis":"SO3-2-u2-X27"}],"explanation":["103쪽 등대 그림이에요.","빨간색은 왼쪽에 장애물이에요.","오른쪽으로 다녀요."],"asset":{"type":"passage","lines":["어린이 보호 구역 — 교통수단이 천천히 다니도록 하는 다양한 표시가 있어요.","신호등 — 횡단보도를 건널 때 남은 보행 시간을 표시해요.","철도 건널목 — 신호기로 기차가 지나갈 때를 알려 줘요.","빨간색 등대 — 왼쪽에 장애물이 있으니 오른쪽으로 다녀요.","흰색 등대 — 오른쪽에 장애물이 있으니 왼쪽으로 다녀요."],"title":"『사회』 103쪽 — 안전한 교통을 위한 신호와 약속"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L10_basic#7','soc',3,2,'u2','L10','tb_g3_2_soc_u2_L10_basic','lesson_basic','SO3-2-u2-C10',2,'mc','auto','오늘날 새로운 교통 시설이 생긴 까닭은 무엇인가요?',ARRAY['SO3-2-u2-X26']::text[],false,'{"seq":7,"concept":"SO3-2-u2-C10","difficulty":2,"kind":"mc","stem":"오늘날 새로운 교통 시설이 생긴 까닭은 무엇인가요?","options":[{"t":"많은 사람이 교통수단을 편리하게 이용하도록 하기 위해서예요","correct":true},{"t":"교통수단을 줄이기 위해서예요","mis":"SO3-2-u2-X26"},{"t":"옛날 교통수단을 다시 쓰기 위해서예요","mis":"SO3-2-u2-X26"},{"t":"거리를 꾸미기 위해서만이에요","mis":"SO3-2-u2-X26"}],"explanation":["100쪽 첫 글이에요.","편리하게 이용해요.","그래서 생겼어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L10_basic#8','soc',3,2,'u2','L10','tb_g3_2_soc_u2_L10_basic','lesson_basic','SO3-2-u2-C10',2,'blank','auto','「교통수단과 교통 시설이 다양해지면서 안전을 위한 여러 가지 (    )와 약속이 생겼습니다.」 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SO3-2-u2-X27','SO3-2-u2-X26']::text[],false,'{"seq":8,"concept":"SO3-2-u2-C10","difficulty":2,"kind":"blank","stem":"「교통수단과 교통 시설이 다양해지면서 안전을 위한 여러 가지 (    )와 약속이 생겼습니다.」 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"신호","correct":true},{"t":"요금","mis":"SO3-2-u2-X27"},{"t":"휴게소","mis":"SO3-2-u2-X26"},{"t":"경주","mis":"SO3-2-u2-X27"}],"explanation":["꼭 기억해요 2예요.","안전을 위해서예요.","신호예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L10_basic#9','soc',3,2,'u2','L10','tb_g3_2_soc_u2_L10_basic','lesson_basic','SO3-2-u2-C10',2,'ox','auto','공항과 항구 같은 교통 시설이 발달하여 다른 나라로 여행을 가거나 섬을 오가기 쉬워졌어요.',ARRAY['SO3-2-u2-X26']::text[],false,'{"seq":9,"concept":"SO3-2-u2-C10","difficulty":2,"kind":"ox","stem":"공항과 항구 같은 교통 시설이 발달하여 다른 나라로 여행을 가거나 섬을 오가기 쉬워졌어요.","answer":"O","reason_options":[{"t":"하늘과 바다의 교통수단이 더 커지고 빨라지고 시설이 발달했기 때문에","correct":true},{"t":"공항과 항구는 물건만 오가는 곳이라 여행과는 상관없기 때문에","mis":"SO3-2-u2-X26"}],"mis":"SO3-2-u2-X26","explanation":["102쪽 첫 글이에요.","여행과 섬이에요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L10_basic#10','soc',3,2,'u2','L10','tb_g3_2_soc_u2_L10_basic','lesson_basic','SO3-2-u2-C10',3,'error','auto','안전을 위한 신호와 약속을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO3-2-u2-X27']::text[],false,'{"seq":10,"concept":"SO3-2-u2-C10","difficulty":3,"kind":"error","stem":"안전을 위한 신호와 약속을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「흰색 등대가 보이면 오른쪽으로 다녀야 해.」","correct":true,"mis_target":"SO3-2-u2-X27"},{"t":"친구 가 — 「철도 건널목 신호기는 기차가 지나갈 때를 알려 줘.」","mis":"SO3-2-u2-X27"},{"t":"친구 나 — 「신호등은 횡단보도를 건널 때 남은 보행 시간을 알려 줘.」","mis":"SO3-2-u2-X27"}],"explanation":["흰색 등대는 오른쪽에 장애물이에요.","왼쪽으로 다녀요.","친구 다가 잘못 말했어요."],"asset":{"type":"passage","lines":["어린이 보호 구역 — 교통수단이 천천히 다니도록 하는 다양한 표시가 있어요.","신호등 — 횡단보도를 건널 때 남은 보행 시간을 표시해요.","철도 건널목 — 신호기로 기차가 지나갈 때를 알려 줘요.","빨간색 등대 — 왼쪽에 장애물이 있으니 오른쪽으로 다녀요.","흰색 등대 — 오른쪽에 장애물이 있으니 왼쪽으로 다녀요."],"title":"『사회』 103쪽 — 안전한 교통을 위한 신호와 약속"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L10_challenge#1','soc',3,2,'u2','L10','tb_g3_2_soc_u2_L10_challenge','lesson_challenge','SO3-2-u2-C10',2,'sa','auto','타이에서 오토바이로 만든 세 발 택시를 무엇이라고 하나요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"SO3-2-u2-C10","difficulty":2,"kind":"sa","stem":"타이에서 오토바이로 만든 세 발 택시를 무엇이라고 하나요? 두 글자로 쓰세요.","answer":["툭툭"],"explanation":["104쪽이에요.","툭◯이에요.","툭툭이에요."],"mis":"SO3-2-u2-X26"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L10_challenge#2','soc',3,2,'u2','L10','tb_g3_2_soc_u2_L10_challenge','lesson_challenge','SO3-2-u2-C10',2,'mc','auto','102쪽 그림에서 다른 나라에 많은 물건을 실어 보내는 배는 무엇인가요?',ARRAY['SO3-2-u2-X22']::text[],false,'{"seq":2,"concept":"SO3-2-u2-C10","difficulty":2,"kind":"mc","stem":"102쪽 그림에서 다른 나라에 많은 물건을 실어 보내는 배는 무엇인가요?","options":[{"t":"화물선","correct":true},{"t":"요트","mis":"SO3-2-u2-X22"},{"t":"잠수함","mis":"SO3-2-u2-X22"},{"t":"구조 헬기","mis":"SO3-2-u2-X22"}],"explanation":["많은 물건이에요.","짐을 싣는 배예요.","화물선이에요."],"asset":{"type":"passage","lines":["하늘 — 비행기, 헬리콥터 / 공항, 관제탑, 활주로","바다 — 여객선, 화물선, 크루즈선, 잠수함, 요트","항구 — 여객 터미널, 선착장, 등대, 방파제, 크레인","말풍선 — 화물선으로 다른 나라에 많은 물건을 실어 보내요.","말풍선 — 잠수함은 물속으로 다녀요."],"title":"『사회』 102쪽 — 하늘과 바다의 교통"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L10_challenge#3','soc',3,2,'u2','L10','tb_g3_2_soc_u2_L10_challenge','lesson_challenge','SO3-2-u2-C10',3,'mc','auto','독일의 슈베베반이 생겨난 까닭은 무엇인가요?',ARRAY['SO3-2-u2-X26','SO3-2-u2-X33']::text[],false,'{"seq":3,"concept":"SO3-2-u2-C10","difficulty":3,"kind":"mc","stem":"독일의 슈베베반이 생겨난 까닭은 무엇인가요?","options":[{"t":"철도를 만들 땅이 부족했기 때문이에요","correct":true},{"t":"물 위에 만들어진 도시였기 때문이에요","mis":"SO3-2-u2-X26"},{"t":"짧은 거리만 오가려고 했기 때문이에요","mis":"SO3-2-u2-X26"},{"t":"비행기보다 빨리 가려고 했기 때문이에요","mis":"SO3-2-u2-X33"}],"explanation":["104쪽 사진 설명이에요.","땅이 부족했어요.","공중으로 다녀요."],"asset":{"type":"passage","lines":["타이의 툭툭 — 오토바이로 만든 세 발 택시로, 짧은 거리를 이동할 때 주로 이용해요.","독일의 슈베베반 — 공중에 매달려 다니는 전동차로, 철도를 만들 땅이 부족해 생겼어요.","이탈리아의 곤돌라 — 물 위에 만들어진 도시 베네치아에서 물길을 따라 이동하는 배예요."],"title":"『사회』 104쪽 — 나라마다 독특한 교통수단"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L10_challenge#4','soc',3,2,'u2','L10','tb_g3_2_soc_u2_L10_challenge','lesson_challenge','SO3-2-u2-C10',3,'mc','auto','100~101쪽 그림 속 사람들이 교통수단을 이용하는 모습과 까닭을 바르게 짝지은 것은 무엇인가요?',ARRAY['SO3-2-u2-X22','SO3-2-u2-X26']::text[],false,'{"seq":4,"concept":"SO3-2-u2-C10","difficulty":3,"kind":"mc","stem":"100~101쪽 그림 속 사람들이 교통수단을 이용하는 모습과 까닭을 바르게 짝지은 것은 무엇인가요?","options":[{"t":"약속 시간에 늦지 않으려고 지하철을 타요","correct":true},{"t":"물건을 많이 옮기려고 택시를 타요","mis":"SO3-2-u2-X22"},{"t":"가려는 장소까지 편하게 가려고 트럭을 타요","mis":"SO3-2-u2-X22"},{"t":"비행기를 고치려고 주유소에 가요","mis":"SO3-2-u2-X26"}],"explanation":["말풍선을 봐요.","지하철은 약속 시간이에요.","그 짝이에요."],"asset":{"type":"speech","turns":[{"who":"말풍선 1","text":"기계의 힘을 이용하는 교통수단이 많아요."},{"who":"말풍선 2","text":"교통수단들은 대부분 석유, 가스, 전기 등을 연료로 사용해요."},{"who":"말풍선 3","text":"지하철을 타면 약속 시간에 늦지 않게 갈 수 있어요."},{"who":"말풍선 4","text":"택시를 타면 가려는 장소까지 편하게 이동할 수 있어요."},{"who":"말풍선 5","text":"트럭은 한 번에 물건을 많이 옮길 수 있어요."},{"who":"말풍선 6","text":"교통수단을 편리하게 이용하도록 돕는 시설이 많이 생겼어요."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L10_challenge#5','soc',3,2,'u2','L10','tb_g3_2_soc_u2_L10_challenge','lesson_challenge','SO3-2-u2-C10',3,'ox','auto','나라마다 자연환경과 생활 모습이 달라서 사람들이 이용하는 교통수단의 모습도 매우 다양해요.',ARRAY['SO3-2-u2-X26']::text[],false,'{"seq":5,"concept":"SO3-2-u2-C10","difficulty":3,"kind":"ox","stem":"나라마다 자연환경과 생활 모습이 달라서 사람들이 이용하는 교통수단의 모습도 매우 다양해요.","answer":"O","reason_options":[{"t":"물 위의 도시 베네치아는 곤돌라를, 땅이 부족한 곳은 슈베베반을 쓰는 것처럼 다르기 때문에","correct":true},{"t":"세계 모든 나라는 똑같은 교통수단만 쓰기 때문에","mis":"SO3-2-u2-X26"}],"mis":"SO3-2-u2-X26","explanation":["104쪽 글이에요.","나라마다 달라요.","그래서 O예요."],"asset":{"type":"passage","lines":["타이의 툭툭 — 오토바이로 만든 세 발 택시로, 짧은 거리를 이동할 때 주로 이용해요.","독일의 슈베베반 — 공중에 매달려 다니는 전동차로, 철도를 만들 땅이 부족해 생겼어요.","이탈리아의 곤돌라 — 물 위에 만들어진 도시 베네치아에서 물길을 따라 이동하는 배예요."],"title":"『사회』 104쪽 — 나라마다 독특한 교통수단"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L10_challenge#6','soc',3,2,'u2','L10','tb_g3_2_soc_u2_L10_challenge','lesson_challenge','SO3-2-u2-C10',3,'match','auto','나라와 독특한 교통수단을 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"SO3-2-u2-C10","difficulty":3,"kind":"match","stem":"나라와 독특한 교통수단을 알맞게 이으세요.","pairs":[{"l":"타이","r":"오토바이로 만든 세 발 택시 툭툭"},{"l":"독일","r":"공중에 매달려 다니는 전동차 슈베베반"},{"l":"이탈리아 베네치아","r":"물길을 따라 이동하는 배 곤돌라"}],"mis":"SO3-2-u2-X26","explanation":["타이는 툭툭이에요.","독일은 슈베베반이에요.","베네치아는 곤돌라예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L10_challenge#7','soc',3,2,'u2','L10','tb_g3_2_soc_u2_L10_challenge','lesson_challenge','SO3-2-u2-C10',3,'error','auto','공항과 항구의 시설을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO3-2-u2-X26']::text[],false,'{"seq":7,"concept":"SO3-2-u2-C10","difficulty":3,"kind":"error","stem":"공항과 항구의 시설을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 가 — 「활주로는 배가 육지에 붙어 머무는 곳이야.」","correct":true,"mis_target":"SO3-2-u2-X26"},{"t":"친구 나 — 「관제탑은 비행기가 다닐 수 있도록 신호를 알려 줘.」","mis":"SO3-2-u2-X26"},{"t":"친구 다 — 「크레인으로 큰 화물을 들어 화물선에 실어.」","mis":"SO3-2-u2-X26"}],"explanation":["활주로는 비행기가 뜨고 내려요.","배가 머무는 곳은 선착장이에요.","친구 가가 잘못 말했어요."],"asset":{"type":"passage","lines":["하늘 — 비행기, 헬리콥터 / 공항, 관제탑, 활주로","바다 — 여객선, 화물선, 크루즈선, 잠수함, 요트","항구 — 여객 터미널, 선착장, 등대, 방파제, 크레인","말풍선 — 화물선으로 다른 나라에 많은 물건을 실어 보내요.","말풍선 — 잠수함은 물속으로 다녀요."],"title":"『사회』 102쪽 — 하늘과 바다의 교통"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L10_challenge#8','soc',3,2,'u2','L10','tb_g3_2_soc_u2_L10_challenge','lesson_challenge','SO3-2-u2-C10',4,'mc','auto','옛날과 견주어 오늘날 교통수단이 달라진 특징으로 알맞은 것은 무엇인가요?',ARRAY['SO3-2-u2-X25','SO3-2-u2-X28','SO3-2-u2-X26']::text[],false,'{"seq":8,"concept":"SO3-2-u2-C10","difficulty":4,"kind":"mc","stem":"옛날과 견주어 오늘날 교통수단이 달라진 특징으로 알맞은 것은 무엇인가요?","options":[{"t":"기계의 힘을 이용하는 것이 많고, 대부분 석유·가스·전기를 연료로 써요","correct":true},{"t":"대부분 사람과 동물의 힘으로 움직여요","mis":"SO3-2-u2-X25"},{"t":"하늘과 바다의 교통수단은 줄어들었어요","mis":"SO3-2-u2-X28"},{"t":"교통 시설은 거의 필요 없어졌어요","mis":"SO3-2-u2-X26"}],"explanation":["101쪽 핵심 질문이에요.","기계의 힘이에요.","연료를 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L10_challenge#9','soc',3,2,'u2','L10','tb_g3_2_soc_u2_L10_challenge','lesson_challenge','SO3-2-u2-C10',4,'ox','auto','교통수단과 교통 시설이 다양해지고 이용하는 사람이 많아지면서 안전한 교통을 위한 신호와 약속이 생겼어요.',ARRAY['SO3-2-u2-X27']::text[],false,'{"seq":9,"concept":"SO3-2-u2-C10","difficulty":4,"kind":"ox","stem":"교통수단과 교통 시설이 다양해지고 이용하는 사람이 많아지면서 안전한 교통을 위한 신호와 약속이 생겼어요.","answer":"O","reason_options":[{"t":"많은 교통수단이 함께 다녀도 사고 없이 다니려면 모두가 따르는 약속이 필요하기 때문에","correct":true},{"t":"교통 신호는 교통수단을 꾸미려고 만든 것이기 때문에","mis":"SO3-2-u2-X27"}],"mis":"SO3-2-u2-X27","explanation":["103쪽 첫 글이에요.","안전을 위해서예요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L10_challenge#10','soc',3,2,'u2','L10','tb_g3_2_soc_u2_L10_challenge','lesson_challenge','SO3-2-u2-C10',4,'essay','teacher','하늘과 바다의 교통수단 가운데 이용해 보고 싶은 것을 하나 골라 이용하는 모습을 한 문장으로 쓰고, 관련 있는 교통 시설을 하나 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO3-2-u2-C10","difficulty":4,"kind":"essay","stem":"하늘과 바다의 교통수단 가운데 이용해 보고 싶은 것을 하나 골라 이용하는 모습을 한 문장으로 쓰고, 관련 있는 교통 시설을 하나 쓰세요.","answer_guide":{"answer":"예: 잠수함 — 잠수함을 타고 바닷속을 구경해요. 관련 시설은 배가 육지에 붙어 머무는 선착장이에요.","scoring_points":["교통수단을 골랐는가","이용하는 모습을 썼는가","관련 있는 교통 시설을 썼는가"]},"explanation":["하나를 골라요.","한 문장이에요.","시설을 써요."],"asset":{"type":"passage","lines":["하늘 — 비행기, 헬리콥터 / 공항, 관제탑, 활주로","바다 — 여객선, 화물선, 크루즈선, 잠수함, 요트","항구 — 여객 터미널, 선착장, 등대, 방파제, 크레인","말풍선 — 화물선으로 다른 나라에 많은 물건을 실어 보내요.","말풍선 — 잠수함은 물속으로 다녀요."],"title":"『사회』 102쪽 — 하늘과 바다의 교통"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L11_basic#1','soc',3,2,'u2','L11','tb_g3_2_soc_u2_L11_basic','lesson_basic','SO3-2-u2-C11',1,'blank','auto','「달구지 → 트럭」 칸의 빈자리에 들어갈 말로 알맞은 것은 무엇인가요?',ARRAY['SO3-2-u2-X28']::text[],true,'{"seq":1,"concept":"SO3-2-u2-C11","difficulty":1,"kind":"blank","stem":"「달구지 → 트럭」 칸의 빈자리에 들어갈 말로 알맞은 것은 무엇인가요?","options":[{"t":"더 많은 짐을 싣고 먼 곳까지 이동할 수 있어요","correct":true},{"t":"짐을 옮기는 일이 더 느려졌어요","mis":"SO3-2-u2-X28"},{"t":"짐을 실을 수 없게 되었어요","mis":"SO3-2-u2-X28"},{"t":"가까운 곳만 갈 수 있게 되었어요","mis":"SO3-2-u2-X28"}],"explanation":["105쪽 셋째 그림이에요.","트럭은 짐을 많이 실어요.","더 많이, 더 멀리예요."],"asset":{"type":"passage","lines":["말 → 고속 열차 : 먼 곳까지 더 빠르고 편하게 갈 수 있어요.","돛단배 → 여객선 : 가기 어려웠던 곳에 쉽고 빠르게 갈 수 있어요.","달구지 → 트럭 : (                    )"],"title":"『사회』 105쪽 — 옛날과 오늘날의 교통수단 견주기(한 칸 비움)"},"variant_rule":{"alt":[{"stem":"「말 → 고속 열차」처럼 교통수단이 바뀌면서 달라진 생활로 알맞은 것은 무엇인가요?","options":[{"t":"먼 곳까지 더 빠르고 편하게 갈 수 있어요","correct":true},{"t":"먼 곳에는 갈 수 없게 되었어요","mis":"SO3-2-u2-X28"},{"t":"이동하는 데 더 오래 걸리게 되었어요","mis":"SO3-2-u2-X28"},{"t":"짐을 하나도 옮길 수 없게 되었어요","mis":"SO3-2-u2-X28"}],"explanation":["105쪽 첫째 그림이에요.","고속 열차는 빨라요.","더 빠르고 편하게예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L11_basic#2','soc',3,2,'u2','L11','tb_g3_2_soc_u2_L11_basic','lesson_basic','SO3-2-u2-C11',1,'sa','auto','박 선비가 부산에서 한양까지 가는 데 걸린 시간은 얼마나 되나요?','{}'::text[],false,'{"seq":2,"concept":"SO3-2-u2-C11","difficulty":1,"kind":"sa","stem":"박 선비가 부산에서 한양까지 가는 데 걸린 시간은 얼마나 되나요?","answer":["15일","보름","15일 정도","보름 정도"],"explanation":["9월 1일에 출발했어요.","9월 15일에 도착했어요.","15일(보름) 정도예요."],"asset":{"type":"passage","lines":["박 선비 — 9월 1일 부산 출발 → 9월 7일 상주 도착","박 선비 — 9월 11일 충주 도착 → 9월 15일 한양(서울) 도착","박 선비 — 부산~상주는 걸어서, 상주~충주는 말을 타고, 충주~한양은 나룻배로","수이 — 오전 6시 집 출발, 지하철을 타고 부산역 도착","수이 — 오전 7시 부산역 출발, 고속 열차로 오전 9시 30분 서울역 도착","수이 — 버스를 타고 낮 12시 친척 집 도착, 택시를 타고 시내 관광"],"title":"『사회』 107쪽 할 수 있어요 — 박 선비와 수이의 여행"},"mis":"SO3-2-u2-X28"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L11_basic#3','soc',3,2,'u2','L11','tb_g3_2_soc_u2_L11_basic','lesson_basic','SO3-2-u2-C11',1,'mc','auto','교통의 변화로 거의 사라진 직업으로, 가마의 앞뒤에서 가마를 들고 가던 사람은 누구인가요?',ARRAY['SO3-2-u2-X29']::text[],true,'{"seq":3,"concept":"SO3-2-u2-C11","difficulty":1,"kind":"mc","stem":"교통의 변화로 거의 사라진 직업으로, 가마의 앞뒤에서 가마를 들고 가던 사람은 누구인가요?","options":[{"t":"가마꾼","correct":true},{"t":"항공기 조종사","mis":"SO3-2-u2-X29"},{"t":"철도 기관사","mis":"SO3-2-u2-X29"},{"t":"도선사","mis":"SO3-2-u2-X29"}],"explanation":["가마를 들어요.","오늘날 거의 볼 수 없어요.","가마꾼이에요."],"variant_rule":{"alt":[{"stem":"교통의 변화로 거의 사라진 직업으로, 노를 젓거나 막대기로 밀어 나룻배를 움직이던 사람은 누구인가요?","options":[{"t":"뱃사공","correct":true},{"t":"선장","mis":"SO3-2-u2-X29"},{"t":"해양 경찰관","mis":"SO3-2-u2-X29"},{"t":"택배 기사","mis":"SO3-2-u2-X29"}],"explanation":["나룻배를 움직여요.","오늘날 거의 볼 수 없어요.","뱃사공이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L11_basic#4','soc',3,2,'u2','L11','tb_g3_2_soc_u2_L11_basic','lesson_basic','SO3-2-u2-C11',1,'ox','auto','교통의 발달로 사람들의 생활 공간은 더욱 축소됐어요.',ARRAY['SO3-2-u2-X28']::text[],false,'{"seq":4,"concept":"SO3-2-u2-C11","difficulty":1,"kind":"ox","stem":"교통의 발달로 사람들의 생활 공간은 더욱 축소됐어요.","answer":"X","reason_options":[{"t":"먼 곳의 직장이나 학교에 다니고 먼 곳으로 여행을 가는 등 생활 공간이 넓어졌기 때문에","correct":true},{"t":"교통이 발달하면 가까운 곳에서만 생활하게 되기 때문에","mis":"SO3-2-u2-X28"}],"mis":"SO3-2-u2-X28","explanation":["꼭 기억해요 1이에요.","생활 공간이 넓어졌어요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L11_basic#5','soc',3,2,'u2','L11','tb_g3_2_soc_u2_L11_basic','lesson_basic','SO3-2-u2-C11',2,'mc','auto','수이가 부산역에서 서울역까지 타고 간 교통수단은 무엇인가요?',ARRAY['SO3-2-u2-X28']::text[],false,'{"seq":5,"concept":"SO3-2-u2-C11","difficulty":2,"kind":"mc","stem":"수이가 부산역에서 서울역까지 타고 간 교통수단은 무엇인가요?","options":[{"t":"고속 열차","correct":true},{"t":"나룻배","mis":"SO3-2-u2-X28"},{"t":"말","mis":"SO3-2-u2-X28"},{"t":"택시","mis":"SO3-2-u2-X28"}],"explanation":["다섯째 줄을 봐요.","오전 7시에 출발했어요.","고속 열차예요."],"asset":{"type":"passage","lines":["박 선비 — 9월 1일 부산 출발 → 9월 7일 상주 도착","박 선비 — 9월 11일 충주 도착 → 9월 15일 한양(서울) 도착","박 선비 — 부산~상주는 걸어서, 상주~충주는 말을 타고, 충주~한양은 나룻배로","수이 — 오전 6시 집 출발, 지하철을 타고 부산역 도착","수이 — 오전 7시 부산역 출발, 고속 열차로 오전 9시 30분 서울역 도착","수이 — 버스를 타고 낮 12시 친척 집 도착, 택시를 타고 시내 관광"],"title":"『사회』 107쪽 할 수 있어요 — 박 선비와 수이의 여행"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L11_basic#6','soc',3,2,'u2','L11','tb_g3_2_soc_u2_L11_basic','lesson_basic','SO3-2-u2-C11',2,'match','auto','106쪽 사진과 교통의 발달로 달라진 생활을 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"SO3-2-u2-C11","difficulty":2,"kind":"match","stem":"106쪽 사진과 교통의 발달로 달라진 생활을 알맞게 이으세요.","pairs":[{"l":"출퇴근 버스","r":"먼 곳에 있는 직장에 다닐 수 있어요"},{"l":"세계 과자 판매점","r":"세계 여러 곳에서 만든 물건을 쉽게 구할 수 있어요"},{"l":"해외여행","r":"다른 나라로 여행하는 사람이 많아졌어요"},{"l":"교통 약자 택시","r":"이동에 불편을 겪는 사람도 안전하고 편하게 이동해요"}],"mis":"SO3-2-u2-X28","explanation":["출퇴근은 직장이에요.","과자는 물건, 해외여행은 다른 나라예요.","교통 약자 택시는 편한 이동이에요."],"asset":{"type":"passage","lines":["출퇴근 버스","세계 과자 판매점","해외여행","교통 약자 택시"],"title":"『사회』 106쪽 사진 네 장의 이름"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L11_basic#7','soc',3,2,'u2','L11','tb_g3_2_soc_u2_L11_basic','lesson_basic','SO3-2-u2-C11',2,'mc','auto','도선사가 하는 일은 무엇인가요?',ARRAY['SO3-2-u2-X29']::text[],false,'{"seq":7,"concept":"SO3-2-u2-C11","difficulty":2,"kind":"mc","stem":"도선사가 하는 일은 무엇인가요?","options":[{"t":"배들이 안전하게 항구를 드나들도록 안내해요","correct":true},{"t":"비행기의 이착륙 순서를 정해요","mis":"SO3-2-u2-X29"},{"t":"버스를 운전해 승객을 날라요","mis":"SO3-2-u2-X29"},{"t":"기차역을 관리해요","mis":"SO3-2-u2-X29"}],"explanation":["110쪽 직업이에요.","항구에 들어오는 배예요.","안전하게 안내해요."],"asset":{"type":"speech","turns":[{"who":"선장","text":"여기는 선장, 도선사를 요청합니다."},{"who":"항구","text":"네. 곧 보내 드리겠습니다."},{"who":"도선사","text":"다양한 배에서 선장으로 일한 경험이 있어 큰 배를 안내하는 일도 문제없어요."},{"who":"도선사","text":"항구의 바다 밑을 속속들이 알고 있어요."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L11_basic#8','soc',3,2,'u2','L11','tb_g3_2_soc_u2_L11_basic','lesson_basic','SO3-2-u2-C11',2,'blank','auto','「교통의 변화로 몇몇 직업이 사라지기도 했지만, 교통수단을 운전하거나 고치는 일, 교통수단을 (    ) 이용하도록 돕는 일 등 다양한 직업이 새로 생겼어요.」 빈칸에 알맞은 말은?',ARRAY['SO3-2-u2-X29','SO3-2-u2-X28']::text[],false,'{"seq":8,"concept":"SO3-2-u2-C11","difficulty":2,"kind":"blank","stem":"「교통의 변화로 몇몇 직업이 사라지기도 했지만, 교통수단을 운전하거나 고치는 일, 교통수단을 (    ) 이용하도록 돕는 일 등 다양한 직업이 새로 생겼어요.」 빈칸에 알맞은 말은?","options":[{"t":"안전하게","correct":true},{"t":"몰래","mis":"SO3-2-u2-X29"},{"t":"혼자서만","mis":"SO3-2-u2-X29"},{"t":"느리게","mis":"SO3-2-u2-X28"}],"explanation":["108쪽 글이에요.","돕는 일이에요.","안전하게예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L11_basic#9','soc',3,2,'u2','L11','tb_g3_2_soc_u2_L11_basic','lesson_basic','SO3-2-u2-C11',2,'ox','auto','크레인 기사는 항구에서만 일하는 직업이에요.',ARRAY['SO3-2-u2-X46']::text[],false,'{"seq":9,"concept":"SO3-2-u2-C11","difficulty":2,"kind":"ox","stem":"크레인 기사는 항구에서만 일하는 직업이에요.","answer":"X","reason_options":[{"t":"크레인 기사는 항구뿐 아니라 땅 위의 공사장이나 공항에서도 일하기 때문에","correct":true},{"t":"크레인은 바다의 배에만 짐을 싣는 기계이기 때문에","mis":"SO3-2-u2-X46"}],"mis":"SO3-2-u2-X46","explanation":["그림에는 항구에 있어요.","다른 곳에서도 일해요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L11_basic#10','soc',3,2,'u2','L11','tb_g3_2_soc_u2_L11_basic','lesson_basic','SO3-2-u2-C11',3,'error','auto','박 선비와 수이의 여행을 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO3-2-u2-X23','SO3-2-u2-X28']::text[],false,'{"seq":10,"concept":"SO3-2-u2-C11","difficulty":3,"kind":"error","stem":"박 선비와 수이의 여행을 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 가 — 「박 선비는 부산에서 상주까지 말을 타고 갔어.」","correct":true,"mis_target":"SO3-2-u2-X23"},{"t":"친구 나 — 「박 선비는 충주에서 한양까지 나룻배를 탔어.」","mis":"SO3-2-u2-X23"},{"t":"친구 다 — 「수이는 반나절 만에 서울에 도착했어.」","mis":"SO3-2-u2-X28"}],"explanation":["부산~상주는 걸어서예요.","말은 상주~충주예요.","친구 가가 잘못 말했어요."],"asset":{"type":"passage","lines":["박 선비 — 9월 1일 부산 출발 → 9월 7일 상주 도착","박 선비 — 9월 11일 충주 도착 → 9월 15일 한양(서울) 도착","박 선비 — 부산~상주는 걸어서, 상주~충주는 말을 타고, 충주~한양은 나룻배로","수이 — 오전 6시 집 출발, 지하철을 타고 부산역 도착","수이 — 오전 7시 부산역 출발, 고속 열차로 오전 9시 30분 서울역 도착","수이 — 버스를 타고 낮 12시 친척 집 도착, 택시를 타고 시내 관광"],"title":"『사회』 107쪽 할 수 있어요 — 박 선비와 수이의 여행"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L11_challenge#1','soc',3,2,'u2','L11','tb_g3_2_soc_u2_L11_challenge','lesson_challenge','SO3-2-u2-C11',2,'sa','auto','배를 대어 사람과 짐이 땅으로 오르내릴 수 있도록 만들어 놓은 곳을 무엇이라고 하나요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"SO3-2-u2-C11","difficulty":2,"kind":"sa","stem":"배를 대어 사람과 짐이 땅으로 오르내릴 수 있도록 만들어 놓은 곳을 무엇이라고 하나요? 두 글자로 쓰세요.","answer":["부두"],"explanation":["110쪽 낱말 풀이예요.","부◯예요.","부두예요."],"mis":"SO3-2-u2-X26"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L11_challenge#2','soc',3,2,'u2','L11','tb_g3_2_soc_u2_L11_challenge','lesson_challenge','SO3-2-u2-C11',2,'mc','auto','108~109쪽 그림에서 하늘(항공) 교통의 발달로 생긴 직업은 무엇인가요?',ARRAY['SO3-2-u2-X29']::text[],false,'{"seq":2,"concept":"SO3-2-u2-C11","difficulty":2,"kind":"mc","stem":"108~109쪽 그림에서 하늘(항공) 교통의 발달로 생긴 직업은 무엇인가요?","options":[{"t":"항공관제사","correct":true},{"t":"철도 기관사","mis":"SO3-2-u2-X29"},{"t":"해양 경찰관","mis":"SO3-2-u2-X29"},{"t":"버스 운전기사","mis":"SO3-2-u2-X29"}],"explanation":["하늘 칸을 봐요.","비행기와 관련 있어요.","항공관제사예요."],"asset":{"type":"passage","lines":["하늘 — 항공관제사, 항공기 조종사, 공항 안전 요원, 항공 정비사, 항공기 승무원","땅 — 철도 기관사, 철도 역무원, 자동차 정비사, 버스 운전기사, 택배 기사","바다 — 해양 경찰관, 등대 관리원, 도선사, 선장, 선원, 크레인 기사"],"title":"『사회』 108~109쪽 — 교통의 변화로 새로 생긴 직업"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L11_challenge#3','soc',3,2,'u2','L11','tb_g3_2_soc_u2_L11_challenge','lesson_challenge','SO3-2-u2-C11',3,'mc','auto','박 선비가 이동한 차례를 바르게 나타낸 것은 무엇인가요?',ARRAY['SO3-2-u2-X23','SO3-2-u2-X28']::text[],false,'{"seq":3,"concept":"SO3-2-u2-C11","difficulty":3,"kind":"mc","stem":"박 선비가 이동한 차례를 바르게 나타낸 것은 무엇인가요?","options":[{"t":"부산~상주 걸어서 → 상주~충주 말 → 충주~한양 나룻배","correct":true},{"t":"부산~상주 말 → 상주~충주 나룻배 → 충주~한양 걸어서","mis":"SO3-2-u2-X23"},{"t":"부산~상주 나룻배 → 상주~충주 걸어서 → 충주~한양 말","mis":"SO3-2-u2-X23"},{"t":"부산~한양 고속 열차","mis":"SO3-2-u2-X28"}],"explanation":["셋째 줄을 봐요.","처음은 걸어서예요.","마지막은 나룻배예요."],"asset":{"type":"passage","lines":["박 선비 — 9월 1일 부산 출발 → 9월 7일 상주 도착","박 선비 — 9월 11일 충주 도착 → 9월 15일 한양(서울) 도착","박 선비 — 부산~상주는 걸어서, 상주~충주는 말을 타고, 충주~한양은 나룻배로","수이 — 오전 6시 집 출발, 지하철을 타고 부산역 도착","수이 — 오전 7시 부산역 출발, 고속 열차로 오전 9시 30분 서울역 도착","수이 — 버스를 타고 낮 12시 친척 집 도착, 택시를 타고 시내 관광"],"title":"『사회』 107쪽 할 수 있어요 — 박 선비와 수이의 여행"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L11_challenge#4','soc',3,2,'u2','L11','tb_g3_2_soc_u2_L11_challenge','lesson_challenge','SO3-2-u2-C11',3,'mc','auto','박 선비와 수이의 이동을 견주어 알 수 있는 것은 무엇인가요?',ARRAY['SO3-2-u2-X28','SO3-2-u2-X44']::text[],false,'{"seq":4,"concept":"SO3-2-u2-C11","difficulty":3,"kind":"mc","stem":"박 선비와 수이의 이동을 견주어 알 수 있는 것은 무엇인가요?","options":[{"t":"교통이 발달하면서 더 먼 곳으로 편하고 빠르게 이동할 수 있게 됐어요","correct":true},{"t":"옛날에 날씨의 영향을 덜 받았어요","mis":"SO3-2-u2-X28"},{"t":"오늘날 이동이 더 오래 걸려요","mis":"SO3-2-u2-X28"},{"t":"교통수단은 바뀌지 않았어요","mis":"SO3-2-u2-X44"}],"explanation":["15일과 반나절이에요.","훨씬 빨라졌어요.","편하고 빠르게예요."],"asset":{"type":"passage","lines":["박 선비 — 9월 1일 부산 출발 → 9월 7일 상주 도착","박 선비 — 9월 11일 충주 도착 → 9월 15일 한양(서울) 도착","박 선비 — 부산~상주는 걸어서, 상주~충주는 말을 타고, 충주~한양은 나룻배로","수이 — 오전 6시 집 출발, 지하철을 타고 부산역 도착","수이 — 오전 7시 부산역 출발, 고속 열차로 오전 9시 30분 서울역 도착","수이 — 버스를 타고 낮 12시 친척 집 도착, 택시를 타고 시내 관광"],"title":"『사회』 107쪽 할 수 있어요 — 박 선비와 수이의 여행"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L11_challenge#5','soc',3,2,'u2','L11','tb_g3_2_soc_u2_L11_challenge','lesson_challenge','SO3-2-u2-C11',3,'ox','auto','큰 배의 선장은 항구의 바닷속 장애물이나 물의 흐름을 몰라도 혼자서 안전하게 항구에 들어갈 수 있어요.',ARRAY['SO3-2-u2-X29']::text[],false,'{"seq":5,"concept":"SO3-2-u2-C11","difficulty":3,"kind":"ox","stem":"큰 배의 선장은 항구의 바닷속 장애물이나 물의 흐름을 몰라도 혼자서 안전하게 항구에 들어갈 수 있어요.","answer":"X","reason_options":[{"t":"바닷속 장애물이나 물의 흐름을 모르면 위험해서 도선사의 안내를 받아야 하기 때문에","correct":true},{"t":"큰 배는 크기 때문에 어떤 장애물도 위험하지 않기 때문에","mis":"SO3-2-u2-X29"}],"mis":"SO3-2-u2-X29","explanation":["110쪽 글이에요.","도선사에게 도움을 요청해요.","그래서 X예요."],"asset":{"type":"speech","turns":[{"who":"선장","text":"여기는 선장, 도선사를 요청합니다."},{"who":"항구","text":"네. 곧 보내 드리겠습니다."},{"who":"도선사","text":"다양한 배에서 선장으로 일한 경험이 있어 큰 배를 안내하는 일도 문제없어요."},{"who":"도선사","text":"항구의 바다 밑을 속속들이 알고 있어요."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L11_challenge#6','soc',3,2,'u2','L11','tb_g3_2_soc_u2_L11_challenge','lesson_challenge','SO3-2-u2-C11',3,'match','auto','교통이 발달한 곳과 새로 생긴 직업을 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"SO3-2-u2-C11","difficulty":3,"kind":"match","stem":"교통이 발달한 곳과 새로 생긴 직업을 알맞게 이으세요.","pairs":[{"l":"땅(육상)","r":"철도 기관사, 자동차 정비사"},{"l":"하늘(항공)","r":"항공기 조종사, 공항 안전 요원"},{"l":"바다(해상)","r":"해양 경찰관, 등대 관리원"}],"mis":"SO3-2-u2-X29","explanation":["땅은 철도와 자동차예요.","하늘은 항공기예요.","바다는 해양 경찰관이에요."],"asset":{"type":"passage","lines":["하늘 — 항공관제사, 항공기 조종사, 공항 안전 요원, 항공 정비사, 항공기 승무원","땅 — 철도 기관사, 철도 역무원, 자동차 정비사, 버스 운전기사, 택배 기사","바다 — 해양 경찰관, 등대 관리원, 도선사, 선장, 선원, 크레인 기사"],"title":"『사회』 108~109쪽 — 교통의 변화로 새로 생긴 직업"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L11_challenge#7','soc',3,2,'u2','L11','tb_g3_2_soc_u2_L11_challenge','lesson_challenge','SO3-2-u2-C11',3,'error','auto','교통과 관련된 직업을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO3-2-u2-X29']::text[],false,'{"seq":7,"concept":"SO3-2-u2-C11","difficulty":3,"kind":"error","stem":"교통과 관련된 직업을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「뱃사공은 교통의 변화로 새로 생긴 직업이야.」","correct":true,"mis_target":"SO3-2-u2-X29"},{"t":"친구 가 — 「택배 기사는 교통의 변화로 새로 생긴 직업이야.」","mis":"SO3-2-u2-X29"},{"t":"친구 나 — 「가마꾼은 교통의 변화로 거의 사라졌어.」","mis":"SO3-2-u2-X29"}],"explanation":["뱃사공은 나룻배를 움직였어요.","거의 사라진 직업이에요.","친구 다가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L11_challenge#8','soc',3,2,'u2','L11','tb_g3_2_soc_u2_L11_challenge','lesson_challenge','SO3-2-u2-C11',4,'mc','auto','그림 속 섬마을의 옛날과 오늘날 생활 모습이 다른 까닭으로 알맞은 것은 무엇인가요?',ARRAY['SO3-2-u2-X28','SO3-2-u2-X32']::text[],false,'{"seq":8,"concept":"SO3-2-u2-C11","difficulty":4,"kind":"mc","stem":"그림 속 섬마을의 옛날과 오늘날 생활 모습이 다른 까닭으로 알맞은 것은 무엇인가요?","options":[{"t":"다리와 도로 같은 교통 시설이 생기고 교통수단이 발달해 생활 모습과 직업이 달라졌기 때문이에요","correct":true},{"t":"섬의 자연환경이 완전히 바뀌었기 때문이에요","mis":"SO3-2-u2-X28"},{"t":"마을 사람들이 모두 이사 갔기 때문이에요","mis":"SO3-2-u2-X28"},{"t":"교통과 생활은 서로 관계가 없기 때문이에요","mis":"SO3-2-u2-X32"}],"explanation":["같은 섬이에요.","교통이 달라졌어요.","생활도 달라졌어요."],"asset":{"type":"passage","lines":["옛날 — 마을 사람들은 돛단배를 타고 섬 밖으로 나갔고, 고기를 잡거나 채소를 기르며 살았어요.","오늘날 — 다리와 도로가 생겨 차를 타고 섬 밖으로 나가요.","오늘날 — 어선, 여객선, 버스, 자가용을 이용하고 항구와 등대가 생겼어요.","오늘날 — 숙박 시설과 음식점이 생기고 버스 운전기사, 여객선 선장 등 직업이 다양해졌어요."],"title":"과정 중심 평가 — 그림 속 섬마을의 옛날과 오늘날(글로 옮김)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L11_challenge#9','soc',3,2,'u2','L11','tb_g3_2_soc_u2_L11_challenge','lesson_challenge','SO3-2-u2-C11',4,'ox','auto','교통이 발달하면서 교통수단을 이용하기 불편했던 사람도 편하게 이동할 수 있게 됐어요.',ARRAY['SO3-2-u2-X28']::text[],false,'{"seq":9,"concept":"SO3-2-u2-C11","difficulty":4,"kind":"ox","stem":"교통이 발달하면서 교통수단을 이용하기 불편했던 사람도 편하게 이동할 수 있게 됐어요.","answer":"O","reason_options":[{"t":"교통 약자 택시처럼 이동에 불편을 겪는 사람을 위한 교통수단이 생겼기 때문에","correct":true},{"t":"교통이 발달해도 몸이 불편한 사람은 이동할 방법이 없기 때문에","mis":"SO3-2-u2-X28"}],"mis":"SO3-2-u2-X28","explanation":["106쪽 사진이에요.","교통 약자 택시예요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L11_challenge#10','soc',3,2,'u2','L11','tb_g3_2_soc_u2_L11_challenge','lesson_challenge','SO3-2-u2-C11',4,'essay','teacher','박 선비와 수이의 이동 모습이 어떻게 다른지 쓰고, 그 차이를 교통의 변화에 따른 생활 모습의 변화와 이어 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO3-2-u2-C11","difficulty":4,"kind":"essay","stem":"박 선비와 수이의 이동 모습이 어떻게 다른지 쓰고, 그 차이를 교통의 변화에 따른 생활 모습의 변화와 이어 쓰세요.","answer_guide":{"answer":"예: 박 선비는 걷고 말과 나룻배를 타서 15일 정도 걸렸지만, 수이는 지하철, 고속 열차, 버스, 택시로 반나절 만에 갔어요. 교통이 발달해 먼 곳도 하루 안에 편하게 오가며 일을 보고 여행할 수 있게 되었어요.","scoring_points":["이용한 교통수단의 차이를 썼는가","걸린 시간의 차이를 썼는가","달라진 생활 모습과 이었는가"]},"explanation":["교통수단을 견줘요.","시간을 견줘요.","생활과 이어요."],"asset":{"type":"passage","lines":["박 선비 — 9월 1일 부산 출발 → 9월 7일 상주 도착","박 선비 — 9월 11일 충주 도착 → 9월 15일 한양(서울) 도착","박 선비 — 부산~상주는 걸어서, 상주~충주는 말을 타고, 충주~한양은 나룻배로","수이 — 오전 6시 집 출발, 지하철을 타고 부산역 도착","수이 — 오전 7시 부산역 출발, 고속 열차로 오전 9시 30분 서울역 도착","수이 — 버스를 타고 낮 12시 친척 집 도착, 택시를 타고 시내 관광"],"title":"『사회』 107쪽 할 수 있어요 — 박 선비와 수이의 여행"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L12_basic#1','soc',3,2,'u2','L12','tb_g3_2_soc_u2_L12_basic','lesson_basic','SO3-2-u2-C12',1,'mc','auto','차가 너무 많이 모여 길이 막히는 문제를 무엇이라고 하나요?',ARRAY['SO3-2-u2-X30']::text[],true,'{"seq":1,"concept":"SO3-2-u2-C12","difficulty":1,"kind":"mc","stem":"차가 너무 많이 모여 길이 막히는 문제를 무엇이라고 하나요?","options":[{"t":"교통 체증","correct":true},{"t":"대기 오염","mis":"SO3-2-u2-X30"},{"t":"주차 공간 부족","mis":"SO3-2-u2-X30"},{"t":"교통 시설 개발","mis":"SO3-2-u2-X30"}],"explanation":["111쪽 첫 붙임딱지예요.","길이 막혀요.","교통 체증이에요."],"asset":{"type":"passage","lines":["먼 곳까지 이동할 수 있지만, 차가 너무 많이 모여 교통 체증이 일어나기도 해요.","빠르게 이동할 수 있지만, 교통수단을 이용하다가 사고가 일어나기도 해요.","다양한 교통수단을 이용할 수 있지만, 대기 오염과 소음 문제가 일어나기도 해요.","가고 싶은 곳으로 편하게 갈 수 있지만, 주차할 곳이 부족할 때가 있어요."],"title":"『사회』 111쪽 — 교통이 변화하면서 생긴 문제"},"variant_rule":{"alt":[{"stem":"다양한 교통수단을 이용하면서 함께 생긴 공기와 소리의 문제는 무엇인가요?","options":[{"t":"대기 오염과 소음","correct":true},{"t":"교통 체증","mis":"SO3-2-u2-X30"},{"t":"주차할 곳 부족","mis":"SO3-2-u2-X30"},{"t":"교통사고","mis":"SO3-2-u2-X30"}],"explanation":["111쪽 셋째 붙임딱지예요.","공기와 소리예요.","대기 오염과 소음이에요."],"asset":{"type":"passage","lines":["먼 곳까지 이동할 수 있지만, 차가 너무 많이 모여 교통 체증이 일어나기도 해요.","빠르게 이동할 수 있지만, 교통수단을 이용하다가 사고가 일어나기도 해요.","다양한 교통수단을 이용할 수 있지만, 대기 오염과 소음 문제가 일어나기도 해요.","가고 싶은 곳으로 편하게 갈 수 있지만, 주차할 곳이 부족할 때가 있어요."],"title":"『사회』 111쪽 — 교통이 변화하면서 생긴 문제"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L12_basic#2','soc',3,2,'u2','L12','tb_g3_2_soc_u2_L12_basic','lesson_basic','SO3-2-u2-C12',1,'sa','auto','신문 기사에서 여러 사람이 함께 이용하는 자전거를 무엇이라고 했나요? 다섯 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SO3-2-u2-C12","difficulty":1,"kind":"sa","stem":"신문 기사에서 여러 사람이 함께 이용하는 자전거를 무엇이라고 했나요? 다섯 글자로 쓰세요.","answer":["공유 자전거","공유자전거"],"explanation":["112쪽 말풍선이에요.","함께 써요.","공유 자전거예요."],"mis":"SO3-2-u2-X30"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L12_basic#3','soc',3,2,'u2','L12','tb_g3_2_soc_u2_L12_basic','lesson_basic','SO3-2-u2-C12',1,'mc','auto','막히는 길이나 교통사고 상황 정보를 빠르게 제공해 교통을 관리하는 노력은 무엇인가요?',ARRAY['SO3-2-u2-X30']::text[],false,'{"seq":3,"concept":"SO3-2-u2-C12","difficulty":1,"kind":"mc","stem":"막히는 길이나 교통사고 상황 정보를 빠르게 제공해 교통을 관리하는 노력은 무엇인가요?","options":[{"t":"과학적인 교통 관리","correct":true},{"t":"친환경 에너지 사용","mis":"SO3-2-u2-X30"},{"t":"새로운 교통 시설 개발","mis":"SO3-2-u2-X30"},{"t":"주차장 없애기","mis":"SO3-2-u2-X30"}],"explanation":["112쪽 첫째 사진이에요.","정보를 빠르게 알려요.","과학적인 교통 관리예요."],"asset":{"type":"passage","lines":["과학적인 교통 관리 — 막히는 길, 교통사고 상황 등의 정보를 빠르게 제공해 교통을 관리해요.","새로운 교통 시설 개발 — 보행자가 안전하고 편리하게 다닐 수 있도록 시설을 개발해요.","친환경 에너지 사용 — 친환경 에너지를 쓰는 교통수단을 이용해 환경 오염을 줄여요."],"title":"『사회』 112쪽 — 교통 문제를 해결하려는 노력"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L12_basic#4','soc',3,2,'u2','L12','tb_g3_2_soc_u2_L12_basic','lesson_basic','SO3-2-u2-C12',1,'ox','auto','친환경 에너지를 사용하는 교통수단을 이용하면 환경 오염을 줄일 수 있어요.',ARRAY['SO3-2-u2-X30']::text[],false,'{"seq":4,"concept":"SO3-2-u2-C12","difficulty":1,"kind":"ox","stem":"친환경 에너지를 사용하는 교통수단을 이용하면 환경 오염을 줄일 수 있어요.","answer":"O","reason_options":[{"t":"친환경 에너지는 공기를 덜 더럽히기 때문에","correct":true},{"t":"친환경 에너지 교통수단은 공기를 더 더럽히기 때문에","mis":"SO3-2-u2-X30"}],"mis":"SO3-2-u2-X30","explanation":["꼭 기억해요 1이에요.","환경 오염을 줄여요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L12_basic#5','soc',3,2,'u2','L12','tb_g3_2_soc_u2_L12_basic','lesson_basic','SO3-2-u2-C12',2,'match','auto','교통이 변화하며 좋아진 점과 함께 생긴 문제를 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"SO3-2-u2-C12","difficulty":2,"kind":"match","stem":"교통이 변화하며 좋아진 점과 함께 생긴 문제를 알맞게 이으세요.","pairs":[{"l":"먼 곳까지 이동할 수 있지만","r":"차가 많이 모여 교통 체증이 일어나요"},{"l":"빠르게 이동할 수 있지만","r":"교통사고가 일어나기도 해요"},{"l":"다양한 교통수단을 이용할 수 있지만","r":"대기 오염과 소음 문제가 일어나요"},{"l":"가고 싶은 곳으로 편하게 갈 수 있지만","r":"주차할 곳이 부족할 때가 있어요"}],"mis":"SO3-2-u2-X32","explanation":["좋은 점 뒤에 문제가 있어요.","체증, 사고예요.","오염, 주차예요."],"asset":{"type":"passage","lines":["먼 곳까지 이동할 수 있지만, 차가 너무 많이 모여 교통 체증이 일어나기도 해요.","빠르게 이동할 수 있지만, 교통수단을 이용하다가 사고가 일어나기도 해요.","다양한 교통수단을 이용할 수 있지만, 대기 오염과 소음 문제가 일어나기도 해요.","가고 싶은 곳으로 편하게 갈 수 있지만, 주차할 곳이 부족할 때가 있어요."],"title":"『사회』 111쪽 — 교통이 변화하면서 생긴 문제"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L12_basic#6','soc',3,2,'u2','L12','tb_g3_2_soc_u2_L12_basic','lesson_basic','SO3-2-u2-C12',2,'mc','auto','○○시가 전기 자전거 공유 사업으로 해결하려는 문제는 무엇인가요?',ARRAY['SO3-2-u2-X30']::text[],false,'{"seq":6,"concept":"SO3-2-u2-C12","difficulty":2,"kind":"mc","stem":"○○시가 전기 자전거 공유 사업으로 해결하려는 문제는 무엇인가요?","options":[{"t":"환경 문제와 교통 혼잡","correct":true},{"t":"교통수단이 너무 적은 문제","mis":"SO3-2-u2-X30"},{"t":"자전거 공장이 없는 문제","mis":"SO3-2-u2-X30"},{"t":"기차가 늦게 오는 문제","mis":"SO3-2-u2-X30"}],"explanation":["기사 첫 줄이에요.","줄이고자 한 것이에요.","환경과 혼잡이에요."],"asset":{"type":"passage","lines":["(간추림) ○○시는 환경 문제와 교통 혼잡을 줄이고자 전기 자전거 공유 사업을 하고 있다.","이 자전거는 페달과 전기 모터를 함께 써서 노인이나 여성들도 힘들지 않게 탈 수 있다.","시는 자전거 전용 도로와 사람들의 안전을 위한 시설을 꾸준히 늘리고 있다.","공유 자전거는 도시의 미세 먼지를 줄이고 여가 생활과 건강에 도움을 준다."],"title":"『사회』 112쪽 미디어 활동 — 전기 자전거 공유 사업 신문 기사"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L12_basic#7','soc',3,2,'u2','L12','tb_g3_2_soc_u2_L12_basic','lesson_basic','SO3-2-u2-C12',2,'mc','auto','보행자가 지켜야 할 안전 수칙으로 알맞은 것은 무엇인가요?',ARRAY['SO3-2-u2-X31']::text[],false,'{"seq":7,"concept":"SO3-2-u2-C12","difficulty":2,"kind":"mc","stem":"보행자가 지켜야 할 안전 수칙으로 알맞은 것은 무엇인가요?","options":[{"t":"횡단보도를 건널 때는 주위를 잘 살피고 건너요","correct":true},{"t":"차가 없으면 무단 횡단을 해도 돼요","mis":"SO3-2-u2-X31"},{"t":"스마트폰을 보면서 걸어도 돼요","mis":"SO3-2-u2-X31"},{"t":"도로 옆에서 뛰어다녀도 돼요","mis":"SO3-2-u2-X31"}],"explanation":["113쪽 수칙이에요.","주위를 살펴요.","안전하게 건너요."],"asset":{"type":"passage","lines":["어린이 보호 구역에서는 천천히 가요.","횡단보도를 건널 때는 주위를 잘 살피고 안전하게 건너요.","자전거나 킥보드는 정해진 도로에서 안전 장비를 착용하고 타요."],"title":"『사회』 113쪽 — 교통안전 수칙"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L12_basic#8','soc',3,2,'u2','L12','tb_g3_2_soc_u2_L12_basic','lesson_basic','SO3-2-u2-C12',2,'blank','auto','「자전거나 킥보드는 정해진 도로에서 (    )를 착용하고 타요.」 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SO3-2-u2-X31']::text[],false,'{"seq":8,"concept":"SO3-2-u2-C12","difficulty":2,"kind":"blank","stem":"「자전거나 킥보드는 정해진 도로에서 (    )를 착용하고 타요.」 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"안전 장비","correct":true},{"t":"이어폰","mis":"SO3-2-u2-X31"},{"t":"슬리퍼","mis":"SO3-2-u2-X31"},{"t":"큰 가방","mis":"SO3-2-u2-X31"}],"explanation":["113쪽 그림이에요.","몸을 보호해요.","안전 장비예요."],"asset":{"type":"passage","lines":["어린이 보호 구역에서는 천천히 가요.","횡단보도를 건널 때는 주위를 잘 살피고 안전하게 건너요.","자전거나 킥보드는 정해진 도로에서 안전 장비를 착용하고 타요."],"title":"『사회』 113쪽 — 교통안전 수칙"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L12_basic#9','soc',3,2,'u2','L12','tb_g3_2_soc_u2_L12_basic','lesson_basic','SO3-2-u2-C12',2,'ox','auto','어린이는 보행자이니 자전거나 킥보드를 탈 때 지켜야 할 안전 수칙은 몰라도 돼요.',ARRAY['SO3-2-u2-X49']::text[],false,'{"seq":9,"concept":"SO3-2-u2-C12","difficulty":2,"kind":"ox","stem":"어린이는 보행자이니 자전거나 킥보드를 탈 때 지켜야 할 안전 수칙은 몰라도 돼요.","answer":"X","reason_options":[{"t":"어린이도 자전거나 킥보드를 타면 운전자가 되어 그 안전 수칙을 지켜야 하기 때문에","correct":true},{"t":"운전자 안전 수칙은 자동차 운전자에게만 있기 때문에","mis":"SO3-2-u2-X49"}],"mis":"SO3-2-u2-X49","explanation":["어린이도 탈것을 타요.","그때는 운전자예요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L12_basic#10','soc',3,2,'u2','L12','tb_g3_2_soc_u2_L12_basic','lesson_basic','SO3-2-u2-C12',3,'error','auto','교통 문제와 해결 노력을 짝지어 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO3-2-u2-X30']::text[],false,'{"seq":10,"concept":"SO3-2-u2-C12","difficulty":3,"kind":"error","stem":"교통 문제와 해결 노력을 짝지어 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「주차할 곳이 부족한 문제는 친환경 에너지 교통수단으로 바로 해결돼.」","correct":true,"mis_target":"SO3-2-u2-X30"},{"t":"친구 가 — 「새로운 주차 시설을 만들어 주차 문제를 줄여.」","mis":"SO3-2-u2-X30"},{"t":"친구 나 — 「막히는 길 정보를 빠르게 알려 교통 체증을 줄여.」","mis":"SO3-2-u2-X30"}],"explanation":["친환경 에너지는 환경 문제예요.","주차 문제는 주차 시설이에요.","친구 다가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L12_challenge#1','soc',3,2,'u2','L12','tb_g3_2_soc_u2_L12_challenge','lesson_challenge','SO3-2-u2-C12',2,'sa','auto','어린이 보호 구역에서 자동차는 어떻게 가야 하나요? 세 글자로 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"SO3-2-u2-C12","difficulty":2,"kind":"sa","stem":"어린이 보호 구역에서 자동차는 어떻게 가야 하나요? 세 글자로 쓰세요.","answer":["천천히"],"explanation":["113쪽 수칙이에요.","속도를 줄여요.","천천히예요."],"mis":"SO3-2-u2-X31"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L12_challenge#2','soc',3,2,'u2','L12','tb_g3_2_soc_u2_L12_challenge','lesson_challenge','SO3-2-u2-C12',2,'mc','auto','공유 전기 자전거가 페달과 전기 모터를 함께 쓰는 까닭은 무엇인가요?',ARRAY['SO3-2-u2-X30']::text[],false,'{"seq":2,"concept":"SO3-2-u2-C12","difficulty":2,"kind":"mc","stem":"공유 전기 자전거가 페달과 전기 모터를 함께 쓰는 까닭은 무엇인가요?","options":[{"t":"노인이나 여성들도 힘들지 않게 이용할 수 있도록요","correct":true},{"t":"더 큰 소리를 내려고요","mis":"SO3-2-u2-X30"},{"t":"자동차보다 빨리 달리려고요","mis":"SO3-2-u2-X30"},{"t":"한 사람만 쓰게 하려고요","mis":"SO3-2-u2-X30"}],"explanation":["기사 둘째 줄이에요.","힘들지 않게예요.","누구나 타도록요."],"asset":{"type":"passage","lines":["(간추림) ○○시는 환경 문제와 교통 혼잡을 줄이고자 전기 자전거 공유 사업을 하고 있다.","이 자전거는 페달과 전기 모터를 함께 써서 노인이나 여성들도 힘들지 않게 탈 수 있다.","시는 자전거 전용 도로와 사람들의 안전을 위한 시설을 꾸준히 늘리고 있다.","공유 자전거는 도시의 미세 먼지를 줄이고 여가 생활과 건강에 도움을 준다."],"title":"『사회』 112쪽 미디어 활동 — 전기 자전거 공유 사업 신문 기사"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L12_challenge#3','soc',3,2,'u2','L12','tb_g3_2_soc_u2_L12_challenge','lesson_challenge','SO3-2-u2-C12',3,'mc','auto','생활 주변에서 겪은 일과 교통 문제를 바르게 짝지은 것은 무엇인가요?',ARRAY['SO3-2-u2-X30']::text[],false,'{"seq":3,"concept":"SO3-2-u2-C12","difficulty":3,"kind":"mc","stem":"생활 주변에서 겪은 일과 교통 문제를 바르게 짝지은 것은 무엇인가요?","options":[{"t":"집 주변 도로에 차가 너무 많아 시끄러워요 — 대기 오염과 소음","correct":true},{"t":"차가 막혀 약속 시간에 늦었어요 — 주차 공간 부족","mis":"SO3-2-u2-X30"},{"t":"주차할 곳이 없어 한참 돌았어요 — 교통사고","mis":"SO3-2-u2-X30"},{"t":"도로에서 다른 차와 부딪쳤어요 — 교통 체증","mis":"SO3-2-u2-X30"}],"explanation":["겪은 일을 봐요.","시끄러운 것은 소음이에요.","그 짝이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L12_challenge#4','soc',3,2,'u2','L12','tb_g3_2_soc_u2_L12_challenge','lesson_challenge','SO3-2-u2-C12',3,'mc','auto','신문 기사에 나타난 전기 자전거 공유 사업의 효과는 무엇인가요?',ARRAY['SO3-2-u2-X32','SO3-2-u2-X30']::text[],false,'{"seq":4,"concept":"SO3-2-u2-C12","difficulty":3,"kind":"mc","stem":"신문 기사에 나타난 전기 자전거 공유 사업의 효과는 무엇인가요?","options":[{"t":"도시의 미세 먼지를 줄이고 여가 생활과 건강에 도움을 줘요","correct":true},{"t":"교통사고가 모두 사라졌어요","mis":"SO3-2-u2-X32"},{"t":"자동차가 더 많아졌어요","mis":"SO3-2-u2-X30"},{"t":"주차할 곳이 더 부족해졌어요","mis":"SO3-2-u2-X30"}],"explanation":["기사 마지막 줄이에요.","미세 먼지를 줄여요.","건강에도 도움을 줘요."],"asset":{"type":"passage","lines":["(간추림) ○○시는 환경 문제와 교통 혼잡을 줄이고자 전기 자전거 공유 사업을 하고 있다.","이 자전거는 페달과 전기 모터를 함께 써서 노인이나 여성들도 힘들지 않게 탈 수 있다.","시는 자전거 전용 도로와 사람들의 안전을 위한 시설을 꾸준히 늘리고 있다.","공유 자전거는 도시의 미세 먼지를 줄이고 여가 생활과 건강에 도움을 준다."],"title":"『사회』 112쪽 미디어 활동 — 전기 자전거 공유 사업 신문 기사"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L12_challenge#5','soc',3,2,'u2','L12','tb_g3_2_soc_u2_L12_challenge','lesson_challenge','SO3-2-u2-C12',3,'ox','auto','교통 문제가 생겼으니 교통수단을 모두 없애는 것이 가장 좋은 해결 방법이에요.',ARRAY['SO3-2-u2-X32']::text[],false,'{"seq":5,"concept":"SO3-2-u2-C12","difficulty":3,"kind":"ox","stem":"교통 문제가 생겼으니 교통수단을 모두 없애는 것이 가장 좋은 해결 방법이에요.","answer":"X","reason_options":[{"t":"교통수단은 생활을 편리하게 해 주므로 문제를 줄이는 노력을 하며 함께 써야 하기 때문에","correct":true},{"t":"문제가 생긴 것은 무조건 없애야 하기 때문에","mis":"SO3-2-u2-X32"}],"mis":"SO3-2-u2-X32","explanation":["편리함도 있어요.","문제를 줄이는 노력을 해요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L12_challenge#6','soc',3,2,'u2','L12','tb_g3_2_soc_u2_L12_challenge','lesson_challenge','SO3-2-u2-C12',3,'match','auto','교통 문제와 해결 노력을 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"SO3-2-u2-C12","difficulty":3,"kind":"match","stem":"교통 문제와 해결 노력을 알맞게 이으세요.","pairs":[{"l":"교통 체증","r":"막히는 길 정보를 빠르게 알리는 과학적인 교통 관리"},{"l":"대기 오염","r":"친환경 에너지를 쓰는 교통수단 이용"},{"l":"주차 공간 부족","r":"새로운 주차 시설 만들기"},{"l":"교통사고","r":"교통안전 수칙 지키기"}],"mis":"SO3-2-u2-X30","explanation":["체증은 정보 관리예요.","오염은 친환경 에너지예요.","주차는 시설, 사고는 수칙이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L12_challenge#7','soc',3,2,'u2','L12','tb_g3_2_soc_u2_L12_challenge','lesson_challenge','SO3-2-u2-C12',3,'error','auto','교통안전 수칙을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO3-2-u2-X31']::text[],false,'{"seq":7,"concept":"SO3-2-u2-C12","difficulty":3,"kind":"error","stem":"교통안전 수칙을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 나 — 「자동차가 조심하면 되니 보행자는 무단 횡단을 해도 괜찮아.」","correct":true,"mis_target":"SO3-2-u2-X31"},{"t":"친구 가 — 「자동차는 어린이 보호 구역에서 천천히 가야 해.」","mis":"SO3-2-u2-X31"},{"t":"친구 다 — 「스마트폰을 보면서 길을 걷지 않아야 해.」","mis":"SO3-2-u2-X31"}],"explanation":["보행자도 수칙이 있어요.","무단 횡단은 안 돼요.","친구 나가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L12_challenge#8','soc',3,2,'u2','L12','tb_g3_2_soc_u2_L12_challenge','lesson_challenge','SO3-2-u2-C12',4,'mc','auto','교통의 변화를 가장 바르게 본 것은 무엇인가요?',ARRAY['SO3-2-u2-X32','SO3-2-u2-X30']::text[],false,'{"seq":8,"concept":"SO3-2-u2-C12","difficulty":4,"kind":"mc","stem":"교통의 변화를 가장 바르게 본 것은 무엇인가요?","options":[{"t":"교통이 변화하며 편리해졌지만 문제도 생겨, 지금도 해결하려고 노력하고 있어요","correct":true},{"t":"편리해졌으니 아무 문제가 없어요","mis":"SO3-2-u2-X32"},{"t":"문제가 있으니 교통은 나빠지기만 했어요","mis":"SO3-2-u2-X32"},{"t":"교통 문제는 저절로 해결돼요","mis":"SO3-2-u2-X30"}],"explanation":["좋은 점이 있어요.","문제도 있어요.","노력하고 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L12_challenge#9','soc',3,2,'u2','L12','tb_g3_2_soc_u2_L12_challenge','lesson_challenge','SO3-2-u2-C12',4,'ox','auto','사람들의 교통안전 의식을 높이는 정책을 만드는 것도 교통 문제를 해결하려는 노력이에요.',ARRAY['SO3-2-u2-X31']::text[],false,'{"seq":9,"concept":"SO3-2-u2-C12","difficulty":4,"kind":"ox","stem":"사람들의 교통안전 의식을 높이는 정책을 만드는 것도 교통 문제를 해결하려는 노력이에요.","answer":"O","reason_options":[{"t":"사람들이 안전 수칙을 잘 지키면 교통사고를 미리 막을 수 있기 때문에","correct":true},{"t":"교통 문제는 시설만 바꾸면 되고 사람의 의식과는 관계없기 때문에","mis":"SO3-2-u2-X31"}],"mis":"SO3-2-u2-X31","explanation":["사람도 바뀌어야 해요.","수칙을 지켜요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L12_challenge#10','soc',3,2,'u2','L12','tb_g3_2_soc_u2_L12_challenge','lesson_challenge','SO3-2-u2-C12',4,'essay','teacher','교통수단 때문에 위험을 느낀 경험을 쓰고, 보행자와 운전자(자전거·킥보드를 탈 때)로서 지켜야 할 안전 수칙을 하나씩 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO3-2-u2-C12","difficulty":4,"kind":"essay","stem":"교통수단 때문에 위험을 느낀 경험을 쓰고, 보행자와 운전자(자전거·킥보드를 탈 때)로서 지켜야 할 안전 수칙을 하나씩 쓰세요.","answer_guide":{"answer":"예: 친구와 장난치다 차도로 뛰어들었는데 차가 갑자기 멈춰서 놀랐어요. 보행자로서 도로에서는 늘 주위를 살피고 장난치지 않아요. 자전거를 탈 때는 안전 장비를 착용하고 자전거 도로로 다녀요.","scoring_points":["위험을 느낀 경험을 썼는가","보행자 수칙을 썼는가","운전자 수칙을 썼는가"]},"explanation":["경험을 떠올려요.","보행자 수칙이에요.","운전자 수칙이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L13_basic#1','soc',3,2,'u2','L13','tb_g3_2_soc_u2_L13_basic','lesson_basic','SO3-2-u2-C13',1,'mc','auto','장애인, 환자 등이 안전하게 이동하도록 돕는 미래 교통수단은 무엇인가요?',ARRAY['SO3-2-u2-X33']::text[],true,'{"seq":1,"concept":"SO3-2-u2-C13","difficulty":1,"kind":"mc","stem":"장애인, 환자 등이 안전하게 이동하도록 돕는 미래 교통수단은 무엇인가요?","options":[{"t":"자율 주행 휠체어","correct":true},{"t":"착용하는 로봇","mis":"SO3-2-u2-X33"},{"t":"우주선","mis":"SO3-2-u2-X33"},{"t":"자율 운항 선박","mis":"SO3-2-u2-X33"}],"explanation":["114쪽 사진이에요.","안전하게 이동해요.","자율 주행 휠체어예요."],"asset":{"type":"passage","lines":["우주선 — 우주여행을 하거나 물건을 운반할 수 있어요.","착용하는 로봇 — 무거운 물건을 쉽게 들도록 도와요.","자율 주행 휠체어 — 장애인, 환자 등이 안전하게 이동하도록 도와요.","자율 주행 자동차 — 사람이 직접 운전할 필요가 없어요.","자율 운항 선박 — 스스로 목적지까지 운항하는 배예요.","초고속 자기 부상 열차 — 터널을 통해 비행기보다 빠르게 달려요."],"title":"『사회』 114~115쪽 — 연구, 개발 중인 미래 교통수단"},"variant_rule":{"alt":[{"stem":"무거운 물건을 쉽게 들도록 돕는 미래 교통수단은 무엇인가요?","options":[{"t":"착용하는 로봇","correct":true},{"t":"자율 주행 휠체어","mis":"SO3-2-u2-X33"},{"t":"초고속 자기 부상 열차","mis":"SO3-2-u2-X33"},{"t":"자율 주행 자동차","mis":"SO3-2-u2-X33"}],"explanation":["114쪽 사진이에요.","몸에 입어요.","착용하는 로봇이에요."],"asset":{"type":"passage","lines":["우주선 — 우주여행을 하거나 물건을 운반할 수 있어요.","착용하는 로봇 — 무거운 물건을 쉽게 들도록 도와요.","자율 주행 휠체어 — 장애인, 환자 등이 안전하게 이동하도록 도와요.","자율 주행 자동차 — 사람이 직접 운전할 필요가 없어요.","자율 운항 선박 — 스스로 목적지까지 운항하는 배예요.","초고속 자기 부상 열차 — 터널을 통해 비행기보다 빠르게 달려요."],"title":"『사회』 114~115쪽 — 연구, 개발 중인 미래 교통수단"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L13_basic#2','soc',3,2,'u2','L13','tb_g3_2_soc_u2_L13_basic','lesson_basic','SO3-2-u2-C13',1,'sa','auto','꼭 기억해요 2에서 전기의 힘으로 공중에 떠서 이동하는 교통수단을 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SO3-2-u2-C13","difficulty":1,"kind":"sa","stem":"꼭 기억해요 2에서 전기의 힘으로 공중에 떠서 이동하는 교통수단을 쓰세요.","answer":["초고속 자기 부상 열차","자기 부상 열차","초고속자기부상열차","자기부상열차"],"explanation":["공중에 떠요.","자기 부상이에요.","초고속 자기 부상 열차예요."],"mis":"SO3-2-u2-X33"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L13_basic#3','soc',3,2,'u2','L13','tb_g3_2_soc_u2_L13_basic','lesson_basic','SO3-2-u2-C13',1,'mc','auto','『사회』 115쪽 사진에서 사람이 직접 운전할 필요가 없는 미래 교통수단은 무엇인가요?',ARRAY['SO3-2-u2-X33','SO3-2-u2-X25','SO3-2-u2-X23']::text[],false,'{"seq":3,"concept":"SO3-2-u2-C13","difficulty":1,"kind":"mc","stem":"『사회』 115쪽 사진에서 사람이 직접 운전할 필요가 없는 미래 교통수단은 무엇인가요?","options":[{"t":"자율 주행 자동차","correct":true},{"t":"초고속 자기 부상 열차","mis":"SO3-2-u2-X33"},{"t":"증기 기차","mis":"SO3-2-u2-X25"},{"t":"달구지","mis":"SO3-2-u2-X23"}],"explanation":["115쪽 사진이에요.","스스로 달려요.","자율 주행 자동차예요."],"asset":{"type":"passage","lines":["우주선 — 우주여행을 하거나 물건을 운반할 수 있어요.","착용하는 로봇 — 무거운 물건을 쉽게 들도록 도와요.","자율 주행 휠체어 — 장애인, 환자 등이 안전하게 이동하도록 도와요.","자율 주행 자동차 — 사람이 직접 운전할 필요가 없어요.","자율 운항 선박 — 스스로 목적지까지 운항하는 배예요.","초고속 자기 부상 열차 — 터널을 통해 비행기보다 빠르게 달려요."],"title":"『사회』 114~115쪽 — 연구, 개발 중인 미래 교통수단"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L13_basic#4','soc',3,2,'u2','L13','tb_g3_2_soc_u2_L13_basic','lesson_basic','SO3-2-u2-C13',1,'ox','auto','미래 교통수단은 더 빨리 이동하는 방향으로만 발전하고 있어요.',ARRAY['SO3-2-u2-X34']::text[],false,'{"seq":4,"concept":"SO3-2-u2-C13","difficulty":1,"kind":"ox","stem":"미래 교통수단은 더 빨리 이동하는 방향으로만 발전하고 있어요.","answer":"X","reason_options":[{"t":"더 빠르고 안전하면서 환경을 보호하는 방향으로 발전하고 있기 때문에","correct":true},{"t":"미래 교통은 빠르기만 하면 되기 때문에","mis":"SO3-2-u2-X34"}],"mis":"SO3-2-u2-X34","explanation":["꼭 기억해요 1이에요.","안전과 환경도 생각해요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L13_basic#5','soc',3,2,'u2','L13','tb_g3_2_soc_u2_L13_basic','lesson_basic','SO3-2-u2-C13',2,'match','auto','114~115쪽에 나온 미래 교통수단과 그 특징을 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"SO3-2-u2-C13","difficulty":2,"kind":"match","stem":"114~115쪽에 나온 미래 교통수단과 그 특징을 알맞게 이으세요.","pairs":[{"l":"우주선","r":"우주여행을 하거나 우주로 물건을 운반해요"},{"l":"자율 운항 선박","r":"스스로 목적지까지 운항하는 배예요"},{"l":"초고속 자기 부상 열차","r":"터널을 통해 비행기보다 빠르게 달려요"},{"l":"자율 주행 휠체어","r":"몸이 불편한 사람이 안전하게 이동하도록 도와요"}],"mis":"SO3-2-u2-X33","explanation":["우주선은 우주예요.","선박은 배, 열차는 터널이에요.","휠체어는 안전한 이동이에요."],"asset":{"type":"passage","lines":["우주선 — 우주여행을 하거나 물건을 운반할 수 있어요.","착용하는 로봇 — 무거운 물건을 쉽게 들도록 도와요.","자율 주행 휠체어 — 장애인, 환자 등이 안전하게 이동하도록 도와요.","자율 주행 자동차 — 사람이 직접 운전할 필요가 없어요.","자율 운항 선박 — 스스로 목적지까지 운항하는 배예요.","초고속 자기 부상 열차 — 터널을 통해 비행기보다 빠르게 달려요."],"title":"『사회』 114~115쪽 — 연구, 개발 중인 미래 교통수단"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L13_basic#6','soc',3,2,'u2','L13','tb_g3_2_soc_u2_L13_basic','lesson_basic','SO3-2-u2-C13',2,'mc','auto','신문 기사에서 도심 항공 교통이 교통로로 삼는 곳은 어디인가요?',ARRAY['SO3-2-u2-X33']::text[],false,'{"seq":6,"concept":"SO3-2-u2-C13","difficulty":2,"kind":"mc","stem":"신문 기사에서 도심 항공 교통이 교통로로 삼는 곳은 어디인가요?","options":[{"t":"300~600 m 높이의 하늘","correct":true},{"t":"땅속 터널","mis":"SO3-2-u2-X33"},{"t":"바닷속","mis":"SO3-2-u2-X33"},{"t":"지금의 도로","mis":"SO3-2-u2-X33"}],"explanation":["기사 첫 줄이에요.","하늘을 나는 택시예요.","하늘이에요."],"asset":{"type":"passage","lines":["(간추림) 도심 항공 교통은 300~600 m 높이의 하늘을 교통로로 삼는 미래 교통 체계이다.","수직으로 이착륙하는 교통수단과 전용 이착륙장, 교통 관리 체계로 이루어진다.","친환경 에너지로 움직여 공해와 소음이 적어 환경에 미치는 영향이 적다.","하늘로 다녀 땅에서와 같은 교통 혼잡 문제를 일으키지 않는다.","말풍선 — 공항처럼 큰 시설이 필요하지 않고, 도로를 더 만들지 않아도 돼요."],"title":"『사회』 116쪽 신문 기사 「‘하늘을 나는 택시’ 도심 항공 교통 기술 개발」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L13_basic#7','soc',3,2,'u2','L13','tb_g3_2_soc_u2_L13_basic','lesson_basic','SO3-2-u2-C13',2,'mc','auto','자율 주행 자동차가 생기면 달라질 생활 모습으로 알맞은 것은 무엇인가요?',ARRAY['SO3-2-u2-X33','SO3-2-u2-X34']::text[],false,'{"seq":7,"concept":"SO3-2-u2-C13","difficulty":2,"kind":"mc","stem":"자율 주행 자동차가 생기면 달라질 생활 모습으로 알맞은 것은 무엇인가요?","options":[{"t":"차 안이 이동뿐 아니라 일하고 쉬는 공간이 될 거예요","correct":true},{"t":"운전하는 사람이 더 바빠질 거예요","mis":"SO3-2-u2-X33"},{"t":"차 안에서는 아무것도 할 수 없을 거예요","mis":"SO3-2-u2-X33"},{"t":"길이 더 막히기만 할 거예요","mis":"SO3-2-u2-X34"}],"explanation":["운전할 필요가 없어요.","시간이 남아요.","일하고 쉬는 공간이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L13_basic#8','soc',3,2,'u2','L13','tb_g3_2_soc_u2_L13_basic','lesson_basic','SO3-2-u2-C13',2,'blank','auto','「(    )의 힘으로 물체를 들어 올리는 것을 자기 부상이라고 해요.」 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SO3-2-u2-X33','SO3-2-u2-X25','SO3-2-u2-X24']::text[],false,'{"seq":8,"concept":"SO3-2-u2-C13","difficulty":2,"kind":"blank","stem":"「(    )의 힘으로 물체를 들어 올리는 것을 자기 부상이라고 해요.」 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"전기","correct":true},{"t":"바람","mis":"SO3-2-u2-X33"},{"t":"수증기","mis":"SO3-2-u2-X25"},{"t":"사람","mis":"SO3-2-u2-X24"}],"explanation":["115쪽 낱말 풀이예요.","전기예요.","자기 부상이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L13_basic#9','soc',3,2,'u2','L13','tb_g3_2_soc_u2_L13_basic','lesson_basic','SO3-2-u2-C13',2,'ox','auto','도심 항공 교통은 하늘로 다니므로 땅에서와 같은 교통 혼잡 문제를 일으키지 않아요.',ARRAY['SO3-2-u2-X33']::text[],false,'{"seq":9,"concept":"SO3-2-u2-C13","difficulty":2,"kind":"ox","stem":"도심 항공 교통은 하늘로 다니므로 땅에서와 같은 교통 혼잡 문제를 일으키지 않아요.","answer":"O","reason_options":[{"t":"기사처럼 땅의 도로가 아닌 하늘을 교통로로 삼기 때문에","correct":true},{"t":"하늘에서도 땅과 똑같이 차가 막히기 때문에","mis":"SO3-2-u2-X33"}],"mis":"SO3-2-u2-X33","explanation":["기사 넷째 줄이에요.","하늘로 다녀요.","그래서 O예요."],"asset":{"type":"passage","lines":["(간추림) 도심 항공 교통은 300~600 m 높이의 하늘을 교통로로 삼는 미래 교통 체계이다.","수직으로 이착륙하는 교통수단과 전용 이착륙장, 교통 관리 체계로 이루어진다.","친환경 에너지로 움직여 공해와 소음이 적어 환경에 미치는 영향이 적다.","하늘로 다녀 땅에서와 같은 교통 혼잡 문제를 일으키지 않는다.","말풍선 — 공항처럼 큰 시설이 필요하지 않고, 도로를 더 만들지 않아도 돼요."],"title":"『사회』 116쪽 신문 기사 「‘하늘을 나는 택시’ 도심 항공 교통 기술 개발」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L13_basic#10','soc',3,2,'u2','L13','tb_g3_2_soc_u2_L13_basic','lesson_basic','SO3-2-u2-C13',3,'error','auto','미래 교통수단을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO3-2-u2-X33']::text[],false,'{"seq":10,"concept":"SO3-2-u2-C13","difficulty":3,"kind":"error","stem":"미래 교통수단을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 나 — 「자율 운항 선박은 하늘을 나는 택시야.」","correct":true,"mis_target":"SO3-2-u2-X33"},{"t":"친구 가 — 「도심 항공 교통은 하늘을 나는 택시라고 불러.」","mis":"SO3-2-u2-X33"},{"t":"친구 다 — 「착용하는 로봇은 무거운 물건을 쉽게 들게 도와.」","mis":"SO3-2-u2-X33"}],"explanation":["선박은 배예요.","하늘을 나는 택시는 도심 항공 교통이에요.","친구 나가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L13_challenge#1','soc',3,2,'u2','L13','tb_g3_2_soc_u2_L13_challenge','lesson_challenge','SO3-2-u2-C13',2,'sa','auto','도심 항공 교통이 발달하면 생길 직업 가운데 하늘길의 교통을 관리하는 직업을 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"SO3-2-u2-C13","difficulty":2,"kind":"sa","stem":"도심 항공 교통이 발달하면 생길 직업 가운데 하늘길의 교통을 관리하는 직업을 쓰세요.","answer":["도심 항공 관제사","도심항공관제사"],"explanation":["116쪽 예시예요.","관제사예요.","도심 항공 관제사예요."],"mis":"SO3-2-u2-X33"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L13_challenge#2','soc',3,2,'u2','L13','tb_g3_2_soc_u2_L13_challenge','lesson_challenge','SO3-2-u2-C13',2,'mc','auto','관광용 우주선이 발달하면 새로 생길 수 있는 직업은 무엇인가요?',ARRAY['SO3-2-u2-X29']::text[],false,'{"seq":2,"concept":"SO3-2-u2-C13","difficulty":2,"kind":"mc","stem":"관광용 우주선이 발달하면 새로 생길 수 있는 직업은 무엇인가요?","options":[{"t":"우주 관광 가이드","correct":true},{"t":"가마꾼","mis":"SO3-2-u2-X29"},{"t":"뱃사공","mis":"SO3-2-u2-X29"},{"t":"달구지를 고치는 사람","mis":"SO3-2-u2-X29"}],"explanation":["우주를 관광해요.","안내하는 사람이에요.","우주 관광 가이드예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L13_challenge#3','soc',3,2,'u2','L13','tb_g3_2_soc_u2_L13_challenge','lesson_challenge','SO3-2-u2-C13',3,'mc','auto','도심 항공 교통의 장점끼리 묶은 것은 무엇인가요?',ARRAY['SO3-2-u2-X34','SO3-2-u2-X24']::text[],false,'{"seq":3,"concept":"SO3-2-u2-C13","difficulty":3,"kind":"mc","stem":"도심 항공 교통의 장점끼리 묶은 것은 무엇인가요?","options":[{"t":"공항처럼 큰 시설이 필요 없고, 공해와 소음이 적어요","correct":true},{"t":"도로를 더 많이 만들어야 하고, 석유를 많이 써요","mis":"SO3-2-u2-X34"},{"t":"사람이 직접 들고 날라야 해요","mis":"SO3-2-u2-X24"},{"t":"땅에서 차가 더 막히게 해요","mis":"SO3-2-u2-X34"}],"explanation":["말풍선을 봐요.","큰 시설이 없어도 돼요.","환경 영향이 적어요."],"asset":{"type":"passage","lines":["(간추림) 도심 항공 교통은 300~600 m 높이의 하늘을 교통로로 삼는 미래 교통 체계이다.","수직으로 이착륙하는 교통수단과 전용 이착륙장, 교통 관리 체계로 이루어진다.","친환경 에너지로 움직여 공해와 소음이 적어 환경에 미치는 영향이 적다.","하늘로 다녀 땅에서와 같은 교통 혼잡 문제를 일으키지 않는다.","말풍선 — 공항처럼 큰 시설이 필요하지 않고, 도로를 더 만들지 않아도 돼요."],"title":"『사회』 116쪽 신문 기사 「‘하늘을 나는 택시’ 도심 항공 교통 기술 개발」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L13_challenge#4','soc',3,2,'u2','L13','tb_g3_2_soc_u2_L13_challenge','lesson_challenge','SO3-2-u2-C13',3,'mc','auto','미래 교통수단의 특징이 될 수 있는 말끼리 묶은 것은 무엇인가요?',ARRAY['SO3-2-u2-X34','SO3-2-u2-X24']::text[],false,'{"seq":4,"concept":"SO3-2-u2-C13","difficulty":3,"kind":"mc","stem":"미래 교통수단의 특징이 될 수 있는 말끼리 묶은 것은 무엇인가요?","options":[{"t":"안전 강화, 환경 보호","correct":true},{"t":"혼잡 유발, 시설 부족","mis":"SO3-2-u2-X34"},{"t":"동물의 힘, 환경 보호","mis":"SO3-2-u2-X24"},{"t":"혼잡 유발, 안전 강화","mis":"SO3-2-u2-X34"}],"explanation":["발전 방향을 떠올려요.","안전하고 환경을 지켜요.","안전 강화, 환경 보호예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L13_challenge#5','soc',3,2,'u2','L13','tb_g3_2_soc_u2_L13_challenge','lesson_challenge','SO3-2-u2-C13',3,'ox','auto','미래 교통수단이 발달하면 교통수단을 이용하기 불편했던 사람들도 편하게 이용할 수 있을 거예요.',ARRAY['SO3-2-u2-X34']::text[],false,'{"seq":5,"concept":"SO3-2-u2-C13","difficulty":3,"kind":"ox","stem":"미래 교통수단이 발달하면 교통수단을 이용하기 불편했던 사람들도 편하게 이용할 수 있을 거예요.","answer":"O","reason_options":[{"t":"자율 주행 휠체어처럼 몸이 불편한 사람의 이동을 돕는 교통수단이 개발되고 있기 때문에","correct":true},{"t":"미래 교통수단은 빠르기만 할 뿐 몸이 불편한 사람과는 상관없기 때문에","mis":"SO3-2-u2-X34"}],"mis":"SO3-2-u2-X34","explanation":["114쪽 사진이에요.","자율 주행 휠체어예요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L13_challenge#6','soc',3,2,'u2','L13','tb_g3_2_soc_u2_L13_challenge','lesson_challenge','SO3-2-u2-C13',3,'match','auto','미래 교통수단과 새로 생길 수 있는 직업을 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"SO3-2-u2-C13","difficulty":3,"kind":"match","stem":"미래 교통수단과 새로 생길 수 있는 직업을 알맞게 이으세요.","pairs":[{"l":"자율 주행 자동차","r":"인공지능 개발자"},{"l":"우주선","r":"우주여행 가이드"},{"l":"도심 항공 교통","r":"이착륙장 관리자"}],"mis":"SO3-2-u2-X33","explanation":["자율 주행은 인공지능이에요.","우주선은 가이드예요.","도심 항공은 이착륙장이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L13_challenge#7','soc',3,2,'u2','L13','tb_g3_2_soc_u2_L13_challenge','lesson_challenge','SO3-2-u2-C13',3,'error','auto','미래 생활을 상상하며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO3-2-u2-X34','SO3-2-u2-X33']::text[],false,'{"seq":7,"concept":"SO3-2-u2-C13","difficulty":3,"kind":"error","stem":"미래 생활을 상상하며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「미래 교통은 지금과 똑같아서 생활 모습도 바뀌지 않을 거야.」","correct":true,"mis_target":"SO3-2-u2-X34"},{"t":"친구 가 — 「더 빠르게 더 먼 곳으로 이동할 수 있을 거야.」","mis":"SO3-2-u2-X33"},{"t":"친구 나 — 「우주로 물건을 옮기는 일이 더 쉬워질 거야.」","mis":"SO3-2-u2-X33"}],"explanation":["미래 교통은 달라져요.","생활도 달라져요.","친구 다가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L13_challenge#8','soc',3,2,'u2','L13','tb_g3_2_soc_u2_L13_challenge','lesson_challenge','SO3-2-u2-C13',4,'mc','auto','미래 교통이 발전하는 방향을 바르게 정리한 것은 무엇인가요?',ARRAY['SO3-2-u2-X34']::text[],false,'{"seq":8,"concept":"SO3-2-u2-C13","difficulty":4,"kind":"mc","stem":"미래 교통이 발전하는 방향을 바르게 정리한 것은 무엇인가요?","options":[{"t":"더 빠르고 안전하면서 환경을 보호하는 방향","correct":true},{"t":"빠르기만 하면 되는 방향","mis":"SO3-2-u2-X34"},{"t":"지금 교통수단을 그대로 두는 방향","mis":"SO3-2-u2-X34"},{"t":"환경은 생각하지 않는 방향","mis":"SO3-2-u2-X34"}],"explanation":["114쪽 첫 글이에요.","세 가지를 함께 봐요.","빠름, 안전, 환경이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L13_challenge#9','soc',3,2,'u2','L13','tb_g3_2_soc_u2_L13_challenge','lesson_challenge','SO3-2-u2-C13',4,'ox','auto','도심 항공 교통수단은 친환경 에너지로 움직여 환경에 미치는 영향이 적어요.',ARRAY['SO3-2-u2-X34']::text[],false,'{"seq":9,"concept":"SO3-2-u2-C13","difficulty":4,"kind":"ox","stem":"도심 항공 교통수단은 친환경 에너지로 움직여 환경에 미치는 영향이 적어요.","answer":"O","reason_options":[{"t":"기사에 공해와 소음이 적다고 나와 있기 때문에","correct":true},{"t":"하늘을 나는 교통수단은 모두 석유를 많이 쓰기 때문에","mis":"SO3-2-u2-X34"}],"mis":"SO3-2-u2-X34","explanation":["기사 셋째 줄이에요.","친환경 에너지예요.","그래서 O예요."],"asset":{"type":"passage","lines":["(간추림) 도심 항공 교통은 300~600 m 높이의 하늘을 교통로로 삼는 미래 교통 체계이다.","수직으로 이착륙하는 교통수단과 전용 이착륙장, 교통 관리 체계로 이루어진다.","친환경 에너지로 움직여 공해와 소음이 적어 환경에 미치는 영향이 적다.","하늘로 다녀 땅에서와 같은 교통 혼잡 문제를 일으키지 않는다.","말풍선 — 공항처럼 큰 시설이 필요하지 않고, 도로를 더 만들지 않아도 돼요."],"title":"『사회』 116쪽 신문 기사 「‘하늘을 나는 택시’ 도심 항공 교통 기술 개발」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L13_challenge#10','soc',3,2,'u2','L13','tb_g3_2_soc_u2_L13_challenge','lesson_challenge','SO3-2-u2-C13',4,'essay','teacher','미래 교통수단 하나를 골라 미래의 내가 이용한다면 좋은 점을 쓰고, 그 교통수단과 관련해 새로 생길 직업을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO3-2-u2-C13","difficulty":4,"kind":"essay","stem":"미래 교통수단 하나를 골라 미래의 내가 이용한다면 좋은 점을 쓰고, 그 교통수단과 관련해 새로 생길 직업을 쓰세요.","answer_guide":{"answer":"예: 초고속 자기 부상 열차 — 비행기보다 빠르게 이동할 수 있어 멀리 사는 친척 집에도 자주 갈 수 있을 거예요. 자기 부상 열차 설계사나 터널 시공자 같은 직업이 생길 거예요.","scoring_points":["미래 교통수단을 골랐는가","좋은 점을 썼는가","새로 생길 직업을 썼는가"]},"explanation":["하나를 골라요.","좋은 점이에요.","직업을 써요."],"asset":{"type":"passage","lines":["우주선 — 우주여행을 하거나 물건을 운반할 수 있어요.","착용하는 로봇 — 무거운 물건을 쉽게 들도록 도와요.","자율 주행 휠체어 — 장애인, 환자 등이 안전하게 이동하도록 도와요.","자율 주행 자동차 — 사람이 직접 운전할 필요가 없어요.","자율 운항 선박 — 스스로 목적지까지 운항하는 배예요.","초고속 자기 부상 열차 — 터널을 통해 비행기보다 빠르게 달려요."],"title":"『사회』 114~115쪽 — 연구, 개발 중인 미래 교통수단"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L14_basic#1','soc',3,2,'u2','L14','tb_g3_2_soc_u2_L14_basic','lesson_basic','SO3-2-u2-C14',1,'mc','auto','117쪽 옛날 사람들이 상상한 미래 교통수단 그림 두 가지 가운데 하늘로 다니는 것은 무엇인가요?',ARRAY['SO3-2-u2-X33','SO3-2-u2-X23','SO3-2-u2-X25']::text[],false,'{"seq":1,"concept":"SO3-2-u2-C14","difficulty":1,"kind":"mc","stem":"117쪽 옛날 사람들이 상상한 미래 교통수단 그림 두 가지 가운데 하늘로 다니는 것은 무엇인가요?","options":[{"t":"하늘을 나는 택시","correct":true},{"t":"기계로 움직이는 눈썰매","mis":"SO3-2-u2-X33"},{"t":"돛단배","mis":"SO3-2-u2-X23"},{"t":"증기선","mis":"SO3-2-u2-X25"}],"explanation":["그림 ②예요.","하늘을 날아요.","하늘을 나는 택시예요."],"asset":{"type":"passage","lines":["옛날 사람들이 상상한 그림 ① — 기계로 움직이는 눈썰매(1899년)","옛날 사람들이 상상한 그림 ② — 하늘을 나는 택시(1912년)","내가 상상한 미래 교통수단 — 하늘을 날 수 있는 장치와 안전하게 착륙하는 기능을 넣은 신발","달라질 생활 모습 — 언제든지 쉽고 빠르게 이동하고, 도로가 줄고 공원이 많아질 거예요."],"title":"『사회』 117쪽 — 100년 후의 교통수단 상상하기 예시"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L14_basic#2','soc',3,2,'u2','L14','tb_g3_2_soc_u2_L14_basic','lesson_basic','SO3-2-u2-C14',1,'sa','auto','거리를 걸으면서 스마트폰을 사용하지 말라는 뜻의 교통 표지판이 있는 나라는 어디인가요?','{}'::text[],false,'{"seq":2,"concept":"SO3-2-u2-C14","difficulty":1,"kind":"sa","stem":"거리를 걸으면서 스마트폰을 사용하지 말라는 뜻의 교통 표지판이 있는 나라는 어디인가요?","answer":["스웨덴"],"explanation":["118쪽이에요.","스◯◯이에요.","스웨덴이에요."],"asset":{"type":"passage","lines":["네덜란드 — 보행자 우선 도로임을 알리는 교통 표지판","영국 — 도로를 가로지르는 동물을 조심하라는 뜻의 교통 표지판","스웨덴 — 거리를 걸으면서 스마트폰을 사용하지 말라는 뜻의 교통 표지판"],"title":"『사회』 118쪽 — 여러 나라의 독특한 교통 표지판"},"mis":"SO3-2-u2-X31"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L14_basic#3','soc',3,2,'u2','L14','tb_g3_2_soc_u2_L14_basic','lesson_basic','SO3-2-u2-C14',1,'mc','auto','118쪽에서 영국의 교통 표지판은 무엇을 알리나요?',ARRAY['SO3-2-u2-X27']::text[],true,'{"seq":3,"concept":"SO3-2-u2-C14","difficulty":1,"kind":"mc","stem":"118쪽에서 영국의 교통 표지판은 무엇을 알리나요?","options":[{"t":"도로를 가로지르는 동물을 조심하라는 뜻","correct":true},{"t":"보행자 우선 도로","mis":"SO3-2-u2-X27"},{"t":"걸으면서 스마트폰을 쓰지 말라는 뜻","mis":"SO3-2-u2-X27"},{"t":"자전거 전용 도로","mis":"SO3-2-u2-X27"}],"explanation":["영국이에요.","동물이에요.","동물 조심이에요."],"asset":{"type":"passage","lines":["네덜란드 — 보행자 우선 도로임을 알리는 교통 표지판","영국 — 도로를 가로지르는 동물을 조심하라는 뜻의 교통 표지판","스웨덴 — 거리를 걸으면서 스마트폰을 사용하지 말라는 뜻의 교통 표지판"],"title":"『사회』 118쪽 — 여러 나라의 독특한 교통 표지판"},"variant_rule":{"alt":[{"stem":"118쪽에서 네덜란드의 교통 표지판은 무엇을 알리나요?","options":[{"t":"보행자 우선 도로","correct":true},{"t":"동물 조심","mis":"SO3-2-u2-X27"},{"t":"걸으면서 스마트폰을 쓰지 말라는 뜻","mis":"SO3-2-u2-X27"},{"t":"철도 건널목","mis":"SO3-2-u2-X27"}],"explanation":["네덜란드예요.","걷는 사람이에요.","보행자 우선 도로예요."],"asset":{"type":"passage","lines":["네덜란드 — 보행자 우선 도로임을 알리는 교통 표지판","영국 — 도로를 가로지르는 동물을 조심하라는 뜻의 교통 표지판","스웨덴 — 거리를 걸으면서 스마트폰을 사용하지 말라는 뜻의 교통 표지판"],"title":"『사회』 118쪽 — 여러 나라의 독특한 교통 표지판"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L14_basic#4','soc',3,2,'u2','L14','tb_g3_2_soc_u2_L14_basic','lesson_basic','SO3-2-u2-C14',1,'ox','auto','돋보기 탐정의 단서 2처럼 교통이 발달하면서 교통의 문제점이 모두 해결됐어요.',ARRAY['SO3-2-u2-X32']::text[],false,'{"seq":4,"concept":"SO3-2-u2-C14","difficulty":1,"kind":"ox","stem":"돋보기 탐정의 단서 2처럼 교통이 발달하면서 교통의 문제점이 모두 해결됐어요.","answer":"X","reason_options":[{"t":"교통 체증, 환경 문제 같은 문제가 생겨 지금도 해결하려고 노력하고 있기 때문에","correct":true},{"t":"교통이 발달하면 문제는 저절로 사라지기 때문에","mis":"SO3-2-u2-X32"}],"mis":"SO3-2-u2-X32","explanation":["18차시를 떠올려요.","문제가 남아 있어요.","그래서 X예요."],"asset":{"type":"passage","lines":["단서 1 — 교통의 발달로 사람들과 물건의 이동이 빨라지고 편리해졌습니다.","단서 2 — 교통이 발달하면서 교통의 문제점이 모두 해결됐습니다.","단서 3 — 교통의 변화로 여러 가지 새로운 시설이 생기고 사람들의 생활 모습이 달라졌습니다."],"numbered":false,"title":"『사회』 119쪽 재미있게 확인해요 — 돋보기 탐정의 단서"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L14_basic#5','soc',3,2,'u2','L14','tb_g3_2_soc_u2_L14_basic','lesson_basic','SO3-2-u2-C14',2,'mc','auto','돋보기 탐정의 단서 가운데 옳은 설명끼리 묶은 것은 무엇인가요?',ARRAY['SO3-2-u2-X32']::text[],false,'{"seq":5,"concept":"SO3-2-u2-C14","difficulty":2,"kind":"mc","stem":"돋보기 탐정의 단서 가운데 옳은 설명끼리 묶은 것은 무엇인가요?","options":[{"t":"단서 1, 단서 3","correct":true},{"t":"단서 1, 단서 2","mis":"SO3-2-u2-X32"},{"t":"단서 2, 단서 3","mis":"SO3-2-u2-X32"},{"t":"단서 1, 단서 2, 단서 3","mis":"SO3-2-u2-X32"}],"explanation":["하나씩 O, X를 해요.","단서 2는 X예요.","단서 1과 3이에요."],"asset":{"type":"passage","lines":["단서 1 — 교통의 발달로 사람들과 물건의 이동이 빨라지고 편리해졌습니다.","단서 2 — 교통이 발달하면서 교통의 문제점이 모두 해결됐습니다.","단서 3 — 교통의 변화로 여러 가지 새로운 시설이 생기고 사람들의 생활 모습이 달라졌습니다."],"numbered":false,"title":"『사회』 119쪽 재미있게 확인해요 — 돋보기 탐정의 단서"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L14_basic#6','soc',3,2,'u2','L14','tb_g3_2_soc_u2_L14_basic','lesson_basic','SO3-2-u2-C14',2,'match','auto','교통 단원의 내용을 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"SO3-2-u2-C14","difficulty":2,"kind":"match","stem":"교통 단원의 내용을 알맞게 이으세요.","pairs":[{"l":"옛날 교통수단","r":"사람, 동물, 자연의 힘을 이용해요"},{"l":"오늘날 교통수단","r":"기계의 힘을 이용해요"},{"l":"교통의 발달","r":"생활 공간이 넓어졌어요"},{"l":"교통의 문제","r":"교통 체증, 환경 문제가 생겼어요"}],"mis":"SO3-2-u2-X24","explanation":["옛날은 자연의 힘이에요.","오늘날은 기계예요.","발달과 문제를 함께 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L14_basic#7','soc',3,2,'u2','L14','tb_g3_2_soc_u2_L14_basic','lesson_basic','SO3-2-u2-C14',2,'mc','auto','117쪽 예시처럼 하늘을 나는 신발이 생기면 달라질 생활 모습으로 알맞은 것은 무엇인가요?',ARRAY['SO3-2-u2-X34']::text[],false,'{"seq":7,"concept":"SO3-2-u2-C14","difficulty":2,"kind":"mc","stem":"117쪽 예시처럼 하늘을 나는 신발이 생기면 달라질 생활 모습으로 알맞은 것은 무엇인가요?","options":[{"t":"차를 타고 이동할 필요가 없어져 도로가 줄고 공원이 많아질 거예요","correct":true},{"t":"도로가 더 많이 필요해질 거예요","mis":"SO3-2-u2-X34"},{"t":"이동이 더 느려질 거예요","mis":"SO3-2-u2-X34"},{"t":"아무것도 바뀌지 않을 거예요","mis":"SO3-2-u2-X34"}],"explanation":["예시를 봐요.","도로가 줄어요.","공원이 많아져요."],"asset":{"type":"passage","lines":["옛날 사람들이 상상한 그림 ① — 기계로 움직이는 눈썰매(1899년)","옛날 사람들이 상상한 그림 ② — 하늘을 나는 택시(1912년)","내가 상상한 미래 교통수단 — 하늘을 날 수 있는 장치와 안전하게 착륙하는 기능을 넣은 신발","달라질 생활 모습 — 언제든지 쉽고 빠르게 이동하고, 도로가 줄고 공원이 많아질 거예요."],"title":"『사회』 117쪽 — 100년 후의 교통수단 상상하기 예시"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L14_basic#8','soc',3,2,'u2','L14','tb_g3_2_soc_u2_L14_basic','lesson_basic','SO3-2-u2-C14',2,'blank','auto','「새로운 교통 표지판은 거리를 다니면서 사람들에게 (    )할 필요성을 느꼈던 일을 떠올려 만들어요.」 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SO3-2-u2-X27']::text[],false,'{"seq":8,"concept":"SO3-2-u2-C14","difficulty":2,"kind":"blank","stem":"「새로운 교통 표지판은 거리를 다니면서 사람들에게 (    )할 필요성을 느꼈던 일을 떠올려 만들어요.」 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"안내","correct":true},{"t":"자랑","mis":"SO3-2-u2-X27"},{"t":"판매","mis":"SO3-2-u2-X27"},{"t":"숨김","mis":"SO3-2-u2-X27"}],"explanation":["표지판의 쓰임이에요.","사람들에게 알려요.","안내예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L14_basic#9','soc',3,2,'u2','L14','tb_g3_2_soc_u2_L14_basic','lesson_basic','SO3-2-u2-C14',2,'ox','auto','교통의 변화로 여러 가지 새로운 시설이 생기고 사람들의 생활 모습이 달라졌어요.',ARRAY['SO3-2-u2-X44']::text[],false,'{"seq":9,"concept":"SO3-2-u2-C14","difficulty":2,"kind":"ox","stem":"교통의 변화로 여러 가지 새로운 시설이 생기고 사람들의 생활 모습이 달라졌어요.","answer":"O","reason_options":[{"t":"역, 터미널, 공항 같은 시설이 생기고 생활 공간과 직업이 달라졌기 때문에","correct":true},{"t":"교통이 변해도 시설과 생활은 그대로이기 때문에","mis":"SO3-2-u2-X44"}],"mis":"SO3-2-u2-X44","explanation":["단서 3이에요.","시설과 생활이 달라졌어요.","그래서 O예요."],"asset":{"type":"passage","lines":["단서 1 — 교통의 발달로 사람들과 물건의 이동이 빨라지고 편리해졌습니다.","단서 2 — 교통이 발달하면서 교통의 문제점이 모두 해결됐습니다.","단서 3 — 교통의 변화로 여러 가지 새로운 시설이 생기고 사람들의 생활 모습이 달라졌습니다."],"numbered":false,"title":"『사회』 119쪽 재미있게 확인해요 — 돋보기 탐정의 단서"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L14_basic#10','soc',3,2,'u2','L14','tb_g3_2_soc_u2_L14_basic','lesson_basic','SO3-2-u2-C14',3,'error','auto','교통 단원을 정리하며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO3-2-u2-X24','SO3-2-u2-X28','SO3-2-u2-X32']::text[],false,'{"seq":10,"concept":"SO3-2-u2-C14","difficulty":3,"kind":"error","stem":"교통 단원을 정리하며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 가 — 「옛날 교통수단은 기계의 힘을, 오늘날 교통수단은 자연의 힘을 주로 이용해.」","correct":true,"mis_target":"SO3-2-u2-X24"},{"t":"친구 나 — 「교통의 발달로 사람과 물건의 이동이 빨라지고 편리해졌어.」","mis":"SO3-2-u2-X28"},{"t":"친구 다 — 「교통 문제를 해결하려는 노력은 지금도 이어지고 있어.」","mis":"SO3-2-u2-X32"}],"explanation":["옛날은 자연의 힘이에요.","오늘날이 기계의 힘이에요.","친구 가가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L14_challenge#1','soc',3,2,'u2','L14','tb_g3_2_soc_u2_L14_challenge','lesson_challenge','SO3-2-u2-C14',2,'sa','auto','117쪽에서 1899년에 옛날 사람들이 상상한 교통수단 그림은 무엇인가요?','{}'::text[],false,'{"seq":1,"concept":"SO3-2-u2-C14","difficulty":2,"kind":"sa","stem":"117쪽에서 1899년에 옛날 사람들이 상상한 교통수단 그림은 무엇인가요?","answer":["기계로 움직이는 눈썰매","눈썰매"],"explanation":["그림 ①이에요.","눈 위를 달려요.","기계로 움직이는 눈썰매예요."],"asset":{"type":"passage","lines":["옛날 사람들이 상상한 그림 ① — 기계로 움직이는 눈썰매(1899년)","옛날 사람들이 상상한 그림 ② — 하늘을 나는 택시(1912년)","내가 상상한 미래 교통수단 — 하늘을 날 수 있는 장치와 안전하게 착륙하는 기능을 넣은 신발","달라질 생활 모습 — 언제든지 쉽고 빠르게 이동하고, 도로가 줄고 공원이 많아질 거예요."],"title":"『사회』 117쪽 — 100년 후의 교통수단 상상하기 예시"},"mis":"SO3-2-u2-X33"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L14_challenge#2','soc',3,2,'u2','L14','tb_g3_2_soc_u2_L14_challenge','lesson_challenge','SO3-2-u2-C14',2,'mc','auto','네덜란드처럼 보행자 우선 도로를 알리는 표지판을 세우는 까닭은 무엇인가요?',ARRAY['SO3-2-u2-X27']::text[],false,'{"seq":2,"concept":"SO3-2-u2-C14","difficulty":2,"kind":"mc","stem":"네덜란드처럼 보행자 우선 도로를 알리는 표지판을 세우는 까닭은 무엇인가요?","options":[{"t":"걸어 다니는 사람이 안전하게 다니도록 하려고요","correct":true},{"t":"자동차가 더 빨리 달리도록 하려고요","mis":"SO3-2-u2-X27"},{"t":"동물을 보호하려고요","mis":"SO3-2-u2-X27"},{"t":"스마트폰을 쓰지 않게 하려고요","mis":"SO3-2-u2-X27"}],"explanation":["보행자가 먼저예요.","걷는 사람을 지켜요.","안전하게 다니도록요."],"asset":{"type":"passage","lines":["네덜란드 — 보행자 우선 도로임을 알리는 교통 표지판","영국 — 도로를 가로지르는 동물을 조심하라는 뜻의 교통 표지판","스웨덴 — 거리를 걸으면서 스마트폰을 사용하지 말라는 뜻의 교통 표지판"],"title":"『사회』 118쪽 — 여러 나라의 독특한 교통 표지판"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L14_challenge#3','soc',3,2,'u2','L14','tb_g3_2_soc_u2_L14_challenge','lesson_challenge','SO3-2-u2-C14',3,'mc','auto','옛날 사람들이 상상한 미래 교통수단 그림을 보고 알 수 있는 것은 무엇인가요?',ARRAY['SO3-2-u2-X48','SO3-2-u2-X33','SO3-2-u2-X34']::text[],false,'{"seq":3,"concept":"SO3-2-u2-C14","difficulty":3,"kind":"mc","stem":"옛날 사람들이 상상한 미래 교통수단 그림을 보고 알 수 있는 것은 무엇인가요?","options":[{"t":"사람들은 오래전부터 더 편리한 교통수단을 꿈꾸어 왔어요","correct":true},{"t":"옛날 사람들은 교통에 관심이 없었어요","mis":"SO3-2-u2-X48"},{"t":"상상한 교통수단은 모두 그대로 만들어졌어요","mis":"SO3-2-u2-X33"},{"t":"미래 교통수단은 상상할 수 없어요","mis":"SO3-2-u2-X34"}],"explanation":["100년도 더 전의 그림이에요.","편리한 교통을 꿈꿨어요.","오래전부터예요."],"asset":{"type":"passage","lines":["옛날 사람들이 상상한 그림 ① — 기계로 움직이는 눈썰매(1899년)","옛날 사람들이 상상한 그림 ② — 하늘을 나는 택시(1912년)","내가 상상한 미래 교통수단 — 하늘을 날 수 있는 장치와 안전하게 착륙하는 기능을 넣은 신발","달라질 생활 모습 — 언제든지 쉽고 빠르게 이동하고, 도로가 줄고 공원이 많아질 거예요."],"title":"『사회』 117쪽 — 100년 후의 교통수단 상상하기 예시"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L14_challenge#4','soc',3,2,'u2','L14','tb_g3_2_soc_u2_L14_challenge','lesson_challenge','SO3-2-u2-C14',3,'mc','auto','교통 변화의 좋은 점과 한계를 함께 본 말은 무엇인가요?',ARRAY['SO3-2-u2-X32','SO3-2-u2-X28','SO3-2-u2-X44']::text[],false,'{"seq":4,"concept":"SO3-2-u2-C14","difficulty":3,"kind":"mc","stem":"교통 변화의 좋은 점과 한계를 함께 본 말은 무엇인가요?","options":[{"t":"반나절 만에 부산에서 서울로 갈 수 있지만, 차가 많아 교통 체증과 대기 오염이 생겨요","correct":true},{"t":"오늘날 교통은 좋은 점만 있어요","mis":"SO3-2-u2-X32"},{"t":"옛날 교통이 오늘날보다 빨랐어요","mis":"SO3-2-u2-X28"},{"t":"교통이 변해도 생활은 같아요","mis":"SO3-2-u2-X44"}],"explanation":["좋은 점이 있어요.","한계도 있어요.","둘을 함께 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L14_challenge#5','soc',3,2,'u2','L14','tb_g3_2_soc_u2_L14_challenge','lesson_challenge','SO3-2-u2-C14',3,'ox','auto','여러 나라에는 그 나라의 교통 환경에 맞는 독특한 교통 표지판이 있어요.',ARRAY['SO3-2-u2-X27']::text[],false,'{"seq":5,"concept":"SO3-2-u2-C14","difficulty":3,"kind":"ox","stem":"여러 나라에는 그 나라의 교통 환경에 맞는 독특한 교통 표지판이 있어요.","answer":"O","reason_options":[{"t":"네덜란드, 영국, 스웨덴처럼 필요한 안내가 달라 표지판도 다르기 때문에","correct":true},{"t":"교통 표지판은 세계 어디에서나 모양과 뜻이 모두 같기 때문에","mis":"SO3-2-u2-X27"}],"mis":"SO3-2-u2-X27","explanation":["118쪽이에요.","나라마다 달라요.","그래서 O예요."],"asset":{"type":"passage","lines":["네덜란드 — 보행자 우선 도로임을 알리는 교통 표지판","영국 — 도로를 가로지르는 동물을 조심하라는 뜻의 교통 표지판","스웨덴 — 거리를 걸으면서 스마트폰을 사용하지 말라는 뜻의 교통 표지판"],"title":"『사회』 118쪽 — 여러 나라의 독특한 교통 표지판"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L14_challenge#6','soc',3,2,'u2','L14','tb_g3_2_soc_u2_L14_challenge','lesson_challenge','SO3-2-u2-C14',3,'match','auto','교통 표지판과 나라를 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"SO3-2-u2-C14","difficulty":3,"kind":"match","stem":"교통 표지판과 나라를 알맞게 이으세요.","pairs":[{"l":"보행자 우선 도로","r":"네덜란드"},{"l":"도로를 가로지르는 동물 조심","r":"영국"},{"l":"걸으면서 스마트폰 사용 금지","r":"스웨덴"}],"mis":"SO3-2-u2-X27","explanation":["보행자는 네덜란드예요.","동물은 영국이에요.","스마트폰은 스웨덴이에요."],"asset":{"type":"passage","lines":["네덜란드 — 보행자 우선 도로임을 알리는 교통 표지판","영국 — 도로를 가로지르는 동물을 조심하라는 뜻의 교통 표지판","스웨덴 — 거리를 걸으면서 스마트폰을 사용하지 말라는 뜻의 교통 표지판"],"title":"『사회』 118쪽 — 여러 나라의 독특한 교통 표지판"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L14_challenge#7','soc',3,2,'u2','L14','tb_g3_2_soc_u2_L14_challenge','lesson_challenge','SO3-2-u2-C14',3,'error','auto','100년 후의 교통수단을 그리며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO3-2-u2-X34','SO3-2-u2-X33']::text[],false,'{"seq":7,"concept":"SO3-2-u2-C14","difficulty":3,"kind":"error","stem":"100년 후의 교통수단을 그리며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 나 — 「지금 교통수단의 문제는 생각할 필요 없이 빠르게만 그리면 돼.」","correct":true,"mis_target":"SO3-2-u2-X34"},{"t":"친구 가 — 「오늘날 교통수단의 한계를 해결하는 기능을 넣고 싶어.」","mis":"SO3-2-u2-X34"},{"t":"친구 다 — 「안전하게 착륙하는 기능을 넣은 신발을 그릴래.」","mis":"SO3-2-u2-X33"}],"explanation":["한계를 해결하는 방안을 넣어요.","빠르기만은 아니에요.","친구 나가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L14_challenge#8','soc',3,2,'u2','L14','tb_g3_2_soc_u2_L14_challenge','lesson_challenge','SO3-2-u2-C14',4,'mc','auto','「교통의 변화로 달라진 생활 모습」에서 공부한 내용을 가장 잘 정리한 것은 무엇인가요?',ARRAY['SO3-2-u2-X44','SO3-2-u2-X32','SO3-2-u2-X28']::text[],false,'{"seq":8,"concept":"SO3-2-u2-C14","difficulty":4,"kind":"mc","stem":"「교통의 변화로 달라진 생활 모습」에서 공부한 내용을 가장 잘 정리한 것은 무엇인가요?","options":[{"t":"이동이 빨라지고 편리해져 새 시설과 직업이 생겼지만, 교통 체증과 환경 문제도 생겨 해결하려고 노력해요","correct":true},{"t":"교통은 옛날과 달라진 것이 없어요","mis":"SO3-2-u2-X44"},{"t":"교통의 문제점은 이미 모두 해결됐어요","mis":"SO3-2-u2-X32"},{"t":"교통의 발달로 생활 공간이 좁아졌어요","mis":"SO3-2-u2-X28"}],"explanation":["좋아진 점이에요.","문제점이에요.","노력이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L14_challenge#9','soc',3,2,'u2','L14','tb_g3_2_soc_u2_L14_challenge','lesson_challenge','SO3-2-u2-C14',4,'essay','teacher','여러 나라의 표지판처럼 새로운 교통 표지판을 하나 생각해 표지판이 알리는 내용을 쓰고, 그 표지판이 필요한 까닭을 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"SO3-2-u2-C14","difficulty":4,"kind":"essay","stem":"여러 나라의 표지판처럼 새로운 교통 표지판을 하나 생각해 표지판이 알리는 내용을 쓰고, 그 표지판이 필요한 까닭을 쓰세요.","answer_guide":{"answer":"예: 횡단보도가 어디에 있는지 알려 주는 표지판 — 처음 온 곳에서 횡단보도를 찾지 못해 무단 횡단하는 사람이 없도록 하기 위해서예요.","scoring_points":["표지판이 알리는 내용을 썼는가","필요한 까닭을 썼는가","안전한 교통과 이어지는가"]},"explanation":["필요했던 일을 떠올려요.","알리는 내용을 써요.","까닭을 써요."],"asset":{"type":"passage","lines":["네덜란드 — 보행자 우선 도로임을 알리는 교통 표지판","영국 — 도로를 가로지르는 동물을 조심하라는 뜻의 교통 표지판","스웨덴 — 거리를 걸으면서 스마트폰을 사용하지 말라는 뜻의 교통 표지판"],"title":"『사회』 118쪽 — 여러 나라의 독특한 교통 표지판"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L14_challenge#10','soc',3,2,'u2','L14','tb_g3_2_soc_u2_L14_challenge','lesson_challenge','SO3-2-u2-C14',4,'essay','teacher','100년 후의 교통수단을 상상해 그 특징을 쓰고, 그 교통수단으로 달라질 생활 모습을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO3-2-u2-C14","difficulty":4,"kind":"essay","stem":"100년 후의 교통수단을 상상해 그 특징을 쓰고, 그 교통수단으로 달라질 생활 모습을 쓰세요.","answer_guide":{"answer":"예: 하늘을 날 수 있는 장치와 안전하게 착륙하는 기능을 넣은 신발이에요. 언제든지 쉽고 빠르게 이동할 수 있고, 도로가 줄어 공원이 많아질 거예요.","scoring_points":["미래 교통수단의 특징을 썼는가","달라질 생활 모습을 썼는가","오늘날 교통의 한계를 해결하는가"]},"explanation":["특징을 상상해요.","생활 모습을 써요.","한계를 떠올려요."],"asset":{"type":"passage","lines":["옛날 사람들이 상상한 그림 ① — 기계로 움직이는 눈썰매(1899년)","옛날 사람들이 상상한 그림 ② — 하늘을 나는 택시(1912년)","내가 상상한 미래 교통수단 — 하늘을 날 수 있는 장치와 안전하게 착륙하는 기능을 넣은 신발","달라질 생활 모습 — 언제든지 쉽고 빠르게 이동하고, 도로가 줄고 공원이 많아질 거예요."],"title":"『사회』 117쪽 — 100년 후의 교통수단 상상하기 예시"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L15_basic#1','soc',3,2,'u2','L15','tb_g3_2_soc_u2_L15_basic','lesson_basic','SO3-2-u2-C15',1,'mc','auto','편지를 쓰거나 전화를 하고, 텔레비전으로 새 소식을 얻는 것처럼 소식이나 정보를 주고받는 것을 무엇이라고 하나요?',ARRAY['SO3-2-u2-X35']::text[],true,'{"seq":1,"concept":"SO3-2-u2-C15","difficulty":1,"kind":"mc","stem":"편지를 쓰거나 전화를 하고, 텔레비전으로 새 소식을 얻는 것처럼 소식이나 정보를 주고받는 것을 무엇이라고 하나요?","options":[{"t":"통신","correct":true},{"t":"교통","mis":"SO3-2-u2-X35"},{"t":"통신수단","mis":"SO3-2-u2-X35"},{"t":"교통로","mis":"SO3-2-u2-X35"}],"explanation":["121쪽 첫 글이에요.","소식과 정보예요.","통신이에요."],"variant_rule":{"alt":[{"stem":"소식이나 정보를 주고받을 때 사용하는 방법이나 도구를 무엇이라고 하나요?","options":[{"t":"통신수단","correct":true},{"t":"통신","mis":"SO3-2-u2-X35"},{"t":"교통수단","mis":"SO3-2-u2-X35"},{"t":"교통 시설","mis":"SO3-2-u2-X35"}],"explanation":["121쪽 낱말이에요.","방법이나 도구예요.","통신수단이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L15_basic#2','soc',3,2,'u2','L15','tb_g3_2_soc_u2_L15_basic','lesson_basic','SO3-2-u2-C15',1,'sa','auto','자동차 등에서 운전자에게 목적지까지 가는 길이나 도로 정보 등을 알려 주는 장치를 무엇이라고 하나요? 네 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SO3-2-u2-C15","difficulty":1,"kind":"sa","stem":"자동차 등에서 운전자에게 목적지까지 가는 길이나 도로 정보 등을 알려 주는 장치를 무엇이라고 하나요? 네 글자로 쓰세요.","answer":["길 도우미","길도우미","내비게이션"],"explanation":["122쪽 낱말 풀이예요.","길을 알려 줘요.","길 도우미예요."],"mis":"SO3-2-u2-X36"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L15_basic#3','soc',3,2,'u2','L15','tb_g3_2_soc_u2_L15_basic','lesson_basic','SO3-2-u2-C15',1,'mc','auto','121쪽 그림에서 아버지가 현관에서 누가 왔는지 확인할 때 쓰는 통신수단은 무엇인가요?',ARRAY['SO3-2-u2-X39']::text[],true,'{"seq":3,"concept":"SO3-2-u2-C15","difficulty":1,"kind":"mc","stem":"121쪽 그림에서 아버지가 현관에서 누가 왔는지 확인할 때 쓰는 통신수단은 무엇인가요?","options":[{"t":"인터폰","correct":true},{"t":"우편물","mis":"SO3-2-u2-X39"},{"t":"노트북","mis":"SO3-2-u2-X39"},{"t":"텔레비전","mis":"SO3-2-u2-X39"}],"explanation":["현관이에요.","누가 왔는지 봐요.","인터폰이에요."],"asset":{"type":"passage","lines":["할아버지 — 태블릿 컴퓨터로 영화를 봐요.","할머니 — 스마트 텔레비전을 시청해요.","아버지 — 현관에서 누가 왔는지 인터폰으로 확인해요.","어머니 — 우편물을 살펴봐요.","남학생 — 노트북으로 온라인 수업을 들어요.","여학생 — 스마트폰으로 모바일 메신저를 해요."],"title":"『사회』 121쪽 — 가정에서 통신수단을 이용하는 모습"},"variant_rule":{"alt":[{"stem":"121쪽 그림에서 남학생이 온라인 수업을 들을 때 쓰는 통신수단은 무엇인가요?","options":[{"t":"노트북","correct":true},{"t":"인터폰","mis":"SO3-2-u2-X39"},{"t":"우편물","mis":"SO3-2-u2-X39"},{"t":"스마트 텔레비전","mis":"SO3-2-u2-X39"}],"explanation":["온라인 수업이에요.","남학생이에요.","노트북이에요."],"asset":{"type":"passage","lines":["할아버지 — 태블릿 컴퓨터로 영화를 봐요.","할머니 — 스마트 텔레비전을 시청해요.","아버지 — 현관에서 누가 왔는지 인터폰으로 확인해요.","어머니 — 우편물을 살펴봐요.","남학생 — 노트북으로 온라인 수업을 들어요.","여학생 — 스마트폰으로 모바일 메신저를 해요."],"title":"『사회』 121쪽 — 가정에서 통신수단을 이용하는 모습"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L15_basic#4','soc',3,2,'u2','L15','tb_g3_2_soc_u2_L15_basic','lesson_basic','SO3-2-u2-C15',1,'ox','auto','요즘은 인터넷이 연결된 통신수단을 편리하게 이용해요.',ARRAY['SO3-2-u2-X38']::text[],false,'{"seq":4,"concept":"SO3-2-u2-C15","difficulty":1,"kind":"ox","stem":"요즘은 인터넷이 연결된 통신수단을 편리하게 이용해요.","answer":"O","reason_options":[{"t":"『사회』 121쪽 말풍선처럼 노트북, 스마트폰, 스마트 텔레비전 등이 인터넷으로 연결되기 때문에","correct":true},{"t":"오늘날 통신수단은 인터넷과 상관없이 편지만 쓰기 때문에","mis":"SO3-2-u2-X38"}],"mis":"SO3-2-u2-X38","explanation":["121쪽 말풍선이에요.","인터넷이에요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L15_basic#5','soc',3,2,'u2','L15','tb_g3_2_soc_u2_L15_basic','lesson_basic','SO3-2-u2-C15',2,'match','auto','122쪽 그림의 상황과 통신수단을 이용하는 목적을 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"SO3-2-u2-C15","difficulty":2,"kind":"match","stem":"122쪽 그림의 상황과 통신수단을 이용하는 목적을 알맞게 이으세요.","pairs":[{"l":"놀이공원에서 친구와 헤어졌을 때","r":"친구와 연락해요"},{"l":"가는 길을 모를 때","r":"길 도우미로 길을 찾아요"},{"l":"우산을 챙길지 궁금할 때","r":"일기 예보로 날씨를 미리 알아요"}],"mis":"SO3-2-u2-X36","explanation":["친구는 연락이에요.","길은 길 도우미예요.","날씨는 일기 예보예요."],"asset":{"type":"speech","turns":[{"who":"놀이공원","text":"친구가 어디 갔지?"},{"who":"자동차 안","text":"길 도우미가 없었으면 길을 못 찾을 뻔했어."},{"who":"비 오는 날","text":"일기 예보를 확인하지 않았더니 우산을 못 챙겼네."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L15_basic#6','soc',3,2,'u2','L15','tb_g3_2_soc_u2_L15_basic','lesson_basic','SO3-2-u2-C15',2,'mc','auto','생각을 열어요에서 형 돼지들이 막내 돼지에게 위험을 알리는 방법으로 알맞은 것은 무엇인가요?',ARRAY['SO3-2-u2-X36']::text[],false,'{"seq":6,"concept":"SO3-2-u2-C15","difficulty":2,"kind":"mc","stem":"생각을 열어요에서 형 돼지들이 막내 돼지에게 위험을 알리는 방법으로 알맞은 것은 무엇인가요?","options":[{"t":"막내 돼지에게 전화해 위험을 알려요","correct":true},{"t":"늑대보다 늦게 막내 집까지 걸어가요","mis":"SO3-2-u2-X36"},{"t":"아무 말도 하지 않고 기다려요","mis":"SO3-2-u2-X36"},{"t":"늑대에게 길을 물어봐요","mis":"SO3-2-u2-X36"}],"explanation":["위험을 빨리 알려야 해요.","소식을 전하는 도구예요.","전화예요."],"asset":{"type":"passage","lines":["(간추림) 첫째 돼지의 초가집과 둘째 돼지의 나무 집을 지나 늑대가 막내 돼지의 집으로 가고 있어요.","형 돼지들은 「막내에게 위험을 알려야 하는데 어떡하지?」 하고 고민해요."],"title":"『사회』 120쪽 생각을 열어요 — 「아기 돼지 삼 형제」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L15_basic#7','soc',3,2,'u2','L15','tb_g3_2_soc_u2_L15_basic','lesson_basic','SO3-2-u2-C15',2,'mc','auto','전화, 전자 우편, 휴대 전화의 공통점은 무엇인가요?',ARRAY['SO3-2-u2-X35','SO3-2-u2-X38']::text[],false,'{"seq":7,"concept":"SO3-2-u2-C15","difficulty":2,"kind":"mc","stem":"전화, 전자 우편, 휴대 전화의 공통점은 무엇인가요?","options":[{"t":"다른 사람과 서로 소식이나 정보를 주고받을 수 있어요","correct":true},{"t":"사람이나 물건을 다른 곳으로 옮겨요","mis":"SO3-2-u2-X35"},{"t":"모두 하늘로 다니는 교통수단이에요","mis":"SO3-2-u2-X35"},{"t":"모두 옛날에만 쓰던 도구예요","mis":"SO3-2-u2-X38"}],"explanation":["무엇을 주고받나요?","소식과 정보예요.","모두 통신수단이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L15_basic#8','soc',3,2,'u2','L15','tb_g3_2_soc_u2_L15_basic','lesson_basic','SO3-2-u2-C15',2,'blank','auto','「전화가 없으면 급하게 전해야 할 소식이 있을 때 (    ) 전해야 합니다.」 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SO3-2-u2-X36']::text[],false,'{"seq":8,"concept":"SO3-2-u2-C15","difficulty":2,"kind":"blank","stem":"「전화가 없으면 급하게 전해야 할 소식이 있을 때 (    ) 전해야 합니다.」 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"직접 가서","correct":true},{"t":"텔레비전으로","mis":"SO3-2-u2-X36"},{"t":"문자 메시지로","mis":"SO3-2-u2-X36"},{"t":"전자 우편으로","mis":"SO3-2-u2-X36"}],"explanation":["통신수단이 없다면이에요.","도구가 없어요.","직접 가야 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L15_basic#9','soc',3,2,'u2','L15','tb_g3_2_soc_u2_L15_basic','lesson_basic','SO3-2-u2-C15',2,'ox','auto','같은 통신수단이라도 여러 가지 목적으로 이용할 수 있어요.',ARRAY['SO3-2-u2-X36']::text[],false,'{"seq":9,"concept":"SO3-2-u2-C15","difficulty":2,"kind":"ox","stem":"같은 통신수단이라도 여러 가지 목적으로 이용할 수 있어요.","answer":"O","reason_options":[{"t":"스마트폰으로 연락도 하고 날씨와 길도 찾는 것처럼 쓰임이 다양하기 때문에","correct":true},{"t":"통신수단마다 쓰는 목적이 하나뿐이기 때문에","mis":"SO3-2-u2-X36"}],"mis":"SO3-2-u2-X36","explanation":["스마트폰을 떠올려요.","쓰임이 많아요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L15_basic#10','soc',3,2,'u2','L15','tb_g3_2_soc_u2_L15_basic','lesson_basic','SO3-2-u2-C15',3,'error','auto','통신수단을 이용하는 목적을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO3-2-u2-X36']::text[],false,'{"seq":10,"concept":"SO3-2-u2-C15","difficulty":3,"kind":"error","stem":"통신수단을 이용하는 목적을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「통신수단이 없어도 다른 지역의 소식을 알기 쉬워.」","correct":true,"mis_target":"SO3-2-u2-X36"},{"t":"친구 가 — 「텔레비전으로 새로운 소식을 얻을 수 있어.」","mis":"SO3-2-u2-X36"},{"t":"친구 나 — 「스마트폰으로 필요한 정보를 찾을 수 있어.」","mis":"SO3-2-u2-X36"}],"explanation":["텔레비전이 없다면요?","다른 지역 소식을 알기 어려워요.","친구 다가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
