INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L15_challenge#2','soc',3,2,'u2','L15','tb_g3_2_soc_u2_L15_challenge','lesson_challenge','SO3-2-u2-C15',2,'mc','auto','121쪽 그림에서 할머니가 이용하는 통신수단은 무엇인가요?',ARRAY['SO3-2-u2-X39']::text[],false,'{"seq":2,"concept":"SO3-2-u2-C15","difficulty":2,"kind":"mc","stem":"121쪽 그림에서 할머니가 이용하는 통신수단은 무엇인가요?","options":[{"t":"스마트 텔레비전","correct":true},{"t":"인터폰","mis":"SO3-2-u2-X39"},{"t":"우편물","mis":"SO3-2-u2-X39"},{"t":"노트북","mis":"SO3-2-u2-X39"}],"explanation":["할머니예요.","방송을 봐요.","스마트 텔레비전이에요."],"asset":{"type":"passage","lines":["할아버지 — 태블릿 컴퓨터로 영화를 봐요.","할머니 — 스마트 텔레비전을 시청해요.","아버지 — 현관에서 누가 왔는지 인터폰으로 확인해요.","어머니 — 우편물을 살펴봐요.","남학생 — 노트북으로 온라인 수업을 들어요.","여학생 — 스마트폰으로 모바일 메신저를 해요."],"title":"『사회』 121쪽 — 가정에서 통신수단을 이용하는 모습"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L15_challenge#3','soc',3,2,'u2','L15','tb_g3_2_soc_u2_L15_challenge','lesson_challenge','SO3-2-u2-C15',3,'mc','auto','다음 가운데 통신의 모습은 무엇인가요?',ARRAY['SO3-2-u2-X35']::text[],false,'{"seq":3,"concept":"SO3-2-u2-C15","difficulty":3,"kind":"mc","stem":"다음 가운데 통신의 모습은 무엇인가요?","options":[{"t":"휴대 전화로 문자 메시지를 보내 친구에게 소식을 알려요","correct":true},{"t":"기차를 타고 할아버지 댁에 가요","mis":"SO3-2-u2-X35"},{"t":"택배 트럭이 물건을 배달해요","mis":"SO3-2-u2-X35"},{"t":"자전거를 타고 학교에 가요","mis":"SO3-2-u2-X35"}],"explanation":["이동과 소식을 갈라요.","소식을 주고받아요.","문자 메시지예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L15_challenge#4','soc',3,2,'u2','L15','tb_g3_2_soc_u2_L15_challenge','lesson_challenge','SO3-2-u2-C15',3,'mc','auto','멀리 이사 간 친구가 보고 싶을 때 통신수단을 이용하는 모습으로 알맞은 것은 무엇인가요?',ARRAY['SO3-2-u2-X35','SO3-2-u2-X36']::text[],false,'{"seq":4,"concept":"SO3-2-u2-C15","difficulty":3,"kind":"mc","stem":"멀리 이사 간 친구가 보고 싶을 때 통신수단을 이용하는 모습으로 알맞은 것은 무엇인가요?","options":[{"t":"스마트폰으로 영상 통화를 하거나 모바일 메신저로 사진을 주고받아요","correct":true},{"t":"날마다 기차를 타고 찾아가요","mis":"SO3-2-u2-X35"},{"t":"텔레비전 뉴스에 나오기를 기다려요","mis":"SO3-2-u2-X36"},{"t":"아무 연락 없이 기다리기만 해요","mis":"SO3-2-u2-X36"}],"explanation":["얼굴을 보고 싶어요.","영상 통화가 있어요.","메신저도 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L15_challenge#5','soc',3,2,'u2','L15','tb_g3_2_soc_u2_L15_challenge','lesson_challenge','SO3-2-u2-C15',3,'ox','auto','통신수단은 위급한 상황에서 위험을 알리고 도움을 청할 때도 중요해요.',ARRAY['SO3-2-u2-X36']::text[],false,'{"seq":5,"concept":"SO3-2-u2-C15","difficulty":3,"kind":"ox","stem":"통신수단은 위급한 상황에서 위험을 알리고 도움을 청할 때도 중요해요.","answer":"O","reason_options":[{"t":"생각을 열어요의 아기 돼지처럼 위험을 빨리 알려야 할 때 통신수단이 필요하기 때문에","correct":true},{"t":"통신수단은 놀 때만 쓰는 도구이기 때문에","mis":"SO3-2-u2-X36"}],"mis":"SO3-2-u2-X36","explanation":["120쪽 그림이에요.","위험을 알려요.","그래서 O예요."],"asset":{"type":"passage","lines":["(간추림) 첫째 돼지의 초가집과 둘째 돼지의 나무 집을 지나 늑대가 막내 돼지의 집으로 가고 있어요.","형 돼지들은 「막내에게 위험을 알려야 하는데 어떡하지?」 하고 고민해요."],"title":"『사회』 120쪽 생각을 열어요 — 「아기 돼지 삼 형제」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L15_challenge#6','soc',3,2,'u2','L15','tb_g3_2_soc_u2_L15_challenge','lesson_challenge','SO3-2-u2-C15',3,'match','auto','121쪽 가족과 통신수단을 이용하는 모습을 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"SO3-2-u2-C15","difficulty":3,"kind":"match","stem":"121쪽 가족과 통신수단을 이용하는 모습을 알맞게 이으세요.","pairs":[{"l":"할아버지","r":"태블릿 컴퓨터로 영화를 봐요"},{"l":"어머니","r":"우편물을 살펴봐요"},{"l":"여학생","r":"스마트폰으로 모바일 메신저를 해요"},{"l":"아버지","r":"인터폰으로 누가 왔는지 확인해요"}],"mis":"SO3-2-u2-X39","explanation":["할아버지는 태블릿이에요.","어머니는 우편물이에요.","여학생은 메신저, 아버지는 인터폰이에요."],"asset":{"type":"passage","lines":["할아버지 — 태블릿 컴퓨터로 영화를 봐요.","할머니 — 스마트 텔레비전을 시청해요.","아버지 — 현관에서 누가 왔는지 인터폰으로 확인해요.","어머니 — 우편물을 살펴봐요.","남학생 — 노트북으로 온라인 수업을 들어요.","여학생 — 스마트폰으로 모바일 메신저를 해요."],"title":"『사회』 121쪽 — 가정에서 통신수단을 이용하는 모습"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L15_challenge#7','soc',3,2,'u2','L15','tb_g3_2_soc_u2_L15_challenge','lesson_challenge','SO3-2-u2-C15',3,'error','auto','통신과 통신수단을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO3-2-u2-X35']::text[],false,'{"seq":7,"concept":"SO3-2-u2-C15","difficulty":3,"kind":"error","stem":"통신과 통신수단을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 나 — 「통신수단은 사람이 이동하거나 물건을 옮길 때 사용하는 도구야.」","correct":true,"mis_target":"SO3-2-u2-X35"},{"t":"친구 가 — 「편지와 전화는 모두 통신수단이야.」","mis":"SO3-2-u2-X35"},{"t":"친구 다 — 「텔레비전으로 새 소식을 얻는 것도 통신이야.」","mis":"SO3-2-u2-X35"}],"explanation":["이동하는 도구는 교통수단이에요.","통신수단은 소식을 주고받아요.","친구 나가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L15_challenge#8','soc',3,2,'u2','L15','tb_g3_2_soc_u2_L15_challenge','lesson_challenge','SO3-2-u2-C15',4,'mc','auto','통신수단이 없다면 생길 일을 바르게 정리한 것은 무엇인가요?',ARRAY['SO3-2-u2-X36','SO3-2-u2-X35']::text[],false,'{"seq":8,"concept":"SO3-2-u2-C15","difficulty":4,"kind":"mc","stem":"통신수단이 없다면 생길 일을 바르게 정리한 것은 무엇인가요?","options":[{"t":"급한 소식은 직접 가서 전해야 하고, 다른 지역의 소식을 알기 어려워요","correct":true},{"t":"생활이 지금과 똑같아요","mis":"SO3-2-u2-X36"},{"t":"소식을 더 빨리 알 수 있어요","mis":"SO3-2-u2-X36"},{"t":"교통수단도 모두 사라져요","mis":"SO3-2-u2-X35"}],"explanation":["122쪽 핵심 질문이에요.","직접 가야 해요.","소식을 알기 어려워요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L15_challenge#9','soc',3,2,'u2','L15','tb_g3_2_soc_u2_L15_challenge','lesson_challenge','SO3-2-u2-C15',4,'ox','auto','통신수단은 멀리 있는 사람과 소식을 주고받을 때만 쓰고 가까이 있는 사람과는 쓰지 않아요.',ARRAY['SO3-2-u2-X36']::text[],false,'{"seq":9,"concept":"SO3-2-u2-C15","difficulty":4,"kind":"ox","stem":"통신수단은 멀리 있는 사람과 소식을 주고받을 때만 쓰고 가까이 있는 사람과는 쓰지 않아요.","answer":"X","reason_options":[{"t":"현관의 인터폰이나 교내 방송처럼 가까이에서도 소식이나 정보를 주고받는 데 쓰기 때문에","correct":true},{"t":"가까이 있는 사람과는 소식을 주고받을 일이 없기 때문에","mis":"SO3-2-u2-X36"}],"mis":"SO3-2-u2-X36","explanation":["인터폰을 떠올려요.","가까이에서도 써요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L15_challenge#10','soc',3,2,'u2','L15','tb_g3_2_soc_u2_L15_challenge','lesson_challenge','SO3-2-u2-C15',4,'essay','teacher','일상생활에서 통신수단이 필요했던 경험을 쓰고, 그때 이용한 통신수단과 이용한 목적을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO3-2-u2-C15","difficulty":4,"kind":"essay","stem":"일상생활에서 통신수단이 필요했던 경험을 쓰고, 그때 이용한 통신수단과 이용한 목적을 쓰세요.","answer_guide":{"answer":"예: 알림장을 잃어버렸을 때 인터넷 학급 게시판에서 알림장 내용을 확인했어요. 학교 소식이라는 정보를 얻으려고 컴퓨터를 이용했어요.","scoring_points":["경험을 썼는가","이용한 통신수단을 썼는가","이용한 목적을 썼는가"]},"explanation":["경험을 떠올려요.","통신수단을 써요.","목적을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L16_basic#1','soc',3,2,'u2','L16','tb_g3_2_soc_u2_L16_basic','lesson_basic','SO3-2-u2-C16',1,'mc','auto','일상생활의 안부나 소식을 글로 적어 사람이 직접 전달한 옛날 통신수단은 무엇인가요?',ARRAY['SO3-2-u2-X37']::text[],true,'{"seq":1,"concept":"SO3-2-u2-C16","difficulty":1,"kind":"mc","stem":"일상생활의 안부나 소식을 글로 적어 사람이 직접 전달한 옛날 통신수단은 무엇인가요?","options":[{"t":"서찰","correct":true},{"t":"방","mis":"SO3-2-u2-X37"},{"t":"봉수","mis":"SO3-2-u2-X37"},{"t":"나발","mis":"SO3-2-u2-X37"}],"explanation":["그림 ①이에요.","글로 적어 직접 전해요.","서찰이에요."],"asset":{"type":"passage","lines":["그림 ① 아씨의 혼인 소식이 적힌 서찰을 사람이 먼 길을 가서 직접 전하려고 해요.","그림 ② 길거리에 붙은 방 앞에 사람들이 모여 「나라에서 큰 공사를 한다는군.」 하고 말해요."],"numbered":false,"title":"『사회』 123쪽 — 옛날 사람들이 일상생활에서 소식을 전한 모습"},"variant_rule":{"alt":[{"stem":"중요한 소식을 널리 알리려고 길거리나 사람들이 많이 모이는 곳에 글을 써서 붙인 옛날 통신수단은 무엇인가요?","options":[{"t":"방","correct":true},{"t":"서찰","mis":"SO3-2-u2-X37"},{"t":"파발","mis":"SO3-2-u2-X37"},{"t":"신호 연","mis":"SO3-2-u2-X37"}],"explanation":["그림 ②예요.","글을 써서 붙여요.","방이에요."],"asset":{"type":"passage","lines":["그림 ① 아씨의 혼인 소식이 적힌 서찰을 사람이 먼 길을 가서 직접 전하려고 해요.","그림 ② 길거리에 붙은 방 앞에 사람들이 모여 「나라에서 큰 공사를 한다는군.」 하고 말해요."],"numbered":false,"title":"『사회』 123쪽 — 옛날 사람들이 일상생활에서 소식을 전한 모습"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L16_basic#2','soc',3,2,'u2','L16','tb_g3_2_soc_u2_L16_basic','lesson_basic','SO3-2-u2-C16',1,'sa','auto','적이 쳐들어왔을 때 봉수에 올린 연기나 불은 몇 개였나요? 숫자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SO3-2-u2-C16","difficulty":1,"kind":"sa","stem":"적이 쳐들어왔을 때 봉수에 올린 연기나 불은 몇 개였나요? 숫자로 쓰세요.","answer":["4","4개","네 개"],"explanation":["표를 봐요.","쳐들어왔을 때예요.","4개예요."],"asset":{"type":"passage","lines":["적이 없는 평상시 — 1개","적이 나타났을 때 — 2개","적이 가까이 왔을 때 — 3개","적이 쳐들어왔을 때 — 4개","적과 싸움이 시작됐을 때 — 5개"],"title":"봉수에 올린 연기나 불의 개수"},"mis":"SO3-2-u2-X37"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L16_basic#3','soc',3,2,'u2','L16','tb_g3_2_soc_u2_L16_basic','lesson_basic','SO3-2-u2-C16',1,'mc','auto','낮에는 연기, 밤에는 불을 피워서 위급한 상황을 알린 옛날 통신수단은 무엇인가요?',ARRAY['SO3-2-u2-X37']::text[],true,'{"seq":3,"concept":"SO3-2-u2-C16","difficulty":1,"kind":"mc","stem":"낮에는 연기, 밤에는 불을 피워서 위급한 상황을 알린 옛날 통신수단은 무엇인가요?","options":[{"t":"봉수","correct":true},{"t":"파발","mis":"SO3-2-u2-X37"},{"t":"신호 연","mis":"SO3-2-u2-X37"},{"t":"서찰","mis":"SO3-2-u2-X37"}],"explanation":["125쪽 그림이에요.","연기와 불이에요.","봉수예요."],"asset":{"type":"passage","lines":["파발 — 나라의 중요한 일이나 소식을 적은 문서를 말을 타고 가거나 걸어가서 전달했어요.","봉수 — 낮에는 연기, 밤에는 불을 피워서 위급한 상황을 알렸어요.","말풍선 — 옛날 통신수단은 소식을 전하는 데 시간이 오래 걸렸어요.","말풍선 — 많은 정보를 자세하고 정확하게 전하기 어려웠고, 봉수는 날씨의 영향을 받았어요."],"title":"『사회』 125쪽 — 파발과 봉수"},"variant_rule":{"alt":[{"stem":"나라의 중요한 일이나 소식을 적은 문서를 말을 타고 가거나 걸어가서 전달한 옛날 통신수단은 무엇인가요?","options":[{"t":"파발","correct":true},{"t":"봉수","mis":"SO3-2-u2-X37"},{"t":"북","mis":"SO3-2-u2-X37"},{"t":"방","mis":"SO3-2-u2-X37"}],"explanation":["125쪽 그림이에요.","문서를 전해요.","파발이에요."],"asset":{"type":"passage","lines":["파발 — 나라의 중요한 일이나 소식을 적은 문서를 말을 타고 가거나 걸어가서 전달했어요.","봉수 — 낮에는 연기, 밤에는 불을 피워서 위급한 상황을 알렸어요.","말풍선 — 옛날 통신수단은 소식을 전하는 데 시간이 오래 걸렸어요.","말풍선 — 많은 정보를 자세하고 정확하게 전하기 어려웠고, 봉수는 날씨의 영향을 받았어요."],"title":"『사회』 125쪽 — 파발과 봉수"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L16_basic#4','soc',3,2,'u2','L16','tb_g3_2_soc_u2_L16_basic','lesson_basic','SO3-2-u2-C16',1,'ox','auto','옛날 군대에서 부하에게 명령하거나 신호하는 데 쓴 악기를 나발이라고 해요.',ARRAY['SO3-2-u2-X37']::text[],false,'{"seq":4,"concept":"SO3-2-u2-C16","difficulty":1,"kind":"ox","stem":"옛날 군대에서 부하에게 명령하거나 신호하는 데 쓴 악기를 나발이라고 해요.","answer":"O","reason_options":[{"t":"『사회』 124쪽 낱말 풀이에 나와 있기 때문에","correct":true},{"t":"나발은 소식을 적어 붙이는 종이이기 때문에","mis":"SO3-2-u2-X37"}],"mis":"SO3-2-u2-X37","explanation":["124쪽 낱말 풀이예요.","악기예요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L16_basic#5','soc',3,2,'u2','L16','tb_g3_2_soc_u2_L16_basic','lesson_basic','SO3-2-u2-C16',2,'match','auto','나라에 위급한 상황이 생겼을 때 쓴 통신수단과 이용 모습을 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"SO3-2-u2-C16","difficulty":2,"kind":"match","stem":"나라에 위급한 상황이 생겼을 때 쓴 통신수단과 이용 모습을 알맞게 이으세요.","pairs":[{"l":"신호 연","r":"암호를 적은 연을 띄워 작전을 알렸어요"},{"l":"신호 깃발","r":"깃발로 명령을 전달했어요"},{"l":"북","r":"큰 소리를 내어 소식이나 작전을 알렸어요"},{"l":"나발","r":"소리를 내어 신호를 보냈어요"}],"mis":"SO3-2-u2-X37","explanation":["연은 암호예요.","깃발은 명령, 북은 큰 소리예요.","나발도 소리예요."],"asset":{"type":"passage","lines":["신호 연 — 암호를 적은 연을 띄워서 작전이 시작되거나 바뀐 것을 알렸어요.","신호 깃발 — 깃발을 이용해 명령을 전달하거나 소식을 전했어요.","북 — 북을 쳐서 큰 소리를 내어 소식이나 작전을 알렸어요.","나발 — 군대에서 명령하거나 신호하는 데 쓴 악기로, 소리를 내어 신호를 보냈어요."],"title":"『사회』 124쪽 — 나라에 위급한 상황이 생겼을 때 쓴 통신수단"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L16_basic#6','soc',3,2,'u2','L16','tb_g3_2_soc_u2_L16_basic','lesson_basic','SO3-2-u2-C16',2,'mc','auto','옛날에 전쟁 중 신호 연을 이용한 까닭은 무엇인가요?',ARRAY['SO3-2-u2-X37','SO3-2-u2-X38']::text[],false,'{"seq":6,"concept":"SO3-2-u2-C16","difficulty":2,"kind":"mc","stem":"옛날에 전쟁 중 신호 연을 이용한 까닭은 무엇인가요?","options":[{"t":"높이 떠서 멀리서도 잘 보이고, 연에 표시한 암호를 적이 알지 못했기 때문이에요","correct":true},{"t":"북보다 소리가 컸기 때문이에요","mis":"SO3-2-u2-X37"},{"t":"많은 내용을 자세히 적을 수 있었기 때문이에요","mis":"SO3-2-u2-X38"},{"t":"비가 와도 잘 보였기 때문이에요","mis":"SO3-2-u2-X38"}],"explanation":["연은 높이 떠요.","암호를 썼어요.","적은 몰라요."],"asset":{"type":"passage","lines":["신호 연 — 암호를 적은 연을 띄워서 작전이 시작되거나 바뀐 것을 알렸어요.","신호 깃발 — 깃발을 이용해 명령을 전달하거나 소식을 전했어요.","북 — 북을 쳐서 큰 소리를 내어 소식이나 작전을 알렸어요.","나발 — 군대에서 명령하거나 신호하는 데 쓴 악기로, 소리를 내어 신호를 보냈어요."],"title":"『사회』 124쪽 — 나라에 위급한 상황이 생겼을 때 쓴 통신수단"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L16_basic#7','soc',3,2,'u2','L16','tb_g3_2_soc_u2_L16_basic','lesson_basic','SO3-2-u2-C16',2,'mc','auto','옛날 통신수단의 특징으로 알맞은 것은 무엇인가요?',ARRAY['SO3-2-u2-X38']::text[],false,'{"seq":7,"concept":"SO3-2-u2-C16","difficulty":2,"kind":"mc","stem":"옛날 통신수단의 특징으로 알맞은 것은 무엇인가요?","options":[{"t":"소식을 전하는 데 시간이 오래 걸렸어요","correct":true},{"t":"실시간으로 빠르게 전했어요","mis":"SO3-2-u2-X38"},{"t":"날씨의 영향을 받지 않았어요","mis":"SO3-2-u2-X38"},{"t":"여러 사람과 동시에 많은 정보를 주고받았어요","mis":"SO3-2-u2-X38"}],"explanation":["125쪽 말풍선이에요.","사람이나 말이 가야 했어요.","오래 걸렸어요."],"asset":{"type":"passage","lines":["파발 — 나라의 중요한 일이나 소식을 적은 문서를 말을 타고 가거나 걸어가서 전달했어요.","봉수 — 낮에는 연기, 밤에는 불을 피워서 위급한 상황을 알렸어요.","말풍선 — 옛날 통신수단은 소식을 전하는 데 시간이 오래 걸렸어요.","말풍선 — 많은 정보를 자세하고 정확하게 전하기 어려웠고, 봉수는 날씨의 영향을 받았어요."],"title":"『사회』 125쪽 — 파발과 봉수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L16_basic#8','soc',3,2,'u2','L16','tb_g3_2_soc_u2_L16_basic','lesson_basic','SO3-2-u2-C16',2,'blank','auto','「봉수는 낮에는 (    ), 밤에는 불을 피워서 위급한 상황을 알렸습니다.」 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SO3-2-u2-X37']::text[],false,'{"seq":8,"concept":"SO3-2-u2-C16","difficulty":2,"kind":"blank","stem":"「봉수는 낮에는 (    ), 밤에는 불을 피워서 위급한 상황을 알렸습니다.」 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"연기","correct":true},{"t":"깃발","mis":"SO3-2-u2-X37"},{"t":"북소리","mis":"SO3-2-u2-X37"},{"t":"서찰","mis":"SO3-2-u2-X37"}],"explanation":["낮에는 불빛이 잘 안 보여요.","연기가 잘 보여요.","연기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L16_basic#9','soc',3,2,'u2','L16','tb_g3_2_soc_u2_L16_basic','lesson_basic','SO3-2-u2-C16',2,'ox','auto','옛날에는 통신수단이 없어서 사람들이 소식을 전할 때 걸어가거나 말을 타고 직접 갔어요.',ARRAY['SO3-2-u2-X48']::text[],false,'{"seq":9,"concept":"SO3-2-u2-C16","difficulty":2,"kind":"ox","stem":"옛날에는 통신수단이 없어서 사람들이 소식을 전할 때 걸어가거나 말을 타고 직접 갔어요.","answer":"X","reason_options":[{"t":"서찰, 방, 봉수, 파발 같은 통신수단을 이용해 소식을 전했기 때문에","correct":true},{"t":"옛날에는 소식을 전하는 방법이 하나도 없었기 때문에","mis":"SO3-2-u2-X48"}],"mis":"SO3-2-u2-X48","explanation":["『사회』 145쪽 말판 문제예요.","옛날에도 통신수단이 있었어요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L16_basic#10','soc',3,2,'u2','L16','tb_g3_2_soc_u2_L16_basic','lesson_basic','SO3-2-u2-C16',3,'error','auto','봉수 표를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO3-2-u2-X37']::text[],false,'{"seq":10,"concept":"SO3-2-u2-C16","difficulty":3,"kind":"error","stem":"봉수 표를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「적이 나타나면 봉수 다섯 개를 피워.」","correct":true,"mis_target":"SO3-2-u2-X37"},{"t":"친구 가 — 「적이 없는 평상시에는 봉수 한 개를 피워.」","mis":"SO3-2-u2-X37"},{"t":"친구 나 — 「적과 싸움이 시작되면 다섯 개를 피워.」","mis":"SO3-2-u2-X37"}],"explanation":["나타났을 때는 2개예요.","5개는 싸움이 시작됐을 때예요.","친구 다가 잘못 말했어요."],"asset":{"type":"passage","lines":["적이 없는 평상시 — 1개","적이 나타났을 때 — 2개","적이 가까이 왔을 때 — 3개","적이 쳐들어왔을 때 — 4개","적과 싸움이 시작됐을 때 — 5개"],"title":"봉수에 올린 연기나 불의 개수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L16_challenge#1','soc',3,2,'u2','L16','tb_g3_2_soc_u2_L16_challenge','lesson_challenge','SO3-2-u2-C16',2,'sa','auto','파발 가운데 말을 타고 가서 소식을 전하는 것을 무엇이라고 하나요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"SO3-2-u2-C16","difficulty":2,"kind":"sa","stem":"파발 가운데 말을 타고 가서 소식을 전하는 것을 무엇이라고 하나요? 두 글자로 쓰세요.","answer":["기발"],"explanation":["걸어가면 보발이에요.","말을 타면 기◯이에요.","기발이에요."],"mis":"SO3-2-u2-X37"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L16_challenge#2','soc',3,2,'u2','L16','tb_g3_2_soc_u2_L16_challenge','lesson_challenge','SO3-2-u2-C16',2,'mc','auto','서찰은 주로 언제 이용했나요?',ARRAY['SO3-2-u2-X37']::text[],false,'{"seq":2,"concept":"SO3-2-u2-C16","difficulty":2,"kind":"mc","stem":"서찰은 주로 언제 이용했나요?","options":[{"t":"혼인 같은 집안의 중요한 행사를 전하거나 일상생활의 안부를 주고받을 때","correct":true},{"t":"나라에 적이 쳐들어왔을 때","mis":"SO3-2-u2-X37"},{"t":"큰 공사 소식을 많은 사람에게 널리 알릴 때","mis":"SO3-2-u2-X37"},{"t":"밤에 위급한 상황을 알릴 때","mis":"SO3-2-u2-X37"}],"explanation":["그림 ①이에요.","아씨의 혼인 소식이에요.","집안일과 안부예요."],"asset":{"type":"passage","lines":["그림 ① 아씨의 혼인 소식이 적힌 서찰을 사람이 먼 길을 가서 직접 전하려고 해요.","그림 ② 길거리에 붙은 방 앞에 사람들이 모여 「나라에서 큰 공사를 한다는군.」 하고 말해요."],"numbered":false,"title":"『사회』 123쪽 — 옛날 사람들이 일상생활에서 소식을 전한 모습"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L16_challenge#3','soc',3,2,'u2','L16','tb_g3_2_soc_u2_L16_challenge','lesson_challenge','SO3-2-u2-C16',3,'mc','auto','봉수로 소식을 전하기 어려웠던 날은 언제인가요?',ARRAY['SO3-2-u2-X38']::text[],false,'{"seq":3,"concept":"SO3-2-u2-C16","difficulty":3,"kind":"mc","stem":"봉수로 소식을 전하기 어려웠던 날은 언제인가요?","options":[{"t":"안개가 짙거나 구름이 많이 낀 날","correct":true},{"t":"맑게 갠 날","mis":"SO3-2-u2-X38"},{"t":"바람이 없는 낮","mis":"SO3-2-u2-X38"},{"t":"달이 밝은 밤","mis":"SO3-2-u2-X38"}],"explanation":["연기와 불을 눈으로 봐요.","안 보이면 못 전해요.","안개 낀 날이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L16_challenge#4','soc',3,2,'u2','L16','tb_g3_2_soc_u2_L16_challenge','lesson_challenge','SO3-2-u2-C16',3,'mc','auto','「나라에서 큰 공사를 한다」는 소식을 많은 사람에게 알리기에 알맞은 옛날 통신수단은 무엇인가요?',ARRAY['SO3-2-u2-X37']::text[],false,'{"seq":4,"concept":"SO3-2-u2-C16","difficulty":3,"kind":"mc","stem":"「나라에서 큰 공사를 한다」는 소식을 많은 사람에게 알리기에 알맞은 옛날 통신수단은 무엇인가요?","options":[{"t":"방","correct":true},{"t":"서찰","mis":"SO3-2-u2-X37"},{"t":"봉수","mis":"SO3-2-u2-X37"},{"t":"신호 연","mis":"SO3-2-u2-X37"}],"explanation":["많은 사람이에요.","길거리에 붙여요.","방이에요."],"asset":{"type":"passage","lines":["그림 ① 아씨의 혼인 소식이 적힌 서찰을 사람이 먼 길을 가서 직접 전하려고 해요.","그림 ② 길거리에 붙은 방 앞에 사람들이 모여 「나라에서 큰 공사를 한다는군.」 하고 말해요."],"numbered":false,"title":"『사회』 123쪽 — 옛날 사람들이 일상생활에서 소식을 전한 모습"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L16_challenge#5','soc',3,2,'u2','L16','tb_g3_2_soc_u2_L16_challenge','lesson_challenge','SO3-2-u2-C16',3,'ox','auto','옛날 사람들은 다양한 통신수단을 이용해 한 번에 많은 정보를 빠르고 정확하게 주고받았어요.',ARRAY['SO3-2-u2-X38']::text[],false,'{"seq":5,"concept":"SO3-2-u2-C16","difficulty":3,"kind":"ox","stem":"옛날 사람들은 다양한 통신수단을 이용해 한 번에 많은 정보를 빠르고 정확하게 주고받았어요.","answer":"X","reason_options":[{"t":"옛날 통신수단은 시간이 오래 걸리고 많은 내용을 자세하고 정확하게 전하기 어려웠기 때문에","correct":true},{"t":"옛날 통신수단은 오늘날 통신수단과 특징이 같기 때문에","mis":"SO3-2-u2-X38"}],"mis":"SO3-2-u2-X38","explanation":["꼭 기억해요 2예요.","시간이 오래 걸렸어요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L16_challenge#6','soc',3,2,'u2','L16','tb_g3_2_soc_u2_L16_challenge','lesson_challenge','SO3-2-u2-C16',3,'match','auto','봉수를 올린 상황과 연기나 불의 개수를 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"SO3-2-u2-C16","difficulty":3,"kind":"match","stem":"봉수를 올린 상황과 연기나 불의 개수를 알맞게 이으세요.","pairs":[{"l":"적이 없는 평상시","r":"1개"},{"l":"적이 나타났을 때","r":"2개"},{"l":"적이 가까이 왔을 때","r":"3개"},{"l":"적과 싸움이 시작됐을 때","r":"5개"}],"mis":"SO3-2-u2-X37","explanation":["평상시는 1개예요.","나타나면 2개, 가까이 오면 3개예요.","싸움이 시작되면 5개예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L16_challenge#7','soc',3,2,'u2','L16','tb_g3_2_soc_u2_L16_challenge','lesson_challenge','SO3-2-u2-C16',3,'error','auto','파발과 봉수를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO3-2-u2-X37']::text[],false,'{"seq":7,"concept":"SO3-2-u2-C16","difficulty":3,"kind":"error","stem":"파발과 봉수를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 나 — 「파발은 낮에는 연기, 밤에는 불을 피워 알렸어.」","correct":true,"mis_target":"SO3-2-u2-X37"},{"t":"친구 가 — 「파발은 문서를 말을 타고 가거나 걸어가서 전했어.」","mis":"SO3-2-u2-X37"},{"t":"친구 다 — 「봉수는 낮에는 연기, 밤에는 불을 피웠어.」","mis":"SO3-2-u2-X37"}],"explanation":["연기와 불은 봉수예요.","파발은 문서예요.","친구 나가 잘못 말했어요."],"asset":{"type":"passage","lines":["파발 — 나라의 중요한 일이나 소식을 적은 문서를 말을 타고 가거나 걸어가서 전달했어요.","봉수 — 낮에는 연기, 밤에는 불을 피워서 위급한 상황을 알렸어요.","말풍선 — 옛날 통신수단은 소식을 전하는 데 시간이 오래 걸렸어요.","말풍선 — 많은 정보를 자세하고 정확하게 전하기 어려웠고, 봉수는 날씨의 영향을 받았어요."],"title":"『사회』 125쪽 — 파발과 봉수"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L16_challenge#8','soc',3,2,'u2','L16','tb_g3_2_soc_u2_L16_challenge','lesson_challenge','SO3-2-u2-C16',4,'mc','auto','내가 전쟁 중인 장군이라면 멀리 흩어진 군사들에게 적이 모르게 작전이 바뀐 것을 알릴 때 무엇을 쓰면 좋을까요?',ARRAY['SO3-2-u2-X37']::text[],false,'{"seq":8,"concept":"SO3-2-u2-C16","difficulty":4,"kind":"mc","stem":"내가 전쟁 중인 장군이라면 멀리 흩어진 군사들에게 적이 모르게 작전이 바뀐 것을 알릴 때 무엇을 쓰면 좋을까요?","options":[{"t":"신호 연","correct":true},{"t":"북","mis":"SO3-2-u2-X37"},{"t":"방","mis":"SO3-2-u2-X37"},{"t":"서찰","mis":"SO3-2-u2-X37"}],"explanation":["멀리서 보여야 해요.","적은 몰라야 해요.","암호를 적은 신호 연이에요."],"asset":{"type":"passage","lines":["신호 연 — 암호를 적은 연을 띄워서 작전이 시작되거나 바뀐 것을 알렸어요.","신호 깃발 — 깃발을 이용해 명령을 전달하거나 소식을 전했어요.","북 — 북을 쳐서 큰 소리를 내어 소식이나 작전을 알렸어요.","나발 — 군대에서 명령하거나 신호하는 데 쓴 악기로, 소리를 내어 신호를 보냈어요."],"title":"『사회』 124쪽 — 나라에 위급한 상황이 생겼을 때 쓴 통신수단"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L16_challenge#9','soc',3,2,'u2','L16','tb_g3_2_soc_u2_L16_challenge','lesson_challenge','SO3-2-u2-C16',4,'ox','auto','옛날 통신수단은 오늘날 보면 불편하지만, 그때에는 소식을 전하는 데 널리 쓰인 중요한 수단이었어요.',ARRAY['SO3-2-u2-X48']::text[],false,'{"seq":9,"concept":"SO3-2-u2-C16","difficulty":4,"kind":"ox","stem":"옛날 통신수단은 오늘날 보면 불편하지만, 그때에는 소식을 전하는 데 널리 쓰인 중요한 수단이었어요.","answer":"O","reason_options":[{"t":"그 시대에는 서찰, 방, 봉수, 파발 등이 사람들이 보편적으로 쓰던 통신수단이었기 때문에","correct":true},{"t":"불편한 통신수단은 그때에도 아무도 쓰지 않았기 때문에","mis":"SO3-2-u2-X48"}],"mis":"SO3-2-u2-X48","explanation":["그때의 눈으로 봐요.","널리 썼어요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L16_challenge#10','soc',3,2,'u2','L16','tb_g3_2_soc_u2_L16_challenge','lesson_challenge','SO3-2-u2-C16',4,'essay','teacher','내가 전쟁 중인 장군이라면 부하에게 명령할 때 이용하고 싶은 옛날 통신수단과 그 까닭을 쓰고, 그 통신수단으로 전하기 어려운 점을 하나 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO3-2-u2-C16","difficulty":4,"kind":"essay","stem":"내가 전쟁 중인 장군이라면 부하에게 명령할 때 이용하고 싶은 옛날 통신수단과 그 까닭을 쓰고, 그 통신수단으로 전하기 어려운 점을 하나 쓰세요.","answer_guide":{"answer":"예: 북을 쓰고 싶어요. 큰 소리로 여러 군사에게 한꺼번에 소식을 전할 수 있기 때문이에요. 하지만 자세한 명령 내용까지 전하기는 어려워요.","scoring_points":["통신수단을 골랐는가","까닭을 썼는가","전하기 어려운 점을 썼는가"]},"explanation":["하나를 골라요.","까닭을 써요.","어려운 점도 써요."],"asset":{"type":"passage","lines":["신호 연 — 암호를 적은 연을 띄워서 작전이 시작되거나 바뀐 것을 알렸어요.","신호 깃발 — 깃발을 이용해 명령을 전달하거나 소식을 전했어요.","북 — 북을 쳐서 큰 소리를 내어 소식이나 작전을 알렸어요.","나발 — 군대에서 명령하거나 신호하는 데 쓴 악기로, 소리를 내어 신호를 보냈어요."],"title":"『사회』 124쪽 — 나라에 위급한 상황이 생겼을 때 쓴 통신수단"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L17_basic#1','soc',3,2,'u2','L17','tb_g3_2_soc_u2_L17_basic','lesson_basic','SO3-2-u2-C17',1,'mc','auto','스마트폰 등을 이용하여 어디에서나 대화하거나 정보를 주고받을 수 있는 통신수단은 무엇인가요?',ARRAY['SO3-2-u2-X39']::text[],true,'{"seq":1,"concept":"SO3-2-u2-C17","difficulty":1,"kind":"mc","stem":"스마트폰 등을 이용하여 어디에서나 대화하거나 정보를 주고받을 수 있는 통신수단은 무엇인가요?","options":[{"t":"모바일 메신저","correct":true},{"t":"디지털 안내판","mis":"SO3-2-u2-X39"},{"t":"무전기","mis":"SO3-2-u2-X39"},{"t":"라디오","mis":"SO3-2-u2-X39"}],"explanation":["126쪽 낱말 풀이예요.","어디에서나 대화해요.","모바일 메신저예요."],"variant_rule":{"alt":[{"stem":"버스 정류장에서 버스가 오는 시각을 미리 알려 주는 통신수단은 무엇인가요?","options":[{"t":"디지털 안내판","correct":true},{"t":"모바일 메신저","mis":"SO3-2-u2-X39"},{"t":"무전기","mis":"SO3-2-u2-X39"},{"t":"등하교 알리미","mis":"SO3-2-u2-X39"}],"explanation":["버스 정류장이에요.","도착 시각을 알려 줘요.","디지털 안내판이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L17_basic#2','soc',3,2,'u2','L17','tb_g3_2_soc_u2_L17_basic','lesson_basic','SO3-2-u2-C17',1,'sa','auto','127쪽 그림에서 119 구급 대원이 구조 헬기를 요청할 때 쓴 통신수단을 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SO3-2-u2-C17","difficulty":1,"kind":"sa","stem":"127쪽 그림에서 119 구급 대원이 구조 헬기를 요청할 때 쓴 통신수단을 쓰세요.","answer":["무전기"],"explanation":["구조 헬기를 불러요.","무◯◯예요.","무전기예요."],"mis":"SO3-2-u2-X39"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L17_basic#3','soc',3,2,'u2','L17','tb_g3_2_soc_u2_L17_basic','lesson_basic','SO3-2-u2-C17',1,'mc','auto','학교에서 수업 종소리나 안내 방송이 나오는 통신수단은 무엇인가요?',ARRAY['SO3-2-u2-X39']::text[],false,'{"seq":3,"concept":"SO3-2-u2-C17","difficulty":1,"kind":"mc","stem":"학교에서 수업 종소리나 안내 방송이 나오는 통신수단은 무엇인가요?","options":[{"t":"스피커","correct":true},{"t":"전자 칠판","mis":"SO3-2-u2-X39"},{"t":"태블릿 컴퓨터","mis":"SO3-2-u2-X39"},{"t":"온라인 게시판","mis":"SO3-2-u2-X39"}],"explanation":["128쪽 그림이에요.","소리가 나와요.","스피커예요."],"asset":{"type":"passage","lines":["텔레비전이나 전자 칠판으로 영상을 보면서 공부해요.","태블릿 컴퓨터로 궁금한 내용을 찾아봐요.","스피커로 수업 종소리나 안내 방송이 나와요.","전화기로 다른 교실에 있는 선생님들과 연락해요.","과제는 온라인 게시판에 제출해요.","복도에는 불이 났을 때 경보가 울리는 화재경보기가 있어요."],"title":"『사회』 128쪽 — 학교에 있는 통신수단"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L17_basic#4','soc',3,2,'u2','L17','tb_g3_2_soc_u2_L17_basic','lesson_basic','SO3-2-u2-C17',1,'ox','auto','축구 심판은 규칙에 따라 여러 색의 카드를 사용해요.',ARRAY['SO3-2-u2-X39']::text[],false,'{"seq":4,"concept":"SO3-2-u2-C17","difficulty":1,"kind":"ox","stem":"축구 심판은 규칙에 따라 여러 색의 카드를 사용해요.","answer":"O","reason_options":[{"t":"『사회』 130쪽처럼 시끄러운 경기장에서 눈으로 보이는 카드로 판정을 알리기 때문에","correct":true},{"t":"축구 심판은 말소리로만 판정을 알리기 때문에","mis":"SO3-2-u2-X39"}],"mis":"SO3-2-u2-X39","explanation":["130쪽 사진이에요.","색 카드예요.","그래서 O예요."],"asset":{"type":"passage","lines":["야구 심판 — 멀리서도 잘 보이도록 수신호를 사용해요.","교통경찰 — 자동차들이 안전하게 이동하도록 수신호와 호루라기를 사용해요.","축구 심판 — 규칙에 따라 여러 색의 카드를 사용해요.","교통정리 — 약속이 담긴 깃발을 사용해요.","농사일을 주로 하는 마을 — 마을 안내 방송으로 소식을 전해요."],"title":"『사회』 130쪽 — 장소나 하는 일에 따라 다른 통신수단"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L17_basic#5','soc',3,2,'u2','L17','tb_g3_2_soc_u2_L17_basic','lesson_basic','SO3-2-u2-C17',2,'match','auto','그림 속 말과 이용하는 통신수단을 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"SO3-2-u2-C17","difficulty":2,"kind":"match","stem":"그림 속 말과 이용하는 통신수단을 알맞게 이으세요.","pairs":[{"l":"「오늘은 미세 먼지 없이 깨끗하네.」","r":"대기 정보 알리미"},{"l":"「곧 버스가 도착하겠군.」","r":"디지털 안내판"},{"l":"「학교에 잘 도착했네.」","r":"등하교 알리미"},{"l":"「바로바로 답장을 확인할 수 있으니 편해.」","r":"모바일 메신저"}],"mis":"SO3-2-u2-X39","explanation":["미세 먼지는 알리미예요.","버스는 안내판, 등교는 등하교 알리미예요.","답장은 메신저예요."],"asset":{"type":"speech","turns":[{"who":"사람 1","text":"오늘은 미세 먼지 없이 깨끗하네."},{"who":"사람 2","text":"곧 버스가 도착하겠군."},{"who":"사람 3","text":"학교에 잘 도착했네."},{"who":"사람 4","text":"바로바로 답장을 확인할 수 있으니 편해."},{"who":"구급 대원","text":"이쪽으로 구조 헬기를 보내 주세요!"},{"who":"사람 5","text":"라디오로 뉴스를 들어 볼까?"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L17_basic#6','soc',3,2,'u2','L17','tb_g3_2_soc_u2_L17_basic','lesson_basic','SO3-2-u2-C17',2,'mc','auto','129쪽 장면 ①이 보여 주는 오늘날 통신수단의 특징은 무엇인가요?',ARRAY['SO3-2-u2-X39','SO3-2-u2-X38']::text[],false,'{"seq":6,"concept":"SO3-2-u2-C17","difficulty":2,"kind":"mc","stem":"129쪽 장면 ①이 보여 주는 오늘날 통신수단의 특징은 무엇인가요?","options":[{"t":"여러 사람에게 실시간으로 빠르게 정보를 전달해요","correct":true},{"t":"하나의 통신수단으로 여러 통신 방법을 이용해요","mis":"SO3-2-u2-X39"},{"t":"소식을 전하는 데 시간이 오래 걸려요","mis":"SO3-2-u2-X38"},{"t":"날씨의 영향을 많이 받아요","mis":"SO3-2-u2-X38"}],"explanation":["버스 정류장이에요.","모두가 바로 봐요.","실시간으로 빠르게예요."],"asset":{"type":"passage","lines":["장면 ① 버스 정류장의 디지털 안내판에 「약 3분 후 도착」이 떠요.","장면 ② 온라인으로 토의하고 각자 의견을 단체 대화방에 올리기로 해요.","장면 ③ 찾은 자료를 전자 우편에 첨부해 한꺼번에 보내요.","장면 ④ 태블릿 컴퓨터로 인터넷 신문 기사를 읽고, 음악을 듣고, 문자 메시지도 확인해요."],"title":"『사회』 129쪽 — 오늘날 통신수단의 특징을 보여 주는 장면"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L17_basic#7','soc',3,2,'u2','L17','tb_g3_2_soc_u2_L17_basic','lesson_basic','SO3-2-u2-C17',2,'mc','auto','교통경찰이 도로에서 자동차들이 안전하게 이동하도록 사용하는 통신수단은 무엇인가요?',ARRAY['SO3-2-u2-X39']::text[],false,'{"seq":7,"concept":"SO3-2-u2-C17","difficulty":2,"kind":"mc","stem":"교통경찰이 도로에서 자동차들이 안전하게 이동하도록 사용하는 통신수단은 무엇인가요?","options":[{"t":"수신호와 호루라기","correct":true},{"t":"여러 색의 카드","mis":"SO3-2-u2-X39"},{"t":"마을 안내 방송","mis":"SO3-2-u2-X39"},{"t":"모바일 메신저","mis":"SO3-2-u2-X39"}],"explanation":["130쪽 사진이에요.","손과 소리예요.","수신호와 호루라기예요."],"asset":{"type":"passage","lines":["야구 심판 — 멀리서도 잘 보이도록 수신호를 사용해요.","교통경찰 — 자동차들이 안전하게 이동하도록 수신호와 호루라기를 사용해요.","축구 심판 — 규칙에 따라 여러 색의 카드를 사용해요.","교통정리 — 약속이 담긴 깃발을 사용해요.","농사일을 주로 하는 마을 — 마을 안내 방송으로 소식을 전해요."],"title":"『사회』 130쪽 — 장소나 하는 일에 따라 다른 통신수단"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L17_basic#8','soc',3,2,'u2','L17','tb_g3_2_soc_u2_L17_basic','lesson_basic','SO3-2-u2-C17',2,'blank','auto','「집들이 서로 떨어져 있거나 농사일을 주로 하는 곳에서는 (    )으로 소식을 전합니다.」 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SO3-2-u2-X39']::text[],false,'{"seq":8,"concept":"SO3-2-u2-C17","difficulty":2,"kind":"blank","stem":"「집들이 서로 떨어져 있거나 농사일을 주로 하는 곳에서는 (    )으로 소식을 전합니다.」 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"마을 안내 방송","correct":true},{"t":"수신호","mis":"SO3-2-u2-X39"},{"t":"색 카드","mis":"SO3-2-u2-X39"},{"t":"깃발","mis":"SO3-2-u2-X39"}],"explanation":["130쪽 마지막 사진이에요.","마을 사람 모두에게예요.","마을 안내 방송이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L17_basic#9','soc',3,2,'u2','L17','tb_g3_2_soc_u2_L17_basic','lesson_basic','SO3-2-u2-C17',2,'ox','auto','오늘날 통신수단은 많은 정보를 자세하고 정확하게 전하기 어려워요.',ARRAY['SO3-2-u2-X38']::text[],false,'{"seq":9,"concept":"SO3-2-u2-C17","difficulty":2,"kind":"ox","stem":"오늘날 통신수단은 많은 정보를 자세하고 정확하게 전하기 어려워요.","answer":"X","reason_options":[{"t":"글, 사진, 동영상 등 다양하고 많은 정보를 날씨와 관계없이 자세하고 정확하게 전할 수 있기 때문에","correct":true},{"t":"오늘날 통신수단도 연기나 불의 개수로만 알리기 때문에","mis":"SO3-2-u2-X38"}],"mis":"SO3-2-u2-X38","explanation":["꼭 기억해요 2예요.","자세하고 정확해요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L17_basic#10','soc',3,2,'u2','L17','tb_g3_2_soc_u2_L17_basic','lesson_basic','SO3-2-u2-C17',3,'error','auto','장소나 하는 일에 따라 쓰는 통신수단을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO3-2-u2-X39']::text[],false,'{"seq":10,"concept":"SO3-2-u2-C17","difficulty":3,"kind":"error","stem":"장소나 하는 일에 따라 쓰는 통신수단을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「야구 심판은 시끄러운 경기장에서 마을 안내 방송으로 판정을 알려.」","correct":true,"mis_target":"SO3-2-u2-X39"},{"t":"친구 가 — 「야구 심판은 멀리서도 잘 보이도록 수신호를 써.」","mis":"SO3-2-u2-X39"},{"t":"친구 나 — 「교통정리를 할 때 약속이 담긴 깃발을 쓰기도 해.」","mis":"SO3-2-u2-X39"}],"explanation":["야구 심판은 수신호예요.","마을 안내 방송은 마을이에요.","친구 다가 잘못 말했어요."],"asset":{"type":"passage","lines":["야구 심판 — 멀리서도 잘 보이도록 수신호를 사용해요.","교통경찰 — 자동차들이 안전하게 이동하도록 수신호와 호루라기를 사용해요.","축구 심판 — 규칙에 따라 여러 색의 카드를 사용해요.","교통정리 — 약속이 담긴 깃발을 사용해요.","농사일을 주로 하는 마을 — 마을 안내 방송으로 소식을 전해요."],"title":"『사회』 130쪽 — 장소나 하는 일에 따라 다른 통신수단"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L17_challenge#1','soc',3,2,'u2','L17','tb_g3_2_soc_u2_L17_challenge','lesson_challenge','SO3-2-u2-C17',2,'sa','auto','학교 복도에 있으며 불이 났을 때 사람들에게 경보를 울려 알리는 통신수단을 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"SO3-2-u2-C17","difficulty":2,"kind":"sa","stem":"학교 복도에 있으며 불이 났을 때 사람들에게 경보를 울려 알리는 통신수단을 쓰세요.","answer":["화재경보기","화재 경보기"],"explanation":["불이 났을 때예요.","경보가 울려요.","화재경보기예요."],"mis":"SO3-2-u2-X39"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L17_challenge#2','soc',3,2,'u2','L17','tb_g3_2_soc_u2_L17_challenge','lesson_challenge','SO3-2-u2-C17',2,'mc','auto','여행을 계획할 때 통신수단을 이용하는 모습으로 알맞은 것은 무엇인가요?',ARRAY['SO3-2-u2-X38']::text[],false,'{"seq":2,"concept":"SO3-2-u2-C17","difficulty":2,"kind":"mc","stem":"여행을 계획할 때 통신수단을 이용하는 모습으로 알맞은 것은 무엇인가요?","options":[{"t":"스마트폰으로 기차표를 예매해요","correct":true},{"t":"방을 붙여 여행 소식을 알려요","mis":"SO3-2-u2-X38"},{"t":"북을 쳐서 출발을 알려요","mis":"SO3-2-u2-X38"},{"t":"봉수를 올려 숙소를 찾아요","mis":"SO3-2-u2-X38"}],"explanation":["오늘날 통신수단이에요.","스마트폰이에요.","기차표를 예매해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L17_challenge#3','soc',3,2,'u2','L17','tb_g3_2_soc_u2_L17_challenge','lesson_challenge','SO3-2-u2-C17',3,'mc','auto','129쪽 장면 ②가 보여 주는 오늘날 통신수단의 특징은 무엇인가요?',ARRAY['SO3-2-u2-X38']::text[],false,'{"seq":3,"concept":"SO3-2-u2-C17","difficulty":3,"kind":"mc","stem":"129쪽 장면 ②가 보여 주는 오늘날 통신수단의 특징은 무엇인가요?","options":[{"t":"여러 사람과 동시에 연락하거나 정보를 주고받아요","correct":true},{"t":"소식을 전하는 데 시간이 오래 걸려요","mis":"SO3-2-u2-X38"},{"t":"한 사람에게만 소식을 전할 수 있어요","mis":"SO3-2-u2-X38"},{"t":"날씨가 나쁘면 쓸 수 없어요","mis":"SO3-2-u2-X38"}],"explanation":["온라인 토의예요.","단체 대화방이에요.","여러 사람과 동시에예요."],"asset":{"type":"passage","lines":["장면 ① 버스 정류장의 디지털 안내판에 「약 3분 후 도착」이 떠요.","장면 ② 온라인으로 토의하고 각자 의견을 단체 대화방에 올리기로 해요.","장면 ③ 찾은 자료를 전자 우편에 첨부해 한꺼번에 보내요.","장면 ④ 태블릿 컴퓨터로 인터넷 신문 기사를 읽고, 음악을 듣고, 문자 메시지도 확인해요."],"title":"『사회』 129쪽 — 오늘날 통신수단의 특징을 보여 주는 장면"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L17_challenge#4','soc',3,2,'u2','L17','tb_g3_2_soc_u2_L17_challenge','lesson_challenge','SO3-2-u2-C17',3,'mc','auto','129쪽 장면 ④가 보여 주는 오늘날 통신수단의 특징은 무엇인가요?',ARRAY['SO3-2-u2-X39','SO3-2-u2-X38']::text[],false,'{"seq":4,"concept":"SO3-2-u2-C17","difficulty":3,"kind":"mc","stem":"129쪽 장면 ④가 보여 주는 오늘날 통신수단의 특징은 무엇인가요?","options":[{"t":"하나의 통신수단으로 다양한 통신 방법을 이용해요","correct":true},{"t":"여러 사람에게 실시간으로 정보를 전달해요","mis":"SO3-2-u2-X39"},{"t":"많은 정보를 전하기 어려워요","mis":"SO3-2-u2-X38"},{"t":"한 가지 일만 할 수 있어요","mis":"SO3-2-u2-X38"}],"explanation":["태블릿 컴퓨터 하나예요.","기사, 음악, 문자예요.","여러 방법이에요."],"asset":{"type":"passage","lines":["장면 ① 버스 정류장의 디지털 안내판에 「약 3분 후 도착」이 떠요.","장면 ② 온라인으로 토의하고 각자 의견을 단체 대화방에 올리기로 해요.","장면 ③ 찾은 자료를 전자 우편에 첨부해 한꺼번에 보내요.","장면 ④ 태블릿 컴퓨터로 인터넷 신문 기사를 읽고, 음악을 듣고, 문자 메시지도 확인해요."],"title":"『사회』 129쪽 — 오늘날 통신수단의 특징을 보여 주는 장면"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L17_challenge#5','soc',3,2,'u2','L17','tb_g3_2_soc_u2_L17_challenge','lesson_challenge','SO3-2-u2-C17',3,'ox','auto','사람들은 생활하는 장소나 하는 일에 따라 알맞은 통신수단을 이용해요.',ARRAY['SO3-2-u2-X39']::text[],false,'{"seq":5,"concept":"SO3-2-u2-C17","difficulty":3,"kind":"ox","stem":"사람들은 생활하는 장소나 하는 일에 따라 알맞은 통신수단을 이용해요.","answer":"O","reason_options":[{"t":"야구장, 도로, 축구장, 마을처럼 장소와 하는 일에 따라 쓰는 통신수단이 다르기 때문에","correct":true},{"t":"어디에서나 누구나 한 가지 통신수단만 쓰기 때문에","mis":"SO3-2-u2-X39"}],"mis":"SO3-2-u2-X39","explanation":["130쪽 제목이에요.","장소마다 달라요.","그래서 O예요."],"asset":{"type":"passage","lines":["야구 심판 — 멀리서도 잘 보이도록 수신호를 사용해요.","교통경찰 — 자동차들이 안전하게 이동하도록 수신호와 호루라기를 사용해요.","축구 심판 — 규칙에 따라 여러 색의 카드를 사용해요.","교통정리 — 약속이 담긴 깃발을 사용해요.","농사일을 주로 하는 마을 — 마을 안내 방송으로 소식을 전해요."],"title":"『사회』 130쪽 — 장소나 하는 일에 따라 다른 통신수단"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L17_challenge#6','soc',3,2,'u2','L17','tb_g3_2_soc_u2_L17_challenge','lesson_challenge','SO3-2-u2-C17',3,'match','auto','하는 일과 그때 쓰는 통신수단을 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"SO3-2-u2-C17","difficulty":3,"kind":"match","stem":"하는 일과 그때 쓰는 통신수단을 알맞게 이으세요.","pairs":[{"l":"야구 심판","r":"멀리서도 잘 보이는 수신호"},{"l":"교통경찰","r":"수신호와 호루라기"},{"l":"축구 심판","r":"규칙에 따른 여러 색의 카드"},{"l":"농사일을 주로 하는 마을","r":"마을 안내 방송"}],"mis":"SO3-2-u2-X39","explanation":["야구는 수신호예요.","교통경찰은 호루라기도 써요.","축구는 카드, 마을은 방송이에요."],"asset":{"type":"passage","lines":["야구 심판 — 멀리서도 잘 보이도록 수신호를 사용해요.","교통경찰 — 자동차들이 안전하게 이동하도록 수신호와 호루라기를 사용해요.","축구 심판 — 규칙에 따라 여러 색의 카드를 사용해요.","교통정리 — 약속이 담긴 깃발을 사용해요.","농사일을 주로 하는 마을 — 마을 안내 방송으로 소식을 전해요."],"title":"『사회』 130쪽 — 장소나 하는 일에 따라 다른 통신수단"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L17_challenge#7','soc',3,2,'u2','L17','tb_g3_2_soc_u2_L17_challenge','lesson_challenge','SO3-2-u2-C17',3,'error','auto','학교의 통신수단을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO3-2-u2-X39']::text[],false,'{"seq":7,"concept":"SO3-2-u2-C17","difficulty":3,"kind":"error","stem":"학교의 통신수단을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 가 — 「온라인 게시판으로 수업 종소리를 울려.」","correct":true,"mis_target":"SO3-2-u2-X39"},{"t":"친구 나 — 「태블릿 컴퓨터로 궁금한 내용을 찾아봐.」","mis":"SO3-2-u2-X39"},{"t":"친구 다 — 「과제는 온라인 게시판에 제출해.」","mis":"SO3-2-u2-X39"}],"explanation":["종소리는 스피커예요.","게시판은 과제예요.","친구 가가 잘못 말했어요."],"asset":{"type":"passage","lines":["텔레비전이나 전자 칠판으로 영상을 보면서 공부해요.","태블릿 컴퓨터로 궁금한 내용을 찾아봐요.","스피커로 수업 종소리나 안내 방송이 나와요.","전화기로 다른 교실에 있는 선생님들과 연락해요.","과제는 온라인 게시판에 제출해요.","복도에는 불이 났을 때 경보가 울리는 화재경보기가 있어요."],"title":"『사회』 128쪽 — 학교에 있는 통신수단"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L17_challenge#8','soc',3,2,'u2','L17','tb_g3_2_soc_u2_L17_challenge','lesson_challenge','SO3-2-u2-C17',4,'mc','auto','오늘날 통신수단의 특징을 가장 잘 정리한 것은 무엇인가요?',ARRAY['SO3-2-u2-X38']::text[],false,'{"seq":8,"concept":"SO3-2-u2-C17","difficulty":4,"kind":"mc","stem":"오늘날 통신수단의 특징을 가장 잘 정리한 것은 무엇인가요?","options":[{"t":"여러 사람과 동시에 많은 양의 정보를 실시간으로 한 번에 빠르게 주고받아요","correct":true},{"t":"시간이 오래 걸리고 날씨의 영향을 받아요","mis":"SO3-2-u2-X38"},{"t":"정보를 한 사람에게 하나씩만 보내요","mis":"SO3-2-u2-X38"},{"t":"글만 보낼 수 있고 사진은 못 보내요","mis":"SO3-2-u2-X38"}],"explanation":["130쪽 정리예요.","동시에, 많이, 실시간이에요.","빠르게예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L17_challenge#9','soc',3,2,'u2','L17','tb_g3_2_soc_u2_L17_challenge','lesson_challenge','SO3-2-u2-C17',4,'ox','auto','축구장이나 도로처럼 시끄러운 곳에서는 말 대신 수신호나 색 카드처럼 눈으로 보는 통신수단이 알맞아요.',ARRAY['SO3-2-u2-X39']::text[],false,'{"seq":9,"concept":"SO3-2-u2-C17","difficulty":4,"kind":"ox","stem":"축구장이나 도로처럼 시끄러운 곳에서는 말 대신 수신호나 색 카드처럼 눈으로 보는 통신수단이 알맞아요.","answer":"O","reason_options":[{"t":"주위가 시끄러우면 말소리가 잘 전해지지 않아 멀리서도 보이는 신호가 필요하기 때문에","correct":true},{"t":"시끄러운 곳일수록 말로만 알려야 잘 들리기 때문에","mis":"SO3-2-u2-X39"}],"mis":"SO3-2-u2-X39","explanation":["시끄러운 곳이에요.","눈으로 보는 신호예요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L17_challenge#10','soc',3,2,'u2','L17','tb_g3_2_soc_u2_L17_challenge','lesson_challenge','SO3-2-u2-C17',4,'essay','teacher','학교에서 공부할 때 통신수단을 이용한 경험을 쓰고, 그 통신수단이 오늘날 통신수단의 어떤 특징을 보여 주는지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO3-2-u2-C17","difficulty":4,"kind":"essay","stem":"학교에서 공부할 때 통신수단을 이용한 경험을 쓰고, 그 통신수단이 오늘날 통신수단의 어떤 특징을 보여 주는지 쓰세요.","answer_guide":{"answer":"예: 태블릿 컴퓨터로 디지털 교과서를 보고 궁금한 내용을 찾았어요. 하나의 통신수단으로 여러 가지 일을 할 수 있다는 특징을 보여 줘요.","scoring_points":["경험을 썼는가","통신수단을 썼는가","오늘날 통신수단의 특징과 이었는가"]},"explanation":["학교를 떠올려요.","통신수단을 써요.","특징과 이어요."],"asset":{"type":"passage","lines":["텔레비전이나 전자 칠판으로 영상을 보면서 공부해요.","태블릿 컴퓨터로 궁금한 내용을 찾아봐요.","스피커로 수업 종소리나 안내 방송이 나와요.","전화기로 다른 교실에 있는 선생님들과 연락해요.","과제는 온라인 게시판에 제출해요.","복도에는 불이 났을 때 경보가 울리는 화재경보기가 있어요."],"title":"『사회』 128쪽 — 학교에 있는 통신수단"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L18_basic#1','soc',3,2,'u2','L18','tb_g3_2_soc_u2_L18_basic','lesson_basic','SO3-2-u2-C18',1,'mc','auto','「삐삐」라고 불렸으며, 휴대 전화가 발달하면서 점차 사라지고 있는 통신수단은 무엇인가요?',ARRAY['SO3-2-u2-X41']::text[],false,'{"seq":1,"concept":"SO3-2-u2-C18","difficulty":1,"kind":"mc","stem":"「삐삐」라고 불렸으며, 휴대 전화가 발달하면서 점차 사라지고 있는 통신수단은 무엇인가요?","options":[{"t":"무선 호출기","correct":true},{"t":"모바일 메신저","mis":"SO3-2-u2-X41"},{"t":"길 도우미","mis":"SO3-2-u2-X41"},{"t":"키오스크","mis":"SO3-2-u2-X41"}],"explanation":["131쪽 말풍선이에요.","삐삐예요.","무선 호출기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L18_basic#2','soc',3,2,'u2','L18','tb_g3_2_soc_u2_L18_basic','lesson_basic','SO3-2-u2-C18',1,'sa','auto','전화 거는 사람과 받는 사람을 연결해 주던 일을 했으나, 전화를 직접 걸고 받게 되면서 점차 사라진 직업을 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SO3-2-u2-C18","difficulty":1,"kind":"sa","stem":"전화 거는 사람과 받는 사람을 연결해 주던 일을 했으나, 전화를 직접 걸고 받게 되면서 점차 사라진 직업을 쓰세요.","answer":["교환원"],"explanation":["132쪽 말풍선이에요.","연결해 줬어요.","교환원이에요."],"mis":"SO3-2-u2-X41"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L18_basic#3','soc',3,2,'u2','L18','tb_g3_2_soc_u2_L18_basic','lesson_basic','SO3-2-u2-C18',1,'mc','auto','휴대 전화나 컴퓨터의 통신을 원활하게 해 주는 기지국을 설치하는 직업은 무엇인가요?',ARRAY['SO3-2-u2-X41']::text[],true,'{"seq":3,"concept":"SO3-2-u2-C18","difficulty":1,"kind":"mc","stem":"휴대 전화나 컴퓨터의 통신을 원활하게 해 주는 기지국을 설치하는 직업은 무엇인가요?","options":[{"t":"통신 설비 기술자","correct":true},{"t":"촬영 기사","mis":"SO3-2-u2-X41"},{"t":"인공위성 개발자","mis":"SO3-2-u2-X41"},{"t":"교환원","mis":"SO3-2-u2-X41"}],"explanation":["기지국이에요.","통신 설비를 설치해요.","통신 설비 기술자예요."],"asset":{"type":"passage","lines":["휴대 전화 기지국 — 통신 설비 기술자: 휴대 전화나 컴퓨터의 통신을 원활하게 해 주는 기지국을 설치해요.","스마트 시티 상황실 — 폐회로 텔레비전 통합 관제 요원: 사람들의 안전을 지켜 줘요.","방송국 — 촬영 기사, 방송 프로듀서: 영상을 촬영하고 방송 시간에 맞춰 내보내요.","우주 센터 — 인공위성 개발자: 다양한 정보를 수집하는 인공위성을 만들어요.","사라진 직업 — 교환원: 전화 거는 사람과 받는 사람을 연결해 주던 일을 했어요."],"title":"『사회』 132쪽 — 통신수단이 발달하며 생긴 시설과 직업"},"variant_rule":{"alt":[{"stem":"우주 센터에서 다양한 정보를 수집할 수 있는 인공위성을 만드는 직업은 무엇인가요?","options":[{"t":"인공위성 개발자","correct":true},{"t":"통신 설비 기술자","mis":"SO3-2-u2-X41"},{"t":"방송 프로듀서","mis":"SO3-2-u2-X41"},{"t":"교환원","mis":"SO3-2-u2-X41"}],"explanation":["우주 센터예요.","인공위성을 만들어요.","인공위성 개발자예요."],"asset":{"type":"passage","lines":["휴대 전화 기지국 — 통신 설비 기술자: 휴대 전화나 컴퓨터의 통신을 원활하게 해 주는 기지국을 설치해요.","스마트 시티 상황실 — 폐회로 텔레비전 통합 관제 요원: 사람들의 안전을 지켜 줘요.","방송국 — 촬영 기사, 방송 프로듀서: 영상을 촬영하고 방송 시간에 맞춰 내보내요.","우주 센터 — 인공위성 개발자: 다양한 정보를 수집하는 인공위성을 만들어요.","사라진 직업 — 교환원: 전화 거는 사람과 받는 사람을 연결해 주던 일을 했어요."],"title":"『사회』 132쪽 — 통신수단이 발달하며 생긴 시설과 직업"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L18_basic#4','soc',3,2,'u2','L18','tb_g3_2_soc_u2_L18_basic','lesson_basic','SO3-2-u2-C18',1,'ox','auto','통신수단의 발달로 병원에 직접 가지 않아도 진료를 받을 수 있어요.',ARRAY['SO3-2-u2-X50']::text[],false,'{"seq":4,"concept":"SO3-2-u2-C18","difficulty":1,"kind":"ox","stem":"통신수단의 발달로 병원에 직접 가지 않아도 진료를 받을 수 있어요.","answer":"O","reason_options":[{"t":"『사회』 131쪽 사진처럼 통신수단을 이용해 먼 곳에서도 진료를 받기 때문에","correct":true},{"t":"진료는 어떤 경우에도 통신수단으로 받을 수 없기 때문에","mis":"SO3-2-u2-X50"}],"mis":"SO3-2-u2-X50","explanation":["131쪽 사진이에요.","직접 가지 않아도 돼요.","그래서 O예요."],"asset":{"type":"passage","lines":["예전 — 친구들과 직접 만나거나 전화로 대화했어요. / 오늘날 — 모바일 메신저로 실시간 대화를 해요.","예전 — 시장이나 은행에 직접 갔어요. / 오늘날 — 집에서 물건을 사고 은행 거래를 해요.","예전 — 병원에 직접 가서 진료를 받았어요. / 오늘날 — 병원에 가지 않아도 진료를 받아요.","예전 — 회사에서 직접 만나 회의했어요. / 오늘날 — 먼 곳의 사람과 화상 회의를 해요."],"title":"『사회』 131쪽 — 통신수단의 발달로 달라진 생활"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L18_basic#5','soc',3,2,'u2','L18','tb_g3_2_soc_u2_L18_basic','lesson_basic','SO3-2-u2-C18',2,'match','auto','예전 모습과 통신수단이 발달한 오늘날 모습을 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"SO3-2-u2-C18","difficulty":2,"kind":"match","stem":"예전 모습과 통신수단이 발달한 오늘날 모습을 알맞게 이으세요.","pairs":[{"l":"친구와 직접 만나거나 전화로 대화했어요","r":"모바일 메신저로 실시간 대화를 해요"},{"l":"시장이나 은행에 직접 갔어요","r":"집에서 물건을 사고 은행 거래를 해요"},{"l":"회사에서 직접 만나 회의했어요","r":"먼 곳의 사람과 화상 회의를 해요"},{"l":"낯선 곳에서는 사람에게 길을 물어봤어요","r":"길 도우미를 이용해 길을 찾아요"}],"mis":"SO3-2-u2-X50","explanation":["대화는 메신저예요.","은행 일은 집에서, 회의는 화상으로 해요.","길은 길 도우미예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L18_basic#6','soc',3,2,'u2','L18','tb_g3_2_soc_u2_L18_basic','lesson_basic','SO3-2-u2-C18',2,'mc','auto','초기의 전화기에 대한 설명으로 알맞은 것은 무엇인가요?',ARRAY['SO3-2-u2-X40']::text[],false,'{"seq":6,"concept":"SO3-2-u2-C18","difficulty":2,"kind":"mc","stem":"초기의 전화기에 대한 설명으로 알맞은 것은 무엇인가요?","options":[{"t":"벽에 걸려 있고 숫자 번호판이 없어 교환원이 연결해 줘요","correct":true},{"t":"들고 다니며 영상 통화를 해요","mis":"SO3-2-u2-X40"},{"t":"숫자 번호판으로 직접 번호를 눌러요","mis":"SO3-2-u2-X40"},{"t":"사진을 찍고 물건을 살 수 있어요","mis":"SO3-2-u2-X40"}],"explanation":["133쪽 첫 그림이에요.","번호판이 없어요.","교환원이 연결해요."],"asset":{"type":"passage","lines":["초기의 전화기 — 벽에 걸려 있고 숫자 번호판이 없어요. 교환원이 중간에서 연결해 줘요.","유선 전화 — 숫자 번호판이 있고 전화선으로 연결돼요. 전화기가 있는 곳에 가야 통화해요.","유선 전화 — 공중전화는 동전이나 전화 카드가 있어야 해요.","휴대 전화 — 들고 다니며 통화하고, 영상 통화도 해요.","휴대 전화 — 사진 촬영, 온라인 쇼핑, 은행 거래도 할 수 있어요."],"title":"『사회』 133쪽 할 수 있어요 — 전화기의 변화"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L18_basic#7','soc',3,2,'u2','L18','tb_g3_2_soc_u2_L18_basic','lesson_basic','SO3-2-u2-C18',2,'mc','auto','신문 기사에 나오는 키오스크는 무엇인가요?',ARRAY['SO3-2-u2-X41','SO3-2-u2-X39']::text[],false,'{"seq":7,"concept":"SO3-2-u2-C18","difficulty":2,"kind":"mc","stem":"신문 기사에 나오는 키오스크는 무엇인가요?","options":[{"t":"음식점이나 역, 병원 등에 설치되어 음식이나 물건을 주문할 때 이용하는 무인 안내기","correct":true},{"t":"교환원이 연결해 주는 전화기","mis":"SO3-2-u2-X41"},{"t":"버스 도착을 알려 주는 디지털 안내판","mis":"SO3-2-u2-X39"},{"t":"미세 먼지를 알려 주는 알리미","mis":"SO3-2-u2-X39"}],"explanation":["134쪽 낱말 풀이예요.","주문할 때 써요.","무인 안내기예요."],"asset":{"type":"passage","lines":["(간추림) 디지털 배움터는 일상생활에 필요한 디지털 교육을 한다.","특히 스마트폰과 키오스크 이용에 어려움을 겪는 노인들을 가르친다.","인터넷 검색, 사진과 동영상 촬영, 은행 거래, 온라인 쇼핑, 키오스크 주문을 배운다.","한 어르신은 이제 혼자서 햄버거도 주문할 수 있다며 자신감을 보였다."],"title":"『사회』 134쪽 신문 기사 「스마트폰과 키오스크를 척척, 디지털 배움터」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L18_basic#8','soc',3,2,'u2','L18','tb_g3_2_soc_u2_L18_basic','lesson_basic','SO3-2-u2-C18',2,'blank','auto','「나라에 위급한 일이 생기면 옛날에는 북이나 봉수 등으로 알렸지만, 오늘날에는 긴급 재난 (    )를 보냅니다.」 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SO3-2-u2-X38']::text[],false,'{"seq":8,"concept":"SO3-2-u2-C18","difficulty":2,"kind":"blank","stem":"「나라에 위급한 일이 생기면 옛날에는 북이나 봉수 등으로 알렸지만, 오늘날에는 긴급 재난 (    )를 보냅니다.」 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"문자","correct":true},{"t":"서찰","mis":"SO3-2-u2-X38"},{"t":"방","mis":"SO3-2-u2-X38"},{"t":"연기","mis":"SO3-2-u2-X38"}],"explanation":["오늘날 휴대 전화예요.","모두에게 한꺼번에 보내요.","긴급 재난 문자예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L18_basic#9','soc',3,2,'u2','L18','tb_g3_2_soc_u2_L18_basic','lesson_basic','SO3-2-u2-C18',2,'ox','auto','통신수단이 발달하면 모든 사람이 똑같이 쉽고 편리하게 이용할 수 있어요.',ARRAY['SO3-2-u2-X51']::text[],false,'{"seq":9,"concept":"SO3-2-u2-C18","difficulty":2,"kind":"ox","stem":"통신수단이 발달하면 모든 사람이 똑같이 쉽고 편리하게 이용할 수 있어요.","answer":"X","reason_options":[{"t":"키오스크와 스마트폰 이용에 어려움을 겪는 노인들처럼 변화를 따라가기 힘든 사람도 있기 때문에","correct":true},{"t":"새 통신수단은 처음 보는 사람도 누구나 바로 쓸 수 있기 때문에","mis":"SO3-2-u2-X51"}],"mis":"SO3-2-u2-X51","explanation":["134쪽 기사예요.","어려움을 겪는 사람이 있어요.","그래서 X예요."],"asset":{"type":"passage","lines":["(간추림) 디지털 배움터는 일상생활에 필요한 디지털 교육을 한다.","특히 스마트폰과 키오스크 이용에 어려움을 겪는 노인들을 가르친다.","인터넷 검색, 사진과 동영상 촬영, 은행 거래, 온라인 쇼핑, 키오스크 주문을 배운다.","한 어르신은 이제 혼자서 햄버거도 주문할 수 있다며 자신감을 보였다."],"title":"『사회』 134쪽 신문 기사 「스마트폰과 키오스크를 척척, 디지털 배움터」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L18_basic#10','soc',3,2,'u2','L18','tb_g3_2_soc_u2_L18_basic','lesson_basic','SO3-2-u2-C18',3,'error','auto','133쪽 전화기 그림 세 장을 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO3-2-u2-X40']::text[],false,'{"seq":10,"concept":"SO3-2-u2-C18","difficulty":3,"kind":"error","stem":"133쪽 전화기 그림 세 장을 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 가 — 「유선 전화는 들고 다니며 어디서나 통화할 수 있었어.」","correct":true,"mis_target":"SO3-2-u2-X40"},{"t":"친구 나 — 「초기의 전화기는 교환원이 중간에서 연결해 줬어.」","mis":"SO3-2-u2-X40"},{"t":"친구 다 — 「공중전화를 쓰려면 동전이나 전화 카드가 필요했어.」","mis":"SO3-2-u2-X40"}],"explanation":["유선 전화는 전화선이 있어요.","들고 다니는 것은 휴대 전화예요.","친구 가가 잘못 말했어요."],"asset":{"type":"passage","lines":["초기의 전화기 — 벽에 걸려 있고 숫자 번호판이 없어요. 교환원이 중간에서 연결해 줘요.","유선 전화 — 숫자 번호판이 있고 전화선으로 연결돼요. 전화기가 있는 곳에 가야 통화해요.","유선 전화 — 공중전화는 동전이나 전화 카드가 있어야 해요.","휴대 전화 — 들고 다니며 통화하고, 영상 통화도 해요.","휴대 전화 — 사진 촬영, 온라인 쇼핑, 은행 거래도 할 수 있어요."],"title":"『사회』 133쪽 할 수 있어요 — 전화기의 변화"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L18_challenge#1','soc',3,2,'u2','L18','tb_g3_2_soc_u2_L18_challenge','lesson_challenge','SO3-2-u2-C18',2,'sa','auto','모바일 메신저에서 쓰는 캐릭터 그림을 만들고 디자인하는 직업을 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"SO3-2-u2-C18","difficulty":2,"kind":"sa","stem":"모바일 메신저에서 쓰는 캐릭터 그림을 만들고 디자인하는 직업을 쓰세요.","answer":["이모티콘 캐릭터 디자이너","이모티콘캐릭터디자이너","이모티콘 디자이너"],"explanation":["135쪽 직업이에요.","이모티콘 캐릭터예요.","이모티콘 캐릭터 디자이너예요."],"mis":"SO3-2-u2-X41"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L18_challenge#2','soc',3,2,'u2','L18','tb_g3_2_soc_u2_L18_challenge','lesson_challenge','SO3-2-u2-C18',2,'mc','auto','가족 조사표에서 아버지가 노트북으로 하는 일은 무엇인가요?',ARRAY['SO3-2-u2-X39']::text[],false,'{"seq":2,"concept":"SO3-2-u2-C18","difficulty":2,"kind":"mc","stem":"가족 조사표에서 아버지가 노트북으로 하는 일은 무엇인가요?","options":[{"t":"화상 회의, 정보 검색","correct":true},{"t":"영상 통화, 은행 거래","mis":"SO3-2-u2-X39"},{"t":"온라인 수업, 음악 감상","mis":"SO3-2-u2-X39"},{"t":"길 도우미, 모바일 메신저","mis":"SO3-2-u2-X39"}],"explanation":["아버지 줄이에요.","노트북이에요.","화상 회의와 정보 검색이에요."],"asset":{"type":"passage","lines":["할아버지 — 스마트폰 / 뉴스 검색, 동영상 시청","할머니 — 스마트폰 / 영상 통화, 은행 거래","아버지 — 노트북 / 화상 회의, 정보 검색","어머니 — 스마트폰 / 길 도우미, 모바일 메신저","누나 — 태블릿 컴퓨터 / 온라인 수업, 음악 감상"],"title":"『사회』 131쪽 스스로 활동 — 우리 가족이 즐겨 쓰는 통신수단"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L18_challenge#3','soc',3,2,'u2','L18','tb_g3_2_soc_u2_L18_challenge','lesson_challenge','SO3-2-u2-C18',3,'mc','auto','유선 전화를 쓰던 때의 생활 모습으로 알맞은 것은 무엇인가요?',ARRAY['SO3-2-u2-X40']::text[],false,'{"seq":3,"concept":"SO3-2-u2-C18","difficulty":3,"kind":"mc","stem":"유선 전화를 쓰던 때의 생활 모습으로 알맞은 것은 무엇인가요?","options":[{"t":"통화하려면 전화기가 있는 곳으로 가야 했고, 자리를 비우면 걸려 오는 전화를 받을 수 없었어요","correct":true},{"t":"교환원과 먼저 이야기해야만 통화할 수 있었어요","mis":"SO3-2-u2-X40"},{"t":"걸어가면서 영상 통화를 했어요","mis":"SO3-2-u2-X40"},{"t":"전화기로 사진을 찍고 물건을 샀어요","mis":"SO3-2-u2-X40"}],"explanation":["전화선으로 연결돼요.","전화기가 있는 곳이에요.","자리를 비우면 못 받아요."],"asset":{"type":"passage","lines":["초기의 전화기 — 벽에 걸려 있고 숫자 번호판이 없어요. 교환원이 중간에서 연결해 줘요.","유선 전화 — 숫자 번호판이 있고 전화선으로 연결돼요. 전화기가 있는 곳에 가야 통화해요.","유선 전화 — 공중전화는 동전이나 전화 카드가 있어야 해요.","휴대 전화 — 들고 다니며 통화하고, 영상 통화도 해요.","휴대 전화 — 사진 촬영, 온라인 쇼핑, 은행 거래도 할 수 있어요."],"title":"『사회』 133쪽 할 수 있어요 — 전화기의 변화"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L18_challenge#4','soc',3,2,'u2','L18','tb_g3_2_soc_u2_L18_challenge','lesson_challenge','SO3-2-u2-C18',3,'mc','auto','디지털 배움터 기사를 읽고 알 수 있는 것은 무엇인가요?',ARRAY['SO3-2-u2-X51']::text[],false,'{"seq":4,"concept":"SO3-2-u2-C18","difficulty":3,"kind":"mc","stem":"디지털 배움터 기사를 읽고 알 수 있는 것은 무엇인가요?","options":[{"t":"통신수단이 발달해도 변화를 따라가기 힘든 사람이 있어 배려하고 도와야 해요","correct":true},{"t":"노인들은 통신수단을 배울 필요가 없어요","mis":"SO3-2-u2-X51"},{"t":"키오스크는 누구나 처음부터 쉽게 써요","mis":"SO3-2-u2-X51"},{"t":"디지털 교육은 어린이만 받아요","mis":"SO3-2-u2-X51"}],"explanation":["기사의 노인들이에요.","배워서 자신감이 생겼어요.","배려가 필요해요."],"asset":{"type":"passage","lines":["(간추림) 디지털 배움터는 일상생활에 필요한 디지털 교육을 한다.","특히 스마트폰과 키오스크 이용에 어려움을 겪는 노인들을 가르친다.","인터넷 검색, 사진과 동영상 촬영, 은행 거래, 온라인 쇼핑, 키오스크 주문을 배운다.","한 어르신은 이제 혼자서 햄버거도 주문할 수 있다며 자신감을 보였다."],"title":"『사회』 134쪽 신문 기사 「스마트폰과 키오스크를 척척, 디지털 배움터」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L18_challenge#5','soc',3,2,'u2','L18','tb_g3_2_soc_u2_L18_challenge','lesson_challenge','SO3-2-u2-C18',3,'ox','auto','통신수단이 발달하면서 새로운 시설과 직업이 생겨났어요.',ARRAY['SO3-2-u2-X41']::text[],false,'{"seq":5,"concept":"SO3-2-u2-C18","difficulty":3,"kind":"ox","stem":"통신수단이 발달하면서 새로운 시설과 직업이 생겨났어요.","answer":"O","reason_options":[{"t":"휴대 전화 기지국, 방송국, 우주 센터 같은 시설과 그곳에서 일하는 직업이 생겼기 때문에","correct":true},{"t":"통신수단이 발달해도 시설과 직업은 그대로이기 때문에","mis":"SO3-2-u2-X41"}],"mis":"SO3-2-u2-X41","explanation":["132쪽이에요.","기지국, 방송국이에요.","그래서 O예요."],"asset":{"type":"passage","lines":["휴대 전화 기지국 — 통신 설비 기술자: 휴대 전화나 컴퓨터의 통신을 원활하게 해 주는 기지국을 설치해요.","스마트 시티 상황실 — 폐회로 텔레비전 통합 관제 요원: 사람들의 안전을 지켜 줘요.","방송국 — 촬영 기사, 방송 프로듀서: 영상을 촬영하고 방송 시간에 맞춰 내보내요.","우주 센터 — 인공위성 개발자: 다양한 정보를 수집하는 인공위성을 만들어요.","사라진 직업 — 교환원: 전화 거는 사람과 받는 사람을 연결해 주던 일을 했어요."],"title":"『사회』 132쪽 — 통신수단이 발달하며 생긴 시설과 직업"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L18_challenge#6','soc',3,2,'u2','L18','tb_g3_2_soc_u2_L18_challenge','lesson_challenge','SO3-2-u2-C18',3,'match','auto','통신수단이 발달하며 생긴 시설과 직업을 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"SO3-2-u2-C18","difficulty":3,"kind":"match","stem":"통신수단이 발달하며 생긴 시설과 직업을 알맞게 이으세요.","pairs":[{"l":"휴대 전화 기지국","r":"통신 설비 기술자"},{"l":"스마트 시티 상황실","r":"폐회로 텔레비전 통합 관제 요원"},{"l":"방송국","r":"촬영 기사, 방송 프로듀서"},{"l":"우주 센터","r":"인공위성 개발자"}],"mis":"SO3-2-u2-X41","explanation":["기지국은 통신 설비예요.","상황실은 관제 요원, 방송국은 촬영 기사예요.","우주 센터는 인공위성이에요."],"asset":{"type":"passage","lines":["휴대 전화 기지국 — 통신 설비 기술자: 휴대 전화나 컴퓨터의 통신을 원활하게 해 주는 기지국을 설치해요.","스마트 시티 상황실 — 폐회로 텔레비전 통합 관제 요원: 사람들의 안전을 지켜 줘요.","방송국 — 촬영 기사, 방송 프로듀서: 영상을 촬영하고 방송 시간에 맞춰 내보내요.","우주 센터 — 인공위성 개발자: 다양한 정보를 수집하는 인공위성을 만들어요.","사라진 직업 — 교환원: 전화 거는 사람과 받는 사람을 연결해 주던 일을 했어요."],"title":"『사회』 132쪽 — 통신수단이 발달하며 생긴 시설과 직업"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L18_challenge#7','soc',3,2,'u2','L18','tb_g3_2_soc_u2_L18_challenge','lesson_challenge','SO3-2-u2-C18',3,'error','auto','통신과 관련된 직업을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO3-2-u2-X41']::text[],false,'{"seq":7,"concept":"SO3-2-u2-C18","difficulty":3,"kind":"error","stem":"통신과 관련된 직업을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「교환원은 통신수단이 발달하면서 새로 생긴 직업이야.」","correct":true,"mis_target":"SO3-2-u2-X41"},{"t":"친구 가 — 「전화를 직접 걸게 되면서 교환원은 점차 사라졌어.」","mis":"SO3-2-u2-X41"},{"t":"친구 나 — 「방송국이 생기며 촬영 기사 같은 직업이 생겼어.」","mis":"SO3-2-u2-X41"}],"explanation":["교환원은 초기 전화기 때 직업이에요.","점차 사라졌어요.","친구 다가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L18_challenge#8','soc',3,2,'u2','L18','tb_g3_2_soc_u2_L18_challenge','lesson_challenge','SO3-2-u2-C18',4,'mc','auto','편지(가)와 메신저(나)를 견주어 옛날과 오늘날 소식을 주고받는 방식의 차이를 바르게 쓴 것은 무엇인가요?',ARRAY['SO3-2-u2-X38','SO3-2-u2-X50']::text[],false,'{"seq":8,"concept":"SO3-2-u2-C18","difficulty":4,"kind":"mc","stem":"편지(가)와 메신저(나)를 견주어 옛날과 오늘날 소식을 주고받는 방식의 차이를 바르게 쓴 것은 무엇인가요?","options":[{"t":"편지는 사람 편에 보내 답을 받기까지 오래 걸리고, 메신저는 바로바로 주고받아요","correct":true},{"t":"편지가 메신저보다 더 빨리 답을 받아요","mis":"SO3-2-u2-X38"},{"t":"메신저는 날씨가 나쁘면 보낼 수 없어요","mis":"SO3-2-u2-X38"},{"t":"둘은 소식을 주고받는 방식이 같아요","mis":"SO3-2-u2-X50"}],"explanation":["가는 편지예요.","나는 메신저예요.","빠르기가 달라요."],"asset":{"type":"passage","lines":["가 — (편지 간추림) 사랑하는 아들 보아라. 산으로 글공부하러 간 지 두 달이 넘었구나.","가 — 먹을 것이 부족하거든 사람 편에 알려 다오. 만들어 보내 주마. — 엄마가","나 — (메신저) 「지한아, 밥 먹었니?」 「친구들이랑 떡볶이 사 먹었어요.」","나 — 「오늘 많이 늦니?」 「아니요, 이제 막 버스 탔어요.」"],"title":"과정 중심 평가 — 옛날과 오늘날의 소식 주고받기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L18_challenge#9','soc',3,2,'u2','L18','tb_g3_2_soc_u2_L18_challenge','lesson_challenge','SO3-2-u2-C18',4,'ox','auto','통신수단이 바뀌어도 사람들이 정보를 찾고 의사소통하는 방식은 옛날과 같아요.',ARRAY['SO3-2-u2-X50']::text[],false,'{"seq":9,"concept":"SO3-2-u2-C18","difficulty":4,"kind":"ox","stem":"통신수단이 바뀌어도 사람들이 정보를 찾고 의사소통하는 방식은 옛날과 같아요.","answer":"X","reason_options":[{"t":"옛날에는 직접 가거나 편지를 보냈지만 오늘날에는 언제 어디서나 실시간으로 정보를 찾고 주고받기 때문에","correct":true},{"t":"통신수단은 도구만 바뀔 뿐 소통하는 방식에는 영향이 없기 때문에","mis":"SO3-2-u2-X50"}],"mis":"SO3-2-u2-X50","explanation":["편지와 메신저를 견줘요.","방식이 달라졌어요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L18_challenge#10','soc',3,2,'u2','L18','tb_g3_2_soc_u2_L18_challenge','lesson_challenge','SO3-2-u2-C18',4,'essay','teacher','설날에 미국에 사는 고모네 가족과 함께 세배하고 싶어요. 통신수단을 활용해 함께 세배하는 방법을 쓰고, 통신수단의 발달로 달라진 생활 모습을 한 가지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO3-2-u2-C18","difficulty":4,"kind":"essay","stem":"설날에 미국에 사는 고모네 가족과 함께 세배하고 싶어요. 통신수단을 활용해 함께 세배하는 방법을 쓰고, 통신수단의 발달로 달라진 생활 모습을 한 가지 쓰세요.","answer_guide":{"answer":"예: 노트북이나 스마트폰으로 영상 통화를 하며 화면을 텔레비전에 연결해 크게 보면서 함께 세배해요. 직접 가지 않아도 먼 곳의 사람과 얼굴을 보며 이야기할 수 있게 되었어요.","scoring_points":["통신수단을 활용한 방법을 썼는가","실제로 할 수 있는 방법인가","달라진 생활 모습을 썼는가"]},"explanation":["먼 곳의 가족이에요.","영상 통화를 떠올려요.","달라진 생활을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L19_basic#1','soc',3,2,'u2','L19','tb_g3_2_soc_u2_L19_basic','lesson_basic','SO3-2-u2-C19',1,'mc','auto','『사회』 137쪽에서 일상생활에 문제가 생길 정도로 스마트폰을 지나치게 사용하는 것을 가리키는 말은 무엇인가요?',ARRAY['SO3-2-u2-X43','SO3-2-u2-X39']::text[],false,'{"seq":1,"concept":"SO3-2-u2-C19","difficulty":1,"kind":"mc","stem":"『사회』 137쪽에서 일상생활에 문제가 생길 정도로 스마트폰을 지나치게 사용하는 것을 가리키는 말은 무엇인가요?","options":[{"t":"스마트폰 과의존","correct":true},{"t":"통신 예절","mis":"SO3-2-u2-X43"},{"t":"개인 정보 보호","mis":"SO3-2-u2-X43"},{"t":"모바일 메신저","mis":"SO3-2-u2-X39"}],"explanation":["137쪽 글이에요.","지나치게 써요.","스마트폰 과의존이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L19_basic#2','soc',3,2,'u2','L19','tb_g3_2_soc_u2_L19_basic','lesson_basic','SO3-2-u2-C19',1,'sa','auto','슬기로운 통신 생활 약속에서, 공공장소에서는 휴대 전화 소리를 무엇으로 바꾸기로 했나요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SO3-2-u2-C19","difficulty":1,"kind":"sa","stem":"슬기로운 통신 생활 약속에서, 공공장소에서는 휴대 전화 소리를 무엇으로 바꾸기로 했나요? 두 글자로 쓰세요.","answer":["진동"],"explanation":["138쪽 예시예요.","소리가 나지 않게 해요.","진동이에요."],"mis":"SO3-2-u2-X43"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L19_basic#3','soc',3,2,'u2','L19','tb_g3_2_soc_u2_L19_basic','lesson_basic','SO3-2-u2-C19',1,'mc','auto','통신수단을 올바르게 이용하지 않는 모습은 무엇인가요?',ARRAY['SO3-2-u2-X43']::text[],true,'{"seq":3,"concept":"SO3-2-u2-C19","difficulty":1,"kind":"mc","stem":"통신수단을 올바르게 이용하지 않는 모습은 무엇인가요?","options":[{"t":"인터넷에서 다른 사람에게 상처 주는 댓글을 써요","correct":true},{"t":"작은 소리로 짧게 통화해요","mis":"SO3-2-u2-X43"},{"t":"정한 시간에만 스마트폰을 써요","mis":"SO3-2-u2-X43"},{"t":"허락을 받고 사진을 찍어요","mis":"SO3-2-u2-X43"}],"explanation":["다른 사람의 마음을 생각해요.","상처 주는 말이에요.","댓글이에요."],"variant_rule":{"alt":[{"stem":"통신수단을 올바르게 이용하지 않는 모습은 무엇인가요? (다른 장면)","options":[{"t":"공공장소에서 큰 소리로 통화해요","correct":true},{"t":"공공장소에서 진동으로 바꿔요","mis":"SO3-2-u2-X43"},{"t":"바른 표현으로 글을 써요","mis":"SO3-2-u2-X43"},{"t":"길에서는 스마트폰을 보지 않아요","mis":"SO3-2-u2-X43"}],"explanation":["여러 사람이 있는 곳이에요.","큰 소리는 피해를 줘요.","큰 소리 통화예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L19_basic#4','soc',3,2,'u2','L19','tb_g3_2_soc_u2_L19_basic','lesson_basic','SO3-2-u2-C19',1,'ox','auto','통신수단을 올바르게 이용하지 않으면 몸과 마음의 건강을 해치고 다른 사람에게 피해를 주기도 해요.',ARRAY['SO3-2-u2-X42']::text[],false,'{"seq":4,"concept":"SO3-2-u2-C19","difficulty":1,"kind":"ox","stem":"통신수단을 올바르게 이용하지 않으면 몸과 마음의 건강을 해치고 다른 사람에게 피해를 주기도 해요.","answer":"O","reason_options":[{"t":"『사회』 136쪽 글처럼 나와 다른 사람 모두에게 문제가 생기기 때문에","correct":true},{"t":"잘못 써도 문제는 나 혼자에게만 생기기 때문에","mis":"SO3-2-u2-X42"}],"mis":"SO3-2-u2-X42","explanation":["꼭 기억해요 1이에요.","건강과 피해예요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L19_basic#5','soc',3,2,'u2','L19','tb_g3_2_soc_u2_L19_basic','lesson_basic','SO3-2-u2-C19',2,'match','auto','올바르지 않은 모습과 고칠 약속을 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"SO3-2-u2-C19","difficulty":2,"kind":"match","stem":"올바르지 않은 모습과 고칠 약속을 알맞게 이으세요.","pairs":[{"l":"이어폰을 끼고 동영상을 보며 걷기","r":"길에서는 안전에 유의하며 쓰기"},{"l":"공공장소에서 큰 소리로 통화하기","r":"진동으로 바꾸고 작은 소리로 짧게 통화하기"},{"l":"상처 주는 댓글 쓰기","r":"바른 표현을 쓰기"},{"l":"허락 없이 사진 찍기","r":"다른 사람의 사진을 허락 없이 찍지 않기"}],"mis":"SO3-2-u2-X43","explanation":["길에서는 안전이에요.","통화는 작게, 댓글은 바르게예요.","사진은 허락이에요."],"asset":{"type":"passage","lines":["㉠ 인터넷에서 다른 사람에게 상처 주는 댓글을 써요.","㉡ 다른 사람의 개인 정보를 본인의 허락 없이 알려요.","㉢ 공공장소에서 큰 소리로 통화해요.","㉣ 다른 사람의 모습을 함부로 사진 찍어요.","㉤ 이어폰을 끼고 스마트폰으로 동영상을 보며 길을 걸어요."],"numbered":false,"title":"통신수단을 올바르게 이용하지 않는 모습"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L19_basic#6','soc',3,2,'u2','L19','tb_g3_2_soc_u2_L19_basic','lesson_basic','SO3-2-u2-C19',2,'mc','auto','신문 기사에서 청소년은 100명 가운데 몇 명이 스마트폰 과의존 위험군이라고 했나요?',ARRAY['SO3-2-u2-X42']::text[],false,'{"seq":6,"concept":"SO3-2-u2-C19","difficulty":2,"kind":"mc","stem":"신문 기사에서 청소년은 100명 가운데 몇 명이 스마트폰 과의존 위험군이라고 했나요?","options":[{"t":"40명","correct":true},{"t":"24명","mis":"SO3-2-u2-X42"},{"t":"4명","mis":"SO3-2-u2-X42"},{"t":"100명","mis":"SO3-2-u2-X42"}],"explanation":["둘째 줄이에요.","청소년이에요.","40명이에요."],"asset":{"type":"passage","lines":["(간추림) 우리나라 스마트폰 이용자 100명 중 24명이 스마트폰 과의존 위험군인 것으로 나타났다.","특히 청소년은 100명 중 40명이 위험군이며 그 비율이 계속 높아지고 있다.","「배터리가 부족해지면 초조하다」, 「주기적으로 확인하지 못하면 불안하다」는 응답이 많았다."],"title":"『사회』 137쪽 신문 기사 — 스마트폰 과의존 실태 조사"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L19_basic#7','soc',3,2,'u2','L19','tb_g3_2_soc_u2_L19_basic','lesson_basic','SO3-2-u2-C19',2,'mc','auto','스마트폰 사용 확인표에서 「예」가 3~4개라면 결과는 무엇인가요?',ARRAY['SO3-2-u2-X42']::text[],false,'{"seq":7,"concept":"SO3-2-u2-C19","difficulty":2,"kind":"mc","stem":"스마트폰 사용 확인표에서 「예」가 3~4개라면 결과는 무엇인가요?","options":[{"t":"주의가 필요해요","correct":true},{"t":"괜찮아요","mis":"SO3-2-u2-X42"},{"t":"전문적인 검사와 치료가 필요해요","mis":"SO3-2-u2-X42"}],"explanation":["기준을 봐요.","3~4개예요.","주의가 필요해요."],"asset":{"type":"passage","lines":["1 스마트폰 이용 시간을 조절하기 어렵다.","2 스마트폰이 옆에 있으면 다른 일에 집중하기 어렵다.","3 스마트폰 이용 때문에 건강에 문제가 생긴 적이 있다.","4 스마트폰 때문에 공부에 어려움이 있다.","「예」 0~2개: 괜찮아요. / 3~4개: 주의가 필요해요.","「예」 5~8개: 전문적인 검사와 치료가 필요해요."],"numbered":false,"title":"『사회』 137쪽 — 스마트폰을 사용하는 나의 모습 확인하기(8문항 가운데 일부와 기준)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L19_basic#8','soc',3,2,'u2','L19','tb_g3_2_soc_u2_L19_basic','lesson_basic','SO3-2-u2-C19',2,'blank','auto','「학교나 가정에서 지켜야 하는 예절이 있듯이 통신수단을 이용할 때도 지켜야 하는 (    )이 있습니다.」 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SO3-2-u2-X43']::text[],false,'{"seq":8,"concept":"SO3-2-u2-C19","difficulty":2,"kind":"blank","stem":"「학교나 가정에서 지켜야 하는 예절이 있듯이 통신수단을 이용할 때도 지켜야 하는 (    )이 있습니다.」 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"예절","correct":true},{"t":"속도","mis":"SO3-2-u2-X43"},{"t":"요금","mis":"SO3-2-u2-X43"},{"t":"순서","mis":"SO3-2-u2-X43"}],"explanation":["138쪽 글이에요.","통신 예절이에요.","예절이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L19_basic#9','soc',3,2,'u2','L19','tb_g3_2_soc_u2_L19_basic','lesson_basic','SO3-2-u2-C19',2,'ox','auto','확인되지 않은 정보도 재미있으면 인터넷에 올려도 괜찮아요.',ARRAY['SO3-2-u2-X42']::text[],false,'{"seq":9,"concept":"SO3-2-u2-C19","difficulty":2,"kind":"ox","stem":"확인되지 않은 정보도 재미있으면 인터넷에 올려도 괜찮아요.","answer":"X","reason_options":[{"t":"확인되지 않은 정보는 다른 사람에게 피해를 줄 수 있어 올리지 않아야 하기 때문에","correct":true},{"t":"인터넷에 올린 글은 아무에게도 영향을 주지 않기 때문에","mis":"SO3-2-u2-X42"}],"mis":"SO3-2-u2-X42","explanation":["138쪽 약속 예시예요.","피해를 줄 수 있어요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L19_basic#10','soc',3,2,'u2','L19','tb_g3_2_soc_u2_L19_basic','lesson_basic','SO3-2-u2-C19',3,'error','auto','슬기로운 통신 생활 약속을 쓰고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO3-2-u2-X43']::text[],false,'{"seq":10,"concept":"SO3-2-u2-C19","difficulty":3,"kind":"error","stem":"슬기로운 통신 생활 약속을 쓰고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 가 — 「모르는 사람이 물어보면 내 이름과 주소를 바로 알려 줄게.」","correct":true,"mis_target":"SO3-2-u2-X43"},{"t":"친구 나 — 「개인 정보가 새어 나가지 않도록 조심할게.」","mis":"SO3-2-u2-X43"},{"t":"친구 다 — 「학교에서는 꼭 필요한 시간에만 학습용으로 쓸게.」","mis":"SO3-2-u2-X43"}],"explanation":["개인 정보예요.","보안에 유의해요.","친구 가가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L19_challenge#1','soc',3,2,'u2','L19','tb_g3_2_soc_u2_L19_challenge','lesson_challenge','SO3-2-u2-C19',2,'sa','auto','스마트폰 사용에 관한 검사를 하고 상담을 받을 수 있는 곳으로 『사회』 137쪽에 소개된 곳을 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"SO3-2-u2-C19","difficulty":2,"kind":"sa","stem":"스마트폰 사용에 관한 검사를 하고 상담을 받을 수 있는 곳으로 『사회』 137쪽에 소개된 곳을 쓰세요.","answer":["스마트 쉼 센터","스마트쉼센터"],"explanation":["137쪽 누리집이에요.","쉼 센터예요.","스마트 쉼 센터예요."],"mis":"SO3-2-u2-X42"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
