INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L19_challenge#4','soc',3,2,'u2','L19','tb_g3_2_soc_u2_L19_challenge','lesson_challenge','SO3-2-u2-C19',3,'mc','auto','스마트폰 사용 확인표에서 「예」가 6개라면 결과는 무엇인가요?',ARRAY['SO3-2-u2-X42']::text[],false,'{"seq":4,"concept":"SO3-2-u2-C19","difficulty":3,"kind":"mc","stem":"스마트폰 사용 확인표에서 「예」가 6개라면 결과는 무엇인가요?","options":[{"t":"전문적인 검사와 치료가 필요해요","correct":true},{"t":"괜찮아요","mis":"SO3-2-u2-X42"},{"t":"주의가 필요해요","mis":"SO3-2-u2-X42"}],"explanation":["5~8개 칸이에요.","6개가 들어가요.","전문적인 검사와 치료예요."],"asset":{"type":"passage","lines":["1 스마트폰 이용 시간을 조절하기 어렵다.","2 스마트폰이 옆에 있으면 다른 일에 집중하기 어렵다.","3 스마트폰 이용 때문에 건강에 문제가 생긴 적이 있다.","4 스마트폰 때문에 공부에 어려움이 있다.","「예」 0~2개: 괜찮아요. / 3~4개: 주의가 필요해요.","「예」 5~8개: 전문적인 검사와 치료가 필요해요."],"numbered":false,"title":"『사회』 137쪽 — 스마트폰을 사용하는 나의 모습 확인하기(8문항 가운데 일부와 기준)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L19_challenge#5','soc',3,2,'u2','L19','tb_g3_2_soc_u2_L19_challenge','lesson_challenge','SO3-2-u2-C19',3,'ox','auto','연락이 오지 않았는데 스마트폰 진동을 느낀 적이 있다면 스마트폰을 지나치게 쓰고 있지 않은지 살펴볼 필요가 있어요.',ARRAY['SO3-2-u2-X42']::text[],false,'{"seq":5,"concept":"SO3-2-u2-C19","difficulty":3,"kind":"ox","stem":"연락이 오지 않았는데 스마트폰 진동을 느낀 적이 있다면 스마트폰을 지나치게 쓰고 있지 않은지 살펴볼 필요가 있어요.","answer":"O","reason_options":[{"t":"스마트폰을 늘 신경 쓰고 있다는 신호일 수 있기 때문에","correct":true},{"t":"스마트폰을 오래 쓰는 것은 아무 문제가 없기 때문에","mis":"SO3-2-u2-X42"}],"mis":"SO3-2-u2-X42","explanation":["137쪽 경험 나누기예요.","늘 신경 쓰고 있어요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L19_challenge#6','soc',3,2,'u2','L19','tb_g3_2_soc_u2_L19_challenge','lesson_challenge','SO3-2-u2-C19',3,'match','auto','슬기로운 통신 생활 약속과 그 약속을 지키는 까닭을 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"SO3-2-u2-C19","difficulty":3,"kind":"match","stem":"슬기로운 통신 생활 약속과 그 약속을 지키는 까닭을 알맞게 이으세요.","pairs":[{"l":"정한 시간에만 쓰기","r":"몸과 마음의 건강을 지키려고"},{"l":"공공장소에서 작은 소리로 짧게 통화하기","r":"다른 사람에게 피해를 주지 않으려고"},{"l":"길에서 스마트폰 보지 않기","r":"교통사고 같은 위험을 막으려고"}],"mis":"SO3-2-u2-X42","explanation":["시간은 건강이에요.","통화는 다른 사람이에요.","길에서는 안전이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L19_challenge#7','soc',3,2,'u2','L19','tb_g3_2_soc_u2_L19_challenge','lesson_challenge','SO3-2-u2-C19',3,'error','auto','통신수단을 쓰며 겪은 문제점을 이야기했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO3-2-u2-X42']::text[],false,'{"seq":7,"concept":"SO3-2-u2-C19","difficulty":3,"kind":"error","stem":"통신수단을 쓰며 겪은 문제점을 이야기했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 나 — 「통신수단은 편리하기만 해서 문제점은 하나도 없어.」","correct":true,"mis_target":"SO3-2-u2-X42"},{"t":"친구 가 — 「동영상을 오래 봐서 눈이 침침했어.」","mis":"SO3-2-u2-X42"},{"t":"친구 다 — 「복도에서 큰 소리로 통화하는 사람 때문에 공부에 방해받았어.」","mis":"SO3-2-u2-X42"}],"explanation":["136쪽 스스로 활동이에요.","문제점도 있어요.","친구 나가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L19_challenge#8','soc',3,2,'u2','L19','tb_g3_2_soc_u2_L19_challenge','lesson_challenge','SO3-2-u2-C19',4,'mc','auto','우리가 정한 슬기로운 통신 생활 약속을 잘 실천하는 방법으로 알맞은 것은 무엇인가요?',ARRAY['SO3-2-u2-X43','SO3-2-u2-X42']::text[],false,'{"seq":8,"concept":"SO3-2-u2-C19","difficulty":4,"kind":"mc","stem":"우리가 정한 슬기로운 통신 생활 약속을 잘 실천하는 방법으로 알맞은 것은 무엇인가요?","options":[{"t":"잘 보이는 곳에 약속을 붙여 자주 확인하고, 시간을 정해 실천했는지 돌아봐요","correct":true},{"t":"약속을 정하고 바로 잊어요","mis":"SO3-2-u2-X43"},{"t":"친구에게만 지키라고 해요","mis":"SO3-2-u2-X42"},{"t":"한 번 지키면 다시 확인하지 않아요","mis":"SO3-2-u2-X43"}],"explanation":["약속은 실천이 중요해요.","자주 확인해요.","돌아보며 반성해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L19_challenge#9','soc',3,2,'u2','L19','tb_g3_2_soc_u2_L19_challenge','lesson_challenge','SO3-2-u2-C19',4,'ox','auto','통신수단의 발달이 우리 생활에 좋은 영향만 주는 것은 아니에요.',ARRAY['SO3-2-u2-X42']::text[],false,'{"seq":9,"concept":"SO3-2-u2-C19","difficulty":4,"kind":"ox","stem":"통신수단의 발달이 우리 생활에 좋은 영향만 주는 것은 아니에요.","answer":"O","reason_options":[{"t":"편리해졌지만 과의존, 상처 주는 댓글처럼 몸과 마음의 건강을 해치거나 피해를 주는 문제도 생기기 때문에","correct":true},{"t":"통신수단이 발달하면 생활은 좋아지기만 하기 때문에","mis":"SO3-2-u2-X42"}],"mis":"SO3-2-u2-X42","explanation":["136쪽 말풍선이에요.","문제점도 있어요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L19_challenge#10','soc',3,2,'u2','L19','tb_g3_2_soc_u2_L19_challenge','lesson_challenge','SO3-2-u2-C19',4,'essay','teacher','내가 통신수단을 쓰면서 겪은 문제점을 쓰고, 그 문제를 해결하는 방법과 슬기로운 통신 생활 약속을 두 가지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO3-2-u2-C19","difficulty":4,"kind":"essay","stem":"내가 통신수단을 쓰면서 겪은 문제점을 쓰고, 그 문제를 해결하는 방법과 슬기로운 통신 생활 약속을 두 가지 쓰세요.","answer_guide":{"answer":"예: 침대에 누워 스마트폰을 오래 써서 눈과 목이 아팠어요. 누워서 쓰지 않고 시간을 정해 써요. 약속 — 1. 스마트폰은 하루에 정한 시간에만 쓰겠다. 2. 길에서 걸어 다니면서 휴대 전화를 보지 않겠다.","scoring_points":["문제점을 썼는가","해결 방법을 썼는가","약속을 두 가지 썼는가"]},"explanation":["경험을 떠올려요.","해결 방법이에요.","약속을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L20_basic#1','soc',3,2,'u2','L20','tb_g3_2_soc_u2_L20_basic','lesson_basic','SO3-2-u2-C20',1,'ox','auto','비밀번호 단서 2처럼 오늘날 사람들은 주로 서찰, 방, 파발 등의 통신수단을 사용해요.',ARRAY['SO3-2-u2-X44']::text[],false,'{"seq":1,"concept":"SO3-2-u2-C20","difficulty":1,"kind":"ox","stem":"비밀번호 단서 2처럼 오늘날 사람들은 주로 서찰, 방, 파발 등의 통신수단을 사용해요.","answer":"X","reason_options":[{"t":"오늘날에는 주로 휴대 전화, 컴퓨터, 텔레비전 같은 통신수단을 쓰기 때문에","correct":true},{"t":"옛날 통신수단과 오늘날 통신수단은 같기 때문에","mis":"SO3-2-u2-X44"}],"mis":"SO3-2-u2-X44","explanation":["단서 2예요.","서찰, 방, 파발은 옛날 것이에요.","그래서 X예요."],"asset":{"type":"passage","lines":["단서 1 — 옛날 통신수단은 자세한 정보를 전달하기 어렵고, 소식을 전하는 데 시간이 오래 걸렸습니다.","단서 2 — 오늘날 사람들은 주로 서찰, 방, 파발 등의 통신수단을 사용합니다.","단서 3 — 통신수단이 발달하면서 오늘날에는 한 번에 많은 정보를 실시간으로 주고받을 수 있습니다.","단서 4 — 통신수단의 변화로 새로운 시설과 직업이 생겨났습니다.","단서 5 — 몸과 마음의 건강을 위해 통신수단을 안전하고 올바르게 사용해야 합니다.","규칙 — 옳은 설명의 번호를 규칙에 따라 비밀번호 네 칸에 써요."],"numbered":false,"title":"『사회』 141쪽 재미있게 확인해요 — 휴대 전화 비밀번호의 단서"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L20_basic#2','soc',3,2,'u2','L20','tb_g3_2_soc_u2_L20_basic','lesson_basic','SO3-2-u2-C20',1,'mc','auto','그림일기 예시 「뽀롱이와의 영상 통화」에서 미래의 통신수단이 해 준 일은 무엇인가요?',ARRAY['SO3-2-u2-X44']::text[],false,'{"seq":2,"concept":"SO3-2-u2-C20","difficulty":1,"kind":"mc","stem":"그림일기 예시 「뽀롱이와의 영상 통화」에서 미래의 통신수단이 해 준 일은 무엇인가요?","options":[{"t":"강아지가 짖는 소리를 화면에 우리말로 보여 줬어요","correct":true},{"t":"강아지를 해외로 데려다줬어요","mis":"SO3-2-u2-X44"},{"t":"비행기표를 사 줬어요","mis":"SO3-2-u2-X44"},{"t":"강아지 먹이를 만들어 줬어요","mis":"SO3-2-u2-X44"}],"explanation":["예시를 읽어요.","짖는 소리예요.","우리말로 보여 줬어요."],"asset":{"type":"passage","lines":["1 통신수단을 이용하면서 불편했거나 아쉬웠던 경험을 떠올려요.","2 이를 해결할 수 있는 미래의 통신수단을 생각해요.","3 미래의 통신수단으로 편리해질 모습을 상상하여 일기를 써요.","4 일기의 내용을 잘 나타내는 장면을 그림으로 그려요.","예시 「뽀롱이와의 영상 통화」 — 강아지가 짖는 소리가 화면에 우리말로 나타났어요.","예시 「조카와의 영상 전화」 — 미국에 사는 조카에게 영상 전화로 바로 한과를 보냈어요."],"numbered":false,"title":"『사회』 139쪽 — 미래 그림일기 쓰기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L20_basic#3','soc',3,2,'u2','L20','tb_g3_2_soc_u2_L20_basic','lesson_basic','SO3-2-u2-C20',1,'sa','auto','비밀번호 단서 1~5 가운데 틀린 설명의 번호를 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"SO3-2-u2-C20","difficulty":1,"kind":"sa","stem":"비밀번호 단서 1~5 가운데 틀린 설명의 번호를 쓰세요.","answer":["2","2번"],"explanation":["하나씩 O, X를 해요.","서찰, 방, 파발은 옛날 것이에요.","2번이에요."],"asset":{"type":"passage","lines":["단서 1 — 옛날 통신수단은 자세한 정보를 전달하기 어렵고, 소식을 전하는 데 시간이 오래 걸렸습니다.","단서 2 — 오늘날 사람들은 주로 서찰, 방, 파발 등의 통신수단을 사용합니다.","단서 3 — 통신수단이 발달하면서 오늘날에는 한 번에 많은 정보를 실시간으로 주고받을 수 있습니다.","단서 4 — 통신수단의 변화로 새로운 시설과 직업이 생겨났습니다.","단서 5 — 몸과 마음의 건강을 위해 통신수단을 안전하고 올바르게 사용해야 합니다.","규칙 — 옳은 설명의 번호를 규칙에 따라 비밀번호 네 칸에 써요."],"numbered":false,"title":"『사회』 141쪽 재미있게 확인해요 — 휴대 전화 비밀번호의 단서"},"mis":"SO3-2-u2-X44"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L20_basic#4','soc',3,2,'u2','L20','tb_g3_2_soc_u2_L20_basic','lesson_basic','SO3-2-u2-C20',1,'mc','auto','비밀번호 단서 가운데 옳은 설명은 무엇인가요?',ARRAY['SO3-2-u2-X44','SO3-2-u2-X38','SO3-2-u2-X42']::text[],true,'{"seq":4,"concept":"SO3-2-u2-C20","difficulty":1,"kind":"mc","stem":"비밀번호 단서 가운데 옳은 설명은 무엇인가요?","options":[{"t":"통신수단의 변화로 새로운 시설과 직업이 생겨났어요","correct":true},{"t":"오늘날 사람들은 주로 서찰, 방, 파발을 사용해요","mis":"SO3-2-u2-X44"},{"t":"옛날 통신수단으로 자세한 정보를 빠르게 전했어요","mis":"SO3-2-u2-X38"},{"t":"통신수단은 아무렇게나 사용해도 돼요","mis":"SO3-2-u2-X42"}],"explanation":["단서 4예요.","시설과 직업이 생겼어요.","옳은 설명이에요."],"variant_rule":{"alt":[{"stem":"비밀번호 단서 가운데 옳은 설명은 무엇인가요? (다른 보기)","options":[{"t":"몸과 마음의 건강을 위해 통신수단을 안전하고 올바르게 사용해야 해요","correct":true},{"t":"오늘날 통신수단으로는 많은 정보를 주고받기 어려워요","mis":"SO3-2-u2-X38"},{"t":"옛날 통신수단은 날씨의 영향을 받지 않았어요","mis":"SO3-2-u2-X38"},{"t":"통신수단이 변해도 새 직업은 생기지 않았어요","mis":"SO3-2-u2-X41"}],"explanation":["단서 5예요.","건강을 위해서예요.","옳은 설명이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L20_basic#5','soc',3,2,'u2','L20','tb_g3_2_soc_u2_L20_basic','lesson_basic','SO3-2-u2-C20',2,'match','auto','통신수단과 그 특징을 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"SO3-2-u2-C20","difficulty":2,"kind":"match","stem":"통신수단과 그 특징을 알맞게 이으세요.","pairs":[{"l":"서찰","r":"사람이 직접 가서 전해 시간이 오래 걸렸어요"},{"l":"봉수","r":"안개가 짙으면 보이지 않아 날씨의 영향을 받았어요"},{"l":"휴대 전화","r":"하나로 통화, 사진, 쇼핑을 할 수 있어요"},{"l":"모바일 메신저","r":"여러 사람과 동시에 실시간으로 대화해요"}],"mis":"SO3-2-u2-X38","explanation":["서찰과 봉수는 옛날이에요.","휴대 전화와 메신저는 오늘날이에요.","특징이 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L20_basic#6','soc',3,2,'u2','L20','tb_g3_2_soc_u2_L20_basic','lesson_basic','SO3-2-u2-C20',2,'mc','auto','나만의 이모티콘 만들기에서 둘째 단계는 무엇인가요?',ARRAY['SO3-2-u2-X43']::text[],false,'{"seq":6,"concept":"SO3-2-u2-C20","difficulty":2,"kind":"mc","stem":"나만의 이모티콘 만들기에서 둘째 단계는 무엇인가요?","options":[{"t":"생각한 말을 사람, 동물, 물건, 글자, 숫자 등 어떤 모습으로 나타낼지 정해요","correct":true},{"t":"스케치한 뒤 색을 칠해 완성해요","mis":"SO3-2-u2-X43"},{"t":"대화 속 상황에 들어갈 말을 생각해요","mis":"SO3-2-u2-X43"},{"t":"만든 이모티콘을 모르는 사람에게 보내요","mis":"SO3-2-u2-X43"}],"explanation":["140쪽 순서예요.","말을 먼저 생각해요.","그다음 모습을 정해요."],"asset":{"type":"passage","lines":["1 대화 속 상황에 들어갈 알맞은 말을 생각해요.","2 생각한 말을 사람, 동물, 물건, 글자, 숫자 등 어떤 모습으로 나타낼지 정해요.","3 생각한 모습으로 스케치한 뒤 어울리는 색을 칠해 완성해요."],"numbered":false,"title":"『사회』 140쪽 — 나만의 이모티콘 만들기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L20_basic#7','soc',3,2,'u2','L20','tb_g3_2_soc_u2_L20_basic','lesson_basic','SO3-2-u2-C20',2,'mc','auto','미래 그림일기를 쓸 때 미래의 통신수단을 생각하기 전에 먼저 떠올리는 것은 무엇인가요?',ARRAY['SO3-2-u2-X44']::text[],false,'{"seq":7,"concept":"SO3-2-u2-C20","difficulty":2,"kind":"mc","stem":"미래 그림일기를 쓸 때 미래의 통신수단을 생각하기 전에 먼저 떠올리는 것은 무엇인가요?","options":[{"t":"통신수단을 이용하면서 불편했거나 아쉬웠던 경험","correct":true},{"t":"미래 통신수단의 이름","mis":"SO3-2-u2-X44"},{"t":"그림에 칠할 색깔","mis":"SO3-2-u2-X44"},{"t":"친구가 쓴 일기","mis":"SO3-2-u2-X44"}],"explanation":["139쪽 순서 1이에요.","불편했던 경험이에요.","그것을 해결해요."],"asset":{"type":"passage","lines":["1 통신수단을 이용하면서 불편했거나 아쉬웠던 경험을 떠올려요.","2 이를 해결할 수 있는 미래의 통신수단을 생각해요.","3 미래의 통신수단으로 편리해질 모습을 상상하여 일기를 써요.","4 일기의 내용을 잘 나타내는 장면을 그림으로 그려요.","예시 「뽀롱이와의 영상 통화」 — 강아지가 짖는 소리가 화면에 우리말로 나타났어요.","예시 「조카와의 영상 전화」 — 미국에 사는 조카에게 영상 전화로 바로 한과를 보냈어요."],"numbered":false,"title":"『사회』 139쪽 — 미래 그림일기 쓰기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L20_basic#8','soc',3,2,'u2','L20','tb_g3_2_soc_u2_L20_basic','lesson_basic','SO3-2-u2-C20',2,'blank','auto','「몸과 마음의 건강을 위해 통신수단을 안전하고 (    ) 사용해야 합니다.」 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SO3-2-u2-X42']::text[],false,'{"seq":8,"concept":"SO3-2-u2-C20","difficulty":2,"kind":"blank","stem":"「몸과 마음의 건강을 위해 통신수단을 안전하고 (    ) 사용해야 합니다.」 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"올바르게","correct":true},{"t":"오래","mis":"SO3-2-u2-X42"},{"t":"몰래","mis":"SO3-2-u2-X42"},{"t":"빠르게만","mis":"SO3-2-u2-X42"}],"explanation":["단서 5예요.","안전하고 바르게예요.","올바르게예요."],"asset":{"type":"passage","lines":["단서 1 — 옛날 통신수단은 자세한 정보를 전달하기 어렵고, 소식을 전하는 데 시간이 오래 걸렸습니다.","단서 2 — 오늘날 사람들은 주로 서찰, 방, 파발 등의 통신수단을 사용합니다.","단서 3 — 통신수단이 발달하면서 오늘날에는 한 번에 많은 정보를 실시간으로 주고받을 수 있습니다.","단서 4 — 통신수단의 변화로 새로운 시설과 직업이 생겨났습니다.","단서 5 — 몸과 마음의 건강을 위해 통신수단을 안전하고 올바르게 사용해야 합니다.","규칙 — 옳은 설명의 번호를 규칙에 따라 비밀번호 네 칸에 써요."],"numbered":false,"title":"『사회』 141쪽 재미있게 확인해요 — 휴대 전화 비밀번호의 단서"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L20_basic#9','soc',3,2,'u2','L20','tb_g3_2_soc_u2_L20_basic','lesson_basic','SO3-2-u2-C20',2,'ox','auto','미래의 통신수단은 오늘날 불편하거나 아쉬웠던 점을 해결하는 모습으로 상상할 수 있어요.',ARRAY['SO3-2-u2-X44']::text[],false,'{"seq":9,"concept":"SO3-2-u2-C20","difficulty":2,"kind":"ox","stem":"미래의 통신수단은 오늘날 불편하거나 아쉬웠던 점을 해결하는 모습으로 상상할 수 있어요.","answer":"O","reason_options":[{"t":"「조카와의 영상 전화」처럼 오늘날의 아쉬움을 해결하는 기능을 떠올려 상상하기 때문에","correct":true},{"t":"미래의 통신수단은 오늘날과 똑같을 것이기 때문에","mis":"SO3-2-u2-X44"}],"mis":"SO3-2-u2-X44","explanation":["139쪽 예시예요.","아쉬움을 해결해요.","그래서 O예요."],"asset":{"type":"passage","lines":["1 통신수단을 이용하면서 불편했거나 아쉬웠던 경험을 떠올려요.","2 이를 해결할 수 있는 미래의 통신수단을 생각해요.","3 미래의 통신수단으로 편리해질 모습을 상상하여 일기를 써요.","4 일기의 내용을 잘 나타내는 장면을 그림으로 그려요.","예시 「뽀롱이와의 영상 통화」 — 강아지가 짖는 소리가 화면에 우리말로 나타났어요.","예시 「조카와의 영상 전화」 — 미국에 사는 조카에게 영상 전화로 바로 한과를 보냈어요."],"numbered":false,"title":"『사회』 139쪽 — 미래 그림일기 쓰기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L20_basic#10','soc',3,2,'u2','L20','tb_g3_2_soc_u2_L20_basic','lesson_basic','SO3-2-u2-C20',3,'error','auto','「통신수단의 변화로 달라진 생활 모습」 주제를 정리하며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO3-2-u2-X38','SO3-2-u2-X41']::text[],false,'{"seq":10,"concept":"SO3-2-u2-C20","difficulty":3,"kind":"error","stem":"「통신수단의 변화로 달라진 생활 모습」 주제를 정리하며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 나 — 「옛날 통신수단은 날씨와 관계없이 자세한 소식을 전했어.」","correct":true,"mis_target":"SO3-2-u2-X38"},{"t":"친구 가 — 「오늘날에는 하나의 통신수단으로 여러 통신 방법을 이용해.」","mis":"SO3-2-u2-X38"},{"t":"친구 다 — 「통신수단의 변화로 새로운 직업이 생겼어.」","mis":"SO3-2-u2-X41"}],"explanation":["봉수는 날씨의 영향을 받았어요.","자세히 전하기 어려웠어요.","친구 나가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L20_challenge#1','soc',3,2,'u2','L20','tb_g3_2_soc_u2_L20_challenge','lesson_challenge','SO3-2-u2-C20',2,'sa','auto','모바일 메신저에서 글 대신 간단한 그림으로 생각이나 감정을 나타내는 것을 무엇이라고 하나요?','{}'::text[],false,'{"seq":1,"concept":"SO3-2-u2-C20","difficulty":2,"kind":"sa","stem":"모바일 메신저에서 글 대신 간단한 그림으로 생각이나 감정을 나타내는 것을 무엇이라고 하나요?","answer":["이모티콘"],"explanation":["140쪽 활동이에요.","이◯◯◯이에요.","이모티콘이에요."],"mis":"SO3-2-u2-X39"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L20_challenge#2','soc',3,2,'u2','L20','tb_g3_2_soc_u2_L20_challenge','lesson_challenge','SO3-2-u2-C20',2,'mc','auto','친구가 생일이었다는 대화에서 「자, 받아!」와 함께 보낼 이모티콘의 말로 가장 알맞은 것은 무엇인가요?',ARRAY['SO3-2-u2-X43']::text[],false,'{"seq":2,"concept":"SO3-2-u2-C20","difficulty":2,"kind":"mc","stem":"친구가 생일이었다는 대화에서 「자, 받아!」와 함께 보낼 이모티콘의 말로 가장 알맞은 것은 무엇인가요?","options":[{"t":"생일 축하해!","correct":true},{"t":"잘 자!","mis":"SO3-2-u2-X43"},{"t":"조심해!","mis":"SO3-2-u2-X43"},{"t":"배고파!","mis":"SO3-2-u2-X43"}],"explanation":["대화 속 상황이에요.","생일이었어요.","축하하는 말이에요."],"asset":{"type":"speech","turns":[{"who":"친구 1","text":"너 어제 생일이었어?"},{"who":"친구 2","text":"응, 미리 얘기하지 못해서 미안해. 가족끼리 생일잔치 했거든."},{"who":"친구 1","text":"그렇구나. 자, 받아! (이모티콘)"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L20_challenge#3','soc',3,2,'u2','L20','tb_g3_2_soc_u2_L20_challenge','lesson_challenge','SO3-2-u2-C20',3,'mc','auto','단서에서 옳은 설명의 번호는 1, 3, 4, 5예요. 「제일 작은 숫자는 두 번째 칸, 제일 큰 숫자는 네 번째 칸, 남은 두 숫자 중 작은 숫자는 세 번째 칸, 나머지는 첫 번째 칸」에 쓰면 비밀번호는 무엇인가요?',ARRAY['SO3-2-u2-X44']::text[],false,'{"seq":3,"concept":"SO3-2-u2-C20","difficulty":3,"kind":"mc","stem":"단서에서 옳은 설명의 번호는 1, 3, 4, 5예요. 「제일 작은 숫자는 두 번째 칸, 제일 큰 숫자는 네 번째 칸, 남은 두 숫자 중 작은 숫자는 세 번째 칸, 나머지는 첫 번째 칸」에 쓰면 비밀번호는 무엇인가요?","options":[{"t":"4135","correct":true},{"t":"1345","mis":"SO3-2-u2-X44"},{"t":"2135","mis":"SO3-2-u2-X44"},{"t":"5431","mis":"SO3-2-u2-X44"}],"explanation":["1은 둘째, 5는 넷째 칸이에요.","3은 셋째, 4는 첫째 칸이에요.","4135예요."],"asset":{"type":"passage","lines":["단서 1 — 옛날 통신수단은 자세한 정보를 전달하기 어렵고, 소식을 전하는 데 시간이 오래 걸렸습니다.","단서 2 — 오늘날 사람들은 주로 서찰, 방, 파발 등의 통신수단을 사용합니다.","단서 3 — 통신수단이 발달하면서 오늘날에는 한 번에 많은 정보를 실시간으로 주고받을 수 있습니다.","단서 4 — 통신수단의 변화로 새로운 시설과 직업이 생겨났습니다.","단서 5 — 몸과 마음의 건강을 위해 통신수단을 안전하고 올바르게 사용해야 합니다.","규칙 — 옳은 설명의 번호를 규칙에 따라 비밀번호 네 칸에 써요."],"numbered":false,"title":"『사회』 141쪽 재미있게 확인해요 — 휴대 전화 비밀번호의 단서"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L20_challenge#4','soc',3,2,'u2','L20','tb_g3_2_soc_u2_L20_challenge','lesson_challenge','SO3-2-u2-C20',3,'mc','auto','그림일기 예시 「조카와의 영상 전화」에서 상상한 미래 통신수단의 기능은 무엇인가요?',ARRAY['SO3-2-u2-X44']::text[],false,'{"seq":4,"concept":"SO3-2-u2-C20","difficulty":3,"kind":"mc","stem":"그림일기 예시 「조카와의 영상 전화」에서 상상한 미래 통신수단의 기능은 무엇인가요?","options":[{"t":"영상 전화로 바로 한과를 보내 줬어요","correct":true},{"t":"조카를 한국으로 데려왔어요","mis":"SO3-2-u2-X44"},{"t":"편지를 대신 써 줬어요","mis":"SO3-2-u2-X44"},{"t":"비행기를 대신 운전했어요","mis":"SO3-2-u2-X44"}],"explanation":["예시를 읽어요.","미국의 조카예요.","바로 한과를 보냈어요."],"asset":{"type":"passage","lines":["1 통신수단을 이용하면서 불편했거나 아쉬웠던 경험을 떠올려요.","2 이를 해결할 수 있는 미래의 통신수단을 생각해요.","3 미래의 통신수단으로 편리해질 모습을 상상하여 일기를 써요.","4 일기의 내용을 잘 나타내는 장면을 그림으로 그려요.","예시 「뽀롱이와의 영상 통화」 — 강아지가 짖는 소리가 화면에 우리말로 나타났어요.","예시 「조카와의 영상 전화」 — 미국에 사는 조카에게 영상 전화로 바로 한과를 보냈어요."],"numbered":false,"title":"『사회』 139쪽 — 미래 그림일기 쓰기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L20_challenge#5','soc',3,2,'u2','L20','tb_g3_2_soc_u2_L20_challenge','lesson_challenge','SO3-2-u2-C20',3,'ox','auto','옛날 통신수단은 자세한 정보를 전달하기 어렵고, 소식을 전하는 데 시간이 오래 걸렸어요.',ARRAY['SO3-2-u2-X38']::text[],false,'{"seq":5,"concept":"SO3-2-u2-C20","difficulty":3,"kind":"ox","stem":"옛날 통신수단은 자세한 정보를 전달하기 어렵고, 소식을 전하는 데 시간이 오래 걸렸어요.","answer":"O","reason_options":[{"t":"사람이나 말이 직접 가거나 연기와 불의 개수로만 알려야 했기 때문에","correct":true},{"t":"옛날 통신수단도 오늘날처럼 실시간으로 자세히 전했기 때문에","mis":"SO3-2-u2-X38"}],"mis":"SO3-2-u2-X38","explanation":["단서 1이에요.","오래 걸렸어요.","그래서 O예요."],"asset":{"type":"passage","lines":["단서 1 — 옛날 통신수단은 자세한 정보를 전달하기 어렵고, 소식을 전하는 데 시간이 오래 걸렸습니다.","단서 2 — 오늘날 사람들은 주로 서찰, 방, 파발 등의 통신수단을 사용합니다.","단서 3 — 통신수단이 발달하면서 오늘날에는 한 번에 많은 정보를 실시간으로 주고받을 수 있습니다.","단서 4 — 통신수단의 변화로 새로운 시설과 직업이 생겨났습니다.","단서 5 — 몸과 마음의 건강을 위해 통신수단을 안전하고 올바르게 사용해야 합니다.","규칙 — 옳은 설명의 번호를 규칙에 따라 비밀번호 네 칸에 써요."],"numbered":false,"title":"『사회』 141쪽 재미있게 확인해요 — 휴대 전화 비밀번호의 단서"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L20_challenge#6','soc',3,2,'u2','L20','tb_g3_2_soc_u2_L20_challenge','lesson_challenge','SO3-2-u2-C20',3,'match','auto','「통신수단의 변화로 달라진 생활 모습」 생각 그물을 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"SO3-2-u2-C20","difficulty":3,"kind":"match","stem":"「통신수단의 변화로 달라진 생활 모습」 생각 그물을 알맞게 이으세요.","pairs":[{"l":"옛날 통신수단","r":"봉수, 신호 깃발, 북"},{"l":"오늘날 통신수단","r":"휴대 전화, 길 도우미, 텔레비전"},{"l":"달라진 생활 모습","r":"정보를 찾고 의사소통하는 방식이 달라졌어요"}],"mis":"SO3-2-u2-X38","explanation":["옛날은 봉수예요.","오늘날은 휴대 전화예요.","소통 방식이 달라졌어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L20_challenge#7','soc',3,2,'u2','L20','tb_g3_2_soc_u2_L20_challenge','lesson_challenge','SO3-2-u2-C20',3,'error','auto','이모티콘을 만들며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO3-2-u2-X43']::text[],false,'{"seq":7,"concept":"SO3-2-u2-C20","difficulty":3,"kind":"error","stem":"이모티콘을 만들며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「이모티콘은 꼭 사람 얼굴 모습으로만 만들어야 해.」","correct":true,"mis_target":"SO3-2-u2-X43"},{"t":"친구 가 — 「생각한 말을 동물이나 글자, 숫자 모습으로도 나타낼 수 있어.」","mis":"SO3-2-u2-X43"},{"t":"친구 나 — 「스케치한 뒤 어울리는 색을 칠해 완성해.」","mis":"SO3-2-u2-X43"}],"explanation":["140쪽 순서 2예요.","여러 모습으로 나타내요.","친구 다가 잘못 말했어요."],"asset":{"type":"passage","lines":["1 대화 속 상황에 들어갈 알맞은 말을 생각해요.","2 생각한 말을 사람, 동물, 물건, 글자, 숫자 등 어떤 모습으로 나타낼지 정해요.","3 생각한 모습으로 스케치한 뒤 어울리는 색을 칠해 완성해요."],"numbered":false,"title":"『사회』 140쪽 — 나만의 이모티콘 만들기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L20_challenge#8','soc',3,2,'u2','L20','tb_g3_2_soc_u2_L20_challenge','lesson_challenge','SO3-2-u2-C20',4,'mc','auto','「통신수단의 변화로 달라진 생활 모습」에서 공부한 내용을 가장 잘 정리한 것은 무엇인가요?',ARRAY['SO3-2-u2-X42','SO3-2-u2-X50','SO3-2-u2-X41']::text[],false,'{"seq":8,"concept":"SO3-2-u2-C20","difficulty":4,"kind":"mc","stem":"「통신수단의 변화로 달라진 생활 모습」에서 공부한 내용을 가장 잘 정리한 것은 무엇인가요?","options":[{"t":"옛날엔 오래 걸리고 자세히 전하기 어려웠지만 오늘날엔 실시간으로 많은 정보를 주고받으며, 건강을 위해 올바르게 써야 해요","correct":true},{"t":"오늘날 통신수단은 문제점이 하나도 없어요","mis":"SO3-2-u2-X42"},{"t":"옛날과 오늘날 소통 방식은 같아요","mis":"SO3-2-u2-X50"},{"t":"통신수단이 변해도 새 직업은 생기지 않았어요","mis":"SO3-2-u2-X41"}],"explanation":["옛날 특징이에요.","오늘날 특징이에요.","올바른 이용이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L20_challenge#9','soc',3,2,'u2','L20','tb_g3_2_soc_u2_L20_challenge','lesson_challenge','SO3-2-u2-C20',4,'essay','teacher','통신수단을 이용하면서 불편했거나 아쉬웠던 경험을 쓰고, 이를 해결할 미래의 통신수단과 그것으로 편리해질 모습을 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"SO3-2-u2-C20","difficulty":4,"kind":"essay","stem":"통신수단을 이용하면서 불편했거나 아쉬웠던 경험을 쓰고, 이를 해결할 미래의 통신수단과 그것으로 편리해질 모습을 쓰세요.","answer_guide":{"answer":"예: 해외여행 중에 집에 있는 강아지가 보고 싶었지만 무슨 마음인지 알 수 없어 아쉬웠어요. 동물 소리를 우리말로 바꿔 주는 영상 통화 기기가 있으면 좋겠어요. 멀리 있어도 강아지와 마음을 나눌 수 있을 거예요.","scoring_points":["불편했던 경험을 썼는가","해결할 미래 통신수단을 썼는가","편리해질 모습을 썼는가"]},"explanation":["경험을 떠올려요.","미래 통신수단이에요.","편리해질 모습이에요."],"asset":{"type":"passage","lines":["1 통신수단을 이용하면서 불편했거나 아쉬웠던 경험을 떠올려요.","2 이를 해결할 수 있는 미래의 통신수단을 생각해요.","3 미래의 통신수단으로 편리해질 모습을 상상하여 일기를 써요.","4 일기의 내용을 잘 나타내는 장면을 그림으로 그려요.","예시 「뽀롱이와의 영상 통화」 — 강아지가 짖는 소리가 화면에 우리말로 나타났어요.","예시 「조카와의 영상 전화」 — 미국에 사는 조카에게 영상 전화로 바로 한과를 보냈어요."],"numbered":false,"title":"『사회』 139쪽 — 미래 그림일기 쓰기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_L20_challenge#10','soc',3,2,'u2','L20','tb_g3_2_soc_u2_L20_challenge','lesson_challenge','SO3-2-u2-C20',4,'essay','teacher','태권도 대화의 마지막 말 다음에 보낼 나만의 이모티콘을 생각해 이모티콘의 말과 어떤 모습으로 나타낼지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO3-2-u2-C20","difficulty":4,"kind":"essay","stem":"태권도 대화의 마지막 말 다음에 보낼 나만의 이모티콘을 생각해 이모티콘의 말과 어떤 모습으로 나타낼지 쓰세요.","answer_guide":{"answer":"예: 말 — 「멋지다, 빨간 띠!」 / 모습 — 빨간 띠를 맨 강아지가 엄지를 들고 있는 모습으로 나타내요.","scoring_points":["대화 상황에 알맞은 말을 썼는가","나타낼 모습을 썼는가","말과 모습이 어울리는가"]},"explanation":["대화 속 상황이에요.","알맞은 말을 생각해요.","모습을 정해요."],"asset":{"type":"speech","turns":[{"who":"친구 1","text":"지한아, 요즘 태권도 배우고 있어?"},{"who":"지한","text":"응, 계속 배우고 있어."},{"who":"친구 1","text":"와! 실력이 많이 늘었겠는데? 지금 파란 띠야?"},{"who":"지한","text":"파란 띠는 전에 받았고, 이제 빨간 띠야."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_review_a#1','soc',3,2,'u2','','tb_g3_2_soc_u2_review_a','unit_review','SO3-2-u2-C1',1,'sa','auto','단원 평가 1번처럼 김장과 전통 결혼식같이 옛날부터 되풀이되어 전해 오는 생활 습관과 생활 모습을 무엇이라고 하는지 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"SO3-2-u2-C1","difficulty":1,"kind":"sa","stem":"단원 평가 1번처럼 김장과 전통 결혼식같이 옛날부터 되풀이되어 전해 오는 생활 습관과 생활 모습을 무엇이라고 하는지 쓰세요.","answer":["풍습"],"explanation":["김장과 결혼식이에요.","풍◯이에요.","풍습이에요."],"mis":"SO3-2-u2-X01"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_review_a#2','soc',3,2,'u2','','tb_g3_2_soc_u2_review_a','unit_review','SO3-2-u2-C2',1,'mc','auto','아기가 태어나면 대문에 금줄을 친 풍습은 일생 동안의 풍습 가운데 무엇과 관련 있나요?',ARRAY['SO3-2-u2-X05']::text[],false,'{"seq":2,"concept":"SO3-2-u2-C2","difficulty":1,"kind":"mc","stem":"아기가 태어나면 대문에 금줄을 친 풍습은 일생 동안의 풍습 가운데 무엇과 관련 있나요?","options":[{"t":"출생","correct":true},{"t":"첫돌","mis":"SO3-2-u2-X05"},{"t":"회갑","mis":"SO3-2-u2-X05"},{"t":"장례","mis":"SO3-2-u2-X05"}],"explanation":["태어날 때예요.","21일 동안이에요.","출생이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
