INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_review_a#4','soc',3,2,'u2','','tb_g3_2_soc_u2_review_a','unit_review','SO3-2-u2-C3',1,'mc','auto','교실 놀이 말판 문제: 옛날 풍습에서 결혼하는 날 신랑이 신부 측에 주었던 것은 무엇인가요?',ARRAY['SO3-2-u2-X07']::text[],false,'{"seq":4,"concept":"SO3-2-u2-C3","difficulty":1,"kind":"mc","stem":"교실 놀이 말판 문제: 옛날 풍습에서 결혼하는 날 신랑이 신부 측에 주었던 것은 무엇인가요?","options":[{"t":"나무 기러기","correct":true},{"t":"반지","mis":"SO3-2-u2-X07"},{"t":"대추와 밤","mis":"SO3-2-u2-X07"},{"t":"복주머니","mis":"SO3-2-u2-X07"}],"explanation":["『사회』 72쪽이에요.","평생 함께하자는 뜻이에요.","나무 기러기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
