INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_review_a#6','soc',3,2,'u2','','tb_g3_2_soc_u2_review_a','unit_review','SO3-2-u2-C9',1,'blank','auto','교실 놀이 말판 문제: 「옛날 교통수단은 (    )에서 쉽게 얻을 수 있는 재료로 만들었습니다.」 빈칸에 알맞은 말은?',ARRAY['SO3-2-u2-X24']::text[],false,'{"seq":6,"concept":"SO3-2-u2-C9","difficulty":1,"kind":"blank","stem":"교실 놀이 말판 문제: 「옛날 교통수단은 (    )에서 쉽게 얻을 수 있는 재료로 만들었습니다.」 빈칸에 알맞은 말은?","options":[{"t":"자연","correct":true},{"t":"공장","mis":"SO3-2-u2-X24"},{"t":"기계","mis":"SO3-2-u2-X24"},{"t":"석유","mis":"SO3-2-u2-X24"}],"explanation":["나무와 풀이에요.","주변에서 얻어요.","자연이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_review_a#7','soc',3,2,'u2','','tb_g3_2_soc_u2_review_a','unit_review','SO3-2-u2-C15',1,'mc','auto','보기 가운데 통신수단이 아닌 것을 고르세요.',ARRAY['SO3-2-u2-X35']::text[],false,'{"seq":7,"concept":"SO3-2-u2-C15","difficulty":1,"kind":"mc","stem":"보기 가운데 통신수단이 아닌 것을 고르세요.","options":[{"t":"여객선","correct":true},{"t":"휴대 전화","mis":"SO3-2-u2-X35"},{"t":"텔레비전","mis":"SO3-2-u2-X35"},{"t":"인터폰","mis":"SO3-2-u2-X35"}],"explanation":["소식을 주고받나요?","여객선은 사람을 옮겨요.","여객선이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_review_a#8','soc',3,2,'u2','','tb_g3_2_soc_u2_review_a','unit_review','SO3-2-u2-C16',1,'mc','auto','단원 평가 10번의 ㉠, ㉡에서 설명하는 옛날 통신수단을 알맞게 짝지은 것은 무엇인가요?',ARRAY['SO3-2-u2-X37']::text[],false,'{"seq":8,"concept":"SO3-2-u2-C16","difficulty":1,"kind":"mc","stem":"단원 평가 10번의 ㉠, ㉡에서 설명하는 옛날 통신수단을 알맞게 짝지은 것은 무엇인가요?","options":[{"t":"㉠ 방, ㉡ 봉수","correct":true},{"t":"㉠ 방, ㉡ 파발","mis":"SO3-2-u2-X37"},{"t":"㉠ 서찰, ㉡ 봉수","mis":"SO3-2-u2-X37"},{"t":"㉠ 파발, ㉡ 신호 연","mis":"SO3-2-u2-X37"}],"explanation":["㉠은 글을 붙여요.","㉡은 연기와 불이에요.","방과 봉수예요."],"asset":{"type":"passage","lines":["㉠ 나라의 중요한 소식을 널리 알리려고 사람들이 많이 모이는 곳에 글을 써서 붙였습니다.","㉡ 낮에는 연기, 밤에는 불을 피워서 나라의 위급한 상황을 알렸습니다."],"numbered":false,"title":"단원 평가 10번 — 옛날 통신수단 설명"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_review_a#9','soc',3,2,'u2','','tb_g3_2_soc_u2_review_a','unit_review','SO3-2-u2-C3',2,'mc','auto','변화하면서 이어져 내려오는 풍습끼리 묶은 것은 무엇인가요?',ARRAY['SO3-2-u2-X09']::text[],false,'{"seq":9,"concept":"SO3-2-u2-C3","difficulty":2,"kind":"mc","stem":"변화하면서 이어져 내려오는 풍습끼리 묶은 것은 무엇인가요?","options":[{"t":"백일잔치, 회갑잔치, 폐백","correct":true},{"t":"금줄 치기, 관례","mis":"SO3-2-u2-X09"},{"t":"신부 집에서 결혼하기, 금줄 치기","mis":"SO3-2-u2-X09"},{"t":"관례, 백일잔치","mis":"SO3-2-u2-X09"}],"explanation":["오늘날에도 해요.","모습이 조금 바뀌었어요.","백일잔치, 회갑잔치, 폐백이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_review_a#10','soc',3,2,'u2','','tb_g3_2_soc_u2_review_a','unit_review','SO3-2-u2-C5',2,'mc','auto','오늘날 세시 풍속의 특징으로 알맞은 것은 무엇인가요?',ARRAY['SO3-2-u2-X14','SO3-2-u2-X02']::text[],false,'{"seq":10,"concept":"SO3-2-u2-C5","difficulty":2,"kind":"mc","stem":"오늘날 세시 풍속의 특징으로 알맞은 것은 무엇인가요?","options":[{"t":"큰 명절을 중심으로 한 세시 풍속이 이어져 와요","correct":true},{"t":"농사와 관련 있는 세시 풍속이 더 늘었어요","mis":"SO3-2-u2-X14"},{"t":"계절마다 세시 풍속이 더 다양해졌어요","mis":"SO3-2-u2-X14"},{"t":"세시 풍속이 모두 사라졌어요","mis":"SO3-2-u2-X02"}],"explanation":["『사회』 84쪽이에요.","농사짓는 사람이 줄었어요.","큰 명절 중심이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_review_a#11','soc',3,2,'u2','','tb_g3_2_soc_u2_review_a','unit_review','SO3-2-u2-C11',2,'mc','auto','수이가 부산에서 서울까지 가는 데 걸린 시간은 어느 정도인가요?',ARRAY['SO3-2-u2-X28']::text[],false,'{"seq":11,"concept":"SO3-2-u2-C11","difficulty":2,"kind":"mc","stem":"수이가 부산에서 서울까지 가는 데 걸린 시간은 어느 정도인가요?","options":[{"t":"3~4시간(반나절) 정도","correct":true},{"t":"15일 정도","mis":"SO3-2-u2-X28"},{"t":"9일 정도","mis":"SO3-2-u2-X28"},{"t":"한 달 정도","mis":"SO3-2-u2-X28"}],"explanation":["오전에 출발했어요.","낮에 도착했어요.","반나절 정도예요."],"asset":{"type":"passage","lines":["박 선비 — 9월 1일 부산 출발 → 9월 7일 상주 도착","박 선비 — 9월 11일 충주 도착 → 9월 15일 한양(서울) 도착","박 선비 — 부산~상주는 걸어서, 상주~충주는 말을 타고, 충주~한양은 나룻배로","수이 — 오전 6시 집 출발, 지하철을 타고 부산역 도착","수이 — 오전 7시 부산역 출발, 고속 열차로 오전 9시 30분 서울역 도착","수이 — 버스를 타고 낮 12시 친척 집 도착, 택시를 타고 시내 관광"],"title":"『사회』 107쪽 할 수 있어요 — 박 선비와 수이의 여행"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_review_a#12','soc',3,2,'u2','','tb_g3_2_soc_u2_review_a','unit_review','SO3-2-u2-C12',2,'mc','auto','교통 체증을 줄이려는 노력으로 알맞은 것은 무엇인가요?',ARRAY['SO3-2-u2-X30','SO3-2-u2-X31']::text[],false,'{"seq":12,"concept":"SO3-2-u2-C12","difficulty":2,"kind":"mc","stem":"교통 체증을 줄이려는 노력으로 알맞은 것은 무엇인가요?","options":[{"t":"막히는 길 정보를 빠르게 알려 교통을 관리해요","correct":true},{"t":"자동차를 더 많이 사요","mis":"SO3-2-u2-X30"},{"t":"주차장을 모두 없애요","mis":"SO3-2-u2-X30"},{"t":"자전거 탈 때 안전 장비를 벗어요","mis":"SO3-2-u2-X31"}],"explanation":["길이 막혀요.","정보를 알려요.","과학적인 교통 관리예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_review_a#13','soc',3,2,'u2','','tb_g3_2_soc_u2_review_a','unit_review','SO3-2-u2-C13',2,'mc','auto','미래 교통수단의 특징이 될 수 있는 말은 무엇인가요?',ARRAY['SO3-2-u2-X34','SO3-2-u2-X24']::text[],false,'{"seq":13,"concept":"SO3-2-u2-C13","difficulty":2,"kind":"mc","stem":"미래 교통수단의 특징이 될 수 있는 말은 무엇인가요?","options":[{"t":"안전 강화","correct":true},{"t":"혼잡 유발","mis":"SO3-2-u2-X34"},{"t":"시설 부족","mis":"SO3-2-u2-X34"},{"t":"동물의 힘","mis":"SO3-2-u2-X24"}],"explanation":["발전 방향이에요.","안전해져요.","안전 강화예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_review_a#14','soc',3,2,'u2','','tb_g3_2_soc_u2_review_a','unit_review','SO3-2-u2-C18',2,'mc','auto','단원 평가 8번에서 통신수단의 변화로 달라진 생활 모습으로 알맞지 않은 것은 무엇인가요?',ARRAY['SO3-2-u2-X50']::text[],false,'{"seq":14,"concept":"SO3-2-u2-C18","difficulty":2,"kind":"mc","stem":"단원 평가 8번에서 통신수단의 변화로 달라진 생활 모습으로 알맞지 않은 것은 무엇인가요?","options":[{"t":"비나 눈이 내리면 소식이나 정보를 전하기 어렵게 되었어요","correct":true},{"t":"길 도우미로 모르는 길도 쉽게 찾아가요","mis":"SO3-2-u2-X50"},{"t":"모바일 메신저로 친구들과 실시간으로 대화해요","mis":"SO3-2-u2-X50"},{"t":"직접 가지 않아도 할 수 있는 일이 많아졌어요","mis":"SO3-2-u2-X50"}],"explanation":["날씨의 영향은 옛날이에요.","오늘날은 날씨와 관계없어요.","그 보기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_review_a#15','soc',3,2,'u2','','tb_g3_2_soc_u2_review_a','unit_review','SO3-2-u2-C19',2,'mc','auto','통신수단을 올바르게 쓰는 방법으로 알맞은 것은 무엇인가요?',ARRAY['SO3-2-u2-X43','SO3-2-u2-X42']::text[],false,'{"seq":15,"concept":"SO3-2-u2-C19","difficulty":2,"kind":"mc","stem":"통신수단을 올바르게 쓰는 방법으로 알맞은 것은 무엇인가요?","options":[{"t":"개인 정보가 새어 나가지 않도록 보안에 유의해요","correct":true},{"t":"모르는 사람에게 주소를 알려 줘요","mis":"SO3-2-u2-X43"},{"t":"허락 없이 친구 사진을 올려요","mis":"SO3-2-u2-X43"},{"t":"밤늦게까지 게임을 해요","mis":"SO3-2-u2-X42"}],"explanation":["개인 정보예요.","지켜야 해요.","보안에 유의해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_review_a#16','soc',3,2,'u2','','tb_g3_2_soc_u2_review_a','unit_review','SO3-2-u2-C4',2,'mc','auto','단원 도입 미션: 행사장 모습과 이야기가 일치하는 학생은 누구인가요?',ARRAY['SO3-2-u2-X44']::text[],false,'{"seq":16,"concept":"SO3-2-u2-C4","difficulty":2,"kind":"mc","stem":"단원 도입 미션: 행사장 모습과 이야기가 일치하는 학생은 누구인가요?","options":[{"t":"호준","correct":true},{"t":"민채","mis":"SO3-2-u2-X44"},{"t":"승혁","mis":"SO3-2-u2-X44"},{"t":"주연","mis":"SO3-2-u2-X44"}],"explanation":["네 학생의 말을 그림과 견줘요.","호준이는 강강술래 체험 부스에 있어요.","호준이에요."],"asset":{"type":"passage","lines":["부스 — 송편 빚기 체험, 송편 판매, 송편 시식, 보름달 카드 쓰기, 강강술래 체험","송편 빚기 부스 앞은 줄이 길고, 바로 옆에 송편 재료가 가득한 트럭이 있어요.","송편 판매 부스에는 직접 판매뿐 아니라 인터넷 주문도 할 수 있다고 적혀 있어요.","민채 — 송편 빚기 부스 앞에 줄 섰는데, 송편 시식 부스 근처에 트럭이 있었어요.","승혁 — 송편을 인터넷으로 주문하고 싶었는데, 직접 사야 한다고 해서 아쉬웠어요.","호준 — 강강술래를 체험하러 갔는데, 송편 빚기 부스 앞에 줄이 길게 서 있었어요.","주연 — 송편 시식 부스에 있었는데, 바로 옆 부스에서 호준이가 보름달 카드를 쓰고 있었어요."],"title":"『사회』 61~63쪽 단원 도입 — 추석맞이 행사장(간추림)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_review_a#17','soc',3,2,'u2','','tb_g3_2_soc_u2_review_a','unit_review','SO3-2-u2-C5',3,'mc','auto','단원 평가 3번에서 세시 풍속에 대한 설명으로 알맞지 않은 것은 무엇인가요?',ARRAY['SO3-2-u2-X12','SO3-2-u2-X01','SO3-2-u2-X14']::text[],false,'{"seq":17,"concept":"SO3-2-u2-C5","difficulty":3,"kind":"mc","stem":"단원 평가 3번에서 세시 풍속에 대한 설명으로 알맞지 않은 것은 무엇인가요?","options":[{"t":"⑤","correct":true},{"t":"①","mis":"SO3-2-u2-X12"},{"t":"③","mis":"SO3-2-u2-X01"},{"t":"④","mis":"SO3-2-u2-X14"}],"explanation":["하나씩 따져요.","생활이 바뀌면 세시 풍속도 바뀌어요.","⑤가 알맞지 않아요."],"asset":{"type":"passage","lines":["① 건강이나 복을 바라는 세시 풍속이 많다.","② 음식을 만들어 먹거나 함께 놀이를 한다.","③ 해마다 일정한 때 되풀이하는 생활 습관이다.","④ 오늘날에는 계절과 관계없이 세시 풍속을 즐길 수 있다.","⑤ 옛날과 오늘날의 생활 모습은 달라졌지만 세시 풍속은 변함이 없다."],"numbered":false,"title":"단원 평가 3번 — 세시 풍속에 대한 설명"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_review_a#18','soc',3,2,'u2','','tb_g3_2_soc_u2_review_a','unit_review','SO3-2-u2-C9',3,'blank','auto','생각 그물의 ㉡에 들어갈 말로 알맞은 것은 무엇인가요?',ARRAY['SO3-2-u2-X24']::text[],false,'{"seq":18,"concept":"SO3-2-u2-C9","difficulty":3,"kind":"blank","stem":"생각 그물의 ㉡에 들어갈 말로 알맞은 것은 무엇인가요?","options":[{"t":"자연","correct":true},{"t":"기계","mis":"SO3-2-u2-X24"},{"t":"석유","mis":"SO3-2-u2-X24"},{"t":"전기","mis":"SO3-2-u2-X24"}],"explanation":["옛날 교통수단이에요.","바람의 힘이에요.","자연이에요."],"asset":{"type":"passage","lines":["관례 — 성인이 된다는 의미로 함 / 혼례 — 남녀가 부부가 됨","회갑 — 만 (  ㉠  )세에 잔치를 함 / 출생 — 21일 동안 금줄을 침","사라져 가는 풍습 — 금줄 치기, 관례, 신부 집에서 결혼하기 등","옛날 교통수단 — 사람, 동물, (  ㉡  )의 힘을 이용 / 오늘날 — 기계의 힘","교통의 변화 — 더 빠르게, 짐을 많이, 생활 공간이 넓어짐","통신의 변화 — 정보를 찾고 의사소통하는 방식이 변함, 새로운 (  ㉢  )과 직업"],"title":"『사회』 142~143쪽 생각 그물(일부, 빈칸 셋)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_review_a#19','soc',3,2,'u2','','tb_g3_2_soc_u2_review_a','unit_review','SO3-2-u2-C11',3,'mc','auto','박 선비와 수이의 여행을 견준 것으로 알맞지 않은 것은 무엇인가요?',ARRAY['SO3-2-u2-X28','SO3-2-u2-X23']::text[],false,'{"seq":19,"concept":"SO3-2-u2-C11","difficulty":3,"kind":"mc","stem":"박 선비와 수이의 여행을 견준 것으로 알맞지 않은 것은 무엇인가요?","options":[{"t":"박 선비가 수이보다 날씨의 영향을 적게 받았어요","correct":true},{"t":"수이는 반나절, 박 선비는 15일 정도 걸렸어요","mis":"SO3-2-u2-X28"},{"t":"박 선비는 걷고, 말과 나룻배를 탔어요","mis":"SO3-2-u2-X23"},{"t":"수이는 지하철, 고속 열차, 버스, 택시를 탔어요","mis":"SO3-2-u2-X28"}],"explanation":["흙길과 나룻배를 떠올려요.","박 선비가 날씨의 영향을 더 받았어요.","그 보기예요."],"asset":{"type":"passage","lines":["박 선비 — 9월 1일 부산 출발 → 9월 7일 상주 도착","박 선비 — 9월 11일 충주 도착 → 9월 15일 한양(서울) 도착","박 선비 — 부산~상주는 걸어서, 상주~충주는 말을 타고, 충주~한양은 나룻배로","수이 — 오전 6시 집 출발, 지하철을 타고 부산역 도착","수이 — 오전 7시 부산역 출발, 고속 열차로 오전 9시 30분 서울역 도착","수이 — 버스를 타고 낮 12시 친척 집 도착, 택시를 타고 시내 관광"],"title":"『사회』 107쪽 할 수 있어요 — 박 선비와 수이의 여행"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_review_a#20','soc',3,2,'u2','','tb_g3_2_soc_u2_review_a','unit_review','SO3-2-u2-C18',3,'mc','auto','과정 중심 평가 자료 가와 나에 나타난 통신수단을 바르게 짝지은 것은 무엇인가요?',ARRAY['SO3-2-u2-X37','SO3-2-u2-X38']::text[],false,'{"seq":20,"concept":"SO3-2-u2-C18","difficulty":3,"kind":"mc","stem":"과정 중심 평가 자료 가와 나에 나타난 통신수단을 바르게 짝지은 것은 무엇인가요?","options":[{"t":"가 — 편지, 나 — 모바일 메신저","correct":true},{"t":"가 — 봉수, 나 — 편지","mis":"SO3-2-u2-X37"},{"t":"가 — 모바일 메신저, 나 — 서찰","mis":"SO3-2-u2-X38"},{"t":"가 — 방, 나 — 텔레비전","mis":"SO3-2-u2-X37"}],"explanation":["가는 엄마의 편지예요.","나는 짧게 주고받아요.","편지와 메신저예요."],"asset":{"type":"passage","lines":["가 — (편지 간추림) 사랑하는 아들 보아라. 산으로 글공부하러 간 지 두 달이 넘었구나.","가 — 먹을 것이 부족하거든 사람 편에 알려 다오. 만들어 보내 주마. — 엄마가","나 — (메신저) 「지한아, 밥 먹었니?」 「친구들이랑 떡볶이 사 먹었어요.」","나 — 「오늘 많이 늦니?」 「아니요, 이제 막 버스 탔어요.」"],"title":"과정 중심 평가 — 옛날과 오늘날의 소식 주고받기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_review_a#21','soc',3,2,'u2','','tb_g3_2_soc_u2_review_a','unit_review','SO3-2-u2-C3',3,'ox','auto','옛날 풍습 가운데에는 변화하면서 오늘날까지 이어져 내려오는 풍습도 있고, 사라져 가는 풍습도 있어요.',ARRAY['SO3-2-u2-X09']::text[],false,'{"seq":21,"concept":"SO3-2-u2-C3","difficulty":3,"kind":"ox","stem":"옛날 풍습 가운데에는 변화하면서 오늘날까지 이어져 내려오는 풍습도 있고, 사라져 가는 풍습도 있어요.","answer":"O","reason_options":[{"t":"백일잔치는 이어지고 금줄 치기는 사라져 가는 것처럼 두 갈래가 있기 때문에","correct":true},{"t":"옛날 풍습은 모두 그대로 이어지기 때문에","mis":"SO3-2-u2-X09"}],"mis":"SO3-2-u2-X09","explanation":["『사회』 74쪽이에요.","두 갈래예요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_review_a#22','soc',3,2,'u2','','tb_g3_2_soc_u2_review_a','unit_review','SO3-2-u2-C3',3,'error','auto','폐백을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO3-2-u2-X45','SO3-2-u2-X07']::text[],false,'{"seq":22,"concept":"SO3-2-u2-C3","difficulty":3,"kind":"error","stem":"폐백을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「오늘날 모든 결혼식은 반드시 신랑 집안 어른들께만 폐백을 드려.」","correct":true,"mis_target":"SO3-2-u2-X45"},{"t":"친구 가 — 「옛날에는 신랑 집안 어른들께 폐백을 드렸어.」","mis":"SO3-2-u2-X45"},{"t":"친구 나 — 「오늘날에는 양쪽 집안 어른들께 폐백을 드리기도 해.」","mis":"SO3-2-u2-X07"}],"explanation":["「드리기도 해요」예요.","양쪽 집안이에요.","친구 다가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_review_a#23','soc',3,2,'u2','','tb_g3_2_soc_u2_review_a','unit_review','SO3-2-u2-C2',4,'essay','teacher','단원 평가 2번: 첫 번째 생일인 돌잔치와 사람이 죽으면 치르는 장례에는 우리 조상들의 어떤 마음이 담겨 있는지 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"SO3-2-u2-C2","difficulty":4,"kind":"essay","stem":"단원 평가 2번: 첫 번째 생일인 돌잔치와 사람이 죽으면 치르는 장례에는 우리 조상들의 어떤 마음이 담겨 있는지 쓰세요.","answer_guide":{"answer":"예: 돌잔치에서는 아기가 오래 살기를 바라는 음식을 먹으며 기쁨을 나누었고, 장례에서는 남은 가족을 위로하고 죽은 사람의 복을 빌었어요. 기쁨과 슬픔을 나누며 서로 돕고 사는 마음이 담겨 있어요.","scoring_points":["돌잔치에 담긴 마음을 썼는가","장례에 담긴 마음을 썼는가","기쁨과 슬픔을 나누는 마음으로 정리했는가"]},"explanation":["기쁜 일이에요.","슬픈 일이에요.","마음을 나눴어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_review_a#24','soc',3,2,'u2','','tb_g3_2_soc_u2_review_a','unit_review','SO3-2-u2-C12',4,'essay','teacher','단원 평가 7번처럼 교통의 발달로 생긴 문제점을 두 가지 쓰고, 그 가운데 환경과 관련한 문제를 해결하기 위한 노력을 한 가지 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"SO3-2-u2-C12","difficulty":4,"kind":"essay","stem":"단원 평가 7번처럼 교통의 발달로 생긴 문제점을 두 가지 쓰고, 그 가운데 환경과 관련한 문제를 해결하기 위한 노력을 한 가지 쓰세요.","answer_guide":{"answer":"예: 교통 체증과 대기 오염이 생겼어요. 대기 오염을 줄이려면 친환경 에너지를 쓰는 교통수단을 이용하거나 공유 자전거, 대중교통을 이용해요.","scoring_points":["문제점 두 가지를 썼는가","환경 문제를 골랐는가","알맞은 노력을 썼는가"]},"explanation":["문제점이에요.","환경 문제예요.","노력을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_review_a#25','soc',3,2,'u2','','tb_g3_2_soc_u2_review_a','unit_review','SO3-2-u2-C20',4,'essay','teacher','과정 중심 평가 자료 가(편지)와 나(모바일 메신저)를 보고 옛날과 오늘날 통신수단의 차이점을 두 가지 이상 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"SO3-2-u2-C20","difficulty":4,"kind":"essay","stem":"과정 중심 평가 자료 가(편지)와 나(모바일 메신저)를 보고 옛날과 오늘날 통신수단의 차이점을 두 가지 이상 쓰세요.","answer_guide":{"answer":"예: 옛날 통신수단은 소식을 전하는 데 시간이 오래 걸렸지만 오늘날에는 바로바로 주고받아요. 옛날에는 많은 정보를 자세히 전하기 어려웠지만 오늘날에는 많은 정보를 한 번에 쉽게 주고받아요.","scoring_points":["차이점을 두 가지 이상 썼는가","옛날과 오늘날을 견주었는가","자료와 이어 썼는가"]},"explanation":["가와 나를 견줘요.","빠르기와 정보의 양이에요.","두 가지 이상 써요."],"asset":{"type":"passage","lines":["가 — (편지 간추림) 사랑하는 아들 보아라. 산으로 글공부하러 간 지 두 달이 넘었구나.","가 — 먹을 것이 부족하거든 사람 편에 알려 다오. 만들어 보내 주마. — 엄마가","나 — (메신저) 「지한아, 밥 먹었니?」 「친구들이랑 떡볶이 사 먹었어요.」","나 — 「오늘 많이 늦니?」 「아니요, 이제 막 버스 탔어요.」"],"title":"과정 중심 평가 — 옛날과 오늘날의 소식 주고받기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_review_b#1','soc',3,2,'u2','','tb_g3_2_soc_u2_review_b','unit_review','SO3-2-u2-C1',1,'mc','auto','『사회』 68쪽 낱말 풀이에서 설날, 정월 대보름, 단오, 추석처럼 해마다 일정하게 지켜 즐기는 날을 가리키는 말은 무엇인가요?',ARRAY['SO3-2-u2-X03']::text[],false,'{"seq":1,"concept":"SO3-2-u2-C1","difficulty":1,"kind":"mc","stem":"『사회』 68쪽 낱말 풀이에서 설날, 정월 대보름, 단오, 추석처럼 해마다 일정하게 지켜 즐기는 날을 가리키는 말은 무엇인가요?","options":[{"t":"명절","correct":true},{"t":"절기","mis":"SO3-2-u2-X03"},{"t":"세시","mis":"SO3-2-u2-X03"},{"t":"차례","mis":"SO3-2-u2-X03"}],"explanation":["해마다 지켜요.","즐기는 날이에요.","명절이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_review_b#2','soc',3,2,'u2','','tb_g3_2_soc_u2_review_b','unit_review','SO3-2-u2-C2',1,'sa','auto','부모님이 60년 동안 건강하게 사신 것을 축하하는 회갑을 달리 부르는 말을 두 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SO3-2-u2-C2","difficulty":1,"kind":"sa","stem":"부모님이 60년 동안 건강하게 사신 것을 축하하는 회갑을 달리 부르는 말을 두 글자로 쓰세요.","answer":["환갑"],"explanation":["『사회』 71쪽 말풍선이에요.","환◯이에요.","환갑이에요."],"mis":"SO3-2-u2-X05"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_review_b#3','soc',3,2,'u2','','tb_g3_2_soc_u2_review_b','unit_review','SO3-2-u2-C4',1,'mc','auto','단원 평가 4번에서 「팥죽 먹기, 버선 주고받기」와 이어지는 명절이나 절기는 무엇인가요?',ARRAY['SO3-2-u2-X11']::text[],false,'{"seq":3,"concept":"SO3-2-u2-C4","difficulty":1,"kind":"mc","stem":"단원 평가 4번에서 「팥죽 먹기, 버선 주고받기」와 이어지는 명절이나 절기는 무엇인가요?","options":[{"t":"동지","correct":true},{"t":"단오","mis":"SO3-2-u2-X11"},{"t":"추석","mis":"SO3-2-u2-X11"},{"t":"설날","mis":"SO3-2-u2-X11"}],"explanation":["팥죽이에요.","밤이 가장 긴 날이에요.","동지예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_review_b#4','soc',3,2,'u2','','tb_g3_2_soc_u2_review_b','unit_review','SO3-2-u2-C6',1,'sa','auto','편을 갈라 윷으로 승부를 겨루는 전통 놀이를 쓰세요.','{}'::text[],false,'{"seq":4,"concept":"SO3-2-u2-C6","difficulty":1,"kind":"sa","stem":"편을 갈라 윷으로 승부를 겨루는 전통 놀이를 쓰세요.","answer":["윷놀이"],"explanation":["윷을 던져요.","윷◯◯예요.","윷놀이예요."],"mis":"SO3-2-u2-X18"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_review_b#5','soc',3,2,'u2','','tb_g3_2_soc_u2_review_b','unit_review','SO3-2-u2-C8',1,'sa','auto','바다나 강에서 배가 다니도록 정해진 길을 무엇이라고 하나요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":5,"concept":"SO3-2-u2-C8","difficulty":1,"kind":"sa","stem":"바다나 강에서 배가 다니도록 정해진 길을 무엇이라고 하나요? 두 글자로 쓰세요.","answer":["수로"],"explanation":["물길이에요.","수◯예요.","수로예요."],"mis":"SO3-2-u2-X21"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_review_b#6','soc',3,2,'u2','','tb_g3_2_soc_u2_review_b','unit_review','SO3-2-u2-C10',1,'mc','auto','비행기가 다닐 수 있도록 신호를 알려 주는 공항의 시설은 무엇인가요?',ARRAY['SO3-2-u2-X26']::text[],false,'{"seq":6,"concept":"SO3-2-u2-C10","difficulty":1,"kind":"mc","stem":"비행기가 다닐 수 있도록 신호를 알려 주는 공항의 시설은 무엇인가요?","options":[{"t":"관제탑","correct":true},{"t":"활주로","mis":"SO3-2-u2-X26"},{"t":"등대","mis":"SO3-2-u2-X26"},{"t":"선착장","mis":"SO3-2-u2-X26"}],"explanation":["신호를 알려 줘요.","공항에 있어요.","관제탑이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_review_b#7','soc',3,2,'u2','','tb_g3_2_soc_u2_review_b','unit_review','SO3-2-u2-C16',1,'sa','auto','단원 평가 10번 ㉡처럼 낮에는 연기, 밤에는 불을 피워서 나라의 위급한 상황을 알린 옛날 통신수단을 쓰세요.','{}'::text[],false,'{"seq":7,"concept":"SO3-2-u2-C16","difficulty":1,"kind":"sa","stem":"단원 평가 10번 ㉡처럼 낮에는 연기, 밤에는 불을 피워서 나라의 위급한 상황을 알린 옛날 통신수단을 쓰세요.","answer":["봉수"],"explanation":["연기와 불이에요.","봉◯예요.","봉수예요."],"mis":"SO3-2-u2-X37"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_review_b#8','soc',3,2,'u2','','tb_g3_2_soc_u2_review_b','unit_review','SO3-2-u2-C18',1,'sa','auto','휴대 전화나 컴퓨터의 통신을 원활하게 해 주며, 통신 설비 기술자가 설치하는 시설을 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"SO3-2-u2-C18","difficulty":1,"kind":"sa","stem":"휴대 전화나 컴퓨터의 통신을 원활하게 해 주며, 통신 설비 기술자가 설치하는 시설을 쓰세요.","answer":["기지국","휴대 전화 기지국","휴대전화 기지국"],"explanation":["『사회』 132쪽이에요.","기◯◯이에요.","기지국이에요."],"mis":"SO3-2-u2-X41"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_review_b#9','soc',3,2,'u2','','tb_g3_2_soc_u2_review_b','unit_review','SO3-2-u2-C3',2,'match','auto','결혼 풍습을 알맞게 이으세요.','{}'::text[],false,'{"seq":9,"concept":"SO3-2-u2-C3","difficulty":2,"kind":"match","stem":"결혼 풍습을 알맞게 이으세요.","pairs":[{"l":"옛날 결혼 장소","r":"신부 집"},{"l":"오늘날 결혼 장소","r":"결혼식장, 공원 등"},{"l":"옛날 주고받는 물건","r":"나무 기러기"},{"l":"오늘날 주고받는 물건","r":"반지"}],"mis":"SO3-2-u2-X07","explanation":["옛날은 신부 집이에요.","오늘날은 결혼식장이에요.","기러기와 반지예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_review_b#10','soc',3,2,'u2','','tb_g3_2_soc_u2_review_b','unit_review','SO3-2-u2-C1',2,'ox','auto','세시 풍속은 절기나 계절과 관계없이 아무 때나 즐길 수 있는 풍습이에요.',ARRAY['SO3-2-u2-X01']::text[],false,'{"seq":10,"concept":"SO3-2-u2-C1","difficulty":2,"kind":"ox","stem":"세시 풍속은 절기나 계절과 관계없이 아무 때나 즐길 수 있는 풍습이에요.","answer":"X","reason_options":[{"t":"세시 풍속은 해마다 일정한 때에 되풀이하는 풍습이기 때문에","correct":true},{"t":"오늘날 체험 행사가 있으니 세시 풍속의 뜻도 바뀌었기 때문에","mis":"SO3-2-u2-X01"}],"mis":"SO3-2-u2-X01","explanation":["교실 놀이 말판 문제예요.","해마다 일정한 때예요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_review_b#11','soc',3,2,'u2','','tb_g3_2_soc_u2_review_b','unit_review','SO3-2-u2-C11',2,'ox','auto','교통이 발달하면서 다른 나라에 가지 않아도 세계 여러 곳에서 만든 물건을 쉽게 구할 수 있게 됐어요.',ARRAY['SO3-2-u2-X28']::text[],false,'{"seq":11,"concept":"SO3-2-u2-C11","difficulty":2,"kind":"ox","stem":"교통이 발달하면서 다른 나라에 가지 않아도 세계 여러 곳에서 만든 물건을 쉽게 구할 수 있게 됐어요.","answer":"O","reason_options":[{"t":"배나 비행기로 여러 나라의 물건을 들여올 수 있게 되었기 때문에","correct":true},{"t":"교통이 발달해도 물건은 가까운 곳에서만 오기 때문에","mis":"SO3-2-u2-X28"}],"mis":"SO3-2-u2-X28","explanation":["세계 과자 판매점 사진이에요.","여러 곳의 물건이에요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_review_b#12','soc',3,2,'u2','','tb_g3_2_soc_u2_review_b','unit_review','SO3-2-u2-C12',2,'ox','auto','자전거나 킥보드를 탈 때 어린이도 안전 장비를 착용해야 해요.',ARRAY['SO3-2-u2-X49']::text[],false,'{"seq":12,"concept":"SO3-2-u2-C12","difficulty":2,"kind":"ox","stem":"자전거나 킥보드를 탈 때 어린이도 안전 장비를 착용해야 해요.","answer":"O","reason_options":[{"t":"어린이도 탈것을 타면 운전자가 되어 안전 수칙을 지켜야 하기 때문에","correct":true},{"t":"안전 장비는 어른 운전자만 착용하면 되기 때문에","mis":"SO3-2-u2-X49"}],"mis":"SO3-2-u2-X49","explanation":["『사회』 113쪽이에요.","어린이도 운전자예요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_review_b#13','soc',3,2,'u2','','tb_g3_2_soc_u2_review_b','unit_review','SO3-2-u2-C13',2,'ox','auto','자율 운항 선박은 스스로 목적지까지 운항하는 배예요.',ARRAY['SO3-2-u2-X33']::text[],false,'{"seq":13,"concept":"SO3-2-u2-C13","difficulty":2,"kind":"ox","stem":"자율 운항 선박은 스스로 목적지까지 운항하는 배예요.","answer":"O","reason_options":[{"t":"『사회』 115쪽에 사람이 조종하지 않아도 스스로 가는 배로 나오기 때문에","correct":true},{"t":"자율 운항 선박은 하늘을 나는 택시이기 때문에","mis":"SO3-2-u2-X33"}],"mis":"SO3-2-u2-X33","explanation":["선박은 배예요.","스스로 가요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_review_b#14','soc',3,2,'u2','','tb_g3_2_soc_u2_review_b','unit_review','SO3-2-u2-C18',2,'sa','auto','「삐삐」라고 불렸으며 휴대 전화가 발달하면서 사라진 통신수단을 쓰세요.','{}'::text[],false,'{"seq":14,"concept":"SO3-2-u2-C18","difficulty":2,"kind":"sa","stem":"「삐삐」라고 불렸으며 휴대 전화가 발달하면서 사라진 통신수단을 쓰세요.","answer":["무선 호출기","무선호출기"],"explanation":["『사회』 131쪽이에요.","호출해요.","무선 호출기예요."],"mis":"SO3-2-u2-X41"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_review_b#15','soc',3,2,'u2','','tb_g3_2_soc_u2_review_b','unit_review','SO3-2-u2-C19',2,'ox','auto','다른 사람의 모습을 허락 없이 찍어 올려도 친한 사이라면 괜찮아요.',ARRAY['SO3-2-u2-X43']::text[],false,'{"seq":15,"concept":"SO3-2-u2-C19","difficulty":2,"kind":"ox","stem":"다른 사람의 모습을 허락 없이 찍어 올려도 친한 사이라면 괜찮아요.","answer":"X","reason_options":[{"t":"허락 없이 사진을 찍거나 올리면 다른 사람에게 피해를 주기 때문에","correct":true},{"t":"친한 사이에는 통신 예절이 필요 없기 때문에","mis":"SO3-2-u2-X43"}],"mis":"SO3-2-u2-X43","explanation":["허락이 필요해요.","친구에게도 예절을 지켜요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_review_b#16','soc',3,2,'u2','','tb_g3_2_soc_u2_review_b','unit_review','SO3-2-u2-C4',2,'mc','auto','단원 도입에서 민채의 이야기가 바르지 않은 까닭은 무엇인가요?',ARRAY['SO3-2-u2-X44']::text[],false,'{"seq":16,"concept":"SO3-2-u2-C4","difficulty":2,"kind":"mc","stem":"단원 도입에서 민채의 이야기가 바르지 않은 까닭은 무엇인가요?","options":[{"t":"트럭은 송편 시식 부스가 아니라 송편 빚기 부스 옆에 있기 때문이에요","correct":true},{"t":"송편 빚기 부스에는 줄이 없었기 때문이에요","mis":"SO3-2-u2-X44"},{"t":"행사장에 트럭이 없었기 때문이에요","mis":"SO3-2-u2-X44"},{"t":"민채는 강강술래를 했기 때문이에요","mis":"SO3-2-u2-X44"}],"explanation":["트럭의 자리를 봐요.","송편 빚기 부스 옆이에요.","그래서 바르지 않아요."],"asset":{"type":"passage","lines":["부스 — 송편 빚기 체험, 송편 판매, 송편 시식, 보름달 카드 쓰기, 강강술래 체험","송편 빚기 부스 앞은 줄이 길고, 바로 옆에 송편 재료가 가득한 트럭이 있어요.","송편 판매 부스에는 직접 판매뿐 아니라 인터넷 주문도 할 수 있다고 적혀 있어요.","민채 — 송편 빚기 부스 앞에 줄 섰는데, 송편 시식 부스 근처에 트럭이 있었어요.","승혁 — 송편을 인터넷으로 주문하고 싶었는데, 직접 사야 한다고 해서 아쉬웠어요.","호준 — 강강술래를 체험하러 갔는데, 송편 빚기 부스 앞에 줄이 길게 서 있었어요.","주연 — 송편 시식 부스에 있었는데, 바로 옆 부스에서 호준이가 보름달 카드를 쓰고 있었어요."],"title":"『사회』 61~63쪽 단원 도입 — 추석맞이 행사장(간추림)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_review_b#17','soc',3,2,'u2','','tb_g3_2_soc_u2_review_b','unit_review','SO3-2-u2-C9',3,'mc','auto','단원 평가 6번에서 옛날 교통수단에 대한 설명으로 알맞은 것은 무엇인가요?',ARRAY['SO3-2-u2-X24','SO3-2-u2-X23']::text[],false,'{"seq":17,"concept":"SO3-2-u2-C9","difficulty":3,"kind":"mc","stem":"단원 평가 6번에서 옛날 교통수단에 대한 설명으로 알맞은 것은 무엇인가요?","options":[{"t":"강을 건널 때는 나룻배를 이용했다","correct":true},{"t":"뗏목은 증기의 힘으로 움직였다","mis":"SO3-2-u2-X24"},{"t":"돛단배는 기계의 힘으로 움직였다","mis":"SO3-2-u2-X24"},{"t":"많은 짐을 실을 때는 가마를 이용했다","mis":"SO3-2-u2-X23"}],"explanation":["뗏목과 돛단배는 자연의 힘이에요.","짐은 달구지예요.","나룻배가 알맞아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_review_b#18','soc',3,2,'u2','','tb_g3_2_soc_u2_review_b','unit_review','SO3-2-u2-C18',3,'blank','auto','생각 그물의 ㉢에 들어갈 말로 알맞은 것은 무엇인가요?',ARRAY['SO3-2-u2-X35','SO3-2-u2-X38','SO3-2-u2-X13']::text[],false,'{"seq":18,"concept":"SO3-2-u2-C18","difficulty":3,"kind":"blank","stem":"생각 그물의 ㉢에 들어갈 말로 알맞은 것은 무엇인가요?","options":[{"t":"시설","correct":true},{"t":"교통로","mis":"SO3-2-u2-X35"},{"t":"봉수","mis":"SO3-2-u2-X38"},{"t":"농사","mis":"SO3-2-u2-X13"}],"explanation":["통신의 변화예요.","기지국, 방송국이에요.","시설이에요."],"asset":{"type":"passage","lines":["관례 — 성인이 된다는 의미로 함 / 혼례 — 남녀가 부부가 됨","회갑 — 만 (  ㉠  )세에 잔치를 함 / 출생 — 21일 동안 금줄을 침","사라져 가는 풍습 — 금줄 치기, 관례, 신부 집에서 결혼하기 등","옛날 교통수단 — 사람, 동물, (  ㉡  )의 힘을 이용 / 오늘날 — 기계의 힘","교통의 변화 — 더 빠르게, 짐을 많이, 생활 공간이 넓어짐","통신의 변화 — 정보를 찾고 의사소통하는 방식이 변함, 새로운 (  ㉢  )과 직업"],"title":"『사회』 142~143쪽 생각 그물(일부, 빈칸 셋)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_review_b#19','soc',3,2,'u2','','tb_g3_2_soc_u2_review_b','unit_review','SO3-2-u2-C11',3,'mc','auto','그림 속 섬마을에 오늘날 새로 생긴 교통 시설끼리 묶은 것은 무엇인가요?',ARRAY['SO3-2-u2-X23','SO3-2-u2-X35']::text[],false,'{"seq":19,"concept":"SO3-2-u2-C11","difficulty":3,"kind":"mc","stem":"그림 속 섬마을에 오늘날 새로 생긴 교통 시설끼리 묶은 것은 무엇인가요?","options":[{"t":"다리, 도로, 항구, 등대","correct":true},{"t":"돛단배, 뗏목","mis":"SO3-2-u2-X23"},{"t":"말, 달구지","mis":"SO3-2-u2-X23"},{"t":"봉수, 파발","mis":"SO3-2-u2-X35"}],"explanation":["교통 시설이에요.","교통수단과 갈라요.","다리, 도로, 항구, 등대예요."],"asset":{"type":"passage","lines":["옛날 — 마을 사람들은 돛단배를 타고 섬 밖으로 나갔고, 고기를 잡거나 채소를 기르며 살았어요.","오늘날 — 다리와 도로가 생겨 차를 타고 섬 밖으로 나가요.","오늘날 — 어선, 여객선, 버스, 자가용을 이용하고 항구와 등대가 생겼어요.","오늘날 — 숙박 시설과 음식점이 생기고 버스 운전기사, 여객선 선장 등 직업이 다양해졌어요."],"title":"과정 중심 평가 — 그림 속 섬마을의 옛날과 오늘날(글로 옮김)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_review_b#20','soc',3,2,'u2','','tb_g3_2_soc_u2_review_b','unit_review','SO3-2-u2-C20',3,'mc','auto','옛날과 오늘날 통신수단의 차이를 날씨와 관련지어 바르게 쓴 것은 무엇인가요?',ARRAY['SO3-2-u2-X38']::text[],false,'{"seq":20,"concept":"SO3-2-u2-C20","difficulty":3,"kind":"mc","stem":"옛날과 오늘날 통신수단의 차이를 날씨와 관련지어 바르게 쓴 것은 무엇인가요?","options":[{"t":"옛날 통신수단은 비나 눈이 오면 소식을 전하기 힘들었지만, 오늘날에는 날씨와 관계없이 전해요","correct":true},{"t":"오늘날 통신수단이 날씨의 영향을 더 받아요","mis":"SO3-2-u2-X38"},{"t":"둘 다 날씨와 상관없이 소식을 전했어요","mis":"SO3-2-u2-X38"},{"t":"옛날 통신수단이 비 오는 날 더 빨리 전했어요","mis":"SO3-2-u2-X38"}],"explanation":["봉수를 떠올려요.","오늘날은 날씨와 관계없어요.","그 차이예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_review_b#21','soc',3,2,'u2','','tb_g3_2_soc_u2_review_b','unit_review','SO3-2-u2-C14',3,'ox','auto','교통수단과 통신수단은 오늘날 사람들의 생활을 더욱 편리하게 만들어 주고 있어요.',ARRAY['SO3-2-u2-X44']::text[],false,'{"seq":21,"concept":"SO3-2-u2-C14","difficulty":3,"kind":"ox","stem":"교통수단과 통신수단은 오늘날 사람들의 생활을 더욱 편리하게 만들어 주고 있어요.","answer":"O","reason_options":[{"t":"먼 곳을 빠르게 오가고 소식을 쉽게 주고받게 해 주기 때문에","correct":true},{"t":"교통수단과 통신수단은 사람들의 생활과 관계가 없기 때문에","mis":"SO3-2-u2-X44"}],"mis":"SO3-2-u2-X44","explanation":["두 주제를 떠올려요.","모두 편리해졌어요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_review_b#22','soc',3,2,'u2','','tb_g3_2_soc_u2_review_b','unit_review','SO3-2-u2-C4',3,'error','auto','동지가 어떤 날인지 정리하며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO3-2-u2-X47','SO3-2-u2-X10','SO3-2-u2-X11']::text[],false,'{"seq":22,"concept":"SO3-2-u2-C4","difficulty":3,"kind":"error","stem":"동지가 어떤 날인지 정리하며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 나 — 「동지는 설날처럼 음력으로 날짜를 정해.」","correct":true,"mis_target":"SO3-2-u2-X47"},{"t":"친구 가 — 「동지는 한 해 중 밤이 가장 긴 날이야.」","mis":"SO3-2-u2-X10"},{"t":"친구 다 — 「동지에는 팥죽을 먹었어.」","mis":"SO3-2-u2-X11"}],"explanation":["동지는 24절기예요.","양력을 따라요.","친구 나가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_review_b#23','soc',3,2,'u2','','tb_g3_2_soc_u2_review_b','unit_review','SO3-2-u2-C4',4,'essay','teacher','옛날 세시 풍속 가운데 명절 하나를 골라 그날 한 일과 먹은 음식을 쓰고, 그 속에 담긴 바람을 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"SO3-2-u2-C4","difficulty":4,"kind":"essay","stem":"옛날 세시 풍속 가운데 명절 하나를 골라 그날 한 일과 먹은 음식을 쓰고, 그 속에 담긴 바람을 쓰세요.","answer_guide":{"answer":"예: 정월 대보름에는 달맞이를 하며 소원을 빌고 부럼을 깨물었으며 오곡밥과 나물을 먹었어요. 한 해 동안 건강하고 풍년이 들기를 바라는 마음이 담겨 있어요.","scoring_points":["명절을 골랐는가","한 일과 먹은 음식을 썼는가","담긴 바람을 썼는가"]},"explanation":["명절을 골라요.","한 일과 음식이에요.","바람을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_review_b#24','soc',3,2,'u2','','tb_g3_2_soc_u2_review_b','unit_review','SO3-2-u2-C11',4,'essay','teacher','그림 속 섬마을의 옛날과 오늘날을 견주어 섬 밖으로 나가는 방법, 마을 사람들의 직업이 어떻게 달라졌는지 쓰고, 달라진 까닭을 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"SO3-2-u2-C11","difficulty":4,"kind":"essay","stem":"그림 속 섬마을의 옛날과 오늘날을 견주어 섬 밖으로 나가는 방법, 마을 사람들의 직업이 어떻게 달라졌는지 쓰고, 달라진 까닭을 쓰세요.","answer_guide":{"answer":"예: 옛날에는 돛단배를 타고 오래 걸려 나갔지만 오늘날에는 다리로 차를 타고 빨리 나가요. 옛날에는 어부나 농부가 많았지만 오늘날에는 버스 운전기사, 여객선 선장 등 직업이 다양해요. 교통수단과 교통 시설이 발달했기 때문이에요.","scoring_points":["나가는 방법을 견주었는가","직업을 견주었는가","달라진 까닭을 교통과 이었는가"]},"explanation":["방법을 견줘요.","직업을 견줘요.","까닭을 써요."],"asset":{"type":"passage","lines":["옛날 — 마을 사람들은 돛단배를 타고 섬 밖으로 나갔고, 고기를 잡거나 채소를 기르며 살았어요.","오늘날 — 다리와 도로가 생겨 차를 타고 섬 밖으로 나가요.","오늘날 — 어선, 여객선, 버스, 자가용을 이용하고 항구와 등대가 생겼어요.","오늘날 — 숙박 시설과 음식점이 생기고 버스 운전기사, 여객선 선장 등 직업이 다양해졌어요."],"title":"과정 중심 평가 — 그림 속 섬마을의 옛날과 오늘날(글로 옮김)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_review_b#25','soc',3,2,'u2','','tb_g3_2_soc_u2_review_b','unit_review','SO3-2-u2-C14',4,'essay','teacher','「옛날과 오늘날의 생활 모습」 단원을 공부하며 새로 알게 된 점이나 느낀 점을 풍습, 교통, 통신 가운데 두 가지 이상과 이어 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"SO3-2-u2-C14","difficulty":4,"kind":"essay","stem":"「옛날과 오늘날의 생활 모습」 단원을 공부하며 새로 알게 된 점이나 느낀 점을 풍습, 교통, 통신 가운데 두 가지 이상과 이어 쓰세요.","answer_guide":{"answer":"예: 옛날 풍습에 기쁨과 슬픔을 나누는 조상들의 마음이 담겨 있다는 것을 알았어요. 교통이 발달해 부산에서 서울까지 반나절이면 간다는 것이 신기했어요. 통신수단을 올바르게 쓰는 사람이 되고 싶어요.","scoring_points":["두 가지 이상과 이었는가","알게 된 점이나 느낀 점을 썼는가","옛날과 오늘날의 변화가 드러나는가"]},"explanation":["두 가지를 골라요.","알게 된 점이에요.","느낀 점이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_review_c#1','soc',3,2,'u2','','tb_g3_2_soc_u2_review_c','unit_review','SO3-2-u2-C4',1,'ox','auto','추석맞이 행사장의 송편 빚기 체험은 추석의 세시 풍속과 관련 있어요.',ARRAY['SO3-2-u2-X11']::text[],false,'{"seq":1,"concept":"SO3-2-u2-C4","difficulty":1,"kind":"ox","stem":"추석맞이 행사장의 송편 빚기 체험은 추석의 세시 풍속과 관련 있어요.","answer":"O","reason_options":[{"t":"추석에 그해 새로 난 쌀로 송편을 빚어 먹었기 때문에","correct":true},{"t":"송편은 설날에만 먹는 음식이기 때문에","mis":"SO3-2-u2-X11"}],"mis":"SO3-2-u2-X11","explanation":["단원 도입 그림이에요.","추석에는 송편이에요.","그래서 O예요."],"asset":{"type":"passage","lines":["부스 — 송편 빚기 체험, 송편 판매, 송편 시식, 보름달 카드 쓰기, 강강술래 체험","송편 빚기 부스 앞은 줄이 길고, 바로 옆에 송편 재료가 가득한 트럭이 있어요.","송편 판매 부스에는 직접 판매뿐 아니라 인터넷 주문도 할 수 있다고 적혀 있어요.","민채 — 송편 빚기 부스 앞에 줄 섰는데, 송편 시식 부스 근처에 트럭이 있었어요.","승혁 — 송편을 인터넷으로 주문하고 싶었는데, 직접 사야 한다고 해서 아쉬웠어요.","호준 — 강강술래를 체험하러 갔는데, 송편 빚기 부스 앞에 줄이 길게 서 있었어요.","주연 — 송편 시식 부스에 있었는데, 바로 옆 부스에서 호준이가 보름달 카드를 쓰고 있었어요."],"title":"『사회』 61~63쪽 단원 도입 — 추석맞이 행사장(간추림)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_review_c#2','soc',3,2,'u2','','tb_g3_2_soc_u2_review_c','unit_review','SO3-2-u2-C2',1,'blank','auto','생각 그물의 ㉠에 들어갈 나이로 알맞은 것은 무엇인가요? 「회갑 — 만 (  ㉠  )세에 잔치를 함」',ARRAY['SO3-2-u2-X05']::text[],false,'{"seq":2,"concept":"SO3-2-u2-C2","difficulty":1,"kind":"blank","stem":"생각 그물의 ㉠에 들어갈 나이로 알맞은 것은 무엇인가요? 「회갑 — 만 (  ㉠  )세에 잔치를 함」","options":[{"t":"60","correct":true},{"t":"21","mis":"SO3-2-u2-X05"},{"t":"100","mis":"SO3-2-u2-X05"},{"t":"1","mis":"SO3-2-u2-X05"}],"explanation":["회갑잔치예요.","60년을 축하해요.","60이에요."],"asset":{"type":"passage","lines":["관례 — 성인이 된다는 의미로 함 / 혼례 — 남녀가 부부가 됨","회갑 — 만 (  ㉠  )세에 잔치를 함 / 출생 — 21일 동안 금줄을 침","사라져 가는 풍습 — 금줄 치기, 관례, 신부 집에서 결혼하기 등","옛날 교통수단 — 사람, 동물, (  ㉡  )의 힘을 이용 / 오늘날 — 기계의 힘","교통의 변화 — 더 빠르게, 짐을 많이, 생활 공간이 넓어짐","통신의 변화 — 정보를 찾고 의사소통하는 방식이 변함, 새로운 (  ㉢  )과 직업"],"title":"『사회』 142~143쪽 생각 그물(일부, 빈칸 셋)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_review_c#3','soc',3,2,'u2','','tb_g3_2_soc_u2_review_c','unit_review','SO3-2-u2-C4',1,'mc','auto','단원 평가 4번에서 「부채 주고받기, 창포물에 머리 감기」와 이어지는 명절은 무엇인가요?',ARRAY['SO3-2-u2-X11']::text[],false,'{"seq":3,"concept":"SO3-2-u2-C4","difficulty":1,"kind":"mc","stem":"단원 평가 4번에서 「부채 주고받기, 창포물에 머리 감기」와 이어지는 명절은 무엇인가요?","options":[{"t":"단오","correct":true},{"t":"정월 대보름","mis":"SO3-2-u2-X11"},{"t":"설날","mis":"SO3-2-u2-X11"},{"t":"동지","mis":"SO3-2-u2-X11"}],"explanation":["부채예요.","창포물이에요.","단오예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_review_c#4','soc',3,2,'u2','','tb_g3_2_soc_u2_review_c','unit_review','SO3-2-u2-C7',1,'mc','auto','어버이날 부모님께 카네이션을 선물하는 풍습에 담긴 뜻은 무엇인가요?',ARRAY['SO3-2-u2-X19']::text[],false,'{"seq":4,"concept":"SO3-2-u2-C7","difficulty":1,"kind":"mc","stem":"어버이날 부모님께 카네이션을 선물하는 풍습에 담긴 뜻은 무엇인가요?","options":[{"t":"부모님의 사랑에 감사하는 마음","correct":true},{"t":"시험에 합격하기를 바라는 마음","mis":"SO3-2-u2-X19"},{"t":"복이 들어오기를 바라는 마음","mis":"SO3-2-u2-X19"},{"t":"여름을 시원하게 보내라는 마음","mis":"SO3-2-u2-X19"}],"explanation":["어버이날이에요.","부모님께 드려요.","감사하는 마음이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_review_c#5','soc',3,2,'u2','','tb_g3_2_soc_u2_review_c','unit_review','SO3-2-u2-C9',1,'mc','auto','교실 놀이 말판 문제: 다음 가운데 기계의 힘을 이용한 교통수단은 무엇인가요?',ARRAY['SO3-2-u2-X24']::text[],false,'{"seq":5,"concept":"SO3-2-u2-C9","difficulty":1,"kind":"mc","stem":"교실 놀이 말판 문제: 다음 가운데 기계의 힘을 이용한 교통수단은 무엇인가요?","options":[{"t":"증기 기차","correct":true},{"t":"달구지","mis":"SO3-2-u2-X24"},{"t":"가마","mis":"SO3-2-u2-X24"},{"t":"뗏목","mis":"SO3-2-u2-X24"}],"explanation":["수증기의 힘이에요.","기계예요.","증기 기차예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_review_c#6','soc',3,2,'u2','','tb_g3_2_soc_u2_review_c','unit_review','SO3-2-u2-C9',1,'sa','auto','사람과 짐을 싣고 주로 노를 저어 강의 양쪽을 오간 옛날 배를 쓰세요.','{}'::text[],false,'{"seq":6,"concept":"SO3-2-u2-C9","difficulty":1,"kind":"sa","stem":"사람과 짐을 싣고 주로 노를 저어 강의 양쪽을 오간 옛날 배를 쓰세요.","answer":["나룻배"],"explanation":["노를 저어요.","나◯◯예요.","나룻배예요."],"mis":"SO3-2-u2-X23"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_review_c#7','soc',3,2,'u2','','tb_g3_2_soc_u2_review_c','unit_review','SO3-2-u2-C17',1,'blank','auto','교실 놀이 말판 문제: 「오늘날 사람들은 일상생활에서 (    )을/를 이용해 여러 가지 일을 합니다.」 빈칸에 알맞은 것은?',ARRAY['SO3-2-u2-X38']::text[],false,'{"seq":7,"concept":"SO3-2-u2-C17","difficulty":1,"kind":"blank","stem":"교실 놀이 말판 문제: 「오늘날 사람들은 일상생활에서 (    )을/를 이용해 여러 가지 일을 합니다.」 빈칸에 알맞은 것은?","options":[{"t":"휴대 전화","correct":true},{"t":"파발","mis":"SO3-2-u2-X38"},{"t":"봉수","mis":"SO3-2-u2-X38"},{"t":"서찰","mis":"SO3-2-u2-X38"}],"explanation":["오늘날이에요.","여러 가지 일을 해요.","휴대 전화예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_review_c#8','soc',3,2,'u2','','tb_g3_2_soc_u2_review_c','unit_review','SO3-2-u2-C19',1,'ox','auto','통신수단을 올바르게 이용하지 않으면 다른 사람에게 피해를 줄 수 있어요.',ARRAY['SO3-2-u2-X42']::text[],false,'{"seq":8,"concept":"SO3-2-u2-C19","difficulty":1,"kind":"ox","stem":"통신수단을 올바르게 이용하지 않으면 다른 사람에게 피해를 줄 수 있어요.","answer":"O","reason_options":[{"t":"큰 소리 통화나 상처 주는 댓글처럼 다른 사람을 불편하게 하거나 아프게 하기 때문에","correct":true},{"t":"통신수단은 혼자 쓰는 것이라 다른 사람과 상관없기 때문에","mis":"SO3-2-u2-X42"}],"mis":"SO3-2-u2-X42","explanation":["교실 놀이 말판 문제예요.","다른 사람도 생각해요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_review_c#9','soc',3,2,'u2','','tb_g3_2_soc_u2_review_c','unit_review','SO3-2-u2-C3',2,'ox','auto','오늘날에는 결혼식을 마치면 신랑 신부가 주로 신혼여행을 떠나요.',ARRAY['SO3-2-u2-X07']::text[],false,'{"seq":9,"concept":"SO3-2-u2-C3","difficulty":2,"kind":"ox","stem":"오늘날에는 결혼식을 마치면 신랑 신부가 주로 신혼여행을 떠나요.","answer":"O","reason_options":[{"t":"『사회』 73쪽 오늘날 결혼 풍습 그림처럼 결혼식 뒤에 신혼여행을 가기 때문에","correct":true},{"t":"오늘날에도 신부 집에서 며칠 보낸 뒤 신랑 집으로 가기 때문에","mis":"SO3-2-u2-X07"}],"mis":"SO3-2-u2-X07","explanation":["오늘날 그림이에요.","신혼여행이에요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_review_c#10','soc',3,2,'u2','','tb_g3_2_soc_u2_review_c','unit_review','SO3-2-u2-C5',2,'blank','auto','교실 놀이 말판 문제: 「우리 조상들은 (    )에 곡식을 거두고, 음식을 만들어 먹으며 수확의 기쁨을 나눴습니다.」 빈칸에 알맞은 계절은?',ARRAY['SO3-2-u2-X13']::text[],false,'{"seq":10,"concept":"SO3-2-u2-C5","difficulty":2,"kind":"blank","stem":"교실 놀이 말판 문제: 「우리 조상들은 (    )에 곡식을 거두고, 음식을 만들어 먹으며 수확의 기쁨을 나눴습니다.」 빈칸에 알맞은 계절은?","options":[{"t":"가을","correct":true},{"t":"봄","mis":"SO3-2-u2-X13"},{"t":"여름","mis":"SO3-2-u2-X13"},{"t":"겨울","mis":"SO3-2-u2-X13"}],"explanation":["곡식을 거둬요.","수확의 계절이에요.","가을이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_review_c#11','soc',3,2,'u2','','tb_g3_2_soc_u2_review_c','unit_review','SO3-2-u2-C11',2,'mc','auto','교통의 변화로 새로 생긴 직업은 무엇인가요?',ARRAY['SO3-2-u2-X29']::text[],false,'{"seq":11,"concept":"SO3-2-u2-C11","difficulty":2,"kind":"mc","stem":"교통의 변화로 새로 생긴 직업은 무엇인가요?","options":[{"t":"항공기 조종사","correct":true},{"t":"가마꾼","mis":"SO3-2-u2-X29"},{"t":"뱃사공","mis":"SO3-2-u2-X29"},{"t":"말을 돌보던 사람","mis":"SO3-2-u2-X29"}],"explanation":["새로 생겼어요.","비행기예요.","항공기 조종사예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_review_c#12','soc',3,2,'u2','','tb_g3_2_soc_u2_review_c','unit_review','SO3-2-u2-C12',2,'mc','auto','보행자로서 지켜야 할 안전 수칙이 아닌 것은 무엇인가요?',ARRAY['SO3-2-u2-X31']::text[],false,'{"seq":12,"concept":"SO3-2-u2-C12","difficulty":2,"kind":"mc","stem":"보행자로서 지켜야 할 안전 수칙이 아닌 것은 무엇인가요?","options":[{"t":"차가 오지 않으면 무단 횡단을 해요","correct":true},{"t":"횡단보도에서 주위를 잘 살펴요","mis":"SO3-2-u2-X31"},{"t":"스마트폰을 보면서 걷지 않아요","mis":"SO3-2-u2-X31"},{"t":"도로 옆에서 장난치지 않아요","mis":"SO3-2-u2-X31"}],"explanation":["무단 횡단은 위험해요.","나머지는 지킬 수칙이에요.","무단 횡단이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_review_c#13','soc',3,2,'u2','','tb_g3_2_soc_u2_review_c','unit_review','SO3-2-u2-C13',2,'mc','auto','미래 교통수단인 우주선으로 할 수 있는 일은 무엇인가요?',ARRAY['SO3-2-u2-X33']::text[],false,'{"seq":13,"concept":"SO3-2-u2-C13","difficulty":2,"kind":"mc","stem":"미래 교통수단인 우주선으로 할 수 있는 일은 무엇인가요?","options":[{"t":"우주여행을 하거나 우주로 물건을 옮겨요","correct":true},{"t":"무거운 물건을 쉽게 들게 도와요","mis":"SO3-2-u2-X33"},{"t":"장애인의 이동을 도와요","mis":"SO3-2-u2-X33"},{"t":"바닷속을 다녀요","mis":"SO3-2-u2-X33"}],"explanation":["우주예요.","여행과 운반이에요.","그 일이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_review_c#14','soc',3,2,'u2','','tb_g3_2_soc_u2_review_c','unit_review','SO3-2-u2-C18',2,'ox','auto','스마트 시티 상황실에서는 폐회로 텔레비전과 인터넷 기술로 사람들의 안전을 지켜요.',ARRAY['SO3-2-u2-X41']::text[],false,'{"seq":14,"concept":"SO3-2-u2-C18","difficulty":2,"kind":"ox","stem":"스마트 시티 상황실에서는 폐회로 텔레비전과 인터넷 기술로 사람들의 안전을 지켜요.","answer":"O","reason_options":[{"t":"폐회로 텔레비전 통합 관제 요원이 그곳에서 일하기 때문에","correct":true},{"t":"스마트 시티 상황실은 방송을 만드는 곳이기 때문에","mis":"SO3-2-u2-X41"}],"mis":"SO3-2-u2-X41","explanation":["『사회』 132쪽이에요.","안전을 지켜요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_review_c#15','soc',3,2,'u2','','tb_g3_2_soc_u2_review_c','unit_review','SO3-2-u2-C19',2,'mc','auto','스마트폰 사용 확인표에서 「예」가 1개라면 결과는 무엇인가요?',ARRAY['SO3-2-u2-X42']::text[],false,'{"seq":15,"concept":"SO3-2-u2-C19","difficulty":2,"kind":"mc","stem":"스마트폰 사용 확인표에서 「예」가 1개라면 결과는 무엇인가요?","options":[{"t":"괜찮아요","correct":true},{"t":"주의가 필요해요","mis":"SO3-2-u2-X42"},{"t":"전문적인 검사와 치료가 필요해요","mis":"SO3-2-u2-X42"}],"explanation":["0~2개 칸이에요.","1개예요.","괜찮아요."],"asset":{"type":"passage","lines":["1 스마트폰 이용 시간을 조절하기 어렵다.","2 스마트폰이 옆에 있으면 다른 일에 집중하기 어렵다.","3 스마트폰 이용 때문에 건강에 문제가 생긴 적이 있다.","4 스마트폰 때문에 공부에 어려움이 있다.","「예」 0~2개: 괜찮아요. / 3~4개: 주의가 필요해요.","「예」 5~8개: 전문적인 검사와 치료가 필요해요."],"numbered":false,"title":"『사회』 137쪽 — 스마트폰을 사용하는 나의 모습 확인하기(8문항 가운데 일부와 기준)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_review_c#16','soc',3,2,'u2','','tb_g3_2_soc_u2_review_c','unit_review','SO3-2-u2-C4',2,'mc','auto','단원 도입 행사장에서 볼 수 있는 추석의 세시 풍속과 관련 있는 것끼리 묶은 것은 무엇인가요?',ARRAY['SO3-2-u2-X11']::text[],false,'{"seq":16,"concept":"SO3-2-u2-C4","difficulty":2,"kind":"mc","stem":"단원 도입 행사장에서 볼 수 있는 추석의 세시 풍속과 관련 있는 것끼리 묶은 것은 무엇인가요?","options":[{"t":"송편 빚기, 강강술래","correct":true},{"t":"쥐불놀이, 부럼 깨물기","mis":"SO3-2-u2-X11"},{"t":"팥죽 먹기, 버선 주고받기","mis":"SO3-2-u2-X11"},{"t":"창포물에 머리 감기, 그네뛰기","mis":"SO3-2-u2-X11"}],"explanation":["추석이에요.","송편과 강강술래예요.","그 둘이에요."],"asset":{"type":"passage","lines":["부스 — 송편 빚기 체험, 송편 판매, 송편 시식, 보름달 카드 쓰기, 강강술래 체험","송편 빚기 부스 앞은 줄이 길고, 바로 옆에 송편 재료가 가득한 트럭이 있어요.","송편 판매 부스에는 직접 판매뿐 아니라 인터넷 주문도 할 수 있다고 적혀 있어요.","민채 — 송편 빚기 부스 앞에 줄 섰는데, 송편 시식 부스 근처에 트럭이 있었어요.","승혁 — 송편을 인터넷으로 주문하고 싶었는데, 직접 사야 한다고 해서 아쉬웠어요.","호준 — 강강술래를 체험하러 갔는데, 송편 빚기 부스 앞에 줄이 길게 서 있었어요.","주연 — 송편 시식 부스에 있었는데, 바로 옆 부스에서 호준이가 보름달 카드를 쓰고 있었어요."],"title":"『사회』 61~63쪽 단원 도입 — 추석맞이 행사장(간추림)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_review_c#17','soc',3,2,'u2','','tb_g3_2_soc_u2_review_c','unit_review','SO3-2-u2-C17',3,'mc','auto','단원 평가 9번에서 오늘날 통신수단의 특징을 바르게 설명한 친구는 누구인가요?',ARRAY['SO3-2-u2-X38']::text[],false,'{"seq":17,"concept":"SO3-2-u2-C17","difficulty":3,"kind":"mc","stem":"단원 평가 9번에서 오늘날 통신수단의 특징을 바르게 설명한 친구는 누구인가요?","options":[{"t":"정윤","correct":true},{"t":"승주","mis":"SO3-2-u2-X38"},{"t":"지한","mis":"SO3-2-u2-X38"},{"t":"아린","mis":"SO3-2-u2-X38"}],"explanation":["승주, 지한, 아린은 옛날 특징이에요.","하나로 여러 방법이에요.","정윤이에요."],"asset":{"type":"speech","turns":[{"who":"승주","text":"소식을 전하는 데 시간이 오래 걸려."},{"who":"지한","text":"많은 정보를 자세하고 정확하게 전하기 어려워."},{"who":"정윤","text":"하나의 통신수단으로 다양한 통신 방법을 이용할 수 있어."},{"who":"아린","text":"동물을 이용하거나 사람이 직접 이동해야 소식을 전할 수 있어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_review_c#18','soc',3,2,'u2','','tb_g3_2_soc_u2_review_c','unit_review','SO3-2-u2-C3',3,'error','auto','생각 그물을 완성하며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO3-2-u2-X09']::text[],false,'{"seq":18,"concept":"SO3-2-u2-C3","difficulty":3,"kind":"error","stem":"생각 그물을 완성하며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「사라져 가는 풍습에 백일잔치를 넣어야 해.」","correct":true,"mis_target":"SO3-2-u2-X09"},{"t":"친구 가 — 「사라져 가는 풍습에는 금줄 치기와 관례가 있어.」","mis":"SO3-2-u2-X09"},{"t":"친구 나 — 「신부 집에서 결혼하기도 사라져 가는 풍습이야.」","mis":"SO3-2-u2-X09"}],"explanation":["백일잔치는 오늘날에도 해요.","이어지는 풍습이에요.","친구 다가 잘못 말했어요."],"asset":{"type":"passage","lines":["관례 — 성인이 된다는 의미로 함 / 혼례 — 남녀가 부부가 됨","회갑 — 만 (  ㉠  )세에 잔치를 함 / 출생 — 21일 동안 금줄을 침","사라져 가는 풍습 — 금줄 치기, 관례, 신부 집에서 결혼하기 등","옛날 교통수단 — 사람, 동물, (  ㉡  )의 힘을 이용 / 오늘날 — 기계의 힘","교통의 변화 — 더 빠르게, 짐을 많이, 생활 공간이 넓어짐","통신의 변화 — 정보를 찾고 의사소통하는 방식이 변함, 새로운 (  ㉢  )과 직업"],"title":"『사회』 142~143쪽 생각 그물(일부, 빈칸 셋)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_review_c#19','soc',3,2,'u2','','tb_g3_2_soc_u2_review_c','unit_review','SO3-2-u2-C12',3,'ox','auto','교통의 변화는 발전만 뜻하는 것이 아니어서 좋아진 점과 문제점을 함께 살펴야 해요.',ARRAY['SO3-2-u2-X32']::text[],false,'{"seq":19,"concept":"SO3-2-u2-C12","difficulty":3,"kind":"ox","stem":"교통의 변화는 발전만 뜻하는 것이 아니어서 좋아진 점과 문제점을 함께 살펴야 해요.","answer":"O","reason_options":[{"t":"편리해졌지만 교통 체증, 교통사고, 환경 문제도 함께 생겼기 때문에","correct":true},{"t":"교통이 변하면 좋아지기만 하기 때문에","mis":"SO3-2-u2-X32"}],"mis":"SO3-2-u2-X32","explanation":["좋아진 점이 있어요.","문제점도 있어요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_review_c#20','soc',3,2,'u2','','tb_g3_2_soc_u2_review_c','unit_review','SO3-2-u2-C18',3,'ox','auto','나라에 위급한 일이 생기면 옛날에는 북이나 봉수로 알렸지만 오늘날에는 긴급 재난 문자를 보내요.',ARRAY['SO3-2-u2-X44']::text[],false,'{"seq":20,"concept":"SO3-2-u2-C18","difficulty":3,"kind":"ox","stem":"나라에 위급한 일이 생기면 옛날에는 북이나 봉수로 알렸지만 오늘날에는 긴급 재난 문자를 보내요.","answer":"O","reason_options":[{"t":"오늘날에는 휴대 전화로 많은 사람에게 한꺼번에 빠르게 알릴 수 있기 때문에","correct":true},{"t":"오늘날에도 위급할 때는 봉수만 올리기 때문에","mis":"SO3-2-u2-X44"}],"mis":"SO3-2-u2-X44","explanation":["옛날은 북과 봉수예요.","오늘날은 문자예요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_review_c#21','soc',3,2,'u2','','tb_g3_2_soc_u2_review_c','unit_review','SO3-2-u2-C18',3,'ox','auto','통신수단의 발달로 사람들은 언제 어디서나 다양한 정보를 쉽고 빠르게 주고받을 수 있게 됐어요.',ARRAY['SO3-2-u2-X50']::text[],false,'{"seq":21,"concept":"SO3-2-u2-C18","difficulty":3,"kind":"ox","stem":"통신수단의 발달로 사람들은 언제 어디서나 다양한 정보를 쉽고 빠르게 주고받을 수 있게 됐어요.","answer":"O","reason_options":[{"t":"휴대 전화와 인터넷 같은 통신수단이 발달했기 때문에","correct":true},{"t":"통신수단이 발달해도 정보를 주고받는 방식은 옛날과 같기 때문에","mis":"SO3-2-u2-X50"}],"mis":"SO3-2-u2-X50","explanation":["『사회』 131쪽이에요.","언제 어디서나예요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_review_c#22','soc',3,2,'u2','','tb_g3_2_soc_u2_review_c','unit_review','SO3-2-u2-C11',3,'error','auto','항구와 바다에서 일하는 사람들을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO3-2-u2-X46','SO3-2-u2-X29']::text[],false,'{"seq":22,"concept":"SO3-2-u2-C11","difficulty":3,"kind":"error","stem":"항구와 바다에서 일하는 사람들을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 가 — 「크레인 기사는 바다의 항구에서만 일할 수 있어.」","correct":true,"mis_target":"SO3-2-u2-X46"},{"t":"친구 나 — 「도선사는 큰 배가 항구를 안전하게 드나들도록 안내해.」","mis":"SO3-2-u2-X29"},{"t":"친구 다 — 「해양 경찰관은 해상 교통이 발달하며 생긴 직업이야.」","mis":"SO3-2-u2-X29"}],"explanation":["크레인은 공사장에도 있어요.","여러 곳에서 일해요.","친구 가가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_review_c#23','soc',3,2,'u2','','tb_g3_2_soc_u2_review_c','unit_review','SO3-2-u2-C4',4,'essay','teacher','단원 도입의 추석맞이 행사장처럼 오늘날 추석에 할 수 있는 세시 풍속 체험을 두 가지 쓰고, 그 속에 담긴 옛날 사람들의 마음을 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"SO3-2-u2-C4","difficulty":4,"kind":"essay","stem":"단원 도입의 추석맞이 행사장처럼 오늘날 추석에 할 수 있는 세시 풍속 체험을 두 가지 쓰고, 그 속에 담긴 옛날 사람들의 마음을 쓰세요.","answer_guide":{"answer":"예: 송편 빚기와 강강술래를 체험할 수 있어요. 옛날 사람들은 그해 새로 난 쌀로 송편을 빚고 보름달 아래에서 강강술래를 하며 풍년을 축하하고 감사하는 마음을 나눴어요.","scoring_points":["체험 두 가지를 썼는가","추석의 세시 풍속인가","담긴 마음을 썼는가"]},"explanation":["행사장 그림이에요.","두 가지를 골라요.","마음을 써요."],"asset":{"type":"passage","lines":["부스 — 송편 빚기 체험, 송편 판매, 송편 시식, 보름달 카드 쓰기, 강강술래 체험","송편 빚기 부스 앞은 줄이 길고, 바로 옆에 송편 재료가 가득한 트럭이 있어요.","송편 판매 부스에는 직접 판매뿐 아니라 인터넷 주문도 할 수 있다고 적혀 있어요.","민채 — 송편 빚기 부스 앞에 줄 섰는데, 송편 시식 부스 근처에 트럭이 있었어요.","승혁 — 송편을 인터넷으로 주문하고 싶었는데, 직접 사야 한다고 해서 아쉬웠어요.","호준 — 강강술래를 체험하러 갔는데, 송편 빚기 부스 앞에 줄이 길게 서 있었어요.","주연 — 송편 시식 부스에 있었는데, 바로 옆 부스에서 호준이가 보름달 카드를 쓰고 있었어요."],"title":"『사회』 61~63쪽 단원 도입 — 추석맞이 행사장(간추림)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_review_c#24','soc',3,2,'u2','','tb_g3_2_soc_u2_review_c','unit_review','SO3-2-u2-C11',4,'essay','teacher','교통의 발달로 생활 공간이 넓어진 사례를 두 가지 쓰고, 교통수단을 이용해 먼 곳에 가서 여가를 즐긴 내 경험을 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"SO3-2-u2-C11","difficulty":4,"kind":"essay","stem":"교통의 발달로 생활 공간이 넓어진 사례를 두 가지 쓰고, 교통수단을 이용해 먼 곳에 가서 여가를 즐긴 내 경험을 쓰세요.","answer_guide":{"answer":"예: 출퇴근 버스로 먼 곳의 직장에 다니고, 해외여행을 가는 사람이 많아졌어요. 나는 비행기를 타고 제주도에 가서 한라산에 올라갔어요.","scoring_points":["사례 두 가지를 썼는가","생활 공간이 넓어진 것과 이어지는가","내 경험을 썼는가"]},"explanation":["『사회』 106쪽이에요.","두 가지를 골라요.","내 경험을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_review_c#25','soc',3,2,'u2','','tb_g3_2_soc_u2_review_c','unit_review','SO3-2-u2-C16',4,'essay','teacher','옛날 통신수단 하나와 오늘날 통신수단 하나를 골라 특징을 견주고, 그 변화로 사람들의 생활이 어떻게 달라졌는지 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"SO3-2-u2-C16","difficulty":4,"kind":"essay","stem":"옛날 통신수단 하나와 오늘날 통신수단 하나를 골라 특징을 견주고, 그 변화로 사람들의 생활이 어떻게 달라졌는지 쓰세요.","answer_guide":{"answer":"예: 파발은 문서를 말을 타고 가서 전해 며칠씩 걸렸지만, 휴대 전화는 문자와 영상으로 바로 전해요. 그래서 먼 곳의 가족과도 언제든 소식을 나누게 되었어요.","scoring_points":["두 통신수단의 특징을 썼는가","견주었는가","달라진 생활을 썼는가"]},"explanation":["하나씩 골라요.","특징을 견줘요.","생활을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_review_d#1','soc',3,2,'u2','','tb_g3_2_soc_u2_review_d','unit_review','SO3-2-u2-C1',1,'mc','auto','태양의 움직임에 따라 일 년을 24개로 나누어 정한 날로, 계절의 기준이 되는 것은 무엇인가요?',ARRAY['SO3-2-u2-X03','SO3-2-u2-X47']::text[],false,'{"seq":1,"concept":"SO3-2-u2-C1","difficulty":1,"kind":"mc","stem":"태양의 움직임에 따라 일 년을 24개로 나누어 정한 날로, 계절의 기준이 되는 것은 무엇인가요?","options":[{"t":"절기","correct":true},{"t":"명절","mis":"SO3-2-u2-X03"},{"t":"음력","mis":"SO3-2-u2-X47"},{"t":"세시","mis":"SO3-2-u2-X03"}],"explanation":["태양이에요.","24개예요.","절기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_review_d#2','soc',3,2,'u2','','tb_g3_2_soc_u2_review_d','unit_review','SO3-2-u2-C2',1,'ox','auto','두레는 한꺼번에 많은 일손이 필요한 농사일을 함께하려고 만든 마을의 공동 조직이에요.',ARRAY['SO3-2-u2-X04']::text[],false,'{"seq":2,"concept":"SO3-2-u2-C2","difficulty":1,"kind":"ox","stem":"두레는 한꺼번에 많은 일손이 필요한 농사일을 함께하려고 만든 마을의 공동 조직이에요.","answer":"O","reason_options":[{"t":"모내기, 김매기, 벼 베기를 마을 사람들이 함께했기 때문에","correct":true},{"t":"두레는 한 집의 김장을 돌아가며 돕는 일이기 때문에","mis":"SO3-2-u2-X04"}],"mis":"SO3-2-u2-X04","explanation":["『사회』 69쪽이에요.","마을의 조직이에요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_review_d#3','soc',3,2,'u2','','tb_g3_2_soc_u2_review_d','unit_review','SO3-2-u2-C4',1,'mc','auto','단원 평가 4번에서 「세배하기, 복조리 걸기」와 이어지는 명절은 무엇인가요?',ARRAY['SO3-2-u2-X11']::text[],false,'{"seq":3,"concept":"SO3-2-u2-C4","difficulty":1,"kind":"mc","stem":"단원 평가 4번에서 「세배하기, 복조리 걸기」와 이어지는 명절은 무엇인가요?","options":[{"t":"설날","correct":true},{"t":"추석","mis":"SO3-2-u2-X11"},{"t":"단오","mis":"SO3-2-u2-X11"},{"t":"동지","mis":"SO3-2-u2-X11"}],"explanation":["세배예요.","복조리를 걸어요.","설날이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_review_d#4','soc',3,2,'u2','','tb_g3_2_soc_u2_review_d','unit_review','SO3-2-u2-C6',1,'ox','auto','제기차기는 제기가 바닥에 떨어지지 않도록 한 발 또는 양발로 차는 놀이예요.',ARRAY['SO3-2-u2-X18']::text[],false,'{"seq":4,"concept":"SO3-2-u2-C6","difficulty":1,"kind":"ox","stem":"제기차기는 제기가 바닥에 떨어지지 않도록 한 발 또는 양발로 차는 놀이예요.","answer":"O","reason_options":[{"t":"『사회』 89쪽 제기차기 방법이기 때문에","correct":true},{"t":"제기차기는 병에 화살을 던져 넣는 놀이이기 때문에","mis":"SO3-2-u2-X18"}],"mis":"SO3-2-u2-X18","explanation":["제기예요.","발로 차요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_review_d#5','soc',3,2,'u2','','tb_g3_2_soc_u2_review_d','unit_review','SO3-2-u2-C8',1,'ox','auto','지하철은 철도를 따라 움직이는 교통수단이에요.',ARRAY['SO3-2-u2-X21']::text[],false,'{"seq":5,"concept":"SO3-2-u2-C8","difficulty":1,"kind":"ox","stem":"지하철은 철도를 따라 움직이는 교통수단이에요.","answer":"O","reason_options":[{"t":"지하철, 고속 열차, 관광 열차는 철도로 다니기 때문에","correct":true},{"t":"지하철은 하늘의 항공로로 다니기 때문에","mis":"SO3-2-u2-X21"}],"mis":"SO3-2-u2-X21","explanation":["철도예요.","열차와 같아요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_review_d#6','soc',3,2,'u2','','tb_g3_2_soc_u2_review_d','unit_review','SO3-2-u2-C11',1,'ox','auto','교통의 발달로 한 번에 많은 사람과 물건을 실어 나를 수 있는 교통수단이 나타났어요.',ARRAY['SO3-2-u2-X28']::text[],false,'{"seq":6,"concept":"SO3-2-u2-C11","difficulty":1,"kind":"ox","stem":"교통의 발달로 한 번에 많은 사람과 물건을 실어 나를 수 있는 교통수단이 나타났어요.","answer":"O","reason_options":[{"t":"트럭, 화물선, 고속 열차처럼 많이 싣는 교통수단이 생겼기 때문에","correct":true},{"t":"교통수단이 발달하면 실어 나르는 양이 줄기 때문에","mis":"SO3-2-u2-X28"}],"mis":"SO3-2-u2-X28","explanation":["교실 놀이 찬스 칸이에요.","더 많이 실어요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_review_d#7','soc',3,2,'u2','','tb_g3_2_soc_u2_review_d','unit_review','SO3-2-u2-C15',1,'ox','auto','길 도우미는 운전자에게 목적지까지 가는 길이나 도로 정보 등을 알려 주는 통신수단이에요.',ARRAY['SO3-2-u2-X35']::text[],false,'{"seq":7,"concept":"SO3-2-u2-C15","difficulty":1,"kind":"ox","stem":"길 도우미는 운전자에게 목적지까지 가는 길이나 도로 정보 등을 알려 주는 통신수단이에요.","answer":"O","reason_options":[{"t":"정보를 알려 주는 장치이기 때문에","correct":true},{"t":"길 도우미는 사람을 태워 옮기는 교통수단이기 때문에","mis":"SO3-2-u2-X35"}],"mis":"SO3-2-u2-X35","explanation":["길을 알려 줘요.","정보를 줘요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_review_d#8','soc',3,2,'u2','','tb_g3_2_soc_u2_review_d','unit_review','SO3-2-u2-C19',1,'mc','auto','공공장소에서 휴대 전화로 통화할 때 알맞은 모습은 무엇인가요?',ARRAY['SO3-2-u2-X43']::text[],false,'{"seq":8,"concept":"SO3-2-u2-C19","difficulty":1,"kind":"mc","stem":"공공장소에서 휴대 전화로 통화할 때 알맞은 모습은 무엇인가요?","options":[{"t":"진동으로 바꾸고 작은 소리로 짧게 통화해요","correct":true},{"t":"큰 소리로 길게 통화해요","mis":"SO3-2-u2-X43"},{"t":"스피커로 모두 들리게 통화해요","mis":"SO3-2-u2-X43"},{"t":"걸으면서 동영상을 함께 봐요","mis":"SO3-2-u2-X43"}],"explanation":["여러 사람이 있어요.","피해를 주지 않아요.","작은 소리로 짧게예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_review_d#9','soc',3,2,'u2','','tb_g3_2_soc_u2_review_d','unit_review','SO3-2-u2-C3',2,'mc','auto','장례 풍습이 어떻게 달라지고 있나요?',ARRAY['SO3-2-u2-X09','SO3-2-u2-X08']::text[],false,'{"seq":9,"concept":"SO3-2-u2-C3","difficulty":2,"kind":"mc","stem":"장례 풍습이 어떻게 달라지고 있나요?","options":[{"t":"시신을 땅에 묻는 매장이 줄고 수목장, 해양장 같은 자연장이 늘어요","correct":true},{"t":"모두 매장만 해요","mis":"SO3-2-u2-X09"},{"t":"장례를 치르지 않아요","mis":"SO3-2-u2-X08"},{"t":"명절에 묘지 성묘가 더 늘었어요","mis":"SO3-2-u2-X09"}],"explanation":["『사회』 75쪽 기사예요.","매장이 줄었어요.","자연장이 늘어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_review_d#10','soc',3,2,'u2','','tb_g3_2_soc_u2_review_d','unit_review','SO3-2-u2-C4',2,'match','auto','세시 음식과 담긴 마음을 알맞게 이으세요.','{}'::text[],false,'{"seq":10,"concept":"SO3-2-u2-C4","difficulty":2,"kind":"match","stem":"세시 음식과 담긴 마음을 알맞게 이으세요.","pairs":[{"l":"떡국 가래떡의 흰색","r":"밝은 한 해가 되기를"},{"l":"떡국 가래떡의 긴 모양","r":"건강하고 오래 살기를"},{"l":"반달 모양 송편","r":"집안과 나라가 점점 나아지기를"}],"mis":"SO3-2-u2-X12","explanation":["흰색은 밝은 한 해예요.","긴 모양은 건강이에요.","반달은 나아지기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_review_d#11','soc',3,2,'u2','','tb_g3_2_soc_u2_review_d','unit_review','SO3-2-u2-C11',2,'mc','auto','큰 배들이 안전하게 항구를 드나들도록 안내하는 직업은 무엇인가요?',ARRAY['SO3-2-u2-X29']::text[],false,'{"seq":11,"concept":"SO3-2-u2-C11","difficulty":2,"kind":"mc","stem":"큰 배들이 안전하게 항구를 드나들도록 안내하는 직업은 무엇인가요?","options":[{"t":"도선사","correct":true},{"t":"항공관제사","mis":"SO3-2-u2-X29"},{"t":"철도 기관사","mis":"SO3-2-u2-X29"},{"t":"택배 기사","mis":"SO3-2-u2-X29"}],"explanation":["항구예요.","배를 안내해요.","도선사예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_review_d#12','soc',3,2,'u2','','tb_g3_2_soc_u2_review_d','unit_review','SO3-2-u2-C12',2,'match','auto','단원을 정리하며 교통 문제와 그 문제를 줄이는 노력을 알맞게 이으세요.','{}'::text[],false,'{"seq":12,"concept":"SO3-2-u2-C12","difficulty":2,"kind":"match","stem":"단원을 정리하며 교통 문제와 그 문제를 줄이는 노력을 알맞게 이으세요.","pairs":[{"l":"대기 오염","r":"친환경 에너지를 쓰는 교통수단 이용"},{"l":"주차 공간 부족","r":"새로운 주차 시설 만들기"},{"l":"교통 혼잡","r":"대중교통 중심의 교통 환경 만들기"}],"mis":"SO3-2-u2-X30","explanation":["오염은 친환경 에너지예요.","주차는 주차 시설이에요.","혼잡은 대중교통이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_review_d#13','soc',3,2,'u2','','tb_g3_2_soc_u2_review_d','unit_review','SO3-2-u2-C13',2,'mc','auto','「하늘을 나는 택시」라고 불리는 미래 교통은 무엇인가요?',ARRAY['SO3-2-u2-X26']::text[],false,'{"seq":13,"concept":"SO3-2-u2-C13","difficulty":2,"kind":"mc","stem":"「하늘을 나는 택시」라고 불리는 미래 교통은 무엇인가요?","options":[{"t":"도심 항공 교통","correct":true},{"t":"슈베베반","mis":"SO3-2-u2-X26"},{"t":"툭툭","mis":"SO3-2-u2-X26"},{"t":"곤돌라","mis":"SO3-2-u2-X26"}],"explanation":["『사회』 116쪽 기사예요.","도심의 하늘이에요.","도심 항공 교통이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_review_d#14','soc',3,2,'u2','','tb_g3_2_soc_u2_review_d','unit_review','SO3-2-u2-C18',2,'mc','auto','휴대 전화가 생기며 할 수 있게 된 일로 알맞은 것은 무엇인가요?',ARRAY['SO3-2-u2-X40']::text[],false,'{"seq":14,"concept":"SO3-2-u2-C18","difficulty":2,"kind":"mc","stem":"휴대 전화가 생기며 할 수 있게 된 일로 알맞은 것은 무엇인가요?","options":[{"t":"들고 다니며 통화하고 사진 촬영, 쇼핑, 은행 거래까지 해요","correct":true},{"t":"교환원이 꼭 연결해 줘야 통화해요","mis":"SO3-2-u2-X40"},{"t":"전화기가 있는 곳으로 가야 통화해요","mis":"SO3-2-u2-X40"},{"t":"동전이 있어야만 통화해요","mis":"SO3-2-u2-X40"}],"explanation":["휴대 전화예요.","들고 다녀요.","여러 가지 일을 해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_review_d#15','soc',3,2,'u2','','tb_g3_2_soc_u2_review_d','unit_review','SO3-2-u2-C19',2,'match','auto','장소와 지켜야 할 통신 예절을 알맞게 이으세요.','{}'::text[],false,'{"seq":15,"concept":"SO3-2-u2-C19","difficulty":2,"kind":"match","stem":"장소와 지켜야 할 통신 예절을 알맞게 이으세요.","pairs":[{"l":"공공장소","r":"진동으로 바꾸고 작은 소리로 짧게 통화해요"},{"l":"인터넷","r":"바른 표현을 쓰고 확인되지 않은 정보는 올리지 않아요"},{"l":"길","r":"걸으면서 스마트폰을 보지 않아요"}],"mis":"SO3-2-u2-X43","explanation":["공공장소는 통화예요.","인터넷은 글이에요.","길은 안전이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_review_d#16','soc',3,2,'u2','','tb_g3_2_soc_u2_review_d','unit_review','SO3-2-u2-C4',2,'mc','auto','단원 도입에서 승혁이의 이야기가 바르지 않은 까닭은 무엇인가요?',ARRAY['SO3-2-u2-X44','SO3-2-u2-X11']::text[],false,'{"seq":16,"concept":"SO3-2-u2-C4","difficulty":2,"kind":"mc","stem":"단원 도입에서 승혁이의 이야기가 바르지 않은 까닭은 무엇인가요?","options":[{"t":"송편 판매 부스는 직접 판매뿐 아니라 인터넷 주문도 할 수 있기 때문이에요","correct":true},{"t":"송편 판매 부스가 행사장에 없었기 때문이에요","mis":"SO3-2-u2-X44"},{"t":"승혁이는 송편 시식 부스에 있었기 때문이에요","mis":"SO3-2-u2-X44"},{"t":"송편은 추석 음식이 아니기 때문이에요","mis":"SO3-2-u2-X11"}],"explanation":["셋째 줄을 봐요.","인터넷 주문도 돼요.","그래서 바르지 않아요."],"asset":{"type":"passage","lines":["부스 — 송편 빚기 체험, 송편 판매, 송편 시식, 보름달 카드 쓰기, 강강술래 체험","송편 빚기 부스 앞은 줄이 길고, 바로 옆에 송편 재료가 가득한 트럭이 있어요.","송편 판매 부스에는 직접 판매뿐 아니라 인터넷 주문도 할 수 있다고 적혀 있어요.","민채 — 송편 빚기 부스 앞에 줄 섰는데, 송편 시식 부스 근처에 트럭이 있었어요.","승혁 — 송편을 인터넷으로 주문하고 싶었는데, 직접 사야 한다고 해서 아쉬웠어요.","호준 — 강강술래를 체험하러 갔는데, 송편 빚기 부스 앞에 줄이 길게 서 있었어요.","주연 — 송편 시식 부스에 있었는데, 바로 옆 부스에서 호준이가 보름달 카드를 쓰고 있었어요."],"title":"『사회』 61~63쪽 단원 도입 — 추석맞이 행사장(간추림)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_review_d#17','soc',3,2,'u2','','tb_g3_2_soc_u2_review_d','unit_review','SO3-2-u2-C4',3,'match','auto','단원 평가 4번처럼 명절이나 절기와 세시 풍속을 알맞게 이으세요.','{}'::text[],false,'{"seq":17,"concept":"SO3-2-u2-C4","difficulty":3,"kind":"match","stem":"단원 평가 4번처럼 명절이나 절기와 세시 풍속을 알맞게 이으세요.","pairs":[{"l":"동지","r":"팥죽 먹기, 버선 주고받기"},{"l":"설날","r":"세배하기, 복조리 걸기"},{"l":"정월 대보름","r":"부럼 깨물기, 달맞이"},{"l":"단오","r":"부채 주고받기, 창포물에 머리 감기"},{"l":"추석","r":"송편 빚기, 강강술래"}],"mis":"SO3-2-u2-X11","explanation":["동지는 팥죽, 설날은 세배예요.","대보름은 부럼, 단오는 부채예요.","추석은 송편이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_review_d#18','soc',3,2,'u2','','tb_g3_2_soc_u2_review_d','unit_review','SO3-2-u2-C11',3,'mc','auto','생각 그물의 「교통의 변화」 칸에 들어갈 내용이 아닌 것은 무엇인가요?',ARRAY['SO3-2-u2-X28']::text[],false,'{"seq":18,"concept":"SO3-2-u2-C11","difficulty":3,"kind":"mc","stem":"생각 그물의 「교통의 변화」 칸에 들어갈 내용이 아닌 것은 무엇인가요?","options":[{"t":"생활 공간이 좁아짐","correct":true},{"t":"먼 곳까지 더 빠르게 감","mis":"SO3-2-u2-X28"},{"t":"한 번에 나를 수 있는 짐이 많아짐","mis":"SO3-2-u2-X28"},{"t":"여러 곳에서 만든 물건을 쉽게 구함","mis":"SO3-2-u2-X28"}],"explanation":["교통이 발달했어요.","생활 공간은 넓어졌어요.","좁아짐이 아니에요."],"asset":{"type":"passage","lines":["관례 — 성인이 된다는 의미로 함 / 혼례 — 남녀가 부부가 됨","회갑 — 만 (  ㉠  )세에 잔치를 함 / 출생 — 21일 동안 금줄을 침","사라져 가는 풍습 — 금줄 치기, 관례, 신부 집에서 결혼하기 등","옛날 교통수단 — 사람, 동물, (  ㉡  )의 힘을 이용 / 오늘날 — 기계의 힘","교통의 변화 — 더 빠르게, 짐을 많이, 생활 공간이 넓어짐","통신의 변화 — 정보를 찾고 의사소통하는 방식이 변함, 새로운 (  ㉢  )과 직업"],"title":"『사회』 142~143쪽 생각 그물(일부, 빈칸 셋)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_review_d#19','soc',3,2,'u2','','tb_g3_2_soc_u2_review_d','unit_review','SO3-2-u2-C10',3,'error','auto','오늘날 교통 시설을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO3-2-u2-X26']::text[],false,'{"seq":19,"concept":"SO3-2-u2-C10","difficulty":3,"kind":"error","stem":"오늘날 교통 시설을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 가 — 「주유소는 고속 국도를 지나다 잠시 쉬며 식사하는 곳이야.」","correct":true,"mis_target":"SO3-2-u2-X26"},{"t":"친구 나 — 「선착장은 배가 육지에 붙어 머무는 곳이야.」","mis":"SO3-2-u2-X26"},{"t":"친구 다 — 「휴게소는 고속 국도에서 잠시 쉬는 곳이야.」","mis":"SO3-2-u2-X26"}],"explanation":["쉬는 곳은 휴게소예요.","주유소는 연료를 넣어요.","친구 가가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_review_d#20','soc',3,2,'u2','','tb_g3_2_soc_u2_review_d','unit_review','SO3-2-u2-C17',3,'error','auto','오늘날 통신수단으로 소식을 전하는 모습을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO3-2-u2-X38','SO3-2-u2-X39']::text[],false,'{"seq":20,"concept":"SO3-2-u2-C17","difficulty":3,"kind":"error","stem":"오늘날 통신수단으로 소식을 전하는 모습을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 나 — 「오늘날에도 여러 사람에게 소식을 전하려면 한 사람씩 차례로 찾아가야 해.」","correct":true,"mis_target":"SO3-2-u2-X38"},{"t":"친구 가 — 「디지털 안내판은 버스 도착 시각을 실시간으로 알려 줘.」","mis":"SO3-2-u2-X39"},{"t":"친구 다 — 「모바일 메신저로 여러 사람과 동시에 대화해.」","mis":"SO3-2-u2-X39"}],"explanation":["오늘날은 동시에 전해요.","찾아갈 필요가 없어요.","친구 나가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_review_d#21','soc',3,2,'u2','','tb_g3_2_soc_u2_review_d','unit_review','SO3-2-u2-C14',3,'ox','auto','옛날 교통수단은 사람, 동물, 자연의 힘을 이용했고 오늘날 교통수단은 주로 기계의 힘을 이용해요.',ARRAY['SO3-2-u2-X24']::text[],false,'{"seq":21,"concept":"SO3-2-u2-C14","difficulty":3,"kind":"ox","stem":"옛날 교통수단은 사람, 동물, 자연의 힘을 이용했고 오늘날 교통수단은 주로 기계의 힘을 이용해요.","answer":"O","reason_options":[{"t":"생각 그물에 정리된 옛날과 오늘날 교통수단의 특징이기 때문에","correct":true},{"t":"옛날 교통수단이 기계의 힘을 이용했기 때문에","mis":"SO3-2-u2-X24"}],"mis":"SO3-2-u2-X24","explanation":["생각 그물이에요.","자연의 힘과 기계의 힘이에요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_review_d#22','soc',3,2,'u2','','tb_g3_2_soc_u2_review_d','unit_review','SO3-2-u2-C18',3,'error','auto','통신수단의 발달을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO3-2-u2-X51']::text[],false,'{"seq":22,"concept":"SO3-2-u2-C18","difficulty":3,"kind":"error","stem":"통신수단의 발달을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「통신수단이 발달했으니 어르신들도 모두 키오스크를 쉽게 쓰실 거야.」","correct":true,"mis_target":"SO3-2-u2-X51"},{"t":"친구 가 — 「디지털 배움터에서 스마트폰 쓰는 법을 배울 수 있어.」","mis":"SO3-2-u2-X51"},{"t":"친구 나 — 「변화를 따라가기 힘든 사람을 배려해야 해.」","mis":"SO3-2-u2-X51"}],"explanation":["어려움을 겪는 분도 있어요.","배려가 필요해요.","친구 다가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_review_d#23','soc',3,2,'u2','','tb_g3_2_soc_u2_review_d','unit_review','SO3-2-u2-C5',4,'essay','teacher','우리 가족의 명절 모습을 옛날 세시 풍속과 견주어 이어지는 점과 달라진 점을 쓰고, 달라진 까닭을 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"SO3-2-u2-C5","difficulty":4,"kind":"essay","stem":"우리 가족의 명절 모습을 옛날 세시 풍속과 견주어 이어지는 점과 달라진 점을 쓰고, 달라진 까닭을 쓰세요.","answer_guide":{"answer":"예: 차례를 지내고 떡국을 먹는 것은 옛날부터 이어져요. 명절에 영화를 보거나 여행을 가는 것은 달라졌어요. 직업과 생활 모습이 다양해졌기 때문이에요.","scoring_points":["이어지는 점을 썼는가","달라진 점을 썼는가","달라진 까닭을 썼는가"]},"explanation":["우리 가족을 떠올려요.","이어지는 점과 달라진 점이에요.","까닭을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_review_d#24','soc',3,2,'u2','','tb_g3_2_soc_u2_review_d','unit_review','SO3-2-u2-C13',4,'essay','teacher','미래 교통수단 하나를 골라 그것으로 달라질 생활 모습을 쓰고, 미래 교통이 발전하는 세 가지 방향 가운데 어디에 맞는지 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"SO3-2-u2-C13","difficulty":4,"kind":"essay","stem":"미래 교통수단 하나를 골라 그것으로 달라질 생활 모습을 쓰고, 미래 교통이 발전하는 세 가지 방향 가운데 어디에 맞는지 쓰세요.","answer_guide":{"answer":"예: 자율 주행 휠체어가 생기면 몸이 불편한 사람도 혼자 안전하게 이동할 수 있어요. 더 안전한 방향에 맞아요.","scoring_points":["미래 교통수단을 골랐는가","달라질 생활을 썼는가","빠르고 안전하며 환경을 보호하는 방향과 이었는가"]},"explanation":["하나를 골라요.","생활을 써요.","방향과 이어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g3_2_soc_u2_review_d#25','soc',3,2,'u2','','tb_g3_2_soc_u2_review_d','unit_review','SO3-2-u2-C19',4,'essay','teacher','통신수단을 올바르게 이용하지 않은 모습을 하나 쓰고, 그것이 어떤 문제를 일으키는지와 지킬 약속을 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"SO3-2-u2-C19","difficulty":4,"kind":"essay","stem":"통신수단을 올바르게 이용하지 않은 모습을 하나 쓰고, 그것이 어떤 문제를 일으키는지와 지킬 약속을 쓰세요.","answer_guide":{"answer":"예: 이어폰을 끼고 동영상을 보며 길을 걸으면 차가 오는 것을 몰라 위험해요. 길에서는 스마트폰을 보지 않겠다고 약속해요.","scoring_points":["올바르지 않은 모습을 썼는가","생기는 문제를 썼는가","알맞은 약속을 썼는가"]},"explanation":["모습을 골라요.","문제를 써요.","약속을 써요."],"asset":{"type":"passage","lines":["㉠ 인터넷에서 다른 사람에게 상처 주는 댓글을 써요.","㉡ 다른 사람의 개인 정보를 본인의 허락 없이 알려요.","㉢ 공공장소에서 큰 소리로 통화해요.","㉣ 다른 사람의 모습을 함부로 사진 찍어요.","㉤ 이어폰을 끼고 스마트폰으로 동영상을 보며 길을 걸어요."],"numbered":false,"title":"통신수단을 올바르게 이용하지 않는 모습"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
